/// Spec section 12: a write into a collection that may be null throws, as a read of it does, so it is refused as the
/// read is, through `.` and through a `?.` whose member is nullable itself.
#[test]
fn a_write_into_a_collection_that_may_be_null_is_refused_as_a_read_is() {
    let sharp = "namespace Demo;\n\nclass Opt\n{\n    public Map<string, int>? tags { get; set; } = null;\n    public List<int>? items { get; set; } = null;\n}\n\nclass Writes\n{\n    public void dot(Opt o)\n    {\n        o.tags[\"k\"] = 1;\n        o.items[0] = 1;\n    }\n\n    public void safe(Opt? o)\n    {\n        o?.tags[\"k\"] = 1;\n        o?.items[0] = 1;\n    }\n\n    public int? read(Opt o) => o.items[0];\n}\n";

    assert_eq!(
        issues(("src/Demo/Writes.sharp", sharp), &[]),
        [
            "13:9 possibly-null-array-access",
            "14:9 possibly-null-array-access",
            "19:9 possibly-null-array-access",
            "20:9 possibly-null-array-access",
            "23:32 possibly-null-array-access",
        ]
    );
}

/// Spec section 14.4: `?.` skips the rest of its chain, as in C#, Kotlin and Swift, so past it each member and index has
/// its declared type and only the whole chain may be null. A second `?.` on a link that is never null is refused, and a
/// read after a write past a `?.` may be null.
#[test]
fn null_safe_access_skips_the_rest_of_its_chain_through_an_index() {
    let sharp = "namespace Demo;\n\nclass Node\n{\n    public string name { get; set; } = \"\";\n    public int total { get; set; } = 0;\n    public List<Node> items { get; set; } = [];\n}\n\nclass Holder\n{\n    public Node inner { get; } = new Node();\n}\n\nclass Chains\n{\n    public void written(Node? a)\n    {\n        a?.items[0].name = \"x\";\n        a?.items[0].total += 1;\n        a?.items[0].total++;\n    }\n\n    public string? read(Node? a) => a?.items[0].name;\n\n    public void redundant(Node? a, Holder? h)\n    {\n        a?.items[0]?.name = \"x\";\n        h?.inner?.name = \"y\";\n    }\n\n    public string? redundantRead(Holder? h) => h?.inner?.name;\n\n    public string after(Node? a)\n    {\n        a?.items[0].name = \"x\";\n        return a?.items[0].name;\n    }\n}\n";

    assert_eq!(
        issues(("src/Demo/Chains.sharp", sharp), &[]),
        [
            "28:20 redundant-nullsafe-operator",
            "29:17 redundant-nullsafe-operator",
            "32:56 redundant-nullsafe-operator",
            "37:16 nullable-return-statement",
            "37:16 invalid-return-statement",
        ]
    );
}

/// Spec section 14.4: a null receiver skips the rest of its chain, the arguments and indexes after its `?.` and the
/// value a write through it stores included, so they read the receiver as not null, as C# does, and a `?.` on it there
/// is redundant. A call in them that may change `this.current` ends that for it. After the chain the receiver may be
/// null again, whatever the skipped part tested or wrote. Plain PHP keeps mago's own reading.
#[test]
fn a_null_safe_receiver_is_not_null_in_the_rest_of_its_chain() {
    let sharp = "namespace Demo;\n\nimport App.Shared.Text.TextExtensions;\nimport Lib.Magic;\n\nclass Router\n{\n    public string route(string label) => label;\n    public string label() => \"router\";\n}\n\npublic abstract class Shape\n{\n    public string draw(string kind) => kind;\n    public string name() => \"shape\";\n    public string check(bool flag) => \"\";\n}\n\npublic class Square : Shape\n{\n}\n\nclass Step\n{\n    public const int MAX = 3;\n    public string title { get; set; } = \"\";\n    public string? note { get; set; } = null;\n    public int count { get; set; } = 0;\n    public Router child { get; } = new Router();\n    public Router? spare { get; set; } = null;\n    public List<string> items { get; set; } = [];\n    public string label() => this.title;\n    public int index() => 0;\n    public string route(string label) => label;\n    public string join(string first, string second) => `${first}${second}`;\n    public void run(Function<void()> action) { action(); }\n    public static int twice(int value) => value * 2;\n}\n\nclass Flow\n{\n    private Step? current = null;\n\n    public void start(Step step) { this.current = step; }\n    public string reset() { this.current = null; return \"\"; }\n\n    public string? call(Step? step) => step?.route(step.label());\n    public string? chain(Step? step) => step?.child.route(step.label());\n    public string? index(Step? step) => step?.items[step.index()];\n    public string? field() => this.current?.route(this.current.label());\n    public string? fieldIndex() => this.current?.items[this.current.index()];\n    public string? reread() => this.current?.join(this.reset(), this.current.label());\n    public string? spareChild(Step? step) => step?.spare?.route(step.spare.label());\n    public string? extension(string? title) => title?.slug(title);\n    public void magic(Magic? magic) { magic?.anything(magic.name()); }\n\n    public int? classValue(bool flag)\n    {\n        const type = flag ? typeof(Step) : null;\n        return type?.twice(type.MAX);\n    }\n\n    public void writes(Step? step)\n    {\n        step?.title = step.label();\n        step?.items[step.index()] = \"x\";\n        step?.note ??= step.label();\n    }\n\n    public string? redundant(Step? step) => step?.route(step?.label() ?? \"\");\n\n    public void known(Step known)\n    {\n        known?.note ??= known.label();\n        known?.title += known.label();\n        known?.items[known.index()] = \"x\";\n        known?.count++;\n        --known?.count;\n    }\n\n    public string after(Step? step)\n    {\n        step?.route(\"x\");\n        return step.label();\n    }\n\n    public string afterTypeTest(Shape? shape)\n    {\n        shape?.draw(shape is Square ? \"square\" : \"other\");\n        return shape.name();\n    }\n\n    public string afterMatch(Shape? shape, bool flag)\n    {\n        shape?.draw(match (flag) { true => (shape = new Square()).name(), default => \"other\" });\n        return shape.name();\n    }\n\n    public string afterOr(Shape? shape, bool a, bool b, bool c, bool d)\n    {\n        shape?.check(a || b || c || d || shape is Square);\n        return shape.name();\n    }\n\n    public string afterLambda(Step? step)\n    {\n        step?.run(() => { step = new Step(); });\n        return step.label();\n    }\n\n    public string afterReference(Step? step)\n    {\n        step?.route(Magic.clear(step));\n        return step.label();\n    }\n\n    public string afterProperty(Step? step)\n    {\n        step?.route(step.title);\n        return step.title;\n    }\n\n    public string afterField()\n    {\n        this.current?.route(this.current.title);\n        return this.current.title;\n    }\n}\n";
    let magic = "<?php\n\nnamespace Lib;\n\nfinal class Magic\n{\n    public function name(): string\n    {\n        return 'm';\n    }\n\n    public function __call(string $method, array $arguments): mixed\n    {\n        return null;\n    }\n\n    public static function clear(?object &$value): string\n    {\n        $value = null;\n\n        return '';\n    }\n}\n";

    assert_eq!(
        issues(
            ("src/Demo/Flow.sharp", sharp),
            &[("src/App/Shared/Text/TextExtensions.sharp", TEXT_EXTENSIONS), ("src/Lib/Magic.php", magic)]
        ),
        [
            "52:65 possible-method-access-on-null",
            "52:65 mixed-argument",
            "55:46 non-documented-method",
            "70:61 redundant-nullsafe-operator",
            "70:57 redundant-null-coalesce",
            "74:14 redundant-nullsafe-operator",
            "75:14 redundant-nullsafe-operator",
            "76:14 redundant-nullsafe-operator",
            "77:14 redundant-nullsafe-operator",
            "78:16 redundant-nullsafe-operator",
            "84:16 possible-method-access-on-null",
            "84:16 mixed-return-statement",
            "90:16 possible-method-access-on-null",
            "90:16 mixed-return-statement",
            "96:16 possible-method-access-on-null",
            "96:16 mixed-return-statement",
            "102:16 possible-method-access-on-null",
            "102:16 mixed-return-statement",
            "108:16 possible-method-access-on-null",
            "108:16 mixed-return-statement",
            "114:16 possible-method-access-on-null",
            "114:21 ambiguous-object-method-access",
            "114:16 mixed-return-statement",
            "120:16 possibly-null-property-access",
            "120:16 nullable-return-statement",
            "120:16 invalid-return-statement",
            "126:16 possibly-null-property-access",
            "126:16 nullable-return-statement",
            "126:16 invalid-return-statement",
        ]
    );

    let php = "<?php\n\nnamespace Demo;\n\nfinal class Step\n{\n    public function label(): string\n    {\n        return 'step';\n    }\n\n    public function route(string $label): string\n    {\n        return $label;\n    }\n\n    public static function next(?self $step): ?string\n    {\n        return $step?->route($step->label());\n    }\n}\n";

    assert_eq!(
        issues(("src/Demo/Step.php", php), &[]),
        ["19:30 possible-method-access-on-null", "19:30 mixed-argument"]
    );
}

/// Spec section 14.4: a write through `?.` that a null receiver skips leaves the member as it was, so a read through the
/// same `?.` after it may be null, in every write form, as it is with no write before it.
#[test]
fn a_read_through_null_safe_access_after_a_write_through_it_may_be_null() {
    let sharp = "namespace Demo;\n\nclass Node\n{\n    public string name { get; set; } = \"\";\n    public int total { get; set; } = 0;\n    public string? gift { get; set; } = null;\n    public Node? next { get; set; } = null;\n    public List<int> counts { get; set; } = [1, 2];\n    public Map<string, int> tags { get; set; } = [:];\n    public List<int> items { get; set; } = [];\n}\n\nclass After\n{\n    public string assigned(Node? a)\n    {\n        a?.name = \"x\";\n        return a?.name;\n    }\n\n    public int compound(Node? a)\n    {\n        a?.total += 1;\n        return a?.total;\n    }\n\n    public int stepped(Node? a)\n    {\n        a?.total++;\n        return a?.total;\n    }\n\n    public string coalesced(Node? a)\n    {\n        a?.gift ??= \"g\";\n        return a?.gift;\n    }\n\n    public int indexed(Node? a)\n    {\n        a?.counts[0] = 1;\n        return a?.counts[0];\n    }\n\n    public List<int> changed(Node? a)\n    {\n        a?.items.add(1);\n        return a?.items;\n    }\n\n    public string nested(Node? a)\n    {\n        a?.next?.name = \"n\";\n        return a?.next?.name;\n    }\n\n    public string element(List<Node?> nodes)\n    {\n        nodes[0]?.name = \"e\";\n        return nodes[0]?.name;\n    }\n\n    public bool checks(Node? a)\n    {\n        a?.name = \"x\";\n        a?.gift = \"g\";\n        a?.tags[\"k\"] = 1;\n        return (a?.name ?? \"-\") == \"x\" && a?.gift == null && (a?.tags[\"k\"] ?? 0) == 1;\n    }\n}\n";

    assert_eq!(
        issues(("src/Demo/After.sharp", sharp), &[]),
        [
            "19:16 nullable-return-statement",
            "19:16 invalid-return-statement",
            "25:16 nullable-return-statement",
            "25:16 invalid-return-statement",
            "31:16 nullable-return-statement",
            "31:16 invalid-return-statement",
            "37:16 nullable-return-statement",
            "37:16 invalid-return-statement",
            "43:16 nullable-return-statement",
            "43:16 invalid-return-statement",
            "49:16 nullable-return-statement",
            "49:16 invalid-return-statement",
            "55:16 nullable-return-statement",
            "55:16 invalid-return-statement",
            "61:16 nullable-return-statement",
            "61:16 invalid-return-statement",
        ]
    );
}

/// Spec section 14.4: a write through `?.` happens only when its receivers are not null, so it is checked against the
/// member's own type, in every write form, and its value is null when it is skipped.
#[test]
fn a_write_through_null_safe_access_is_checked_against_the_member_and_may_be_null() {
    let sharp = "namespace Demo;\n\nclass Customer\n{\n    public string name { get; set; } = \"\";\n}\n\nclass Order\n{\n    public string note { get; set; } = \"\";\n    public string? gift { get; set; } = null;\n    public List<int> items { get; set; } = [];\n    public int total { get; set; } = 0;\n    public Map<string, bool> tags { get; set; } = [:];\n    public Map<string, int> fixed { get; private set; } = [:];\n    public List<int> counts { get; set; } = [1, 2];\n    public Customer customer { get; } = new Customer();\n}\n\nclass Shop\n{\n    public string change(Order? order, Order known, int fee)\n    {\n        order?.note = \"gift\";\n        order?.items.add(fee);\n        order?.total += fee;\n        order?.customer.name = \"Ada\";\n        order?.total++;\n        --order?.total;\n        order?.gift ??= \"card\";\n        order?.tags[\"vip\"] = true;\n        order?.counts[0] = 5;\n        order?.counts[1]++;\n        order?.fixed[\"a\"] = 1;\n        order?.note += \"!\";\n        order?.note = 1;\n        known?.note = \"x\";\n        const note = (order?.note = \"gift\");\n        return note;\n    }\n}\n";

    assert_eq!(
        issues(("src/Demo/Shop.sharp", sharp), &[]),
        [
            "34:16 invalid-property-write",
            "36:23 invalid-property-assignment-value",
            "37:14 redundant-nullsafe-operator",
            "39:16 nullable-return-statement",
            "39:16 invalid-return-statement",
        ]
    );
}

#[test]
fn a_nullable_value_where_a_value_is_required_is_reported_as_in_php() {
    let sharp = "namespace Demo;\n\nimport Lib.Calc;\n\nclass Report\n{\n    public static int total(int? extra, Calc? calc)\n    {\n        const sum = calc.add(extra, 1);\n        return extra;\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nuse Lib\\Calc;\n\nclass Report\n{\n    public static function total(?int $extra, ?Calc $calc): int\n    {\n        $sum = $calc->add($extra, 1);\n        return $extra;\n    }\n}\n";

    let sharp_issues = issues(("src/Demo/Report.sharp", sharp), &[("src/Lib/Calc.php", CALC)]);
    let php_issues = issues(("src/Demo/Report.php", php), &[("src/Lib/Calc.php", CALC)]);

    assert_eq!(
        sharp_issues,
        [
            "9:21 possible-method-access-on-null",
            "9:30 possibly-null-argument",
            "10:16 nullable-return-statement",
            "10:16 invalid-return-statement",
        ]
    );
    // PHP reports storing the `mixed` result of the call, and PHP# stores it as `Any?` without a report.
    let php_codes: Vec<&str> = codes(&php_issues).into_iter().filter(|code| *code != "mixed-assignment").collect();
    assert_eq!(codes(&sharp_issues), php_codes);
}

#[test]
fn a_typed_local_takes_values_of_its_written_type_with_no_issues() {
    let sharp = "namespace Demo;\n\nimport Lib.Calc;\n\nclass Report\n{\n    public static int total(int? value, bool make)\n    {\n        Calc? found = null;\n        if (make) {\n            found = Calc.make();\n        }\n        int? first = null;\n        first ??= value;\n        const int base = 10;\n        int total = base;\n        total += first ?? 1;\n        return found?.add(total, 1) ?? total;\n    }\n}\n";

    assert_eq!(issues(("src/Demo/Report.sharp", sharp), &[("src/Lib/Calc.php", CALC)]), Vec::<String>::new());
}

#[test]
fn locals_of_sibling_blocks_keep_their_own_written_types() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public static void total(bool flag)\n    {\n        if (flag) {\n            int value = 1;\n            value = 2;\n        } else {\n            string value = \"one\";\n            value = \"two\";\n        }\n        {\n            float value = 1.5;\n            value = 2.5;\n        }\n    }\n}\n";

    assert_eq!(issues(("src/Demo/Report.sharp", sharp), &[]), Vec::<String>::new());
}

#[test]
fn a_value_that_is_not_the_written_type_of_a_local_is_reported() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public static int total(int? value)\n    {\n        int count = \"one\";\n        count = 2;\n        count = 2.5;\n        count = value;\n        const string label = 1;\n        return count;\n    }\n}\n";

    assert_eq!(
        issues(("src/Demo/Report.sharp", sharp), &[]),
        [
            "7:21 invalid-local-assignment-value",
            "9:17 invalid-local-assignment-value",
            "10:17 invalid-local-assignment-value",
            "11:30 invalid-local-assignment-value",
        ]
    );

    let first = analyze(&PLUGIN_REGISTRY, settings(), ("src/Demo/Report.sharp", sharp), &[]).remove(0);
    assert_eq!(first.message, "Invalid assignment to `count`: it is declared as `int`.");
}

#[test]
fn a_typed_for_counter_takes_only_values_of_its_written_type() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public static int total(int? extra)\n    {\n        for (int step = \"one\"; step < 3; step++) {\n        }\n        for (int? found = null; found == null; ) {\n            found = extra;\n        }\n        for (int count = 0; count < 3; count++) {\n            count = 1.5;\n        }\n        return 0;\n    }\n}\n";

    assert_eq!(
        issues(("src/Demo/Report.sharp", sharp), &[]),
        ["7:25 invalid-local-assignment-value", "13:21 invalid-local-assignment-value"]
    );
}

/// The standard library alone passes a plain PHP function an argument by reference, and a write that can never fit
/// the local's written type is refused there.
#[test]
fn a_by_reference_write_that_can_never_fit_the_written_type_of_a_local_is_reported() {
    let sharp = "namespace Sharp;\n\nclass Response\n{\n    public static List<string> line()\n    {\n        string file = \"\";\n        List<string> line = [];\n        global.headers_sent(file, line);\n        return line;\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nclass Response\n{\n    /** @return list<string> */\n    public static function line(): array\n    {\n        $file = '';\n        $line = [];\n        headers_sent($file, $line);\n        return $line;\n    }\n}\n";

    assert_eq!(
        issues(("vendor/heyjordanparker/php-sharp-composer/library/Sharp/Response.sharp", sharp), &[]),
        ["9:35 invalid-local-assignment-value"]
    );
    assert_eq!(issues(("src/Demo/Response.php", php), &[]), ["13:16 invalid-return-statement"]);
}

/// A local plain PHP holds by reference keeps the type the first reference parameter gives it, so a later write that
/// may not fit that type is reported in PHP#'s words: each type as PHP# writes it, `Any?` for plain PHP's `mixed`.
#[test]
fn a_write_that_may_break_a_by_reference_constraint_is_reported_in_php_sharp_words() {
    let sorter = "<?php\n\nnamespace Lib;\n\nfinal class Sorter\n{\n    /** @param array<int, string> $items */\n    public static function sort(array &$items): void\n    {\n    }\n\n    public static function keep(&$value): void\n    {\n    }\n}\n";
    let sharp = "namespace Demo;\n\nimport Lib.Sorter;\n\nclass Report\n{\n    public static void run()\n    {\n        let names = [1: \"a\"];\n        Sorter.sort(names);\n        Sorter.keep(names);\n    }\n}\n";

    assert_eq!(
        worded(("src/Demo/Report.sharp", sharp), &[("src/Lib/Sorter.php", sorter)]),
        [
            "11:21 reference-constraint-violation Potentially invalid assignment to referenced variable `names`. | This assignment to type `Any?` may violate a reference constraint. | Variable was passed as a by-reference argument here, constraining it to type `Map<int, string>`. | An object may still hold a reference to this variable. Changing its type can lead to a `TypeError` at runtime. | Ensure this variable's type remains compatible, or refactor to avoid holding onto the external reference.",
            "11:21 invalid-local-assignment-value Invalid assignment to `names`: it is declared as `Map<int, string>`. | This value has type `Any?`. | `names` is declared as `Map<int, string>` here. | Assign a `Map<int, string>` value, or change the type `names` is declared with.",
        ]
    );
}

#[test]
fn the_nullable_return_help_writes_the_nullable_type_as_the_file_does() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public static int total(int? extra)\n    {\n        return extra;\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nclass Report\n{\n    public static function total(?int $extra): int\n    {\n        return $extra;\n    }\n}\n";

    let help = |analyzed| {
        analyze(&PLUGIN_REGISTRY, settings(), analyzed, &[])
            .into_iter()
            .find(|issue| issue.code.as_deref() == Some("nullable-return-statement"))
            .and_then(|issue| issue.help)
            .expect("a nullable-return-statement help")
    };

    assert!(help(("src/Demo/Report.sharp", sharp)).contains("(e.g., 'int?')"));
    assert!(help(("src/Demo/Report.php", php)).contains("(e.g., '?int')"));
}

#[test]
fn assigning_a_property_of_one_local_keeps_the_memoized_calls_of_another_as_in_php() {
    let box_class = "<?php\n\nnamespace Lib;\n\nfinal class Box\n{\n    public int $value = 0;\n\n    /** @mutation-free */\n    public function count(): ?int\n    {\n        return null;\n    }\n}\n";
    let sharp = "namespace Demo;\n\nimport Lib.Box;\n\nclass Report\n{\n    public static int total(Box box, Box other)\n    {\n        if (other.count() != null) {\n            box.value = 1;\n            return other.count();\n        }\n        return 0;\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nuse Lib\\Box;\n\nclass Report\n{\n    public static function total(Box $box, Box $other): int\n    {\n        if ($other->count() !== null) {\n            $box->value = 1;\n            return $other->count();\n        }\n        return 0;\n    }\n}\n";

    let sharp_issues = issues(("src/Demo/Report.sharp", sharp), &[("src/Lib/Box.php", box_class)]);
    let php_issues = issues(("src/Demo/Report.php", php), &[("src/Lib/Box.php", box_class)]);

    assert_eq!(sharp_issues, Vec::<String>::new());
    assert_eq!(codes(&sharp_issues), codes(&php_issues));
}

#[test]
fn a_sharp_import_passes_the_use_statement_and_casing_checks_as_in_php() {
    let sharp = "namespace Demo;\n\nimport Lib.Calc;\nimport Lib.Money;\nimport Lib.missing;\n\nclass Report\n{\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nuse Lib\\Calc;\nuse Lib\\Money;\nuse Lib\\missing;\n\nclass Report\n{\n}\n";
    let money = "<?php\n\nnamespace Lib;\n\nfinal class money\n{\n}\n";
    let settings = || Settings { check_use_statements: true, check_name_casing: true, ..settings() };

    let others = [("src/Lib/Calc.php", CALC), ("src/Lib/money.php", money)];

    let sharp_issues = issues_with(settings(), ("src/Demo/Report.sharp", sharp), &others);
    let php_issues = issues_with(settings(), ("src/Demo/Report.php", php), &others);

    assert_eq!(sharp_issues, ["4:8 incorrect-class-like-casing", "5:8 non-existent-use-import"]);
    assert_eq!(codes(&sharp_issues), codes(&php_issues));
    assert_eq!(
        messages_with(settings(), ("src/Demo/Report.sharp", sharp), &others)[0],
        "Incorrect casing for class-like `Lib.Money`."
    );
    assert_eq!(
        messages_with(settings(), ("src/Demo/Report.php", php), &others)[0],
        "Incorrect casing for class-like `Lib\\Money`."
    );
}

/// `Sharp\Text\Regex`, a plain PHP class with a static method.
const REGEX: (&str, &str) = (
    "src/Sharp/Text/Regex.php",
    "<?php\n\nnamespace Sharp\\Text;\n\nfinal class Regex\n{\n    public static function matches(string $pattern, string $text): bool\n    {\n        return preg_match($pattern, $text) === 1;\n    }\n}\n",
);

/// The PHP twin of a `.sharp` file that calls `Sharp\Text\Regex` through `import … as Rx`.
const RENAMED_REGEX_CALL: (&str, &str) = (
    "src/Demo/Report.php",
    "<?php\n\ndeclare(strict_types=1);\n\nnamespace Demo;\n\nuse Sharp\\Text\\Regex as Rx;\n\nclass Report\n{\n    public static function run(string $text): bool\n    {\n        return Rx::matches('/a/', $text) && Rx::matches(1, $text);\n    }\n}\n",
);

/// The issues of `RENAMED_REGEX_CALL`.
fn renamed_regex_call_issues() -> Vec<String> {
    issues(RENAMED_REGEX_CALL, &[REGEX])
}

#[test]
fn a_php_call_through_a_use_renamed_with_as_is_checked_as_the_imported_class() {
    assert_eq!(codes(&renamed_regex_call_issues()), ["invalid-argument"]);
}

/// Spec section 23: `Rx.matches(…)` calls `Sharp\Text\Regex::matches` when the file imports the class as `Rx`, so its
/// arguments are checked against that method, as in PHP.
#[test]
fn a_call_through_a_renamed_import_is_checked_as_the_imported_class_as_in_php() {
    let sharp = "namespace Demo;\n\nimport Sharp.Text.Regex as Rx;\n\nclass Report\n{\n    public static bool run(string text) => Rx.matches(\"/a/\", text) && Rx.matches(1, text);\n}\n";

    let sharp_issues = analyze(&PLUGIN_REGISTRY, settings(), ("src/Demo/Report.sharp", sharp), &[REGEX]);
    let located_issues: Vec<String> = sharp_issues.iter().map(|issue| located(sharp, issue)).collect();

    assert_eq!(located_issues, ["7:82 invalid-argument"]);
    assert_eq!(codes(&located_issues), codes(&renamed_regex_call_issues()));
    assert!(sharp_issues[0].message.contains("`Rx.matches`"), "{}", sharp_issues[0].message);
    assert_eq!(
        messages(RENAMED_REGEX_CALL, &[REGEX]),
        [
            "Invalid argument type for argument #1 of `Sharp\\Text\\Regex::matches`: expected `string`, but found `int(1)`."
        ]
    );
}

/// A message names a class the file renames by the name the file imports it as.
#[test]
fn a_type_in_a_message_names_a_renamed_class_by_its_new_name() {
    let sharp = "namespace Demo;\n\nimport Lib.Calc as Tool;\n\nclass Report\n{\n    public static Tool pick(List<Tool> tools, int|string key) => tools[key];\n}\n";

    let issues = analyze(&PLUGIN_REGISTRY, settings(), ("src/Demo/Report.sharp", sharp), &[("src/Lib/Calc.php", CALC)]);

    assert_eq!(issues.iter().map(|issue| issue.code.as_deref()).collect::<Vec<_>>(), [Some("mismatched-array-index")]);
    assert!(issues[0].message.contains("`List<Tool>`"), "{}", issues[0].message);
}

/// Spec section 23: a renamed import of a class that does not exist reports what the plain import of it reports.
#[test]
fn an_unknown_class_imported_under_another_name_is_reported_as_its_plain_import_is() {
    let settings = || Settings { check_use_statements: true, ..settings() };
    let reported = |code: &'static str| -> Vec<String> {
        analyze(&PLUGIN_REGISTRY, settings(), ("src/Demo/Report.sharp", code), &[])
            .iter()
            .map(|issue| format!("{} {}", located(code, issue), issue.message))
            .collect()
    };

    let plain = reported("namespace Demo;\n\nimport Nope.Thing;\n\nclass Report\n{\n}\n");
    let renamed = reported("namespace Demo;\n\nimport Nope.Thing as T;\n\nclass Report\n{\n}\n");

    assert_eq!(
        plain,
        ["3:8 non-existent-use-import Imported class, interface, trait, or enum `Nope.Thing` does not exist."]
    );
    assert_eq!(renamed, plain);
    assert_eq!(
        messages_with(settings(), ("src/Demo/Report.php", "<?php\n\nnamespace Demo;\n\nuse Nope\\Thing as T;\n"), &[]),
        ["Imported class, interface, trait, or enum `Nope\\Thing` does not exist."]
    );
}

#[test]
fn a_php_use_of_an_unknown_class_renamed_with_as_is_reported_as_its_plain_use_is() {
    let settings = || Settings { check_use_statements: true, ..settings() };

    let plain = issues_with(settings(), ("src/Demo/Report.php", "<?php\n\nnamespace Demo;\n\nuse Nope\\Thing;\n"), &[]);
    let renamed =
        issues_with(settings(), ("src/Demo/Report.php", "<?php\n\nnamespace Demo;\n\nuse Nope\\Thing as T;\n"), &[]);

    assert_eq!(plain, ["5:5 non-existent-use-import"]);
    assert_eq!(renamed, plain);
}

#[test]
fn a_field_is_the_php_property_of_the_same_name() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    private int count = 0;\n    protected string label = \"one\";\n\n    public int total(int extra)\n    {\n        this.count += extra;\n        this.label = 2;\n        return this.count;\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nclass Report\n{\n    private int $count = 0;\n    protected string $label = \"one\";\n\n    public function total(int $extra): int\n    {\n        $this->count += $extra;\n        $this->label = 2;\n        return $this->count;\n    }\n}\n";

    let sharp_issues = issues(("src/Demo/Report.sharp", sharp), &[]);
    let php_issues = issues(("src/Demo/Report.php", php), &[]);

    assert_eq!(sharp_issues, ["11:22 invalid-property-assignment-value"]);
    assert_eq!(codes(&sharp_issues), codes(&php_issues));
}

#[test]
fn new_checks_the_constructor_arguments_as_in_php() {
    let money = "<?php\n\nnamespace Lib;\n\nfinal class Money\n{\n    public function __construct(public int $cents)\n    {\n    }\n}\n";
    let sharp = "namespace Demo;\n\nimport Lib.Money;\n\nclass Report\n{\n    public static int total()\n    {\n        const money = new Money(\"one\");\n        return new Money(cents: 2).cents + money.cents;\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nuse Lib\\Money;\n\nclass Report\n{\n    public static function total(): int\n    {\n        $money = new Money(\"one\");\n        return new Money(cents: 2)->cents + $money->cents;\n    }\n}\n";

    let sharp_issues = issues(("src/Demo/Report.sharp", sharp), &[("src/Lib/Money.php", money)]);
    let php_issues = issues(("src/Demo/Report.php", php), &[("src/Lib/Money.php", money)]);

    assert_eq!(sharp_issues, ["9:33 invalid-argument"]);
    assert_eq!(codes(&sharp_issues), codes(&php_issues));
}

#[test]
fn the_constructor_is_the_php_constructor() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    private int count;\n\n    public Report(int start)\n    {\n        this.count = start;\n    }\n\n    public int total()\n    {\n        return this.count;\n    }\n\n    public static int make()\n    {\n        return new Report(\"one\").total() + new Report(start: 2).total();\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nclass Report\n{\n    private int $count;\n\n    public function __construct(int $start)\n    {\n        $this->count = $start;\n    }\n\n    public function total(): int\n    {\n        return $this->count;\n    }\n\n    public static function make(): int\n    {\n        return new Report(\"one\")->total() + new Report(start: 2)->total();\n    }\n}\n";
    let caller =
        "<?php\n\nnamespace App;\n\nfunction run(): int\n{\n    return (new \\Demo\\Report(\"one\"))->total();\n}\n";

    let sharp_issues = issues(("src/Demo/Report.sharp", sharp), &[]);
    let php_issues = issues(("src/Demo/Report.php", php), &[]);

    assert_eq!(sharp_issues, ["19:27 invalid-argument"]);
    assert_eq!(codes(&sharp_issues), codes(&php_issues));
    assert_eq!(issues(("src/App/run.php", caller), &[("src/Demo/Report.sharp", sharp)]), ["7:30 invalid-argument"]);
}

#[test]
fn an_auto_property_is_the_php_property_with_its_set_visibility() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public int views { get; private set; } = 0;\n    public string name { get; set; }\n    public int id { get; }\n\n    public Report(int id)\n    {\n        this.id = id;\n        this.name = \"report\";\n    }\n\n    public int bump()\n    {\n        this.views++;\n        return this.views + this.id;\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nclass Report\n{\n    public private(set) int $views = 0;\n    public string $name;\n    public readonly int $id;\n\n    public function __construct(int $id)\n    {\n        $this->id = $id;\n        $this->name = \"report\";\n    }\n\n    public function bump(): int\n    {\n        $this->views++;\n        return $this->views + $this->id;\n    }\n}\n";
    let caller = "<?php\n\nnamespace App;\n\nfunction run(\\Demo\\Report $report): string\n{\n    $report->name = 'other';\n    $report->views = 2;\n    $report->id = 3;\n    return $report->name . $report->views . $report->id;\n}\n";

    let sharp_issues = issues(("src/Demo/Report.sharp", sharp), &[]);
    let php_issues = issues(("src/Demo/Report.php", php), &[]);
    let caller_of_sharp = issues(("src/App/run.php", caller), &[("src/Demo/Report.sharp", sharp)]);
    let caller_of_php = issues(("src/App/run.php", caller), &[("src/Demo/Report.php", php)]);

    assert_eq!(sharp_issues, Vec::<String>::new());
    assert_eq!(codes(&sharp_issues), codes(&php_issues));
    assert_eq!(caller_of_sharp.len(), 2, "{caller_of_sharp:?}");
    assert_eq!(caller_of_sharp, caller_of_php);
}

#[test]
fn a_promoted_member_is_the_promoted_php_property() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public Report(private int count, public int id { get; }, public string name { get; protected set; })\n    {\n    }\n\n    public int total()\n    {\n        return this.count + this.id;\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nclass Report\n{\n    public function __construct(private int $count, public readonly int $id, public protected(set) string $name)\n    {\n    }\n\n    public function total(): int\n    {\n        return $this->count + $this->id;\n    }\n}\n";
    let caller = "<?php\n\nnamespace App;\n\nfunction run(\\Demo\\Report $report): string\n{\n    $report->id = 3;\n    $report->name = 'other';\n    return $report->name . $report->id;\n}\n";

    let sharp_issues = issues(("src/Demo/Report.sharp", sharp), &[]);
    let php_issues = issues(("src/Demo/Report.php", php), &[]);
    let caller_of_sharp = issues(("src/App/run.php", caller), &[("src/Demo/Report.sharp", sharp)]);
    let caller_of_php = issues(("src/App/run.php", caller), &[("src/Demo/Report.php", php)]);

    assert_eq!(sharp_issues, Vec::<String>::new());
    assert_eq!(codes(&sharp_issues), codes(&php_issues));
    assert_eq!(caller_of_sharp.len(), 2, "{caller_of_sharp:?}");
    assert_eq!(caller_of_sharp, caller_of_php);
}

#[test]
fn an_initial_value_that_is_not_constant_is_checked_against_the_member_type() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    private Clock clock = new Clock();\n    public int ticks { get; private set; } = new Clock().tick();\n    private string label = new Clock();\n\n    public string read()\n    {\n        return this.label;\n    }\n\n    public Clock now()\n    {\n        return this.clock;\n    }\n}\n\nclass Clock\n{\n    public int tick()\n    {\n        return 1;\n    }\n}\n";

    assert_eq!(issues(("src/Demo/Report.sharp", sharp), &[]), ["7:28 invalid-property-default-value"]);
}

#[test]
fn a_get_only_property_is_readonly_and_set_once_in_the_constructor() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public string code { get; } = \"none\";\n    public int count { get; }\n\n    public Report(public int id { get; }, int start)\n    {\n        this.count = start;\n        this.count = 2;\n        this.id = 3;\n        this.code = \"x\";\n    }\n\n    public void reset(Report other)\n    {\n        other.count = 1;\n        this.count = 0;\n    }\n}\n";

    // The first write in the constructor sets `count`. Every other write would throw `Error` on `readonly`: a second
    // write, a property set from its parameter or its initial value, another object's property, and a write outside
    // the constructor.
    assert_eq!(
        issues(("src/Demo/Report.sharp", sharp), &[]),
        [
            "11:14 invalid-property-write",
            "12:14 invalid-property-write",
            "13:14 invalid-property-write",
            "18:15 invalid-property-write",
            "19:14 invalid-property-write",
        ]
    );
}

const NEGATIVE: &str = "<?php\n\nnamespace Lib;\n\nfinal class Negative extends \\Exception\n{\n}\n";

/// Spec section 6.1: an accessor body reads and writes `field`, the storage, and a `set` body reads `value`, both of
/// the property's type, as PHP's hooks read `$this->name` and `$value`.
#[test]
fn accessor_bodies_read_field_and_value_with_the_property_type() {
    let sharp = "namespace Demo;\n\nimport Lib.Negative;\nimport Lib.Words;\n\nclass Product\n{\n    public string name { get => field; set => field = Words.trim(value); } = \"\";\n    public int stock { get; private set { if (value < 0) { throw new Negative(); } field = value; } } = 0;\n    public int doubled { get => this.stock * 2; }\n    public int hits { get => field; set { field += value; field++; } } = 0;\n    public List<string> seen { get => field; set { field = []; field.add(value[0]); } } = [];\n    public Map<string, int> counts { get => field; set { field = value; field[\"all\"] = 1; } } = [:];\n    public List<string> tags { get => field; set { field = value; } } = [];\n\n    public void tag(string tag)\n    {\n        this.tags.add(tag);\n        this.stock = this.doubled + 1;\n        this.name = tag;\n    }\n}\n";

    assert_eq!(
        issues(("src/Demo/Product.sharp", sharp), &[("src/Lib/Negative.php", NEGATIVE), WORDS]),
        Vec::<String>::new()
    );
}

/// `field` has the property's type, so a value of another type assigned to it is the error assigning that value to
/// the property is, as `$this->count = 'many'` is in the PHP twin's hook.
#[test]
fn a_value_of_the_wrong_type_assigned_to_field_is_reported_as_in_php() {
    let sharp = "namespace Demo;\n\nclass Counter\n{\n    public int count { get => field; set => field = \"many\"; } = 0;\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nclass Counter\n{\n    public int $count = 0 {\n        get => $this->count;\n        set {\n            $this->count = 'many';\n        }\n    }\n}\n";

    let sharp_issues = issues(("src/Demo/Counter.sharp", sharp), &[]);
    let php_issues = issues(("src/Demo/Counter.php", php), &[]);

    assert_eq!(sharp_issues, ["5:53 invalid-property-assignment-value"]);
    assert_eq!(codes(&sharp_issues), codes(&php_issues));
}

/// `field` and `value` read as the property's type, and a `get` body returns it, as the PHP twin's hooks do.
#[test]
fn field_value_and_a_get_body_have_the_property_type_as_in_php() {
    let sharp = "namespace Demo;\n\nimport Lib.Words;\n\nclass Counter\n{\n    public int count { get => Words.length(field); set => field = Words.length(value); } = 0;\n    public string label { get { return 1; } }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nuse Lib\\Words;\n\nclass Counter\n{\n    public int $count = 0 {\n        get => Words::length($this->count);\n        set {\n            $this->count = Words::length($value);\n        }\n    }\n    public string $label {\n        get {\n            return 1;\n        }\n    }\n}\n";

    let sharp_issues = issues(("src/Demo/Counter.sharp", sharp), &[WORDS]);
    let php_issues = issues(("src/Demo/Counter.php", php), &[WORDS]);

    assert_eq!(sharp_issues.len(), 3, "{sharp_issues:?}");
    assert_eq!(codes(&sharp_issues), codes(&php_issues));
}

/// A property whose accessors all have bodies that never use `field` has no storage, so nothing initializes it, as
/// PHP's virtual property. Every other property is backed, and is initialized as a field is. Spec section 6 holds a
/// backed property to a value from the start, so PHP#'s own error names `count` and `total` where PHP reports a missing
/// constructor, and PHP's own check stays off PHP# code.
#[test]
fn only_a_property_with_storage_needs_initializing_as_in_php() {
    let sharp = "namespace Demo;\n\nclass Store\n{\n    public int open { get => 1; }\n    public int named { get => this.open; set => this.save(value); }\n    public int count { get => field; set => field = value; }\n    public int total { get; set => field = value; }\n\n    public void save(int value)\n    {\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nclass Store\n{\n    public int $open {\n        get => 1;\n    }\n    public int $named {\n        get => $this->open;\n        set {\n            $this->save($value);\n        }\n    }\n    public int $count {\n        get => $this->count;\n        set {\n            $this->count = $value;\n        }\n    }\n    public int $total {\n        set {\n            $this->total = $value;\n        }\n    }\n\n    public function save(int $value): void\n    {\n    }\n}\n";

    let settings = || Settings { check_property_initialization: true, ..settings() };
    let sharp_issues = issues_with(settings(), ("src/Demo/Store.sharp", sharp), &[]);
    let php_issues = issues_with(settings(), ("src/Demo/Store.php", php), &[]);

    assert_eq!(php_issues, ["5:7 missing-constructor"]);
    assert_eq!(sharp_issues, ["7:16 uninitialized-property", "8:16 uninitialized-property"]);
}

/// A get-only property whose `get` body uses `field` is set where a get-only auto-property is: once, in the
/// constructor.
#[test]
fn a_get_only_property_with_a_get_body_is_set_only_where_readonly_allows() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public int count { get => field * 2; }\n\n    public Report(int start)\n    {\n        this.count = start;\n    }\n\n    public void reset()\n    {\n        this.count = 0;\n    }\n}\n";

    assert_eq!(issues(("src/Demo/Report.sharp", sharp), &[]), ["14:14 invalid-property-write"]);
}

/// An accessor body writes another property as a method of its class does, so a write to a get-only property there
/// is the error the same write in a method is. Writing `field` writes the accessor's own storage, which its get-only
/// property allows.
#[test]
fn a_write_to_a_get_only_property_from_another_accessor_is_reported_as_from_a_method() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public int id { get; }\n    public int code { get => field; set { field = value; this.id = value; } } = 0;\n    public int hits { get { field = field + 1; return field; } } = 0;\n\n    public Report(int id)\n    {\n        this.id = id;\n    }\n}\n";

    assert_eq!(issues(("src/Demo/Report.sharp", sharp), &[]), ["6:63 invalid-property-write"]);
}

/// The same write in a plain PHP hook stays unreported, as before PHP# accessors.
#[test]
fn a_write_to_a_readonly_property_from_a_php_hook_stays_unreported() {
    let php = "<?php\n\nnamespace Demo;\n\nclass Report\n{\n    public readonly int $id;\n    public int $code = 0 {\n        get => $this->code;\n        set {\n            $this->code = $value;\n            $this->id = $value;\n        }\n    }\n\n    public function __construct(int $id)\n    {\n        $this->id = $id;\n    }\n}\n";

    assert_eq!(issues(("src/Demo/Report.php", php), &[]), Vec::<String>::new());
}

/// A `get` block runs as PHP's `get` hook, which returns the property's type on every path, as a method with a return
/// type does.
#[test]
fn a_get_block_with_a_path_that_ends_without_returning_is_reported() {
    let sharp = "namespace Demo;\n\nimport Lib.Negative;\n\nclass Report\n{\n    public int open { get { if (this.ready()) { return 1; } } }\n    public int closed { get { if (this.ready()) { return 1; } throw new Negative(); } }\n\n    public bool ready()\n    {\n        return true;\n    }\n}\n";

    assert_eq!(
        issues(("src/Demo/Report.sharp", sharp), &[("src/Lib/Negative.php", NEGATIVE)]),
        ["7:23 missing-return-statement"]
    );
}

/// A property, with accessor bodies or without, overrides a plain PHP parent's untyped property: it writes its type,
/// and the engine drops it as decision 028 does, so PHP runs the hooks untyped. Without `override` it names the fix.
/// A PHP twin that keeps the type is what PHP refuses.
#[test]
fn a_property_with_accessors_overrides_a_php_parents_untyped_property() {
    let parent = "<?php\n\nnamespace Lib;\n\nclass Record\n{\n    public $label;\n    public $code;\n}\n";
    let sharp = "namespace Demo;\n\nimport Lib.Record;\n\nclass Order : Record\n{\n    public override string label { get => field; set => field = value; } = \"\";\n    public override string code { get; set; } = \"\";\n}\n";
    let missing = "namespace Demo;\n\nimport Lib.Record;\n\nclass Order : Record\n{\n    public string label { get => field; set => field = value; } = \"\";\n    public string code { get; set; } = \"\";\n}\n";
    let others = [("src/Lib/Record.php", parent)];

    assert_eq!(issues(("src/Demo/Order.sharp", sharp), &others), Vec::<String>::new());
    assert_eq!(
        issues(("src/Demo/Order.sharp", missing), &others),
        ["7:19 missing-override-attribute", "8:19 missing-override-attribute"]
    );

    let php = "<?php\n\nnamespace Demo;\n\nuse Lib\\Record;\n\nclass Order extends Record\n{\n    public string $label = '' {\n        get => $this->label;\n        set => $value;\n    }\n    public string $code = '';\n}\n";
    assert_eq!(
        issues(("src/Demo/Order.php", php), &others),
        ["9:12 incompatible-property-type", "13:12 incompatible-property-type"]
    );
}

/// A property over a plain PHP parent's attributes has no storage. A `get` body that returns the `mixed` that
/// `getAttribute` returns without converting it with `as` reports `mixed` as the PHP twin's hook does.
#[test]
fn a_property_over_a_php_parents_attributes_reports_its_mixed_get_as_in_php() {
    let sharp = "namespace Demo;\n\nimport Lib.Model;\n\nclass Order : Model\n{\n    public Address shipping { get => this.getAttribute(\"shipping\"); set => this.setAttribute(\"shipping\", value); }\n}\n\nclass Address\n{\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nuse Lib\\Model;\n\nclass Order extends Model\n{\n    public Address $shipping {\n        get => $this->getAttribute('shipping');\n        set {\n            $this->setAttribute('shipping', $value);\n        }\n    }\n}\n\nclass Address\n{\n}\n";

    let sharp_issues = issues(("src/Demo/Order.sharp", sharp), &[("src/Lib/Model.php", MODEL)]);
    let php_issues = issues(("src/Demo/Order.php", php), &[("src/Lib/Model.php", MODEL)]);

    assert_eq!(sharp_issues, ["7:38 mixed-return-statement"]);
    assert_eq!(codes(&sharp_issues), codes(&php_issues));
}

/// A nullable property with accessor bodies has the issues of its PHP twin. Over a plain PHP parent's attributes it
/// has no storage, so its `get` reports `mixed` unless it converts the value with `as`. One whose body uses
/// `field` has storage, so it writes `= null` as its twin does, and a get-only one without storage needs no initial value.
#[test]
fn nullable_properties_with_accessor_bodies_have_the_issues_of_their_php_twins() {
    let sharp = "namespace Demo;\n\nimport Lib.Model;\n\nclass Order : Model\n{\n    public Address? shipping { get => this.getAttribute(\"shipping\"); set => this.setAttribute(\"shipping\", value); }\n    public string? note { get => field; set => field = value; } = null;\n    public string? summary { get => this.note; }\n}\n\nclass Address\n{\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nuse Lib\\Model;\n\nclass Order extends Model\n{\n    public ?Address $shipping {\n        get => $this->getAttribute('shipping');\n        set {\n            $this->setAttribute('shipping', $value);\n        }\n    }\n    public ?string $note = null {\n        get => $this->note;\n        set {\n            $this->note = $value;\n        }\n    }\n    public ?string $summary {\n        get => $this->note;\n    }\n}\n\nclass Address\n{\n}\n";

    let sharp_issues = issues(("src/Demo/Order.sharp", sharp), &[("src/Lib/Model.php", MODEL)]);
    let php_issues = issues(("src/Demo/Order.php", php), &[("src/Lib/Model.php", MODEL)]);

    assert_eq!(sharp_issues, ["7:39 mixed-return-statement"]);
    assert_eq!(codes(&sharp_issues), codes(&php_issues));
}

/// `typeof(X)` of a class is its class name, as PHP's `X::class` is, so passing either where another class's name is
/// expected reports the same. Of a missing class, PHP's `Missing::class` is still a string and reports where it is
/// passed too, while a PHP# file's `typeof(Missing)` has no type, so it reports only that the class is missing.
#[test]
fn typeof_is_the_class_name_as_in_php() {
    let registry = "<?php\n\nnamespace Lib;\n\nfinal class Registry\n{\n    /** @param class-string<Calc> $class */\n    public static function keep(string $class): string\n    {\n        return $class;\n    }\n}\n";
    let sharp = "namespace Demo;\n\nimport Lib.Calc;\nimport Lib.Registry;\n\nclass Report\n{\n    public static string total()\n    {\n        Registry.keep(typeof(Report));\n        Registry.keep(typeof(Missing));\n        return Registry.keep(typeof(Calc));\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nuse Lib\\Calc;\nuse Lib\\Registry;\n\nclass Report\n{\n    public static function total(): string\n    {\n        Registry::keep(Report::class);\n        Registry::keep(Missing::class);\n        return Registry::keep(Calc::class);\n    }\n}\n";
    let others = [("src/Lib/Calc.php", CALC), ("src/Lib/Registry.php", registry)];

    let sharp_issues = issues(("src/Demo/Report.sharp", sharp), &others);
    let php_issues = issues(("src/Demo/Report.php", php), &others);

    assert_eq!(sharp_issues, ["10:23 invalid-argument", "11:30 non-existent-class-like"]);
    assert_eq!(php_issues, ["12:24 invalid-argument", "13:24 non-existent-class-like", "13:24 invalid-argument"]);
}

/// A static member written through its class name is checked as PHP checks `Class::$name`.
#[test]
fn a_static_member_write_is_checked_as_in_php() {
    let sharp = "namespace Demo;\n\nclass Counter\n{\n    public const int START = 10;\n    private static int count = 0;\n    public static string last { get; private set; } = \"none\";\n\n    public static void touch()\n    {\n        Counter.count = 5;\n        Counter.count++;\n        Counter.count += 2;\n        Counter.last ??= \"never\";\n        Counter.count = \"many\";\n        Counter.missing = 1;\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nclass Counter\n{\n    public const int START = 10;\n    private static int $count = 0;\n    public private(set) static string $last = \"none\";\n\n    public static function touch(): void\n    {\n        Counter::$count = 5;\n        Counter::$count++;\n        Counter::$count += 2;\n        Counter::$last ??= \"never\";\n        Counter::$count = \"many\";\n        Counter::$missing = 1;\n    }\n}\n";

    let sharp_issues = issues(("src/Demo/Counter.sharp", sharp), &[]);
    let php_issues = issues(("src/Demo/Counter.php", php), &[]);

    assert_eq!(codes(&sharp_issues), codes(&php_issues), "{sharp_issues:?} {php_issues:?}");
    assert_eq!(php_issues.len(), 3, "{php_issues:?}");
}

/// `Class.y` reads a constant or an enum case when the class has one by that name, and the static property otherwise,
/// so each read is checked as the PHP twin's `::` read of that member.
#[test]
fn a_class_member_read_is_checked_as_its_constant_enum_case_or_static_property_in_php() {
    let registry = "<?php\n\nnamespace Lib;\n\nenum Order: string\n{\n    case Ascending = 'asc';\n}\n\nfinal class Registry\n{\n    public const int VERSION = 2;\n    public static string $label = 'registry';\n    protected static int $hidden = 1;\n}\n";
    let sharp = "namespace Demo;\n\nimport Lib.Order;\nimport Lib.Registry;\n\nclass Members\n{\n    public static int version()\n    {\n        return Registry.VERSION;\n    }\n\n    public static Order order()\n    {\n        return Order.Ascending;\n    }\n\n    public static int label()\n    {\n        return Registry.label;\n    }\n\n    public static int missing()\n    {\n        return Registry.missing;\n    }\n\n    public static int hidden()\n    {\n        return Registry.hidden;\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nuse Lib\\Order;\nuse Lib\\Registry;\n\nclass Members\n{\n    public static function version(): int\n    {\n        return Registry::VERSION;\n    }\n\n    public static function order(): Order\n    {\n        return Order::Ascending;\n    }\n\n    public static function label(): int\n    {\n        return Registry::$label;\n    }\n\n    public static function missing(): int\n    {\n        return Registry::$missing;\n    }\n\n    public static function hidden(): int\n    {\n        return Registry::$hidden;\n    }\n}\n";

    let sharp_issues = issues(("src/Demo/Members.sharp", sharp), &[("src/Lib/Registry.php", registry)]);
    let php_issues = issues(("src/Demo/Members.php", php), &[("src/Lib/Registry.php", registry)]);

    assert_eq!(codes(&sharp_issues), codes(&php_issues), "{sharp_issues:?} {php_issues:?}");
    assert_eq!(
        sharp_issues,
        [
            "20:16 invalid-return-statement",
            "25:25 non-existent-property",
            "25:16 invalid-return-statement",
            "30:25 invalid-property-read",
            "30:16 never-return",
        ]
    );
}

/// A constant expression reads `Class.y` as the class constant or enum case, as PHP's `Class::y`: a parameter default,
/// a constant's value and a constant initial value check as their PHP twins, and a static property there is a
/// constant the class does not have.
#[test]
fn a_class_member_read_in_a_constant_expression_is_checked_as_a_class_constant() {
    let registry = "<?php\n\nnamespace Lib;\n\nenum Order: string\n{\n    case Ascending = 'asc';\n}\n\nfinal class Registry\n{\n    public const int VERSION = 2;\n    public static string $label = 'registry';\n}\n";
    let sharp = "namespace Demo;\n\nimport Lib.Order;\nimport Lib.Registry;\n\nclass Members\n{\n    public const int NEXT = Registry.VERSION + 1;\n    public const string LABEL = Registry.label;\n    private Order sort = Order.Ascending;\n\n    public string run(Order order = Order.Ascending, int version = Registry.VERSION)\n    {\n        return this.sort.value;\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nuse Lib\\Order;\nuse Lib\\Registry;\n\nclass Members\n{\n    public const int NEXT = Registry::VERSION + 1;\n    public const string LABEL = Registry::label;\n    private Order $sort = Order::Ascending;\n\n    public function run(Order $order = Order::Ascending, int $version = Registry::VERSION): string\n    {\n        return $this->sort->value;\n    }\n}\n";

    let sharp_issues = issues(("src/Demo/Members.sharp", sharp), &[("src/Lib/Registry.php", registry)]);
    let php_issues = issues(("src/Demo/Members.php", php), &[("src/Lib/Registry.php", registry)]);

    assert_eq!(codes(&sharp_issues), codes(&php_issues), "{sharp_issues:?} {php_issues:?}");
    assert_eq!(sharp_issues, ["9:42 non-existent-class-constant"]);
}

/// Spec section 21: a pattern takes types and constants only, so its value is a constant expression. `Class.y` there is
/// the class constant or enum case, and a static property is a constant the class does not have.
#[test]
fn a_pattern_takes_constants_of_the_codebase_only() {
    let registry = "<?php\n\nnamespace Lib;\n\nenum Order: string\n{\n    case Ascending = 'asc';\n}\n\nfinal class Registry\n{\n    public const int VERSION = 2;\n    public static string $label = 'registry';\n}\n";
    let sharp = "namespace Demo;\n\nimport Lib.Order;\nimport Lib.Registry;\n\nclass Members\n{\n    public bool run(Any? value)\n    {\n        return value is Registry.VERSION or Order.Ascending or Registry.label;\n    }\n\n    public bool below(int value) => value is < Registry.label;\n}\n";

    assert_eq!(
        issues(("src/Demo/Members.sharp", sharp), &[("src/Lib/Registry.php", registry)]),
        ["10:73 non-existent-class-constant", "13:57 non-existent-class-constant"]
    );
}

/// A PHP class extends a PHP# abstract class and implements a PHP# interface, whose method has no access modifier
/// and is public, as their PHP twins are.
#[test]
fn abstract_and_final_classes_and_interfaces_are_checked_as_in_php() {
    let square = "<?php\n\nnamespace Demo;\n\nfinal class Square extends Shape implements Measured\n{\n    public function area(): float\n    {\n        return 4.0;\n    }\n\n    protected function name(): string\n    {\n        return 'square';\n    }\n}\n\nfunction measure(Measured $shape): float\n{\n    return $shape->area() + (new Square())->area();\n}\n";
    let sharp = "namespace Demo;\n\nabstract class Shape\n{\n    public abstract float area();\n\n    protected abstract string name();\n}\n\nfinal class Unit\n{\n}\n\ninterface Measured\n{\n    float area();\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nabstract class Shape\n{\n    abstract public function area(): float;\n\n    abstract protected function name(): string;\n}\n\nfinal class Unit\n{\n}\n\ninterface Measured\n{\n    public function area(): float;\n}\n";

    let sharp_issues = issues(("src/Demo/Square.php", square), &[("src/Demo/Shape.sharp", sharp)]);
    let php_issues = issues(("src/Demo/Square.php", square), &[("src/Demo/Shape.php", php)]);

    assert_eq!(sharp_issues, php_issues);
    assert_eq!(issues(("src/Demo/Shape.sharp", sharp), &[]), issues(("src/Demo/Shape.php", php), &[]));
}

/// A header names a PHP base class and a PHP interface, so the class calls the base's methods and passes where the
/// interface is expected. `super.size()` calls the PHP# base's method, as `parent::size()` does in PHP.
#[test]
fn a_header_names_the_base_class_and_the_interfaces_as_in_php() {
    let library = "<?php\n\nnamespace Lib;\n\ninterface Named\n{\n    public function name(): string;\n}\n\nabstract class Entity\n{\n    public function id(): int\n    {\n        return 7;\n    }\n}\n\nfinal class Shelf\n{\n    public static function show(Named $named, Entity $entity): string\n    {\n        return $named->name() . $entity->id();\n    }\n}\n";
    let sharp = "namespace Demo;\n\nimport Lib.Entity;\nimport Lib.Named;\nimport Lib.Shelf;\n\npublic class Page : Entity, Named\n{\n    public string name()\n    {\n        return \"page\";\n    }\n\n    public int number()\n    {\n        return this.id();\n    }\n\n    public string shown()\n    {\n        return Shelf.show(this, this);\n    }\n}\n\npublic class Image\n{\n    public virtual int size()\n    {\n        return 10;\n    }\n}\n\npublic class Thumbnail : Image\n{\n    public override int size()\n    {\n        return super.size() + 1;\n    }\n}\n";
    let others = [("src/Lib/Entity.php", library)];

    assert_eq!(issues(("src/Demo/Page.sharp", sharp), &others), Vec::<String>::new());
}

/// A header with two classes, a missing name, a final class, an enum or an interface whose method the class lacks
/// reports what its PHP twin's `extends` and `implements` report.
#[test]
fn a_header_reports_what_extends_and_implements_report_in_php() {
    let library = "<?php\n\nnamespace Lib;\n\ninterface Named\n{\n    public function name(): string;\n}\n\nclass Entity\n{\n}\n\nclass Other\n{\n}\n\nfinal class Sealed\n{\n}\n\nenum Suit\n{\n    case Hearts;\n}\n";
    let sharp = "namespace Demo;\n\nimport Lib.Entity;\nimport Lib.Named;\nimport Lib.Other;\nimport Lib.Sealed;\nimport Lib.Suit;\n\npublic class Twice : Entity, Other\n{\n}\n\npublic class Lost : Missing\n{\n}\n\npublic class Closed : Sealed\n{\n}\n\npublic class Suited : Suit\n{\n}\n\npublic class Partial : Named\n{\n}\n\npublic interface Wide : Entity\n{\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nuse Lib\\Entity;\nuse Lib\\Named;\nuse Lib\\Other;\nuse Lib\\Sealed;\nuse Lib\\Suit;\n\nclass Twice extends Entity implements Other\n{\n}\n\nclass Lost implements Missing\n{\n}\n\nclass Closed extends Sealed\n{\n}\n\nclass Suited implements Suit\n{\n}\n\nclass Partial implements Named\n{\n}\n\ninterface Wide extends Entity\n{\n}\n";
    let others = [("src/Lib/Named.php", library)];

    let sharp_issues = issues(("src/Demo/Twice.sharp", sharp), &others);
    let php_issues = issues(("src/Demo/Twice.php", php), &others);

    assert_eq!(
        codes(&php_issues),
        [
            "invalid-implement",
            "non-existent-class-like",
            "extend-final-class",
            "invalid-implement",
            "unimplemented-abstract-method",
            "invalid-extend"
        ]
    );
    assert_eq!(codes(&sharp_issues), codes(&php_issues));
}

/// Plain PHP traits for spec section 22's header: one with a field and a method, one whose method collides with it,
/// one that asks for an abstract method of another arity, and one that asks for a method a class must give.
const HAS_LABEL: &str = "<?php\n\nnamespace Lib;\n\ntrait HasLabel\n{\n    public string $name = 'order';\n\n    public function describe(): string\n    {\n        return 'labeled ' . $this->name;\n    }\n}\n\ntrait HasTitle\n{\n    public function describe(): string\n    {\n        return 'titled';\n    }\n}\n\ntrait Measured\n{\n    abstract public function describe(int $width): string;\n}\n\ntrait Priced\n{\n    abstract public function price(): int;\n}\n";

/// A header names a plain PHP trait, and the class uses it as `use HasLabel;` does, spec section 22: it calls the
/// trait's method and reads its field through `this.`, and passes itself where the trait is the type, as a parameter
/// and as a `List<HasLabel>` element. Its subclass does the same, and plain PHP's `instanceof HasLabel` holds for both.
#[test]
fn a_header_trait_gives_the_class_its_members_and_its_type_as_use_does_in_php() {
    let sharp = "namespace Demo;\n\nimport Lib.HasLabel;\n\npublic class Order : HasLabel\n{\n    public string title()\n    {\n        return this.describe() + this.name + Order.show(this);\n    }\n\n    public static string show(HasLabel labeled)\n    {\n        return labeled.describe();\n    }\n}\n\npublic class RushOrder : Order\n{\n    public string rushed()\n    {\n        return this.describe() + this.name + Order.show(this);\n    }\n\n    public int counted()\n    {\n        List<HasLabel> all = [this];\n        return all.count();\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nuse Lib\\HasLabel;\n\nclass Order\n{\n    use HasLabel;\n\n    public function title(): string\n    {\n        return $this->describe() . $this->name . Order::show($this);\n    }\n\n    public static function show(HasLabel $labeled): string\n    {\n        return $labeled->describe();\n    }\n}\n\nclass RushOrder extends Order\n{\n    public function rushed(): string\n    {\n        return $this->describe() . $this->name . Order::show($this);\n    }\n\n    public function counted(): int\n    {\n        $all = [$this];\n        return count($all);\n    }\n}\n";
    let caller = "<?php\n\nnamespace App;\n\nuse Demo\\Order;\nuse Demo\\RushOrder;\nuse Lib\\HasLabel;\n\nfunction label(Order $order, RushOrder $rush, object $any): string\n{\n    if ($any instanceof HasLabel) {\n        return $any->describe();\n    }\n\n    return $order instanceof HasLabel && $rush instanceof HasLabel ? 'both' : 'none';\n}\n";
    let library = ("src/Lib/HasLabel.php", HAS_LABEL);

    assert_eq!(issues(("src/Demo/Order.php", php), &[library]), Vec::<String>::new());
    assert_eq!(issues(("src/Demo/Order.sharp", sharp), &[library]), Vec::<String>::new());
    assert_eq!(
        issues(("src/App/label.php", caller), &[library, ("src/Demo/Order.sharp", sharp)]),
        issues(("src/App/label.php", caller), &[library, ("src/Demo/Order.php", php)]),
    );
}

/// A header trait may stand alone or come before the base class, an enum's header may name a trait without fields, as
/// an enum's `use` does, and a struct's and an event's headers name one too: a trait works everywhere an interface
/// does, spec section 22.
#[test]
fn a_header_trait_stands_anywhere_in_a_class_header_and_in_an_enum_header() {
    let sharp = "namespace Demo;\n\nimport Lib.Entity;\nimport Lib.HasLabel;\nimport Lib.HasTitle;\n\npublic class Alone : HasTitle\n{\n}\n\npublic class First : HasTitle, Entity\n{\n    public string shown() => this.describe() + this.kind();\n}\n\npublic enum Kind : HasTitle\n{\n    case One;\n\n    public string shown() => this.describe();\n}\n\npublic struct Stamp : HasLabel\n{\n    public Stamp(public int at { get; }) { }\n\n    public string shown() => this.describe();\n}\n\npublic event Copied(int id) : HasTitle;\n";
    let library = "<?php\n\nnamespace Lib;\n\nclass Entity\n{\n    public function kind(): string\n    {\n        return 'entity';\n    }\n}\n";

    assert_eq!(
        issues(
            ("src/Demo/Alone.sharp", sharp),
            &[("src/Lib/HasLabel.php", HAS_LABEL), ("src/Lib/Entity.php", library)]
        ),
        Vec::<String>::new()
    );
}

/// Spec section 22: a generic plain PHP trait takes its type arguments in a header, as `@use HasFactory<OrderFactory>`
/// gives them, and its methods return them.
#[test]
fn a_generic_header_trait_takes_its_type_arguments() {
    let library = "<?php\n\nnamespace Lib;\n\nabstract class Model {}\n\nclass Factory {}\n\nclass OrderFactory extends Factory {}\n\n/**\n * @template TFactory of Factory\n */\ntrait HasFactory\n{\n    /** @return TFactory */\n    public static function factory()\n    {\n        throw new \\LogicException('stub');\n    }\n}\n";
    let sharp = "namespace Demo;\n\nimport Lib.HasFactory;\nimport Lib.Model;\nimport Lib.OrderFactory;\n\npublic class Order : Model, HasFactory<OrderFactory>\n{\n    public static OrderFactory make() => Order.factory();\n}\n";

    assert_eq!(messages(("src/Demo/Order.sharp", sharp), &[("src/Lib/HasFactory.php", library)]), Vec::<String>::new());
}

/// A header trait's abstract method the class leaves out, one whose arity differs from another trait's, and a trait
/// field the class declares again with another type, as a field or a computed property, each report what the PHP
/// twin's `use` reports.
#[test]
fn a_header_trait_reports_what_use_reports_in_php() {
    let sharp = "namespace Demo;\n\nimport Lib.HasLabel;\nimport Lib.Measured;\nimport Lib.Priced;\n\npublic class Narrow : HasLabel, Measured\n{\n}\n\npublic class Clash : HasLabel\n{\n    private int name = 1;\n}\n\npublic class Unpriced : Priced\n{\n}\n\npublic class Computed : HasLabel\n{\n    public int name => 1;\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nuse Lib\\HasLabel;\nuse Lib\\Measured;\nuse Lib\\Priced;\n\nclass Narrow\n{\n    use HasLabel, Measured;\n}\n\nclass Clash\n{\n    use HasLabel;\n\n    private int $name = 1;\n}\n\nclass Unpriced\n{\n    use Priced;\n}\n\nclass Computed\n{\n    use HasLabel;\n\n    public int $name { get => 1; }\n}\n";
    let others = [("src/Lib/HasLabel.php", HAS_LABEL)];

    let sharp_issues = issues(("src/Demo/Narrow.sharp", sharp), &others);
    let php_issues = issues(("src/Demo/Narrow.php", php), &others);

    assert!(!php_issues.is_empty());
    assert_eq!(codes(&sharp_issues), codes(&php_issues), "{sharp_issues:?} {php_issues:?}");
    assert!(sharp_issues.contains(&"22:5 incompatible-property-override".to_owned()), "{sharp_issues:?}");
}

/// Spec section 22: an interface's default body sees only the interface's own members, a PHP# class that implements
/// the interface gets the body, and a plain PHP class gets it only by using the trait `<Interface>\Defaults`. A plain
/// PHP class without the trait is one error that names it, in place of each method it leaves abstract.
#[test]
fn a_default_body_sees_only_its_interface_and_a_plain_php_class_gets_it_through_the_defaults_trait() {
    let sharp = "namespace App;\n\npublic interface HasDesign\n{\n    string designColumn { get; }\n    string designKey() => `design:${this.designColumn}`;\n    string designId() => `design:${this.id}`;\n}\n\npublic class Page : HasDesign\n{\n    public int id => 7;\n    public string designColumn => \"design\";\n    public string shown() => this.designKey();\n}\n";
    let php = "<?php\n\nnamespace Legacy;\n\nuse App\\HasDesign;\n\nclass LegacyPage implements HasDesign\n{\n    use HasDesign\\Defaults;\n\n    public string $designColumn = 'design';\n}\n\nclass Bare implements HasDesign\n{\n    public string $designColumn = 'design';\n}\n";

    assert_eq!(issues(("src/App/HasDesign.sharp", sharp), &[]), ["7:41 non-existent-property", "7:34 invalid-operand"]);
    assert_eq!(
        worded(("src/Legacy/LegacyPage.php", php), &[("src/App/HasDesign.sharp", sharp)]),
        [
            "14:7 unimplemented-abstract-method `Legacy\\Bare` implements `App\\HasDesign` without its default bodies: write `use \\App\\HasDesign\\Defaults;` in `Legacy\\Bare`. | Declared here. | `App\\HasDesign` is declared here. | A plain PHP class gets the default bodies of the PHP# interface `App\\HasDesign` through the trait `App\\HasDesign\\Defaults`."
        ]
    );
}

/// Spec sections 19 and 22: an interface's constant is read through the interface and through each class that
/// implements it, a default body reads it, and the interface's operator orders two values of the interface and two of a
/// class that gets it. A class's own operator for two of its values replaces none, so it overrides nothing the
/// interface declares.
#[test]
fn an_interface_gives_each_class_its_constant_and_its_operator() {
    let sharp = "namespace App;\n\npublic interface Priced\n{\n    const string CURRENCY = \"USD\";\n    int cents { get; }\n    string label => `${this.cents} ${Priced.CURRENCY}`;\n    static int operator <=>(Priced a, Priced b) => a.cents <=> b.cents;\n}\n\npublic class Book : Priced\n{\n    public int cents { get; }\n    public Book(int cents) { this.cents = cents; }\n}\n\npublic class Rare : Priced\n{\n    public int cents { get; }\n    public Rare(int cents) { this.cents = cents; }\n    public static int operator <=>(Rare a, Rare b) => b.cents <=> a.cents;\n}\n\npublic static class Uses\n{\n    public static string currencies() => Priced.CURRENCY + Book.CURRENCY;\n\n    public static bool cheaper(Priced a, Priced b) => a < b;\n\n    public static int books() => new Book(1) <=> new Book(2);\n\n    public static bool rares() => new Rare(1) >= new Rare(2);\n\n    public static string label() => new Book(1).label;\n\n    public static bool unpriced(Priced a) => a < 3;\n}\n";

    assert_eq!(issues(("src/App/Priced.sharp", sharp), &[]), ["36:46 invalid-operand"]);
}

/// Spec section 19: an operator is chosen from the static types of both operands, as C# chooses one. Of the operators
/// the two types and their interfaces declare, the most specific one that takes both runs: `Priced`'s for a `Rare` and
/// a `Book`, in either order, for a `Rare` and a `Priced`, for two `Book`s when `Book`'s own takes a `Book` and an
/// `int`, for a union of implementers and for an enum that gets it from its interface. Two that take the operands with
/// neither more specific are one error at the use, which names the operator and both interfaces, and the operator it
/// says to declare wins over both.
#[test]
fn an_operator_is_chosen_from_the_types_of_both_operands() {
    let sharp = "namespace App;\n\npublic interface Priced\n{\n    int cents { get; }\n    static int operator <=>(Priced a, Priced b) => a.cents <=> b.cents;\n}\n\npublic class Book : Priced\n{\n    public int cents { get; }\n    public Book(int cents) { this.cents = cents; }\n    public static int operator <=>(Book a, int b) => a.cents <=> b;\n}\n\npublic class Rare : Priced\n{\n    public int cents { get; }\n    public Rare(int cents) { this.cents = cents; }\n    public static int operator <=>(Rare a, Rare b) => b.cents <=> a.cents;\n}\n\npublic enum Coin : int, Priced\n{\n    case Penny = 1;\n    case Dime = 10;\n\n    public int cents => this.value;\n}\n\npublic static class Uses\n{\n    public static bool rareFirst(Rare r, Book b) => r < b;\n\n    public static int againstPriced(Rare r, Priced p) => r <=> p;\n\n    public static bool books(Book a, Book b) => a < b;\n\n    public static bool bookAgainstInt(Book a) => a < 3;\n\n    public static List<int> union() => [new Book(1), new Rare(2)].sortedBy(item => item).map(item => item.cents);\n\n    public static bool coins() => Coin.Penny < Coin.Dime;\n}\n";
    let tied = "namespace App;\n\npublic interface Weighed\n{\n    int grams { get; }\n    int hash();\n    static bool operator ==(Weighed a, Weighed b) => a.grams == b.grams;\n}\n\npublic interface Valued\n{\n    int cents { get; }\n    int hash();\n    static bool operator ==(Valued a, Valued b) => a.cents == b.cents;\n}\n\npublic class Parcel : Valued, Weighed\n{\n    public int cents => 1;\n    public int grams => 2;\n    public int hash() => 0;\n}\n\npublic static class Uses\n{\n    public static bool same(Parcel a, Parcel b) => a == b;\n\n    public static bool asWeighed(Weighed a, Weighed b) => a == b;\n}\n";
    let advised = "namespace App;\n\npublic interface Weighed\n{\n    int grams { get; }\n    int hash();\n    static bool operator ==(Weighed a, Weighed b) => a.grams == b.grams;\n}\n\npublic interface Valued\n{\n    int cents { get; }\n    int hash();\n    static bool operator ==(Valued a, Valued b) => a.cents == b.cents;\n}\n\npublic class Parcel : Valued, Weighed\n{\n    public int cents => 1;\n    public int grams => 2;\n    public int hash() => 0;\n\n    public static bool operator ==(Parcel a, Parcel b)\n    {\n        readonly Weighed x = a;\n        readonly Weighed y = b;\n        return x == y;\n    }\n}\n\npublic static class Uses\n{\n    public static bool same(Parcel a, Parcel b) => a == b;\n}\n";

    assert_eq!(issues(("src/App/Priced.sharp", sharp), &[]), Vec::<String>::new());
    assert_eq!(
        worded(("src/App/Weighed.sharp", tied), &[]),
        [
            "26:52 invalid-operand `==` on `Parcel` and `Parcel` is ambiguous: `Valued` and `Weighed` each declare an `operator ==` that takes them. | Applied here. | An operator is chosen from the types of its operands, and the most specific one runs. | Declare `public static bool operator ==(Parcel a, Parcel b)` in `Parcel`, which wins over each of them."
        ]
    );
    assert_eq!(issues(("src/App/Weighed.sharp", advised), &[]), Vec::<String>::new());
}

/// Spec section 19: two interfaces that each declare an operator for a class tie on every use that takes the class on
/// both sides: `<`, `+`, `sortedBy` and `contains`, each one error that names the operator and both interfaces. A
/// `Set` of the class, a `Map` keyed by it and a struct that holds it in a `Set` are refused too, since they compare
/// two of it by `==`. An operand of a class the codebase does not hold declares no operator.
#[test]
fn every_use_of_two_tied_operators_is_one_error() {
    let sharp = "namespace App;\n\npublic interface Weighed\n{\n    int grams { get; }\n    int hash();\n    static bool operator ==(Weighed a, Weighed b) => a.grams == b.grams;\n    static int operator <=>(Weighed a, Weighed b) => a.grams <=> b.grams;\n    static readonly Weighed operator +(Weighed a, Weighed b) => a;\n}\n\npublic interface Valued\n{\n    int cents { get; }\n    int hash();\n    static bool operator ==(Valued a, Valued b) => a.cents == b.cents;\n    static int operator <=>(Valued a, Valued b) => a.cents <=> b.cents;\n    static readonly Valued operator +(Valued a, Valued b) => a;\n}\n\npublic class Parcel : Valued, Weighed\n{\n    public int cents => 1;\n    public int grams => 2;\n    public int hash() => 0;\n}\n\npublic static class Uses\n{\n    public static bool lighter(Parcel a, Parcel b) => a < b;\n\n    public static readonly Parcel sum(Parcel a, Parcel b) => a + b;\n\n    public static List<Parcel> sorted(List<Parcel> parcels) => parcels.sortedBy(parcel => parcel);\n\n    public static bool held(List<Parcel> parcels, Parcel parcel) => parcels.contains(parcel);\n}\n";
    let missing = "namespace App;\n\npublic static class Uses\n{\n    public static bool lighter(Missing a, Missing b) => a < b;\n}\n";
    let held = "namespace App;\n\npublic struct Shipment\n{\n    public Parcel parcel { get; init; }\n}\n\npublic static class Held\n{\n    public static int shipments(Set<Shipment> held) => held.count();\n\n    public static int parcels(Set<Parcel> held) => held.count();\n\n    public static int keys(Map<Parcel, int> held) => held.count();\n}\n";

    assert_eq!(
        messages(("src/App/Weighed.sharp", sharp), &[]),
        [
            "`<` on `Parcel` and `Parcel` is ambiguous: `Valued` and `Weighed` each declare an `operator <=>` that takes them.",
            "`+` on `Parcel` and `Parcel` is ambiguous: `Valued` and `Weighed` each declare an `operator +` that takes them.",
            "`<=>` on `Parcel` and `Parcel` is ambiguous: `Valued` and `Weighed` each declare an `operator <=>` that takes them.",
            "`==` on `Parcel` and `Parcel` is ambiguous: `Valued` and `Weighed` each declare an `operator ==` that takes them.",
        ]
    );
    assert_eq!(
        issues(("src/App/Uses.sharp", missing), &[]),
        ["5:32 non-existent-class-like", "5:43 non-existent-class-like"]
    );
    assert_eq!(
        messages(("src/App/Shipment.sharp", held), &[("src/App/Weighed.sharp", sharp)]),
        [
            "`Shipment` can't be in a `Set`: `parcel` is a `Parcel`, a class, and a `Set` holds only values.",
            "`==` on `Parcel` and `Parcel` is ambiguous: `Valued` and `Weighed` each declare an `operator ==` that takes them.",
            "`==` on `Parcel` and `Parcel` is ambiguous: `Valued` and `Weighed` each declare an `operator ==` that takes them.",
        ]
    );
}

/// Spec section 22: a constant that implements an interface's is public, as each interface member is, and an
/// interface that declares `operator ==` states its `hash()` bare.
#[test]
fn an_interface_constant_is_implemented_public_and_its_hash_is_stated_bare() {
    let sharp = "namespace App;\n\npublic interface Priced\n{\n    const string CURRENCY = \"USD\";\n    int cents { get; }\n    static bool operator ==(Priced a, Priced b) => a.cents == b.cents;\n}\n\npublic class Euro : Priced\n{\n    const string CURRENCY = \"EUR\";\n    public int cents => 1;\n}\n";

    assert_eq!(
        messages(("src/App/Priced.sharp", sharp), &[]),
        [
            "`Priced` declares `operator ==` without `int hash()`: declare it in `Priced` or a parent, so equal values hash alike.",
            "`CURRENCY` implements `Priced.CURRENCY`, so it is written `public const`.",
        ]
    );
}

/// Spec section 19: an enum that declares `operator <=>` orders its cases by it, as a class does, and its operator
/// takes only its own cases.
#[test]
fn an_enum_that_declares_comparison_orders_its_cases() {
    let sharp = "namespace App;\n\npublic enum Size : int\n{\n    case Small = 1;\n    case Large = 3;\n\n    public static int operator <=>(Size a, Size b) => a.value <=> b.value;\n}\n\npublic enum Mood\n{\n    case Calm;\n}\n\npublic static class Uses\n{\n    public static bool smaller() => Size.Small < Size.Large;\n\n    public static int order(Size a, Size b) => a <=> b;\n\n    public static bool calmer() => Mood.Calm < Mood.Calm;\n\n    public static bool mixed() => Size.Small < 1;\n}\n";

    assert_eq!(issues(("src/App/Size.sharp", sharp), &[]), ["22:36 invalid-operand", "24:35 invalid-operand"]);
}

/// Spec section 22: a generic interface's default bodies read the type arguments each class gives the interface, in its
/// header or through an interface that extends it, as a class's own methods do.
#[test]
fn a_generic_interface_gives_each_class_its_default_bodies_with_its_type_arguments() {
    let sharp = "namespace Demo;\n\npublic interface Keyed<TKey>\n{\n    TKey key();\n\n    List<TKey> keys() => [this.key()];\n\n    TKey first() => this.keys()[0];\n}\n\npublic interface Named<TName> : Keyed<TName>\n{\n}\n\npublic class Order : Keyed<int>\n{\n    public int key() => 7;\n}\n\npublic class Tag : Named<string>\n{\n    public string key() => \"seven\";\n}\n\npublic static class Uses\n{\n    public static List<int> orderKeys() => new Order().keys();\n\n    public static string tagFirst() => new Tag().first();\n\n    public static string wrong() => new Order().first();\n}\n";

    assert_eq!(issues(("src/Demo/Keyed.sharp", sharp), &[]), ["32:37 invalid-return-statement"]);

    // A default body reads the interface's type parameters while the code runs, as the class gives them.
    let reads = "namespace Demo;\n\npublic class Box<TValue>\n{\n    public TValue? value = null;\n}\n\npublic interface Held<TItem>\n{\n    bool holds(Any value) => value is TItem;\n\n    Box<TItem> boxed() => new Box<TItem>();\n}\n";
    assert_eq!(messages(("src/Demo/Held.sharp", reads), &[]), Vec::<String>::new());
}

/// Spec section 22: a PHP# enum implements a plain PHP interface that extends `BackedEnum`. The engine writes the
/// enum's `from` and `tryFrom`, which take `int|string` as PHP's own do, so neither is checked against `BackedEnum`'s.
#[test]
fn a_backed_enum_implements_a_plain_php_interface_that_extends_backed_enum() {
    let library = "<?php\n\nnamespace Lib;\n\ninterface Aligned extends \\BackedEnum\n{\n    public function label(): string;\n}\n";
    let sharp = "namespace Demo;\n\nimport Lib.Aligned;\n\npublic enum Align : string, Aligned\n{\n    case Left = \"left\";\n    case Right = \"right\";\n\n    public string label() => \"align\";\n}\n\npublic enum Level : int, Aligned\n{\n    case Low = 1;\n\n    public string label() => \"level\";\n}\n";

    assert_eq!(issues(("src/Demo/Align.sharp", sharp), &[("src/Lib/Aligned.php", library)]), Vec::<String>::new());
}

/// Spec section 22: implementing an abstract interface method takes no `override`, as the spec's `Page` implements
/// `HasDesign`, and replacing a default body or a header trait's method replaces a method, so it takes `override`, as
/// replacing a computed property's default body does.
#[test]
fn override_replaces_a_default_body_or_a_trait_method_and_never_marks_an_implementation() {
    let sharp = "namespace Demo;\n\nimport Lib.HasTitle;\n\npublic interface Labeled\n{\n    string label();\n    string shout() => \"hey\";\n}\n\npublic class Implementer : Labeled\n{\n    public override string label() => \"x\";\n}\n\npublic class Replacer : Labeled\n{\n    public string label() => \"x\";\n    public string shout() => \"mine\";\n}\n\npublic class Fine : Labeled\n{\n    public string label() => \"x\";\n    public override string shout() => \"mine\";\n}\n\npublic class TraitReplacer : HasTitle\n{\n    public string describe() => \"mine\";\n}\n\npublic class TraitOverrider : HasTitle\n{\n    public override string describe() => \"mine\";\n}\n\npublic interface Tagged\n{\n    string tag => \"t\";\n}\n\npublic class TagReplacer : Tagged\n{\n    public string tag => \"mine\";\n}\n\npublic class TagOverrider : Tagged\n{\n    public override string tag => \"mine\";\n}\n";
    let others = [("src/Lib/HasLabel.php", HAS_LABEL)];

    assert_eq!(
        issues(("src/Demo/Labeled.sharp", sharp), &others),
        [
            "13:12 invalid-override-attribute",
            "19:19 missing-override-attribute",
            "30:19 missing-override-attribute",
            "45:19 missing-override-attribute"
        ]
    );
    assert_eq!(
        messages(("src/Demo/Labeled.sharp", sharp), &others)[0],
        "`Implementer.label` implements `Labeled.label`, which takes no `override`."
    );
}

/// `super.m()` calls the parent's body, spec section 22, so a parent's abstract method, PHP# or plain PHP, has none to
/// call, and PHP would throw `Error` at runtime.
#[test]
fn super_of_an_abstract_method_is_an_error() {
    let sharp = "namespace Demo;\n\nimport Lib.Report;\n\npublic abstract class Shape\n{\n    public abstract string draw();\n    public virtual string name() => \"shape\";\n}\n\npublic class Square : Shape\n{\n    public override string draw() => super.draw();\n    public override string name() => super.name();\n}\n\npublic class Sales : Report\n{\n    protected override string render() => super.render();\n}\n";
    let library =
        "<?php\n\nnamespace Lib;\n\nabstract class Report\n{\n    abstract protected function render(): string;\n}\n";

    assert_eq!(
        messages(("src/Demo/Shape.sharp", sharp), &[("src/Lib/Report.php", library)]),
        [
            "`Shape.draw` is abstract, so `super.draw()` has no body to run.",
            "`Report.render` is abstract, so `super.render()` has no body to run.",
        ]
    );
}

/// Replacing a closed PHP# method names `virtual`, which the parent leaves out, not `final`, which nobody wrote, and a
/// header with two classes says so, spec section 22.
#[test]
fn a_closed_method_and_a_header_with_two_classes_speak_sharp() {
    let sharp = "namespace Demo;\n\nimport Lib.Other;\n\npublic class Base\n{\n    public string save() => \"saved\";\n}\n\npublic class Child : Base\n{\n    public override string save() => \"child\";\n}\n\npublic class Quiet : Base\n{\n    public string save() => \"quiet\";\n}\n\npublic class Twice : Base, Other\n{\n}\n";
    let library = "<?php\n\nnamespace Lib;\n\nclass Other\n{\n}\n";

    assert_eq!(
        messages(("src/Demo/Base.sharp", sharp), &[("src/Lib/Other.php", library)]),
        [
            "`Base.save` is not `virtual`, so no subclass replaces it.",
            "`Base.save` is not `virtual`, so no subclass replaces it.",
            "`Twice` names two base classes, `Base` and `Other`.",
        ]
    );
}

/// Spec section 22 gives a class one method per name: when two places give the class a body for one method, two
/// header traits, two interfaces' default bodies, or a default body beside the base class's method, the class writes
/// the method itself. Until it does, the class is an error that names both places. A computed property two interfaces
/// give a default body, or one interface beside the base class's property, is one too.
#[test]
fn a_class_that_gets_one_method_from_two_places_writes_it() {
    let sharp = "namespace Demo;\n\nimport Lib.HasLabel;\nimport Lib.HasTitle;\n\npublic class Twice : HasLabel, HasTitle\n{\n}\n\npublic interface Described\n{\n    string describe() => \"described\";\n}\n\npublic interface Told\n{\n    string describe() => \"told\";\n}\n\npublic class Both : Described, Told\n{\n}\n\npublic class Base\n{\n    public virtual string describe() => \"base\";\n}\n\npublic class Beside : Base, Described\n{\n}\n\npublic class Written : Described, Told\n{\n    public override string describe() => \"written\";\n}\n\npublic class WrittenOverBase : Base, Described\n{\n    public override string describe() => super.describe();\n}\n\npublic interface Tagged\n{\n    string tag => \"t\";\n}\n\npublic interface Labelled\n{\n    string tag => \"l\";\n}\n\npublic class Tags : Tagged, Labelled\n{\n}\n\npublic class TagBase\n{\n    public string tag => \"base\";\n}\n\npublic class TagBeside : TagBase, Tagged\n{\n}\n";
    let others = [("src/Lib/HasLabel.php", HAS_LABEL)];

    assert_eq!(
        issues(("src/Demo/Twice.sharp", sharp), &others),
        [
            "6:14 ambiguous-inherited-member",
            "20:14 ambiguous-inherited-member",
            "29:14 ambiguous-inherited-member",
            "53:14 ambiguous-inherited-member",
            "62:14 ambiguous-inherited-member"
        ]
    );
    assert_eq!(
        messages(("src/Demo/Twice.sharp", sharp), &others),
        [
            "`Twice` gets `describe` from both `HasLabel` and `HasTitle`: write `describe` in `Twice`.",
            "`Both` gets `describe` from both `Described` and `Told`: write `describe` in `Both`.",
            "`Beside` gets `describe` from both `Base` and `Described`: write `describe` in `Beside`.",
            "`Tags` gets `tag` from both `Labelled` and `Tagged`: write `tag` in `Tags`.",
            "`TagBeside` gets `tag` from both `TagBase` and `Tagged`: write `tag` in `TagBeside`.",
        ]
    );

    // A header trait replaces the base class's method, as PHP's `use` does, and Laravel's `SoftDeletes` and
    // `HasUniqueStringIds` replace `Model`'s. A header trait's property beside a default body is two places.
    let library = "<?php\n\nnamespace Lib;\n\nabstract class Model\n{\n    public function forceDelete() { return 'model force'; }\n    protected function performDeleteOnModel() { return 'model delete'; }\n    public function getKeyType() { return 'int'; }\n    public function getIncrementing() { return true; }\n}\n\ntrait SoftDeletes\n{\n    public function forceDelete() { return 'soft force'; }\n    protected function performDeleteOnModel() { return 'soft delete'; }\n}\n\ntrait HasUniqueStringIds\n{\n    public function getKeyType() { return 'string'; }\n    public function getIncrementing() { return false; }\n}\n\ntrait HasTag\n{\n    public string $tag = 'trait tag';\n}\n";
    let laravel = "namespace Demo;\n\nimport Lib.HasTag;\nimport Lib.HasUniqueStringIds;\nimport Lib.Model;\nimport Lib.SoftDeletes;\n\npublic class Post : Model, SoftDeletes, HasUniqueStringIds\n{\n}\n\npublic interface Labelled\n{\n    string tag => \"interface tag\";\n}\n\npublic class TagClash : HasTag, Labelled\n{\n}\n";
    let library = [("src/Lib/Model.php", library)];

    assert_eq!(
        messages(("src/Demo/Post.sharp", laravel), &library),
        ["`TagClash` gets `tag` from both `Labelled` and `HasTag`: write `tag` in `TagClash`."]
    );
}

/// Spec section 22: a sub-interface replaces its parent's default body with `override`, as a class replaces a method,
/// and the most specific interface's body wins, as in Java, C# and Kotlin. Giving an abstract parent method a body takes
/// no `override`.
#[test]
fn a_sub_interface_replaces_its_parents_default_body_with_override() {
    let sharp = "namespace Demo;\n\npublic interface Shows\n{\n    string label() => \"shows\";\n}\n\npublic interface ShowsMore : Shows\n{\n    override string label() => \"more\";\n}\n\npublic interface ShowsLess : Shows\n{\n    string label() => \"less\";\n}\n\npublic interface Named\n{\n    string name();\n}\n\npublic interface DefaultNamed : Named\n{\n    string name() => \"default\";\n}\n\npublic class Fancy : ShowsMore\n{\n    public string again() => super<Shows>.label() + super<ShowsMore>.label();\n}\n\npublic class Listed : ShowsMore, Shows\n{\n}\n\npublic class Person : DefaultNamed\n{\n}\n\npublic static class Uses\n{\n    public static string fancy() => new Fancy().label();\n}\n";

    assert_eq!(issues(("src/Demo/Shows.sharp", sharp), &[]), ["15:12 missing-override-attribute"]);
}

/// Spec section 22: PHP# code never names an interface's trait of default bodies, so an import, a header and a test
/// that name `Greets.Defaults` are each an error.
#[test]
fn sharp_code_never_names_the_trait_of_default_bodies() {
    let sharp = "namespace Probe;\n\nimport Probe.Greets.Defaults;\n\npublic interface Greets\n{\n    string greet() => \"hello\";\n}\n\npublic class Sneaky : Defaults\n{\n    public static bool marked(Any value) => value is Defaults;\n}\n";

    assert_eq!(
        issues(("src/Probe/Greets.sharp", sharp), &[]),
        ["3:8 invalid-trait-use", "10:23 invalid-trait-use", "12:54 invalid-trait-use"]
    );
    assert_eq!(
        messages(("src/Probe/Greets.sharp", sharp), &[])[0],
        "`Greets.Defaults` holds the default bodies of `Greets`, which PHP# code never names: implement `Greets`."
    );
}

/// Spec sections 22 and 31: an enum takes an interface's default bodies as a class does, its computed properties as
/// well as its methods, whether it is a plain enum, a backed enum or an enum whose cases carry data.
#[test]
fn an_enum_gets_a_computed_property_from_a_default_body() {
    let sharp = "namespace Demo;\n\npublic interface Tagged\n{\n    string code { get; }\n\n    string tag => `tag ${this.code}`;\n\n    string label() => \"l\";\n}\n\npublic enum Mood : Tagged\n{\n    case Calm;\n\n    public string code => \"calm\";\n}\n\npublic enum Kind : string, Tagged\n{\n    case Big = \"big\";\n\n    public string code => \"big\";\n}\n\npublic enum Verdict : Tagged\n{\n    case Pending;\n    case Ruled(string by);\n\n    public string code => \"verdict\";\n}\n\npublic class Reads\n{\n    public string mood() => Mood.Calm.tag;\n\n    public string kind() => Kind.Big.tag;\n\n    public string verdict() => Verdict.Ruled(\"judge\").tag;\n\n    public int wrong() => Mood.Calm.tag;\n}\n";

    assert_eq!(
        messages(("src/Demo/Tagged.sharp", sharp), &[]),
        ["Invalid return type for method `Reads.wrong`: expected `int`, but found `string`."]
    );
}

/// Spec section 22: `super.name()` and `super<Told>.describe()` run a method on `this`, so a static method, which has
/// no `this`, calls neither, and a static `super.make()` still runs the base class's static method.
#[test]
fn a_static_method_calls_no_instance_method_through_super() {
    let sharp = "namespace Demo;\n\npublic interface Told\n{\n    string describe() => \"told\";\n}\n\npublic class Ancestor\n{\n    public virtual string name() => \"parent\";\n\n    public static string make() => \"made\";\n}\n\npublic class Heir : Ancestor, Told\n{\n    public static string again() => super.name();\n\n    public static string told() => super<Told>.describe();\n\n    public static string remake() => super.make();\n}\n";

    assert_eq!(
        messages(("src/Demo/Heir.sharp", sharp), &[]),
        [
            "`Ancestor.name` runs on `this`, and a static method has no `this`.",
            "`Told.describe` runs on `this`, and a static method has no `this`.",
        ]
    );
}

/// Spec section 22: inside its own methods, a class reuses one interface's default body with `super<HasLabel>`. It is
/// an error when the class does not implement the interface, when the interface gives the method no default body, and
/// outside a class. A subclass of a PHP# class that implements the interface reuses it too, and a subclass of a plain
/// PHP one can't, since only a PHP# class keeps each default body under a name its subclasses call. `super<Told>` as a
/// value is the semantics checker's error, and the analysis adds none.
#[test]
fn super_of_an_interface_reuses_its_default_body_in_a_class_that_implements_it() {
    let library =
        "<?php\n\nnamespace Lib;\n\nclass Legacy implements \\Demo\\Told\n{\n    use \\Demo\\Told\\Defaults;\n}\n";
    let sharp = "namespace Demo;\n\nimport Lib.Legacy;\n\npublic interface Described\n{\n    string describe() => \"described\";\n    string title();\n    string shout() => super<Told>.describe();\n}\n\npublic interface Told\n{\n    string describe() => \"told\";\n}\n\npublic class Both : Described, Told\n{\n    public override string describe() => super<Described>.describe() + super<Told>.describe();\n    public string title() => super<Described>.title();\n}\n\npublic class Stranger\n{\n    public string describe() => super<Told>.describe();\n}\n\npublic class Base : Told\n{\n}\n\npublic class Child : Base\n{\n    public string again() => super<Told>.describe();\n}\n\npublic class Heir : Legacy\n{\n    public string again() => super<Told>.describe();\n}\n\npublic class Holder : Told\n{\n    public Any? held() => super<Told>;\n}\n";
    let others = [("src/Lib/Legacy.php", library)];

    assert_eq!(
        messages(("src/Demo/Described.sharp", sharp), &others),
        [
            "`super<Told>` reuses a default body only in the methods of a class that implements `Told`.",
            "`Described.title` has no default body, so `super<Described>.title()` has nothing to run.",
            "`Stranger` does not implement `Told`, so `super<Told>` has no default body to reuse.",
            "`super<Told>` reuses a default body a PHP# class keeps, and `Legacy`, which implements `Told`, is plain PHP.",
        ]
    );
    assert_eq!(
        issues(("src/Demo/Described.sharp", sharp), &others),
        [
            "9:23 parent-outside-class-scope",
            "20:30 abstract-super-call",
            "25:33 invalid-parent-type",
            "39:30 invalid-parent-type",
        ]
    );
}

/// Spec section 21: an arm that binds a data case's fields, as `ChargeError.Declined(string reason)`, tests the case and
/// binds each field, whose test is always true, so it reports no redundant `&&`.
#[test]
fn a_data_case_arm_that_binds_its_fields_reports_no_redundant_test() {
    let code = "namespace App;\n\npublic enum ChargeError\n{\n    case Declined(string reason);\n    case Timeout;\n\n    public string message => match (this) {\n        ChargeError.Declined(string reason) => `declined: ${reason}`,\n        ChargeError.Timeout => \"timeout\",\n    };\n\n    public string explain(ChargeError failure) => match (failure) {\n        ChargeError.Declined(string reason) => reason,\n        ChargeError.Timeout => \"timeout\",\n    };\n\n    public bool declined => this is ChargeError.Declined(string reason) && reason != \"\";\n}\n";

    assert_eq!(issues(("src/App/ChargeError.sharp", code), &[]), Vec::<String>::new());
}

/// Spec section 23: a constant of the standard library whose value reads a plain PHP constant through `global.`, as
/// `Int.MAX` does, has that constant's type.
#[test]
fn a_constant_read_from_a_plain_php_constant_has_its_type() {
    let code = "namespace Sharp;\n\npublic class Limits\n{\n    public const int TOP = global.PHP_INT_MAX;\n\n    public static int top() => Limits.TOP;\n}\n";

    assert_eq!(
        issues(("vendor/heyjordanparker/php-sharp-composer/library/Sharp/Limits.sharp", code), &[]),
        Vec::<String>::new()
    );
}

/// Spec section 2: a lambda constant reads as the function type it declares, so its call gives the type that function
/// returns, and a plain case of an enum whose other cases carry data is a constant's value, as any case is.
#[test]
fn a_lambda_constant_has_its_function_type_and_a_constant_holds_a_plain_case_of_a_data_enum() {
    let code = "namespace App;\n\npublic enum Tier\n{\n    case Free;\n    case Seats(int count);\n}\n\npublic class Billing\n{\n    public const Function<int(int)> DOUBLE = (int x) => x * 2;\n    public const Tier DEFAULT_TIER = Tier.Free;\n\n    public static int doubled(int value) => (Billing.DOUBLE)(value);\n\n    public static string wrong() => (Billing.DOUBLE)(\"x\");\n\n    public static bool free() => Billing.DEFAULT_TIER == Tier.Free;\n}\n";

    assert_eq!(
        issues(("src/App/Billing.sharp", code), &[]),
        ["16:54 invalid-argument", "16:37 invalid-return-statement"]
    );
}

/// Spec section 2: a constant's value is known before the code runs, so a constant whose value reads its way back to
/// it, through constants of its class or of another, is an error that names the constants on the way. A lambda reads
/// a constant only when it is called.
#[test]
fn a_constant_whose_value_reads_back_to_it_is_an_error_that_names_the_cycle() {
    let code = "namespace App;\n\npublic class Loop\n{\n    public const string A = `a${Loop.B}`;\n    public const string B = `b${Loop.A}`;\n    public const int C = Loop.D + 1;\n    public const int D = Loop.C + 1;\n    public const int E = Loop.E + 1;\n    public const int F = Other.G * 2;\n    public const int TOP = Loop.F + Loop.H;\n    public const int H = 1;\n    public const Function<int()> LATER = () => Loop.LATER_VALUE;\n    public const int LATER_VALUE = (Loop.LATER)();\n    public const int P = Loop.Q;\n    public const int Q = Loop.R;\n    public const int R = Loop.P;\n}\n";
    let other = "namespace App;\n\npublic class Other\n{\n    public const int G = Loop.F + 1;\n}\n";

    assert_eq!(
        messages(("src/App/Loop.sharp", code), &[("src/App/Other.sharp", other)]),
        [
            "`Loop.A` refers back to itself through `Loop.B`.",
            "`Loop.B` refers back to itself through `Loop.A`.",
            "`Loop.C` refers back to itself through `Loop.D`.",
            "`Loop.D` refers back to itself through `Loop.C`.",
            "`Loop.E` refers back to itself.",
            "`Loop.F` refers back to itself through `Other.G`.",
            "`Loop.P` refers back to itself through `Loop.Q` and `Loop.R`.",
            "`Loop.Q` refers back to itself through `Loop.R` and `Loop.P`.",
            "`Loop.R` refers back to itself through `Loop.P` and `Loop.Q`.",
        ]
    );
}

/// Spec section 2: a backed case's value is a constant value too, and reading the case reads its value, so a case
/// whose value reads its way back to it through a constant, or a constant that reads its way back through a case, is
/// the same error that names the reads on the way.
#[test]
fn a_backed_case_whose_value_reads_back_to_it_is_an_error_that_names_the_cycle() {
    let code = "namespace App;\n\npublic enum Code : string\n{\n    case A = `a-${Keys.KEY}`;\n    case B = Code.SELF_KEY;\n    case C = \"c\";\n\n    public const string SELF_KEY = Code.B.value;\n    public const string C_KEY = Code.C.value;\n}\n";
    let keys = "namespace App;\n\npublic class Keys\n{\n    public const string KEY = Code.A.value;\n}\n";

    assert_eq!(
        messages(("src/App/Code.sharp", code), &[("src/App/Keys.sharp", keys)]),
        [
            "`Code.A` refers back to itself through `Keys.KEY`.",
            "`Code.B` refers back to itself through `Code.SELF_KEY`.",
            "`Code.SELF_KEY` refers back to itself through `Code.B`.",
        ]
    );
    assert_eq!(
        messages(("src/App/Keys.sharp", keys), &[("src/App/Code.sharp", code)]),
        ["`Keys.KEY` refers back to itself through `Code.A`."]
    );
}

/// Spec section 19: a function has no `==`, so a pattern compares no function, whether it names a function constant,
/// as `is Ops.DOUBLE` and a `match` arm `Ops.DOUBLE`, or writes a lambda, with a parameter or without, and whatever the
/// value it tests, an unchecked `Any?` included. Each is the error `is == Ops.DOUBLE` gives.
#[test]
fn a_pattern_that_compares_a_function_is_an_error_as_its_equality_is() {
    let code = "namespace App;\n\npublic class Ops\n{\n    public const Function<int(int)> DOUBLE = (int x) => x * 2;\n\n    public static bool named(Function<int(int)> f) => f is Ops.DOUBLE;\n\n    public static bool compared(Function<int(int)> f) => f is == Ops.DOUBLE;\n\n    public static string arm(Function<int(int)> f) => match (f) {\n        Ops.DOUBLE => \"double\",\n        default => \"other\",\n    };\n\n    public static string withParameter(Function<int(int)> f) => match (f) {\n        == ((int x) => x) => \"same\",\n        default => \"other\",\n    };\n\n    public static string unchecked(Any? f) => match (f) {\n        == (() => 1) => \"one\",\n        default => \"other\",\n    };\n\n    public static bool none(Function<int(int)>? f) => f is null;\n}\n";
    let refusal = |function: &str, other: &str| {
        format!("`==` cannot compare `{function}` with `{other}`: `{other}` declares no `operator ==`.")
    };

    assert_eq!(
        messages(("src/App/Ops.sharp", code), &[]),
        [
            refusal("Function<int(int)>", "Function<int(int)>"),
            refusal("Function<int(int)>", "Function<int(int)>"),
            refusal("Function<int(int)>", "Function<int(int)>"),
            refusal("Function<int(int)>", "Function<int(int)>"),
            refusal("Any?", "Function<1()>"),
        ]
    );
}

/// Spec section 2: a constant's value is known before the code runs, so an index outside the list a constant holds is
/// an error that names the index and the list's size, in a constant's value, a template of one and a pattern's value. A
/// method body's index runs, and throws `OutOfRangeException` when it misses.
#[test]
fn an_index_outside_a_constant_list_in_a_constant_value_is_an_error_that_names_the_size() {
    let code = "namespace App;\n\npublic class Billing\n{\n    public const List<string> PLANS = [\"free\", \"pro\"];\n    public const string SECOND = Billing.PLANS[1];\n    public const string MISSING = Billing.PLANS[5];\n    public const string MISSING_IN_TEMPLATE = `${Billing.PLANS[2]}`;\n    public const List<string> NONE = [];\n    public const string NONE_FIRST = Billing.NONE[0];\n\n    public static bool first(string plan) => plan is == Billing.PLANS[3];\n\n    public static string body() => Billing.PLANS[5];\n}\n";

    assert_eq!(
        messages(("src/App/Billing.sharp", code), &[]),
        [
            "`Billing.PLANS` holds 2 elements, so it has no index 5.",
            "`Billing.PLANS` holds 2 elements, so it has no index 2.",
            "`Billing.NONE` holds 0 elements, so it has no index 0.",
            "`Billing.PLANS` holds 2 elements, so it has no index 3.",
        ]
    );
}

/// Spec section 2: a template in a constant value shows `string`, `int`, `float` and `bool` constants, and one that
/// shows an object runs its `toString()`, so it is an error in a constant's value, an enum case's value, an attribute
/// argument and a pattern's value. A lambda's body runs when it is called, and a method's template as it runs.
#[test]
fn a_template_in_a_constant_value_that_shows_an_object_is_an_error_that_names_the_part() {
    let tier = "namespace App;\n\npublic enum Tier\n{\n    case Free;\n    case Seats(int count);\n\n    public string toString() => \"tier\";\n}\n";
    let code = "namespace App;\n\nimport Lib.Route;\n\npublic class Labels\n{\n    public const string TIER_LABEL = `tier: ${Tier.Free}`;\n    public const string SHOWN = `${1} ${1.5} ${true} ${Labels.TIER_LABEL}`;\n    public const Function<string()> LATER = () => `${Tier.Free}`;\n\n    public static bool pattern(string text) => text is == `${Tier.Free}`;\n\n    [Route(`/${Tier.Free}`)]\n    public static string page() => `${Tier.Free}`;\n}\n";
    let r#enum = "namespace App;\n\npublic enum Kind : string\n{\n    case Tiered = `${Tier.Free}-kind`;\n}\n";
    let route = (
        "src/Lib/Route.php",
        "<?php\n\nnamespace Lib;\n\n#[\\Attribute]\nfinal class Route\n{\n    public function __construct(public string $path) {}\n}\n",
    );
    let message = |part: &str, instead: &str| {
        format!("A constant's value is known before the code runs, and `{part}` runs `toString()`: {instead}")
    };

    assert_eq!(
        messages(("src/App/Labels.sharp", code), &[("src/App/Tier.sharp", tier), route]),
        [
            message("${Tier.Free}", "use a static field."),
            message("${Tier.Free}", "compare with it in `when`."),
            message("${Tier.Free}", "use a static field."),
        ]
    );
    assert_eq!(
        messages(("src/App/Kind.sharp", r#enum), &[("src/App/Tier.sharp", tier)]),
        [message("${Tier.Free}", "use a static field.")]
    );
}

/// Spec section 22: a call of a default body names the method by its interface, which PHP# code writes, and never by
/// the trait that holds the body.
#[test]
fn a_default_body_call_names_the_method_by_its_interface() {
    let sharp = "namespace Demo;\n\npublic interface HasLabel\n{\n    string label() => \"label\";\n    int size(int by) => by;\n}\n\npublic class Tag : HasLabel\n{\n    public string again() => super<HasLabel>.label(5);\n    public int measured(Tag tag) => tag.size(\"y\");\n}\n";

    assert_eq!(
        messages(("src/Demo/HasLabel.sharp", sharp), &[]),
        [
            "Too many arguments provided for method `HasLabel.label`.",
            "Invalid argument type for argument #1 of `HasLabel.size`: expected `int`, but found `string`.",
        ]
    );
}

/// A generic type in a header links its class by the name before its type arguments, so the class calls the base's
/// methods, a type argument the base has no template for is reported as `@extends` reports it, and a missing generic
/// base is reported where it is named.
#[test]
fn a_generic_type_in_a_header_links_its_class_by_its_name() {
    let library = "<?php\n\nnamespace Lib;\n\nabstract class Listing\n{\n    public function count(): int\n    {\n        return 0;\n    }\n}\n";
    let sharp = "namespace Demo;\n\nimport Lib.Listing;\n\npublic class OrderPage : Listing<Order>\n{\n    public int size()\n    {\n        return this.count();\n    }\n}\n\npublic class Lost : Missing<Order>\n{\n}\n";

    assert_eq!(
        issues(("src/Demo/OrderPage.sharp", sharp), &[("src/Lib/Listing.php", library)]),
        ["5:26 excess-template-parameter", "13:21 non-existent-class-like"]
    );
}

/// `List`, `Map` and `Class` are never classes, so the binder resolves no name for them, and a header that names one,
/// which `check_slice` refuses, links no parent.
#[test]
fn a_header_naming_a_built_in_generic_type_links_no_parent() {
    let sharp = "namespace Demo;\n\npublic class Lines : List<int>, Map<string, int>, Class<Lines>\n{\n}\n";

    assert_eq!(issues(("src/Demo/Lines.sharp", sharp), &[]), Vec::<String>::new());
}

/// A method is closed unless it is `virtual`, and `override` is required to replace one, spec section 22. So PHP#
/// reports what PHP reports for a `final` method and a missing or stray `#[\Override]`, without the
/// `check-missing-override` setting. Implementing an interface method takes no `override`.
#[test]
fn virtual_and_override_are_checked_as_final_and_the_override_attribute_in_php() {
    let library = "<?php\n\nnamespace Lib;\n\ninterface Named\n{\n    public function name(): string;\n}\n";
    let sharp = "namespace Demo;\n\nimport Lib.Named;\n\npublic class Base\n{\n    public virtual int size()\n    {\n        return 1;\n    }\n\n    public string label()\n    {\n        return \"base\";\n    }\n\n    public virtual int depth()\n    {\n        return 0;\n    }\n}\n\npublic class Child : Base, Named\n{\n    public int size()\n    {\n        return 2;\n    }\n\n    public override string label()\n    {\n        return \"child\";\n    }\n\n    public override int width()\n    {\n        return 3;\n    }\n\n    public final override int depth()\n    {\n        return 1;\n    }\n\n    public string name()\n    {\n        return \"child\";\n    }\n}\n\npublic class GrandChild : Child\n{\n    public override int depth()\n    {\n        return 2;\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nuse Lib\\Named;\n\nclass Base\n{\n    public function size(): int\n    {\n        return 1;\n    }\n\n    final public function label(): string\n    {\n        return \"base\";\n    }\n\n    public function depth(): int\n    {\n        return 0;\n    }\n}\n\nclass Child extends Base implements Named\n{\n    public function size(): int\n    {\n        return 2;\n    }\n\n    #[\\Override]\n    public function label(): string\n    {\n        return \"child\";\n    }\n\n    #[\\Override]\n    public function width(): int\n    {\n        return 3;\n    }\n\n    #[\\Override]\n    final public function depth(): int\n    {\n        return 1;\n    }\n\n    #[\\Override]\n    public function name(): string\n    {\n        return \"child\";\n    }\n}\n\nclass GrandChild extends Child\n{\n    #[\\Override]\n    public function depth(): int\n    {\n        return 2;\n    }\n}\n";
    let others = [("src/Lib/Named.php", library)];

    let sharp_issues = issues(("src/Demo/Base.sharp", sharp), &others);
    let php_issues =
        issues_with(Settings { check_missing_override: true, ..settings() }, ("src/Demo/Base.php", php), &others);

    assert_eq!(
        codes(&php_issues),
        ["override-final-method", "missing-override-attribute", "invalid-override-attribute", "override-final-method"],
        "{php_issues:?}"
    );
    assert_eq!(codes(&sharp_issues), codes(&php_issues), "{sharp_issues:?}");

    let missing = analyze(&PLUGIN_REGISTRY, settings(), ("src/Demo/Base.sharp", sharp), &others).remove(1);
    assert_eq!(missing.message, "Missing `override` modifier on overriding method `Child.size`.");
    assert_eq!(
        messages_with(Settings { check_missing_override: true, ..settings() }, ("src/Demo/Base.php", php), &others),
        [
            "Cannot override final method `Demo\\Base::label()`",
            "Missing `#[Override]` attribute on overriding method `Demo\\Child::size`.",
            "Invalid `#[Override]` attribute on `Demo\\Child::width`.",
            "Cannot override final method `Demo\\Child::depth()`",
        ]
    );
}

/// A plain PHP base class with untyped properties typed by `@var`, one declared in a trait, typed properties, and
/// attributes read and written through `getAttribute` and `setAttribute`.
const MODEL: &str = "<?php\n\nnamespace Lib;\n\ntrait HasTimestamps\n{\n    /** @var bool */\n    public $timestamps = true;\n}\n\nabstract class Model\n{\n    use HasTimestamps;\n\n    /** @var string|null */\n    protected $table;\n\n    /** @var array<int, string> */\n    protected $fillable = [];\n\n    protected $with = [];\n\n    protected int $perPage = 15;\n\n    protected array $appends = [];\n\n    private $secret = 'model';\n\n    /** @var array<string, mixed> */\n    private array $attributes = [];\n\n    public function getAttribute(string $key): mixed\n    {\n        return $this->attributes[$key] ?? null;\n    }\n\n    public function setAttribute(string $key, mixed $value): static\n    {\n        $this->attributes[$key] = $value;\n\n        return $this;\n    }\n}\n";

/// An override of a plain PHP parent's property writes a type that fits the parent's `@var`, or any type when the
/// parent has none, and the type of a typed parent, with the parent's access level, spec section 6.1.
#[test]
fn a_property_overrides_a_plain_php_property_with_a_type_that_fits_the_parent() {
    let sharp = "namespace Demo;\n\nimport Lib.Model;\n\npublic class Order : Model\n{\n    protected override string? table { get; set; } = \"orders\";\n    protected override List<string> fillable { get; set; } = [\"number\", \"total\"];\n    protected override List<string> with { get => field; set => field = value; } = [\"customer\"];\n    public override bool timestamps { get; set; } = false;\n    protected override int perPage { get; set => field = value > 0 ? value : 15; } = 20;\n    protected override List<string> appends { get; set; } = [];\n}\n";
    let others = [("src/Lib/Model.php", MODEL)];

    assert_eq!(issues(("src/Demo/Order.sharp", sharp), &others), Vec::<String>::new());
}

/// An override whose type does not fit the parent's, whose access level differs, that overrides nothing, or a property
/// or field that replaces a parent's property without `override`, is an error, spec section 6.1.
#[test]
fn an_override_that_does_not_match_the_plain_php_property_is_an_error() {
    let sharp = "namespace Demo;\n\nimport Lib.Model;\n\npublic class Order : Model\n{\n    public override List<string> fillable { get; set; } = [\"number\"];\n    protected override string? table { get; set; } = 5;\n    public override int timestamps { get; set; } = 0;\n    protected override string appends { get; set; } = \"\";\n    protected string with { get; set; } = \"customer\";\n    protected override string missing { get; set; } = \"none\";\n    protected override string secret { get; set; } = \"order\";\n    protected int perPage = 20;\n}\n";

    let issues =
        analyze(&PLUGIN_REGISTRY, settings(), ("src/Demo/Order.sharp", sharp), &[("src/Lib/Model.php", MODEL)]);
    let reported: Vec<(&str, &str)> =
        issues.iter().map(|issue| (issue.code.as_deref().unwrap_or("none"), issue.message.as_str())).collect();

    for expected in [
        (
            "incompatible-property-access",
            "The override `Order.fillable` is `public`, but `Model.fillable` is `protected`.",
        ),
        (
            "invalid-property-default-value",
            "Default value for property `Order.table` is not assignable to its declared type.",
        ),
        (
            "incompatible-property-type",
            "The override `Order.timestamps` has type `int`, which does not fit `bool`, the type of `Model.timestamps`.",
        ),
        (
            "incompatible-property-type",
            "The override `Order.appends` has type `string`, which does not fit `Map<int|string, Any?>`, the type of `Model.appends`.",
        ),
        ("missing-override-attribute", "Missing `override` modifier on overriding property `Order.with`."),
        ("invalid-override-attribute", "Invalid `override` modifier on `Order.missing`."),
        ("invalid-override-attribute", "Invalid `override` modifier on `Order.secret`."),
        (
            "missing-override-attribute",
            "The field `Order.perPage` replaces `Model.perPage`: an override is a property marked `override`.",
        ),
    ] {
        assert!(reported.contains(&expected), "{expected:?} is missing from {reported:#?}");
    }
    assert_eq!(reported.len(), 8, "{reported:#?}");

    let php = "<?php\n\nnamespace Demo;\n\nuse Lib\\Model;\n\nclass Order extends Model\n{\n    #[\\Override]\n    public $fillable = ['number'];\n    #[\\Override]\n    protected $table = 5;\n    #[\\Override]\n    public $timestamps = 0;\n    #[\\Override]\n    protected array $appends = [];\n    protected $with = 'customer';\n    #[\\Override]\n    protected $missing = 'none';\n    #[\\Override]\n    protected $secret = 'order';\n}\n";
    assert_eq!(
        messages(("src/Demo/Order.php", php), &[("src/Lib/Model.php", MODEL)]),
        [
            "Default value for property `Demo\\Order::$table` is not assignable to its declared type.",
            "Default value for property `Demo\\Order::$timestamps` is not assignable to its declared type.",
        ]
    );
}

/// An override keeps its written type instead of inheriting the parent's `@var` type, so a type that does not fit is
/// one issue, not a second one for its initial value against the inherited type. Both types are named as PHP# writes
/// them. The PHP twin keeps Mago's text.
#[test]
fn an_override_whose_type_does_not_fit_the_parent_is_reported_once() {
    let sharp = "namespace Demo;\n\nimport Lib.Model;\n\npublic class Order : Model\n{\n    protected override int table { get; set; } = 5;\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nuse Lib\\Model;\n\nclass Order extends Model\n{\n    #[\\Override]\n    protected int $table = 5;\n}\n";
    let others = [("src/Lib/Model.php", MODEL)];

    assert_eq!(
        worded(("src/Demo/Order.php", php), &others),
        [
            "10:15 incompatible-property-type Property `Demo\\Order::$table` adds a type that is missing on the parent property. | This type declaration is not present on the parent property | The parent property is defined here without a type | Adding a type to a property that was untyped in a parent class is an incompatible change. | You can either remove the type from this property or add an identical type to the property in the parent class.",
            "10:15 docblock-type-mismatch Docblock property type `null|string` is incompatible with native property type `int`. | Native type is `int`... | ...but docblock declares `null|string` | The docblock type must be compatible with the native type declaration. | Either change the docblock type to match `int`, or update the native type to be compatible with `null|string`.",
            "10:28 invalid-property-default-value Default value for property `Demo\\Order::$table` is not assignable to its declared type. | This default value has type `int(5)` | Property is declared with type `null|string` | A property's default value must be assignable to the property's declared type. | Change the default value to match the declared type, or update the property type to accept the default.",
        ]
    );
    assert_eq!(
        worded(("src/Demo/Order.sharp", sharp), &others),
        [
            "7:24 incompatible-property-type The override `Order.table` has type `int`, which does not fit `string?`, the type of `Model.table`. | `int` is written here. | `string?` is the parent's `@var` type. | PHP does not check this property's type, so the override's type must fit the one the parent's code relies on. | Write a type that fits `string?`."
        ]
    );

    let php = "<?php\n\nnamespace Demo;\n\nuse Lib\\Model;\n\nclass Order extends Model\n{\n    #[\\Override]\n    protected int $table = 5;\n}\n";
    assert_eq!(
        messages(("src/Demo/Order.php", php), &[("src/Lib/Model.php", MODEL)])
            .into_iter()
            .filter(|message| message.contains("adds a type"))
            .collect::<Vec<_>>(),
        ["Property `Demo\\Order::$table` adds a type that is missing on the parent property."]
    );
}

/// A PHP# class that overrides a plain PHP parent's property, for a subclass to override it again.
const ORDER: &str = "namespace Demo;\n\nimport Lib.Model;\n\npublic class Order : Model\n{\n    protected override string? table { get; set; } = \"orders\";\n}\n";

/// A plain PHP base class that types the property `ORDER` overrides.
const TYPED_MODEL: &str =
    "<?php\n\nnamespace Lib;\n\nabstract class Model\n{\n    protected ?string $table = null;\n}\n";

/// A property overrides a PHP# parent's override as it overrides a plain PHP parent's property, spec section 6.1,
/// whether the plain PHP root of the chain leaves the property untyped or types it. An override stays open.
#[test]
fn a_property_overrides_a_sharp_override_with_its_type_and_access_level() {
    let sharp = "namespace Demo;\n\npublic class RushOrder : Order\n{\n    protected override string? table { get; set; } = \"rush_orders\";\n}\n";

    for model in [MODEL, TYPED_MODEL] {
        let others = [("src/Demo/Order.sharp", ORDER), ("src/Lib/Model.php", model)];

        assert_eq!(issues(("src/Demo/RushOrder.sharp", sharp), &others), Vec::<String>::new());
    }
}

/// An override of a PHP# parent's override writes `override`, the parent's written type and its access level, spec
/// section 6.1, measured against that override alone, so each break is one error. A field can't replace it.
#[test]
fn an_override_that_does_not_match_the_sharp_override_is_an_error() {
    let reported = |sharp: &'static str| {
        analyze(
            &PLUGIN_REGISTRY,
            settings(),
            ("src/Demo/RushOrder.sharp", sharp),
            &[("src/Demo/Order.sharp", ORDER), ("src/Lib/Model.php", MODEL)],
        )
        .into_iter()
        .map(|issue| (issue.code.unwrap_or_default(), issue.message))
        .collect::<Vec<_>>()
    };
    let error = |code: &str, message: &str| vec![(code.to_owned(), message.to_owned())];

    assert_eq!(
        reported(
            "namespace Demo;\n\npublic class RushOrder : Order\n{\n    protected override string table { get; set; } = \"rush_orders\";\n}\n"
        ),
        error("incompatible-property-type", "Property `RushOrder.table` has an incompatible type declaration.")
    );
    assert_eq!(
        reported(
            "namespace Demo;\n\npublic class RushOrder : Order\n{\n    protected override int table { get; set; } = 5;\n}\n"
        ),
        error("incompatible-property-type", "Property `RushOrder.table` has an incompatible type declaration.")
    );
    assert_eq!(
        reported(
            "namespace Demo;\n\npublic class RushOrder : Order\n{\n    public override string? table { get; set; } = \"rush_orders\";\n}\n"
        ),
        error(
            "incompatible-property-access",
            "The override `RushOrder.table` is `public`, but `Order.table` is `protected`."
        )
    );
    assert_eq!(
        reported(
            "namespace Demo;\n\npublic class RushOrder : Order\n{\n    protected string? table = \"rush_orders\";\n}\n"
        ),
        error(
            "missing-override-attribute",
            "The field `RushOrder.table` replaces `Order.table`: an override is a property marked `override`."
        )
    );
    assert_eq!(
        reported(
            "namespace Demo;\n\npublic class RushOrder : Order\n{\n    protected string? table { get; set; } = \"rush_orders\";\n}\n"
        ),
        error("missing-override-attribute", "Missing `override` modifier on overriding property `RushOrder.table`.")
    );
}

/// PHP makes a property whose `set` is private final, so nothing overrides one, whether a PHP# parent writes it
/// `{ get; private set; }`, `virtual` or not, or a plain PHP parent writes `private(set)`, as the engine refuses the
/// class when it links.
#[test]
fn an_override_of_a_property_whose_set_is_private_is_an_error() {
    let php = "<?php\n\nnamespace Lib;\n\nclass Tally\n{\n    public private(set) int $views = 0;\n}\n";
    let sharp = "namespace Demo;\n\nimport Lib.Tally;\n\npublic class Counter\n{\n    public virtual int views { get; private set; } = 0;\n    public virtual int likes { get; set; } = 0;\n}\n\npublic class PageCounter : Counter\n{\n    public override int views { get; private set; } = 1;\n    public override int likes { get; set; } = 1;\n}\n\npublic class PageTally : Tally\n{\n    public override int views { get; private set; } = 1;\n}\n";

    assert_eq!(
        analyze(&PLUGIN_REGISTRY, settings(), ("src/Demo/Counter.sharp", sharp), &[("src/Lib/Tally.php", php)])
            .into_iter()
            .map(|issue| (issue.code.unwrap_or_default(), issue.message))
            .collect::<Vec<_>>(),
        [
            ("override-final-property".to_owned(), "Cannot override final property `Counter.views`.".to_owned()),
            ("override-final-property".to_owned(), "Cannot override final property `Tally.views`.".to_owned()),
        ]
    );
}

/// Spec sections 6.1 and 22: a PHP# property is closed unless it is `virtual` or `abstract`, and an override of one
/// is a property with accessor bodies or a computed one too. A `protected` field is open (line 289).
#[test]
fn a_property_overrides_a_sharp_property_only_when_it_is_open() {
    let sharp = "namespace Demo;\n\npublic abstract class Base\n{\n    public virtual string slug => \"base\";\n    protected string label = \"base\";\n    public abstract int count { get; }\n    public string closed => \"base\";\n    public int total { get; set; } = 0;\n}\n\npublic class Child : Base\n{\n    public override string slug => \"child\";\n    protected override string label { get => field; set => field = value; } = \"child\";\n    public override int count => 1;\n    public override string closed => \"child\";\n    public override int total { get; set; } = 1;\n}\n";

    assert_eq!(
        analyze(&PLUGIN_REGISTRY, settings(), ("src/Demo/Base.sharp", sharp), &[])
            .into_iter()
            .map(|issue| (issue.code.unwrap_or_default(), issue.message))
            .collect::<Vec<_>>(),
        [
            (
                "override-final-property".to_owned(),
                "Cannot override `Base.total`: a PHP# property is closed unless it is `virtual` or `abstract`."
                    .to_owned()
            ),
            (
                "override-final-property".to_owned(),
                "Cannot override `Base.closed`: a PHP# property is closed unless it is `virtual` or `abstract`."
                    .to_owned()
            ),
        ]
    );
}

/// Spec section 6.1: a plain PHP parent's own code writes its property at any time, so an override of it has `set`,
/// never `init`, and its access level matches the parent's, `set` included (line 287).
#[test]
fn an_override_of_a_plain_php_property_keeps_its_set_and_its_level() {
    let sharp = "namespace Demo;\n\nimport Lib.Model;\n\npublic class Order : Model\n{\n    protected override string? table { get; } = \"orders\";\n    public override bool timestamps { get; protected set; } = false;\n    protected override List<string> fillable => [];\n    protected override int perPage { get; private set; } = 20;\n    protected override List<string> with { get; init; } = [];\n}\n";

    assert_eq!(
        analyze(&PLUGIN_REGISTRY, settings(), ("src/Demo/Order.sharp", sharp), &[("src/Lib/Model.php", MODEL)])
            .into_iter()
            .map(|issue| (issue.code.unwrap_or_default(), issue.message))
            .collect::<Vec<_>>(),
        [
            (
                "incompatible-property-access".to_owned(),
                "`Model.timestamps` is set at `public`, so its override `Order.timestamps` is set at `public` too."
                    .to_owned()
            ),
            (
                "incompatible-property-access".to_owned(),
                "`Model.perPage` is set at `protected`, so its override `Order.perPage` is set at `protected` too."
                    .to_owned()
            ),
            (
                "incompatible-property-access".to_owned(),
                "`Model.with` is settable, and `Model`'s own code writes it, so its override `Order.with` has `set`, not `init`."
                    .to_owned()
            ),
            (
                "incompatible-property-access".to_owned(),
                "`Model.table` is settable, and `Model`'s own code writes it, so its override `Order.table` has `set`."
                    .to_owned()
            ),
            (
                "incompatible-property-access".to_owned(),
                "`Model.fillable` is settable, and `Model`'s own code writes it, so its override `Order.fillable` has `set`."
                    .to_owned()
            ),
        ]
    );
}

/// `nameof(X.y)` is the string `'y'`, spec section 6.3, and the checker proves `X` declares or inherits `y`, a
/// property or a field, instance or static, readable where `nameof` is written, as C#'s `nameof` does. A method is not
/// a property, and a misspelled name is an error wherever it is written.
#[test]
fn nameof_names_a_property_the_class_has_and_is_a_string() {
    let order = "namespace Demo;\n\npublic class Entity\n{\n    public int id { get; set; } = 0;\n}\n\npublic class Order : Entity\n{\n    public int total { get; set; } = 0;\n    public static int count { get; private set; } = 0;\n    private int secret = 0;\n    public int sum() => 1;\n\n    public string own() => nameof(Order.secret);\n}\n";
    let sharp = "namespace Demo;\n\npublic class Report\n{\n    public string column() => nameof(Order.total);\n    public string parent() => nameof(Order.id);\n    public string shared() => nameof(Order.count);\n    public string misspelled() => nameof(Order.totl);\n    public string hidden() => nameof(Order.secret);\n    public string method() => nameof(Order.sum);\n    public string missing() => nameof(Missing.total);\n    public int number() => nameof(Order.total);\n}\n";

    assert_eq!(issues(("src/Demo/Order.sharp", order), &[]), Vec::<String>::new());
    assert_eq!(
        messages(("src/Demo/Report.sharp", sharp), &[("src/Demo/Order.sharp", order)]),
        [
            "Property `Order.totl` does not exist.",
            "`Order.secret` is `private`, so `nameof` can't name it here.",
            "Property `Order.sum` does not exist.",
            "Cannot find type `Demo.Missing`.",
            "Invalid return type for method `Report.number`: expected `int`, but found `string`.",
        ]
    );

    // A class whose parent is missing may inherit the name, so only the missing parent is reported.
    let orphan =
        "namespace Demo;\n\npublic class Orphan : Lost\n{\n    public string name() => nameof(Orphan.total);\n}\n";
    assert_eq!(codes(&issues(("src/Demo/Orphan.sharp", orphan), &[])), ["non-existent-class-like"]);
}

/// The `App.Tenant.Store` classes the `internal` tests reach: `Hidden`, `internal` by default, and `Shop`, public
/// with `internal` members.
const TENANT_STORE: [(&str, &str); 2] = [
    (
        "src/App/Tenant/Store/Hidden.sharp",
        "namespace App.Tenant.Store;\n\nclass Hidden\n{\n    public int total() => 1;\n}\n",
    ),
    (
        "src/App/Tenant/Store/Shop.sharp",
        "namespace App.Tenant.Store;\n\npublic class Shop\n{\n    internal const int MAX = 3;\n    public int views { get; internal set; } = 0;\n    internal int stock { get; set; } = 0;\n\n    internal int secret() => 1;\n\n    public Hidden make() => new Hidden();\n}\n",
    ),
];

/// Spec section 5: `internal` reaches its namespace and every namespace below it, and is the default for classes. A
/// member is never more visible than its class, so a public member of an `internal` class is `internal` too. Code
/// outside the reach, a sibling or the parent namespace, gets the error where it reaches: the import of a class, or
/// the member. A member it can't reach reads as no value, as a private one does, so only `internal-access` is kept.
#[test]
fn internal_reaches_its_namespace_and_every_namespace_below_it() {
    let reach = |analyzed: (&'static str, &'static str)| -> Vec<String> {
        analyze(&PLUGIN_REGISTRY, settings(), analyzed, &TENANT_STORE)
            .into_iter()
            .filter(|issue| issue.code.as_deref() == Some("internal-access"))
            .map(|issue| issue.message)
            .collect()
    };
    let body = "{\n    public int run(Shop shop)\n    {\n        const stock = shop.stock;\n        shop.secret();\n        shop.make().total();\n        shop.views = 2;\n        shop.stock = 1;\n        return Shop.MAX + shop.views + stock;\n    }\n}\n";
    let code = |namespace: &str| -> &'static str {
        leak(format!(
            "namespace {namespace};\n\nimport App.Tenant.Store.Hidden;\nimport App.Tenant.Store.Shop;\n\npublic class Use\n{body}"
        ))
    };

    assert_eq!(
        messages(("src/App/Tenant/Store/Inner/Use.sharp", code("App.Tenant.Store.Inner")), &TENANT_STORE),
        Vec::<String>::new()
    );
    assert_eq!(
        messages(("src/App/Tenant/Store/Use.sharp", code("App.Tenant.Store")), &TENANT_STORE),
        Vec::<String>::new()
    );

    for (path, namespace) in
        [("src/App/Tenant/Other/Use.sharp", "App.Tenant.Other"), ("src/App/Tenant/Use.sharp", "App.Tenant")]
    {
        let outside =
            |reached: &str| format!("`{reached}` is internal to `App.Tenant.Store`, and `{namespace}` is outside it.");

        assert_eq!(
            reach((path, code(namespace))),
            [
                outside("Hidden"),
                outside("Shop.stock"),
                outside("Shop.secret"),
                outside("Hidden.total"),
                outside("Shop.views.set"),
                outside("Shop.stock"),
                outside("Shop.MAX"),
            ],
            "{namespace}"
        );
    }

    // Plain PHP has no namespace visibility, so a `.php` file reaches every PHP# class and member.
    let php = "<?php\n\nnamespace App\\Tenant\\Other;\n\nuse App\\Tenant\\Store\\Hidden;\nuse App\\Tenant\\Store\\Shop;\n\nfinal class Plain\n{\n    public function run(Shop $shop, Hidden $hidden): int\n    {\n        $shop->views = 2;\n        return $shop->secret() + $hidden->total() + Shop::MAX;\n    }\n}\n";
    assert_eq!(reach(("src/App/Tenant/Other/Plain.php", php)), Vec::<String>::new());
}

/// A PHP class that implements a class reports it, and keeps the metadata upstream Mago builds: only a PHP# header
/// links its class as the parent.
#[test]
fn a_php_class_that_implements_a_class_is_still_an_error() {
    let php = "<?php\n\nnamespace Demo;\n\nclass Entity\n{\n    public function id(): int\n    {\n        return 7;\n    }\n}\n\nclass Page implements Entity\n{\n    public function number(): int\n    {\n        return parent::id();\n    }\n}\n";

    assert_eq!(
        codes(&issues(("src/Demo/Page.php", php), &[])),
        ["invalid-implement", "invalid-parent-type", "mixed-return-statement"]
    );
}

/// A plain PHP method is open unless PHP marks it `final`, and replacing one needs `override`, spec section 22. So
/// PHP# reports what PHP reports for its `#[\Override]` twin: a missing `override`, `override` with no parent method,
/// replacing a `final` method, and, as errors, renamed parameters.
#[test]
fn replacing_a_php_method_follows_php_rules_with_override_required() {
    let library = "<?php\n\nnamespace Lib;\n\nabstract class Report\n{\n    abstract protected function render(): string;\n\n    public function title(): string\n    {\n        return 'Report';\n    }\n\n    final public function id(): string\n    {\n        return 'report';\n    }\n\n    public function resize(int $width, int $height): void\n    {\n    }\n}\n";
    let sharp = "namespace Demo;\n\nimport Lib.Report;\n\npublic class SalesReport : Report\n{\n    protected override string render()\n    {\n        return \"sales\";\n    }\n\n    public override string title()\n    {\n        return \"Sales\";\n    }\n}\n\npublic class PlainReport : Report\n{\n    protected override string render()\n    {\n        return \"plain\";\n    }\n\n    public string title()\n    {\n        return \"Plain\";\n    }\n}\n\npublic class FinalReport : Report\n{\n    protected override string render()\n    {\n        return \"final\";\n    }\n\n    public override string id()\n    {\n        return \"final\";\n    }\n}\n\npublic class StrayReport : Report\n{\n    protected override string render()\n    {\n        return \"stray\";\n    }\n\n    public override string footer()\n    {\n        return \"\";\n    }\n}\n\npublic class RenamedReport : Report\n{\n    protected override string render()\n    {\n        return \"renamed\";\n    }\n\n    public override void resize(int w, int h)\n    {\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nuse Lib\\Report;\n\nclass SalesReport extends Report\n{\n    #[\\Override]\n    protected function render(): string\n    {\n        return \"sales\";\n    }\n\n    #[\\Override]\n    public function title(): string\n    {\n        return \"Sales\";\n    }\n}\n\nclass PlainReport extends Report\n{\n    #[\\Override]\n    protected function render(): string\n    {\n        return \"plain\";\n    }\n\n    public function title(): string\n    {\n        return \"Plain\";\n    }\n}\n\nclass FinalReport extends Report\n{\n    #[\\Override]\n    protected function render(): string\n    {\n        return \"final\";\n    }\n\n    #[\\Override]\n    public function id(): string\n    {\n        return \"final\";\n    }\n}\n\nclass StrayReport extends Report\n{\n    #[\\Override]\n    protected function render(): string\n    {\n        return \"stray\";\n    }\n\n    #[\\Override]\n    public function footer(): string\n    {\n        return \"\";\n    }\n}\n\nclass RenamedReport extends Report\n{\n    #[\\Override]\n    protected function render(): string\n    {\n        return \"renamed\";\n    }\n\n    #[\\Override]\n    public function resize(int $w, int $h): void\n    {\n    }\n}\n";
    let others = [("src/Lib/Report.php", library)];

    let sharp_issues = issues(("src/Demo/Report.sharp", sharp), &others);
    let php_issues =
        issues_with(Settings { check_missing_override: true, ..settings() }, ("src/Demo/Report.php", php), &others);

    assert_eq!(
        codes(&php_issues),
        [
            "missing-override-attribute",
            "override-final-method",
            "invalid-override-attribute",
            "incompatible-parameter-name",
            "incompatible-parameter-name"
        ],
        "{php_issues:?}"
    );
    assert_eq!(codes(&sharp_issues), codes(&php_issues), "{sharp_issues:?}");

    let renamed: Vec<_> = analyze(&PLUGIN_REGISTRY, settings(), ("src/Demo/Report.sharp", sharp), &others)
        .into_iter()
        .filter(|issue| issue.code.as_deref() == Some("incompatible-parameter-name"))
        .collect();
    assert!(renamed.iter().all(|issue| issue.level == Level::Error), "{renamed:?}");
    assert_eq!(
        renamed[0].message,
        "Parameter #1 of `RenamedReport.resize` is named `w` but parent `Report.resize` names it `width`"
    );
    assert_eq!(
        messages_with(Settings { check_missing_override: true, ..settings() }, ("src/Demo/Report.php", php), &others),
        [
            "Missing `#[Override]` attribute on overriding method `Demo\\PlainReport::title`.",
            "Cannot override final method `Lib\\Report::id()`",
            "Invalid `#[Override]` attribute on `Demo\\StrayReport::footer`.",
            "Parameter #1 of `Demo\\RenamedReport::resize()` is named `$w` but parent `Lib\\Report::resize()` names it `$width`",
            "Parameter #2 of `Demo\\RenamedReport::resize()` is named `$h` but parent `Lib\\Report::resize()` names it `$height`",
        ]
    );
}

/// A plain PHP parent's parameter named as a PHP# keyword is written with `@`, spec section 2, so an override keeps
/// `$event` as `@event`, and a rename names the `@event` to write.
#[test]
fn an_override_keeps_a_keyword_parameter_name_with_at() {
    let library = "<?php\n\nnamespace Lib;\n\nabstract class Behavior\n{\n    abstract public function submit(string $form, string $event): string;\n}\n";
    let others = [("src/Lib/Behavior.php", library)];
    let kept = "namespace Demo;\n\nimport Lib.Behavior;\n\npublic class Form : Behavior\n{\n    public override string submit(string form, string @event) => @event;\n}\n";
    let renamed = "namespace Demo;\n\nimport Lib.Behavior;\n\npublic class Form : Behavior\n{\n    public override string submit(string form, string e) => e;\n}\n";

    assert_eq!(issues(("src/Demo/Form.sharp", kept), &others), Vec::<String>::new());
    let refused: Vec<_> = analyze(&PLUGIN_REGISTRY, settings(), ("src/Demo/Form.sharp", renamed), &others)
        .into_iter()
        .map(|issue| (issue.message, issue.help))
        .collect();
    assert_eq!(
        refused,
        [(
            "Parameter #2 of `Form.submit` is named `e` but parent `Behavior.submit` names it `event`".to_owned(),
            Some("Name it `@event`, as the parent does.".to_owned()),
        )]
    );
}

/// A plain PHP parent whose methods type a native `array` return and parameter in their docblocks.
const COUNTER: &str = "<?php\n\nnamespace Lib;\n\nabstract class Counter\n{\n    /** @return list<int> */\n    public function counts(): array\n    {\n        return [];\n    }\n\n    /** @param list<string> $tags */\n    public function tag(array $tags): void\n    {\n    }\n}\n";

/// A PHP# override of `COUNTER`'s `counts` that writes a `Map` return type.
const TALLY: &str = "namespace Demo;\n\nimport Lib.Counter;\n\npublic class Tally : Counter\n{\n    public override Map<int, int> counts()\n    {\n        return [:];\n    }\n}\n";

/// A PHP# override returns the type it writes, because PHP# reads no docblock, so the parent's `@return list<int>`
/// never replaces its `Map<int, int>` and an empty `Map` literal is accepted. The signature check compares that type
/// with the parent's `@return` and reports that it does not fit. The PHP twin inherits the parent's `@return`, so a
/// string-keyed array is refused.
#[test]
fn an_override_of_a_plain_php_method_returns_the_type_it_writes() {
    let php = "<?php\n\nnamespace Demo;\n\nuse Lib\\Counter;\n\nclass Tally extends Counter\n{\n    #[\\Override]\n    public function counts(): array\n    {\n        return ['a' => 1];\n    }\n}\n";
    let others = [("src/Lib/Counter.php", COUNTER)];

    assert_eq!(issues(("src/Demo/Tally.php", php), &others), ["12:16 invalid-return-statement"]);
    assert_eq!(
        messages(("src/Demo/Tally.sharp", TALLY), &others),
        [
            "Return type `Map<int, int>` of `Tally.counts` is incompatible with parent return type `List<int>` of `Counter.counts`"
        ]
    );
}

/// A PHP# override whose written return type fits the parent's `@return` passes the signature check.
#[test]
fn an_override_of_a_plain_php_method_whose_return_type_fits_the_parents_docblock_is_accepted() {
    let sharp = "namespace Demo;\n\nimport Lib.Counter;\n\npublic class Tally : Counter\n{\n    public override List<int> counts()\n    {\n        return [1];\n    }\n}\n";
    let others = [("src/Lib/Counter.php", COUNTER)];

    assert_eq!(issues(("src/Demo/Tally.sharp", sharp), &others), Vec::<String>::new());
}

/// A plain PHP subclass of a PHP# override meets the type the override's PHP declaration writes, `\Sharp\Map|array`
/// for a `Map` plain PHP gets as its array, as a subclass of any PHP# method does, and inherits no `@return` from the
/// plain PHP class above the override. So `array` links, as the engine links it, and `string` doesn't.
#[test]
fn a_plain_php_subclass_of_a_sharp_override_meets_the_type_the_override_writes() {
    let plain = "namespace Demo;\n\npublic class Tally\n{\n    public virtual Map<int, int> counts()\n    {\n        return [:];\n    }\n}\n";
    let rush = |result: &str| -> &'static str {
        let value = if result == "array" { "[1 => 1]" } else { "'one'" };

        String::leak(format!(
            "<?php\n\nnamespace Demo;\n\nclass Rush extends Tally\n{{\n    #[\\Override]\n    public function counts(): {result}\n    {{\n        return {value};\n    }}\n}}\n"
        ))
    };

    for result in ["array", "string"] {
        let below_plain = issues(("src/Demo/Rush.php", rush(result)), &[("src/Demo/Tally.sharp", plain)]);
        let below_override = issues(
            ("src/Demo/Rush.php", rush(result)),
            &[("src/Demo/Tally.sharp", TALLY), ("src/Lib/Counter.php", COUNTER)],
        );

        let expected: &[&str] = if result == "array" { &[] } else { &["8:21 incompatible-return-type"] };
        assert_eq!(below_plain, expected, "counts(): {result}");
        assert_eq!(below_override, below_plain, "counts(): {result}");
    }
}

/// A PHP# override takes the parameter type it writes, so `tags` is a `Map` whose `get` takes its key. The signature
/// check compares that type with the parent's `@param` type and reports that it accepts less. The PHP twin inherits
/// the parent's `@param`.
#[test]
fn an_override_of_a_plain_php_method_takes_the_parameter_type_it_writes() {
    let sharp = "namespace Demo;\n\nimport Lib.Counter;\n\npublic class Labels : Counter\n{\n    public int? last = null;\n\n    public override void tag(Map<string, int> tags)\n    {\n        this.last = tags.get(\"a\");\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nuse Lib\\Counter;\n\nclass Labels extends Counter\n{\n    #[\\Override]\n    public function tag(array $tags): void\n    {\n        /** @psalm-trace $tags */\n        $count = count($tags);\n    }\n}\n";
    let others = [("src/Lib/Counter.php", COUNTER)];

    assert_eq!(messages(("src/Demo/Labels.php", php), &others), ["Trace: Type of `$tags` is `list<string>`"]);
    assert_eq!(
        messages(("src/Demo/Labels.sharp", sharp), &others),
        [
            "Parameter `tags` of `Labels.tag` expects type `Map<string, int>` but parent `Counter.tag` expects type `List<string>`"
        ]
    );
}

/// A PHP# method that implements a plain PHP interface method keeps the types it writes, as an override does, and the
/// signature check reports each one that does not fit the interface's docblock. The PHP twin inherits the interface's
/// `@return` and `@param`.
#[test]
fn an_implementation_of_a_plain_php_interface_method_keeps_the_types_it_writes() {
    let library = "<?php\n\nnamespace Lib;\n\ninterface Source\n{\n    /** @return list<int> */\n    public function counts(): array;\n\n    /** @param list<string> $tags */\n    public function tag(array $tags): void;\n}\n";
    let sharp = "namespace Demo;\n\nimport Lib.Source;\n\npublic class Feed : Source\n{\n    public int? last = null;\n\n    public Map<int, int> counts()\n    {\n        return [:];\n    }\n\n    public void tag(Map<string, int> tags)\n    {\n        this.last = tags.get(\"a\");\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nuse Lib\\Source;\n\nclass Feed implements Source\n{\n    public function counts(): array\n    {\n        return ['a' => 1];\n    }\n\n    public function tag(array $tags): void\n    {\n        /** @psalm-trace $tags */\n        $count = count($tags);\n    }\n}\n";
    let others = [("src/Lib/Source.php", library)];

    assert_eq!(issues(("src/Demo/Feed.php", php), &others), ["11:16 invalid-return-statement", "16:26 psalm-trace"]);
    assert_eq!(
        messages(("src/Demo/Feed.sharp", sharp), &others),
        [
            "Return type `Map<int, int>` of `Feed.counts` is incompatible with parent return type `List<int>` of `Source.counts`",
            "Parameter `tags` of `Feed.tag` expects type `Map<string, int>` but parent `Source.tag` expects type `List<string>`"
        ]
    );
}

/// A PHP# override throws nothing its parent's `@throws` names, so a plain PHP caller that checks thrown types has
/// nothing to handle. The PHP twin inherits the `@throws`.
#[test]
fn an_override_of_a_plain_php_method_takes_no_throws_from_the_parent() {
    let library = "<?php\n\nnamespace Lib;\n\nabstract class Loader\n{\n    /** @throws \\RuntimeException */\n    public function load(): int\n    {\n        return 1;\n    }\n}\n";
    let sharp = "namespace Demo;\n\nimport Lib.Loader;\n\npublic class FileLoader : Loader\n{\n    public override int load() => 2;\n}\n";
    let php_twin = "<?php\n\nnamespace Demo;\n\nuse Lib\\Loader;\n\nclass FileLoader extends Loader\n{\n    #[\\Override]\n    public function load(): int\n    {\n        return 2;\n    }\n}\n";
    let caller =
        "<?php\n\nnamespace Demo;\n\nfunction run(FileLoader $loader): int\n{\n    return $loader->load();\n}\n";

    assert_eq!(
        issues(("src/Demo/run.php", caller), &[("src/Demo/FileLoader.php", php_twin), ("src/Lib/Loader.php", library)]),
        ["7:12 unhandled-thrown-type"]
    );
    assert_eq!(
        issues(("src/Demo/run.php", caller), &[("src/Demo/FileLoader.sharp", sharp), ("src/Lib/Loader.php", library)]),
        Vec::<String>::new()
    );
}

/// A PHP# override declares no template its parent's `@template` declares, so a call of it is not generic and records
/// no type argument for the running program. The PHP twin inherits the template.
#[test]
fn an_override_of_a_plain_php_method_takes_no_template_from_the_parent() {
    let library = "<?php\n\nnamespace Lib;\n\nabstract class Keeper\n{\n    /**\n     * @template T\n     * @param T $value\n     * @return T\n     */\n    public function keep(mixed $value): mixed\n    {\n        return $value;\n    }\n}\n";
    let sharp = "namespace Demo;\n\nimport Lib.Keeper;\n\npublic class Box : Keeper\n{\n    public override Any? keep(Any? value) => value;\n\n    public int run()\n    {\n        this.keep(5);\n        return 1;\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nuse Lib\\Keeper;\n\nclass Box extends Keeper\n{\n    #[\\Override]\n    public function keep(mixed $value): mixed\n    {\n        return $value;\n    }\n\n    public function run(): int\n    {\n        $this->keep(5);\n        return 1;\n    }\n}\n";
    let type_arguments = |analyzed: (&'static str, &'static str), call: &str| {
        let start = analyzed.1.find(call).unwrap() as u32;
        let (issues, artifacts) =
            analyze_with_artifacts(&PLUGIN_REGISTRY, settings(), analyzed, &[("src/Lib/Keeper.php", library)]);
        assert!(issues.is_empty(), "{issues:?}");

        artifacts
            .inferred_type_arguments
            .get(&(start, start + call.len() as u32))
            .map(|arguments| arguments.iter().map(|argument| argument.get_id().to_string()).collect::<Vec<_>>())
    };

    assert_eq!(type_arguments(("src/Demo/Box.php", php), "$this->keep(5)"), Some(vec!["int".to_owned()]));
    assert_eq!(type_arguments(("src/Demo/Box.sharp", sharp), "this.keep(5)"), None);
}

/// A PHP# override takes no `@psalm-assert-if-true` from its parent, so a call of it narrows nothing the parent's
/// docblock promises and a later `is string` check is possible. The PHP twin inherits the assertion.
#[test]
fn an_override_of_a_plain_php_method_takes_no_assertion_from_the_parent() {
    let library = "<?php\n\nnamespace Lib;\n\nabstract class Check\n{\n    /** @psalm-assert-if-true int $value */\n    public function matches(mixed $value): bool\n    {\n        return is_int($value);\n    }\n}\n";
    let sharp = "namespace Demo;\n\nimport Lib.Check;\n\npublic class TextCheck : Check\n{\n    public override bool matches(Any? value) => value is string;\n\n    public int size(Any? value)\n    {\n        if (this.matches(value) && value is string) {\n            return 1;\n        }\n        return 0;\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nuse Lib\\Check;\n\nclass TextCheck extends Check\n{\n    #[\\Override]\n    public function matches(mixed $value): bool\n    {\n        return is_string($value);\n    }\n\n    public function size(mixed $value): int\n    {\n        if ($this->matches($value) && is_string($value)) {\n            return 1;\n        }\n        return 0;\n    }\n}\n";
    let others = [("src/Lib/Check.php", library)];

    assert_eq!(
        codes(&issues(("src/Demo/TextCheck.php", php), &others)),
        ["impossible-type-comparison", "redundant-logical-operation", "impossible-condition"]
    );
    assert_eq!(issues(("src/Demo/TextCheck.sharp", sharp), &others), Vec::<String>::new());
}

/// A parse error reports its spot once, so returning what failed to parse adds no `never-return`, in PHP# and PHP.
#[test]
fn returning_a_value_that_failed_to_parse_adds_no_issue() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public int make()\n    {\n        return );\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nfunction make(): int\n{\n    return );\n}\n";

    assert_eq!(issues(("src/Demo/make.php", php), &[]), ["7:12 parse"]);
    assert_eq!(issues(("src/Demo/Report.sharp", sharp), &[]), ["7:16 parse"]);
}

/// `super` names the base class, so a class whose header names only interfaces has none, as `parent::` in a PHP
/// class without `extends` has none.
#[test]
fn super_in_a_class_without_a_base_class_is_an_error_as_in_php() {
    let sharp = "namespace Demo;\n\npublic interface Named\n{\n    string name();\n}\n\npublic class Tag : Named\n{\n    public string name()\n    {\n        return super.name();\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\ninterface Named\n{\n    public function name(): string;\n}\n\nclass Tag implements Named\n{\n    public function name(): string\n    {\n        return parent::name();\n    }\n}\n";

    let sharp_issues = issues(("src/Demo/Tag.sharp", sharp), &[]);
    let php_issues = issues(("src/Demo/Tag.php", php), &[]);

    assert_eq!(codes(&php_issues), ["invalid-parent-type", "mixed-return-statement"], "{php_issues:?}");
    assert_eq!(codes(&sharp_issues), codes(&php_issues), "{sharp_issues:?}");

    let invalid = analyze(&PLUGIN_REGISTRY, settings(), ("src/Demo/Tag.sharp", sharp), &[]).remove(0);
    assert_eq!(invalid.level, Level::Error);
    assert_eq!(invalid.message, "Cannot use `super` as the current type (`Tag`) does not have a parent class.");

    let php_invalid = analyze(&PLUGIN_REGISTRY, settings(), ("src/Demo/Tag.php", php), &[]).remove(0);
    assert_eq!(
        php_invalid.message,
        "Cannot use `parent` as the current type (`Demo\\Tag`) does not have a parent class."
    );
}

/// The checker refuses a member of `typeof(X)` once, so the analyzer adds no issue on the refused read, its chain, or
/// the value it gives.
#[test]
fn a_member_read_through_a_class_value_is_checked_as_the_static_member_in_php() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public const int MAX = 3;\n    private static int count = 0;\n\n    public static string tag() => \"div\";\n\n    public int total()\n    {\n        const type = typeof(Report);\n        const max = type.MAX;\n        const seen = type.count;\n        return typeof(Report).MAX + max + seen;\n    }\n\n    public string label()\n    {\n        const type = typeof(Report);\n        return type.tag();\n    }\n\n    public int missing()\n    {\n        const type = typeof(Report);\n        return type.absent;\n    }\n\n    public void named()\n    {\n        const type = typeof(Report);\n        type.attributes();\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nclass Report\n{\n    public const int MAX = 3;\n    private static int $count = 0;\n\n    public static function tag(): string\n    {\n        return \"div\";\n    }\n\n    public function total(): int\n    {\n        $type = Report::class;\n        $max = $type::MAX;\n        $seen = $type::$count;\n        return Report::MAX + $max + $seen;\n    }\n\n    public function label(): string\n    {\n        $type = Report::class;\n        return $type::tag();\n    }\n\n    public function missing(): int\n    {\n        $type = Report::class;\n        return $type::$absent;\n    }\n\n    public function named(): void\n    {\n        $type = Report::class;\n        $type::attributes();\n    }\n}\n";

    let (issues, artifacts) =
        analyze_with_artifacts(&PLUGIN_REGISTRY, settings(), ("src/Demo/Report.sharp", sharp), &[]);
    let sharp_issues: Vec<String> = issues.iter().map(|issue| issue.code.clone().unwrap_or_default()).collect();
    let php_issues = issues_with(settings(), ("src/Demo/Report.php", php), &[]);
    let type_at = |text: &str| {
        let start = sharp.find(text).unwrap() as u32;
        artifacts.expression_types.get(&(start, start + text.len() as u32)).map(|r#type| r#type.get_id().to_string())
    };

    assert_eq!(sharp_issues, codes(&php_issues), "{php_issues:?}");
    assert_eq!(sharp_issues, ["non-existent-property", "invalid-return-statement", "non-existent-method"]);
    assert_eq!(type_at("type.MAX").as_deref(), Some("int(3)"));
    assert_eq!(type_at("type.count").as_deref(), Some("int"));
    assert_eq!(type_at("type.tag()").as_deref(), Some("string"));
    assert_eq!(type_at("typeof(Report).MAX").as_deref(), Some("int(3)"));
}

/// The receiver of a class value read is a class value: `typeof(X)` and a `const` local holding it are the class-string
/// of `X`.
#[test]
fn a_local_holding_typeof_is_the_class_string_of_its_class() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public const int MAX = 3;\n\n    public int total()\n    {\n        const type = typeof(Report);\n        return type.MAX;\n    }\n}\n";
    let (issues, artifacts) =
        analyze_with_artifacts(&PLUGIN_REGISTRY, settings(), ("src/Demo/Report.sharp", sharp), &[]);
    let start = sharp.find("type.MAX").unwrap() as u32;

    assert!(issues.is_empty(), "{issues:?}");
    assert_eq!(
        artifacts.expression_types.get(&(start, start + 4)).map(|r#type| r#type.get_id().to_string()).as_deref(),
        Some("class-string('Demo\\Report')")
    );
}

/// PHP reads a class-string's members only through `::`. An arrow read of one stays the error it is in PHP.
#[test]
fn an_arrow_read_of_a_class_string_stays_an_error_in_php() {
    let php = "<?php\n\nnamespace Demo;\n\nclass Report\n{\n    public const int MAX = 3;\n\n    public function total(): mixed\n    {\n        $type = Report::class;\n        return $type->MAX;\n    }\n}\n";

    assert_eq!(issues(("src/Demo/Report.php", php), &[]), ["12:23 invalid-property-access"]);
}

/// A null-safe read or call through a class value that may be null reads the member when the value holds a class, and
/// is `null` otherwise, as spec section 14.4 defines `a?.b`.
#[test]
fn a_null_safe_member_read_through_a_class_value_is_the_member_or_null() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public const int MAX = 3;\n    private static int count = 0;\n\n    public static string tag() => \"div\";\n\n    public int? max(bool flag)\n    {\n        const type = flag ? typeof(Report) : null;\n        return type?.MAX;\n    }\n\n    public int? seen(bool flag)\n    {\n        const type = flag ? typeof(Report) : null;\n        return type?.count;\n    }\n\n    public string? label(bool flag)\n    {\n        const type = flag ? typeof(Report) : null;\n        return type?.tag();\n    }\n}\n";
    let (issues, artifacts) =
        analyze_with_artifacts(&PLUGIN_REGISTRY, settings(), ("src/Demo/Report.sharp", sharp), &[]);
    let type_at = |text: &str| {
        let start = sharp.find(text).unwrap() as u32;
        artifacts.expression_types.get(&(start, start + text.len() as u32)).map(|r#type| r#type.get_id().to_string())
    };

    assert!(issues.is_empty(), "{issues:?}");
    assert_eq!(type_at("type?.MAX").as_deref(), Some("int(3)|null"));
    assert_eq!(type_at("type?.count").as_deref(), Some("int|null"));
    assert_eq!(type_at("type?.tag()").as_deref(), Some("null|string"));
}

/// A null receiver skips a null-safe call's arguments, so a local an argument writes may keep its value from before.
#[test]
fn a_local_a_null_safe_call_through_a_class_value_writes_may_keep_its_value() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public static string make(int? value) => \"made\";\n\n    public int? last(bool flag)\n    {\n        let seen = null;\n        const type = flag ? typeof(Report) : null;\n        type?.make(seen = 5);\n        return seen;\n    }\n}\n";
    let (issues, artifacts) =
        analyze_with_artifacts(&PLUGIN_REGISTRY, settings(), ("src/Demo/Report.sharp", sharp), &[]);
    let start = sharp.rfind("seen;").unwrap() as u32;

    assert!(issues.is_empty(), "{issues:?}");
    assert_eq!(
        artifacts.expression_types.get(&(start, start + 4)).map(|r#type| r#type.get_id().to_string()).as_deref(),
        Some("int(5)|null")
    );
}

/// A class value that may be null is refused before a member read, as PHP's `$type::MAX` throws "Cannot use null as
/// class" when `$type` is null.
#[test]
fn a_member_read_through_a_class_value_that_may_be_null_is_an_error() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public const int MAX = 3;\n\n    public int read(bool flag)\n    {\n        const type = flag ? typeof(Report) : null;\n        return type.MAX;\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nclass Report\n{\n    public const int MAX = 3;\n\n    public function read(bool $flag): int\n    {\n        $type = $flag ? Report::class : null;\n        return $type::MAX;\n    }\n}\n";

    let sharp_issues = issues(("src/Demo/Report.sharp", sharp), &[]);

    assert_eq!(codes(&sharp_issues), codes(&issues(("src/Demo/Report.php", php), &[])));
    assert_eq!(
        messages(("src/Demo/Report.sharp", sharp), &[]),
        ["Attempting static access on a possibly `null` value."]
    );
    assert_eq!(sharp_issues.len(), 1, "{sharp_issues:?}");
}

#[test]
fn a_catch_variable_has_the_caught_classes_as_its_type_as_in_php() {
    let sharp = "namespace Demo;\n\nimport RuntimeException;\nimport LogicException;\n\nclass Report\n{\n    public static int total(int extra)\n    {\n        try {\n            if (extra < 0) {\n                throw new RuntimeException(\"negative\");\n            }\n        } catch (RuntimeException | LogicException failure) {\n            return failure.getLine();\n        } finally {\n            extra += 1;\n        }\n        return extra;\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nuse RuntimeException;\nuse LogicException;\n\nclass Report\n{\n    public static function total(int $extra): int\n    {\n        try {\n            if ($extra < 0) {\n                throw new RuntimeException(\"negative\");\n            }\n        } catch (RuntimeException | LogicException $failure) {\n            return $failure->getLine();\n        } finally {\n            $extra += 1;\n        }\n        return $extra;\n    }\n}\n";

    let sharp_issues = issues(("src/Demo/Report.sharp", sharp), &[]);
    let php_issues = issues(("src/Demo/Report.php", php), &[]);

    assert_eq!(sharp_issues, Vec::<String>::new());
    assert_eq!(codes(&sharp_issues), codes(&php_issues));
}

/// Spec section 23 calls a plain PHP function through its namespace: `Pdf.render(html)` after `import Vendor.Pdf;`
/// calls a function of that namespace, and `Pdf.helper(extra)` the function `helper` the library declares in PHP's
/// root namespace beside its classes. Each checks its arguments as its PHP twin's call does.
#[test]
fn a_plain_php_function_is_called_through_its_namespace() {
    let pdf = "<?php\n\nnamespace Vendor\\Pdf;\n\nfunction render(string $html): string\n{\n    return $html;\n}\n";
    let helpers = "<?php\n\nfunction helper(int $value): int\n{\n    return $value;\n}\n";
    let document = "<?php\n\nnamespace Vendor\\Pdf;\n\nfinal class Document\n{\n}\n";
    let sharp = "namespace Demo;\n\nimport Vendor.Pdf;\n\nclass Report\n{\n    public static string page(string html) => Pdf.render(html);\n    public static int counted(int extra) => Pdf.helper(extra);\n    public static string wrongPage() => Pdf.render(5);\n    public static int wrongCount() => Pdf.helper(\"one\");\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nuse function Vendor\\Pdf\\render;\n\nclass Report\n{\n    public static function page(string $html): string { return render($html); }\n    public static function counted(int $extra): int { return \\helper($extra); }\n    public static function wrongPage(): string { return render(5); }\n    public static function wrongCount(): int { return \\helper(\"one\"); }\n}\n";
    let others = [
        ("src/Vendor/Pdf/functions.php", pdf),
        ("src/Vendor/Pdf/helpers.php", helpers),
        ("src/Vendor/Pdf/Document.php", document),
    ];

    let sharp_issues = issues(("src/Demo/Report.sharp", sharp), &others);

    assert_eq!(sharp_issues, ["9:52 invalid-argument", "10:50 invalid-argument"]);
    assert_eq!(codes(&sharp_issues), codes(&issues(("src/Demo/Report.php", php), &others)));
}

/// Laravel's `helpers.php` files and stancl/tenancy's, each a library's functions in PHP's root namespace beside its
/// classes. Laravel keeps `collect` in `Illuminate/Collections`, beside the classes of `Illuminate\Support`.
const ROOT_HELPERS: [(&str, &str); 6] = [
    (
        "vendor/laravel/framework/src/Illuminate/Foundation/helpers.php",
        "<?php\n\nfunction abort(int $code, string $message = ''): never\n{\n    exit($code);\n}\n\nfunction app(): object\n{\n    return new stdClass();\n}\n\nfunction now(): int\n{\n    return time();\n}\n",
    ),
    (
        "vendor/laravel/framework/src/Illuminate/Foundation/Application.php",
        "<?php\n\nnamespace Illuminate\\Foundation;\n\nclass Application\n{\n}\n",
    ),
    (
        "vendor/laravel/framework/src/Illuminate/Collections/helpers.php",
        "<?php\n\n/** @param list<int> $items */\nfunction collect(array $items): int\n{\n    return count($items);\n}\n",
    ),
    (
        "vendor/laravel/framework/src/Illuminate/Collections/Collection.php",
        "<?php\n\nnamespace Illuminate\\Support;\n\nclass Collection\n{\n}\n",
    ),
    ("vendor/stancl/tenancy/src/helpers.php", "<?php\n\nfunction tenant(): ?string\n{\n    return null;\n}\n"),
    ("vendor/stancl/tenancy/src/Tenancy.php", "<?php\n\nnamespace Stancl\\Tenancy;\n\nclass Tenancy\n{\n}\n"),
];

/// Jordan's ruling of 10-22, spec section 23: a function a library declares outside any namespace belongs to the
/// namespace of the library's classes in the same folder, so `Foundation.abort(…)` calls Laravel's `abort`,
/// `Support.collect(…)` its `collect`, which sits in `Illuminate/Collections` beside `Illuminate\Support`'s classes, and
/// `Tenancy.tenant()` stancl/tenancy's `tenant`. A function is a value through its namespace too, as `Foundation.app`.
/// The folder's name is no namespace, so `Collections.collect` names nothing.
#[test]
fn a_function_a_library_declares_outside_any_namespace_belongs_to_the_namespace_of_its_classes() {
    let controller = (
        "app/Http/CartsController.sharp",
        "namespace App.Http;\n\nimport Illuminate.Foundation;\nimport Illuminate.Support;\nimport Stancl.Tenancy;\n\npublic class CartsController\n{\n    public Any? missing() => Foundation.abort(404, \"Cart not found.\");\n    public int stamp() => Foundation.now();\n    public Any container() => Foundation.app;\n    public int counted() => Support.collect([1, 2]);\n    public string? current() => Tenancy.tenant();\n    public int wrong() => Support.collect(\"one\");\n}\n",
    );
    let folder = (
        "app/Http/Folder.sharp",
        "namespace App.Http;\n\npublic class Folder\n{\n    public int counted() => Collections.collect([1, 2]);\n}\n",
    );

    assert_eq!(
        refusals(controller, &ROOT_HELPERS),
        [
            "14:43 invalid-argument Invalid argument type for argument #1 of `Support.collect`: expected `List<int>`, but found `string`. | Change the argument value to match `List<int>`, or update the parameter's type declaration."
        ]
    );
    assert_eq!(
        refusals(folder, &ROOT_HELPERS),
        [
            "5:29 non-existent-class-like `Collections` names no class, and no namespace this file imports. | Check the spelling of `Collections`, or import the class or the namespace whose member this names."
        ]
    );
}

/// Jordan's ruling of 10-22: `global` does not exist in a project's PHP# code, so `global.levenshtein(a, b)`,
/// `global.CURLOPT_TIMEOUT`, the value `global.strlen` and `extern global.levenshtein;` each get what any name that
/// names nothing gets, as `gadget` does, and a file that declares a namespace under `Sharp` is no exception. Only the
/// standard library reaches PHP's own functions through `global`.
#[test]
fn global_is_an_ordinary_name_in_a_project_s_code() {
    let written = |name: &str, namespace: &str| -> &'static str {
        leak(format!(
            "namespace {namespace};\n\npublic class Probe\n{{\n    public int distance(string a, string b) => {name}.levenshtein(a, b);\n    public int timeout() => {name}.CURLOPT_TIMEOUT;\n    public Any length() => {name}.strlen;\n}}\n"
        ))
    };
    let declared =
        |name: &str| -> &'static str { leak(format!("namespace App.Stubs;\n\nextern {name}.levenshtein;\n")) };
    let unknown = |at: &str, name: &str| {
        format!(
            "{at} non-existent-class-like `{name}` names no class, and no namespace this file imports. | Check the spelling of `{name}`, or import the class or the namespace whose member this names."
        )
    };

    let reserved = "1:11 reserved-name-outside-library `Sharp.Fake` is a namespace of the standard library, and only the standard library declares code in it. | Declare the file in a namespace of the app.";
    for (namespace, first) in [("App.Http", None), ("Sharp.Fake", Some(reserved.to_owned()))] {
        for name in ["global", "gadget"] {
            assert_eq!(
                refusals(("app/Http/Probe.sharp", written(name, namespace)), &[]),
                first
                    .clone()
                    .into_iter()
                    .chain([unknown("5:48", name), unknown("6:29", name), unknown("7:28", name)])
                    .collect::<Vec<_>>(),
                "{namespace}"
            );
        }
    }
    assert_eq!(
        refusals(("app/Stubs/Builtins.sharp", declared("global")), &[]),
        refusals(("app/Stubs/Builtins.sharp", declared("gadget")), &[])
            .iter()
            .map(|refusal| refusal.replace("gadget", "global"))
            .collect::<Vec<_>>()
    );
    assert_ne!(refusals(("app/Stubs/Builtins.sharp", declared("global")), &[]), Vec::<String>::new());
    assert_eq!(
        issues(
            ("vendor/heyjordanparker/php-sharp-composer/library/Sharp/Probe.sharp", written("global", "Sharp")),
            &[]
        ),
        Vec::<String>::new()
    );
}

/// Spec section 23 reads a plain PHP constant through its namespace, as it calls a function: `Pdf.DEFAULT_DPI` after
/// `import Vendor.Pdf;` reads the library's, and `Pdf.VERSION` the one the library declares in PHP's root namespace
/// beside its classes, each with its type. A bare uppercase name is the code's own constant, so a bare `VERSION` and a
/// bare PHP constant are each the error a misspelled name gets. A `.php` file reads each.
#[test]
fn a_plain_php_constant_is_read_through_its_namespace() {
    let pdf = "<?php\n\nnamespace Vendor\\Pdf;\n\nconst DEFAULT_DPI = 300;\n";
    let version = "<?php\n\nconst VERSION = 2;\n";
    let document = "<?php\n\nnamespace Vendor\\Pdf;\n\nfinal class Document\n{\n}\n";
    let sharp = "namespace Demo;\n\nimport Vendor.Pdf;\n\nclass Layout\n{\n    public static int dpi() => Pdf.DEFAULT_DPI;\n    public static int release() => Pdf.VERSION;\n    public static Any? bareRelease() => VERSION;\n    public static Any? bare() => PHP_EOL;\n    public static Any? misspelled() => LAYOUT_DPI;\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nclass Layout\n{\n    public static function dpi(): int { return \\Vendor\\Pdf\\DEFAULT_DPI; }\n    public static function release(): int { return \\VERSION; }\n    public static function bareRelease(): int { return VERSION; }\n    public static function bare(string $text): string { return $text . PHP_EOL; }\n}\n";
    let others = [
        ("src/Vendor/Pdf/constants.php", pdf),
        ("src/Vendor/Pdf/version.php", version),
        ("src/Vendor/Pdf/Document.php", document),
    ];

    let undefined = |at: &str, name: &str| {
        format!(
            "{at} non-existent-constant Undefined constant: `{name}`. | Check `{name}` for typos. A bare name reads a constant of this file's namespace, declared in a `.php` file. A class constant is read through its class, as in `Limits.MAX`, and a plain PHP library's constant through its namespace, as in `Pdf.DEFAULT_DPI`."
        )
    };

    assert_eq!(
        refusals(("src/Demo/Layout.sharp", sharp), &others),
        [undefined("9:41", "VERSION"), undefined("10:34", "PHP_EOL"), undefined("11:40", "LAYOUT_DPI")]
    );
    assert_eq!(issues(("src/Demo/Layout.php", php), &others), Vec::<String>::new());
}

/// Spec section 23: a value the standard library gives is read from it, so PHP's `int` bounds are `Int.MAX` and
/// `Int.MIN`, and a bare `PHP_INT_MAX` names no constant, as a misspelled name does. The library's own `Int` reads them
/// through `global`.
#[test]
fn the_int_bounds_are_read_from_the_standard_library() {
    let int = (
        "vendor/heyjordanparker/php-sharp-composer/library/Sharp/Int.sharp",
        "namespace Sharp;\n\npublic static class Int\n{\n    public const int MAX = global.PHP_INT_MAX;\n\n    public const int MIN = global.PHP_INT_MIN;\n}\n",
    );
    let sharp = "namespace Demo;\n\nclass Bounds\n{\n    public static int largest() => Int.MAX - 1;\n    public static int smallest() => Int.MIN;\n    public static Any? bare() => PHP_INT_MAX;\n}\n";

    assert_eq!(
        refusals(("src/Demo/Bounds.sharp", sharp), &[int]),
        [
            "7:34 non-existent-constant Undefined constant: `PHP_INT_MAX`. | Check `PHP_INT_MAX` for typos. A bare name reads a constant of this file's namespace, declared in a `.php` file. A class constant is read through its class, as in `Limits.MAX`, and a plain PHP library's constant through its namespace, as in `Pdf.DEFAULT_DPI`."
        ]
    );
}

/// A `Name.member` read that reaches no constant is refused for what it names: `Pdf.NOPE` names no constant, and the
/// note names the namespace that lacks it. `Pdf.render` is a function, so its read is the function's value, spec
/// section 14.3, and `Nope` names no class and no namespace. The checker accepted each refused read before, and the
/// compile panicked on it.
#[test]
fn a_read_through_a_name_that_reaches_no_constant_is_refused() {
    let pdf = (
        "src/Vendor/Pdf/functions.php",
        "<?php\n\nnamespace Vendor\\Pdf;\n\nfunction render(string $html): string\n{\n    return $html;\n}\n",
    );
    let sharp = (
        "src/Demo/Reads.sharp",
        "namespace Demo;\n\nimport Vendor.Pdf;\n\nclass Reads\n{\n    public static Any? render() => Pdf.render;\n    public static Any? nope() => Nope.render;\n    public static Any? dpi() => Pdf.NOPE;\n}\n",
    );

    assert_eq!(
        refusals(sharp, &[pdf]),
        [
            "8:34 non-existent-class-like `Nope` names no class, and no namespace this file imports. | Check the spelling of `Nope`, or import the class or the namespace whose member this names.",
            "9:33 non-existent-constant Undefined constant: `Pdf.NOPE`. | Check `NOPE` for typos.",
        ]
    );
    let notes: Vec<Vec<String>> = analyze(&PLUGIN_REGISTRY, settings(), sharp, &[pdf])
        .iter()
        .filter(|issue| issue.message.starts_with("Undefined constant"))
        .map(|issue| issue.notes.clone())
        .collect();
    assert_eq!(notes, [vec!["The namespace `Vendor.Pdf` declares no constant `NOPE`.".to_owned()]]);
}

/// A static read or call through a name that names no class and no namespace the file imports is that name's one
/// error, the same for a read and a call, as `global.strlen(name)` gets in a project's code, and the read or call is
/// refused, so what uses it reports nothing more: no return type the analysis could not infer, and no member of the
/// missing class.
#[test]
fn a_static_member_of_a_missing_class_is_one_error() {
    let sharp = "namespace Demo;\n\nclass Reads\n{\n    public static int read() => Gadget.LIMIT;\n    public static int called() => Gadget.count();\n    public static string chained() => Gadget.make().name;\n}\n";
    let unknown = |at: &str| {
        format!(
            "{at} non-existent-class-like `Gadget` names no class, and no namespace this file imports. | Names nothing here. | Check the spelling of `Gadget`, or import the class or the namespace whose member this names."
        )
    };

    assert_eq!(worded(("src/Demo/Reads.sharp", sharp), &[]), [unknown("5:33"), unknown("6:35"), unknown("7:39")]);
}

/// A member written as an expression, `Pdf.{"render"}(html)`, names no function of the namespace, so the analysis,
/// which still reads the file, reads it as a static call. The checker refuses the member, and `mago` prints only that.
#[test]
fn a_member_written_as_an_expression_after_a_namespace_calls_no_function() {
    let pdf = "<?php\n\nnamespace Vendor\\Pdf;\n\nfunction render(string $html): string\n{\n    return $html;\n}\n";
    let sharp = "namespace Demo;\n\nimport Vendor.Pdf;\n\nclass Report\n{\n    public static void draft(string html) { Pdf.{\"render\"}(html); }\n}\n";

    assert_eq!(
        issues(("src/Demo/Report.sharp", sharp), &[("src/Vendor/Pdf/functions.php", pdf)]),
        ["7:49 non-existent-method"]
    );
}

/// A message names a plain PHP function as the `.sharp` file calls it, through its namespace: `Pdf.helper` for the
/// `helper` the library declares in PHP's root namespace beside its classes, and `Pdf.missing` for a function an
/// imported namespace lacks, which is a missing function, not a missing method.
#[test]
fn a_message_names_a_plain_php_function_as_the_file_calls_it() {
    let pdf = "<?php\n\nnamespace Vendor\\Pdf;\n\nfunction render(string $html): string\n{\n    return $html;\n}\n";
    let helpers = "<?php\n\nfunction helper(int $value): int\n{\n    return $value;\n}\n";
    let document = "<?php\n\nnamespace Vendor\\Pdf;\n\nfinal class Document\n{\n}\n";
    let sharp = "namespace Demo;\n\nimport Vendor.Pdf;\n\nclass Report\n{\n    public static void draft(string html) { Pdf.missing(html); }\n    public static int counted() => Pdf.helper(\"five\");\n}\n";
    let others = [
        ("src/Vendor/Pdf/functions.php", pdf),
        ("src/Vendor/Pdf/helpers.php", helpers),
        ("src/Vendor/Pdf/Document.php", document),
    ];

    assert_eq!(
        refusals(("src/Demo/Report.sharp", sharp), &others),
        [
            "7:49 non-existent-function Function `Pdf.missing` does not exist. | Check the spelling of `Pdf.missing`, or declare `function missing()` in a `.php` file of the namespace `Vendor.Pdf`.",
            "8:47 invalid-argument Invalid argument type for argument #1 of `Pdf.helper`: expected `int`, but found `string`. | Change the argument value to match `int`, or update the parameter's type declaration.",
        ]
    );
}

/// PHP# has no top-level functions, spec section 8, so a bare call that names no local calls nothing. A PHP built-in,
/// a library's function an imported namespace declares, one of the file's own namespace, Mago's `exit` construct and a
/// function a collection method or a PHP# form replaces are each the error a misspelled name gets, with no message that
/// recognizes the function or names what to write instead. A `.php` file calls each.
#[test]
fn a_bare_call_of_a_plain_php_function_is_the_error_a_misspelled_name_gets() {
    let pdf = "<?php\n\nnamespace Vendor\\Pdf;\n\nfunction render(string $html): string\n{\n    return $html;\n}\n";
    let tally = "<?php\n\nnamespace Demo;\n\nfunction tally(int $value): int\n{\n    return $value;\n}\n";
    let calls = [
        ("strlen", "strlen(html)"),
        ("trim", "trim(html)"),
        ("levenshtein", "levenshtein(html, html)"),
        ("render", "render(html)"),
        ("is_string", "is_string(html)"),
        ("count", "count(items)"),
        ("array_map", "array_map(f, items)"),
        ("tally", "tally(1)"),
        ("ceil", "ceil(1.5)"),
        ("strlenn", "strlenn(html)"),
    ];
    let sharp = leak(format!(
        "namespace Demo;\n\nimport Vendor.Pdf;\n\nclass Report\n{{\n{}    public static void stop() {{ exit(1); }}\n}}\n",
        calls
            .iter()
            .enumerate()
            .map(|(index, (_, call))| format!(
                "    public static Any? call{index}(string html, List<int> items, Function<int(int) uses none> f) => {call};\n"
            ))
            .collect::<Vec<_>>()
            .concat()
    ));
    let php = "<?php\n\nnamespace Demo;\n\nuse function Vendor\\Pdf\\render;\n\nclass Report\n{\n    public static function length(string $html): int { return strlen($html) + levenshtein($html, $html); }\n    public static function draft(string $html): string { return trim(render($html)); }\n    public static function text(mixed $value): bool { return is_string($value); }\n    public static function stop(): void { exit(1); }\n    public static function count(int $value): int { return tally($value); }\n}\n";
    let others = [("src/Vendor/Pdf/functions.php", pdf), ("src/Demo/functions.php", tally)];

    let column =
        "    public static Any? call0(string html, List<int> items, Function<int(int) uses none> f) => ".len() + 1;
    let expected: Vec<String> = calls
        .iter()
        .enumerate()
        .map(|(index, (name, _))| {
            format!(
                "{}:{column} non-existent-function Function `{name}` does not exist. | Check the spelling of `{name}`.",
                index + 7
            )
        })
        .chain([
            "17:33 non-existent-function Function `exit` does not exist. | Check the spelling of `exit`.".to_owned()
        ])
        .collect();

    assert_eq!(refusals(("src/Demo/Report.sharp", sharp), &others), expected);
    assert_eq!(issues(("src/Demo/Report.php", php), &others), Vec::<String>::new());
}

/// A method that only some kinds of a collection value have, as `contains` on a value that may be a `List` or a
/// `Map`, is one error: the call is refused once, so nothing that uses its result reports again.
#[test]
fn a_method_only_some_kinds_of_a_collection_value_have_is_one_error() {
    let sharp = "namespace Demo;\n\nclass Kinds\n{\n    public bool held(bool listed, List<string> names, Map<string, int> stock)\n    {\n        let held = listed ? names : stock;\n        return held.contains(\"tea\");\n    }\n\n    public int? indexed(bool listed, List<string> names, Set<string> tags)\n    {\n        let held = listed ? names : tags;\n        return held.indexOf(\"tea\");\n    }\n}\n";
    let codes: Vec<String> = refusals(("src/Demo/Kinds.sharp", sharp), &[])
        .into_iter()
        .map(|refusal| refusal.split(' ').take(2).collect::<Vec<_>>().join(" "))
        .collect();

    assert_eq!(codes, ["8:21 non-existent-method", "14:21 non-existent-method"]);
}

/// Spec section 29: a `.sharp` file's call of a plain PHP function has the effects its `extern` declares, so a call of
/// `Shell.variable`, which uses `Environment`, is never a pure call whose result goes unused.
#[test]
fn a_call_of_a_function_whose_extern_declares_an_effect_is_never_unused() {
    let functions = (
        "src/Vendor/Shell/functions.php",
        "<?php\n\nnamespace Vendor\\Shell;\n\n/** @pure */\nfunction variable(string $name): string|false\n{\n    return getenv($name);\n}\n",
    );
    let stub = (
        "app/Stubs/Shell.sharp",
        "namespace App.Stubs;\n\nimport Vendor.Shell;\n\nextern Shell.variable uses Environment;\n",
    );
    let sharp = "namespace Demo;\n\nimport Vendor.Shell;\n\nclass Runner\n{\n    public void run(string name)\n    {\n        Shell.variable(name);\n    }\n}\n";
    let unused = |others: &[(&'static str, &'static str)]| -> Vec<String> {
        issues(("src/Demo/Runner.sharp", sharp), others).into_iter().filter(|issue| issue.contains("unused")).collect()
    };

    assert_eq!(unused(&[functions, stub]), Vec::<String>::new());
    // The library's own docblock calls the function pure, which only a declared effect corrects.
    assert_eq!(unused(&[functions]), ["9:9 unused-statement"]);
}

/// Spec section 7: `Math.max(0, ...prices)` gives 0 for an empty list, and the empty list may be written `[]`.
#[test]
fn a_spread_of_an_empty_list_passes_no_values() {
    let math = "namespace Sharp.Math;\n\npublic static class Math\n{\n    public static int max(int first, int ...rest) => global.max([first, ...rest]);\n}\n";
    let library = [("vendor/heyjordanparker/php-sharp-composer/library/Sharp/Math/Math.sharp", math)];
    let sharp = "namespace Demo;\n\nimport Sharp.Math.Math;\n\nclass Sizes\n{\n    public static int largest() => Math.max(0, ...[]);\n}\n";

    assert_eq!(refusals(("src/Demo/Sizes.sharp", sharp), &library), Vec::<String>::new());
}

/// Spec section 23: an import names a class, or the namespace of a plain PHP library's functions, never one function.
/// A `.php` file imports a function with `use function`. One of PHP's own functions belongs to no library, so its import
/// names nothing PHP# code imports, as a misspelled name does.
#[test]
fn an_import_of_one_function_is_refused_with_the_namespace_to_import() {
    let pdf = "<?php\n\nnamespace Vendor\\Pdf;\n\nfunction render(string $html): string\n{\n    return $html;\n}\n";
    let sharp = "namespace Demo;\n\nimport Vendor.Pdf.render;\n\nclass Draft\n{\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nuse function Vendor\\Pdf\\render;\n\nclass Draft\n{\n}\n";
    let others = [("src/Vendor/Pdf/functions.php", pdf)];

    assert_eq!(
        refusals(("src/Demo/Draft.sharp", sharp), &others),
        [
            "3:8 function-import An import names a class or a namespace, not a function: import `Vendor.Pdf`, and call `Pdf.render(…)`. | "
        ]
    );
    assert_eq!(issues(("src/Demo/Draft.php", php), &others), Vec::<String>::new());

    let root = "namespace Demo;\n\nimport strlen;\n\nclass Draft\n{\n}\n";
    assert_eq!(
        refusals(("src/Demo/Draft.sharp", root), &[]),
        [
            "3:8 non-existent-use-import Imported class, interface, trait, or enum `strlen` does not exist. | Ensure that the class, interface, trait, or enum `strlen` is defined in the codebase."
        ]
    );
}

/// Spec section 31 makes an exception a bug and an expected failure a `Result`, so PHP# declares no thrown exceptions.
#[test]
fn check_throws_skips_sharp_files_and_keeps_reporting_in_php() {
    let vault = "<?php\n\nnamespace Lib;\n\nfinal class Vault\n{\n    /** @throws \\RuntimeException */\n    public static function seal(string $text): string\n    {\n        throw new \\RuntimeException($text);\n    }\n}\n";
    let sharp = "namespace Demo;\n\nimport Lib.Vault;\n\nclass Report\n{\n    public static string token()\n    {\n        return Vault.seal(\"a\");\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nuse Lib\\Vault;\n\nclass Report\n{\n    public static function token(): string\n    {\n        return Vault::seal('a');\n    }\n}\n";
    let others = [("src/Lib/Vault.php", vault)];

    assert_eq!(issues(("src/Demo/Report.sharp", sharp), &others), Vec::<String>::new());
    assert_eq!(issues(("src/Demo/Report.php", php), &others), ["11:16 unhandled-thrown-type"]);
}

/// Jordan's ruling of 10-18 on loop names: `break orders;` leaves the loop named `orders` from a loop inside it, so a
/// `while (true)` that only a named `break` leaves ends, and the code after it runs with what the loop gave its locals.
/// `continue orders;` goes on with the named loop, so an inner `while (true)` that only continues it never ends, and
/// the statement after it in the named loop never runs.
#[test]
fn a_named_break_or_continue_leaves_or_continues_the_loop_it_names() {
    let sharp = "namespace Demo;\n\nclass Flow\n{\n    public static int breaksOuter(List<int> items)\n    {\n        let found = 0;\n        orders: while (true) {\n            for (const item of items) {\n                found = item;\n                break orders;\n            }\n        }\n        return found;\n    }\n\n    public static void continuesOuter(bool again)\n    {\n        orders: do {\n            while (true) {\n                continue orders;\n            }\n            Halt.note(\"never\");\n        } while (again);\n    }\n\n    public static int leavesInner(bool again, bool more)\n    {\n        let rounds = 0;\n        while (again) {\n            do {\n                break;\n            } while (more);\n            rounds = rounds + 1;\n            again = rounds < 3;\n        }\n        return rounds;\n    }\n}\n";
    let halt = "<?php\n\nnamespace Demo;\n\nfinal class Halt\n{\n    public static function note(int|string $value): void\n    {\n    }\n}\n";

    assert_eq!(
        refusals(("src/Demo/Flow.sharp", sharp), &[("src/Demo/Halt.php", halt)]),
        [
            "23:13 unevaluated-code This statement never runs, because line 20 ends the block. | Delete it, or move it above line 20."
        ]
    );

    // A plain PHP level that is no integer literal says nothing about which loop the jump leaves, so the code after
    // the inner `foreach` still runs.
    let php = "<?php\n\nnamespace Demo;\n\nfinal class Levels\n{\n    public static function run(int $levels): int\n    {\n        while ($levels > 0) {\n            foreach ([1, 2] as $step) {\n                break $levels;\n            }\n            $levels--;\n        }\n        return $levels;\n    }\n}\n";
    assert_eq!(issues(("src/Demo/Levels.php", php), &[]), ["11:23 invalid-break"]);
}

/// A loop whose body always leaves past it, through `return`, or a `break` or `continue` that names a loop around it,
/// never checks its condition after a pass, so it ends only when the condition fails before the first one: the code
/// after it runs with what the locals held before the loop, narrowed by the failed condition, and never with `never`.
/// Plain PHP's `break 2` and `continue 2` are the same.
#[test]
fn a_loop_whose_body_always_leaves_past_it_ends_with_the_locals_it_began_with() {
    let sharp = "namespace Demo;\n\nclass Rows\n{\n    public static int named(List<int> rows, int? limit)\n    {\n        let total = 0;\n        orders: for (const row of rows) {\n            while (limit != null) {\n                total = row + limit;\n                break orders;\n            }\n            Rows.note(limit);\n        }\n        return total;\n    }\n\n    public static int returned(List<int> rows, int? limit)\n    {\n        for (const row of rows) {\n            while (limit != null) {\n                return row + limit;\n            }\n            Rows.note(limit);\n        }\n        return 0;\n    }\n\n    public static int continued(List<int> rows, int? limit)\n    {\n        let total = 0;\n        orders: for (const row of rows) {\n            while (limit != null) {\n                total = row + limit;\n                continue orders;\n            }\n            Rows.note(limit);\n        }\n        return total;\n    }\n\n    public static int stepped(List<int> rows, int? limit)\n    {\n        let total = 0;\n        orders: for (const row of rows) {\n            for (let step = 0; limit != null; step++) {\n                total = row + step;\n                continue orders;\n            }\n            Rows.note(limit);\n        }\n        return total;\n    }\n\n    private static void note(int? limit)\n    {\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nfinal class Rows\n{\n    /** @param list<int> $rows */\n    public static function levels(array $rows, ?int $limit): int\n    {\n        $total = 0;\n        foreach ($rows as $row) {\n            while ($limit !== null) {\n                $total = $row + $limit;\n                break 2;\n            }\n            self::none($limit);\n        }\n        return $total;\n    }\n\n    public static function returned(?int $limit): int\n    {\n        while ($limit !== null) {\n            return $limit;\n        }\n        self::none($limit);\n        return 0;\n    }\n\n    public static function passes(?int $limit): void\n    {\n        while ($limit !== null) {\n            $limit = $limit > 3 ? null : $limit + 1;\n        }\n        self::none($limit);\n    }\n\n    /** @param list<int> $rows */\n    public static function continued(array $rows, ?int $limit): int\n    {\n        $total = 0;\n        foreach ($rows as $row) {\n            while ($limit !== null) {\n                $total = $row + $limit;\n                continue 2;\n            }\n            self::none($limit);\n        }\n        return $total;\n    }\n\n    private static function none(null $limit): void\n    {\n    }\n}\n";

    assert_eq!(
        (issues(("src/Demo/Rows.sharp", sharp), &[]), issues(("src/Demo/Rows.php", php), &[])),
        (Vec::<String>::new(), Vec::<String>::new())
    );
}

/// A loop never ends on its condition only when that condition is the constant `true`, judged from its words before any
/// pass, as TypeScript and Kotlin judge it: a `for` whose condition is `true` never ends, as `while (true)` doesn't, so
/// it needs no `return` after it, and a `do … while` on a `bool` local ends once the local is false, whatever the last
/// pass narrowed it to, so the statement after it runs. Plain PHP's loops are the same.
#[test]
fn a_loop_never_ends_on_its_condition_only_when_the_condition_is_true() {
    let sharp = "namespace Demo;\n\nclass Passes\n{\n    public static int again(bool again)\n    {\n        let passes = 0;\n        do {\n            passes = passes + 1;\n        } while (again);\n        return passes;\n    }\n\n    public static int counted()\n    {\n        for (let step = 0; true; step++) {\n            return step;\n        }\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nfinal class Passes\n{\n    public static function again(bool $again): int\n    {\n        $passes = 0;\n        do {\n            $passes = $passes + 1;\n        } while ($again);\n        return $passes;\n    }\n\n    public static function counted(): int\n    {\n        for ($step = 0; true; $step++) {\n            return $step;\n        }\n    }\n}\n";

    assert_eq!(
        (refusals(("src/Demo/Passes.sharp", sharp), &[]), issues(("src/Demo/Passes.php", php), &[])),
        (Vec::<String>::new(), Vec::<String>::new())
    );
}

/// Spec section 7 refuses a statement that can never run, as Java and Zig do: one after `return`, `throw`, a call that
/// never returns, `break` or `continue` in its block, one after an `if` whose every branch ends the block, one after
/// a loop that never ends, and a block after a condition that never finishes, which is refused at the condition. The
/// first statement that never runs is refused once for its block, naming the line that ends the block, and a bare call
/// that never runs is refused for that alone. `finally`, a `catch`, and code after a loop that breaks or an `if` with no
/// `else` all run. A `.php` file keeps Mago's help.
#[test]
fn a_statement_that_can_never_run_is_refused() {
    let sharp = "namespace Demo;\n\nimport RuntimeException;\n\nclass Flow\n{\n    public static int afterReturn()\n    {\n        return 1;\n        return 2;\n    }\n\n    public static int afterThrow()\n    {\n        throw new RuntimeException(\"no\");\n        return 3;\n    }\n\n    public static void afterNever()\n    {\n        Halt.now();\n        return;\n    }\n\n    public static void afterBreak()\n    {\n        while (true) {\n            break;\n            Halt.note(\"never\");\n        }\n    }\n\n    public static void afterContinue(List<int> items)\n    {\n        for (const item of items) {\n            continue;\n            Halt.note(item);\n        }\n    }\n\n    public static int bareCall()\n    {\n        return 4;\n        strlen(\"never\");\n    }\n\n    public static int afterEveryBranch(bool up)\n    {\n        if (up) {\n            return 5;\n        } else {\n            return 6;\n        }\n        return 7;\n    }\n\n    public static void conditionNeverFinishes()\n    {\n        if (Halt.now()) {\n            Halt.note(\"never\");\n        }\n    }\n\n    public static int afterReturnThree()\n    {\n        return 8;\n        Halt.note(\"one\");\n        Halt.note(\"two\");\n        Halt.note(\"three\");\n    }\n\n    public static int doNeverEnds(bool again)\n    {\n        do {\n            return 9;\n        } while (again);\n        return 10;\n    }\n\n    public static int loopNeverEnds()\n    {\n        while (true) {\n            Halt.note(\"again\");\n        }\n        return 11;\n    }\n\n    public static int finallyAfterReturn()\n    {\n        try {\n            return 12;\n        } finally {\n            Halt.note(\"done\");\n        }\n    }\n\n    public static int afterLoopWithBreak()\n    {\n        while (true) {\n            break;\n        }\n        return 13;\n    }\n\n    public static int afterIfWithoutElse(bool up)\n    {\n        if (up) {\n            return 14;\n        }\n        return 15;\n    }\n\n    public static int catchAfterReturningTry()\n    {\n        try {\n            return 16;\n        } catch (RuntimeException failure) {\n            return 17;\n        }\n    }\n\n    public static int doThatBreaks(bool stop, bool again)\n    {\n        do {\n            if (stop) {\n                break;\n            }\n            return 18;\n        } while (again);\n        return 19;\n    }\n\n    public static void conditionNeverFinishesWithElse()\n    {\n        if (Halt.now()) {\n            Halt.note(\"never\");\n        } else {\n            Halt.note(\"never either\");\n        }\n    }\n\n    public static void iterableNeverFinishes()\n    {\n        for (const item of Halt.now()) {\n            Halt.note(\"never\");\n        }\n    }\n\n    public static void whileConditionNeverFinishes()\n    {\n        while (Halt.now()) {\n            Halt.note(\"never\");\n        }\n        Halt.note(\"after\");\n    }\n\n    public static void forConditionNeverFinishes()\n    {\n        for (int step = 0; Halt.now(); step++) {\n            Halt.note(\"never\");\n        }\n        Halt.note(\"after\");\n    }\n\n    public static void neverInForOfBody(List<int> items)\n    {\n        for (const item of items) {\n            Halt.now();\n            Halt.note(item);\n        }\n    }\n\n    public static void neverInWhileBody(bool again)\n    {\n        while (again) {\n            Halt.now();\n            Halt.note(\"never\");\n        }\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nclass Flow\n{\n    public static function afterReturn(): int\n    {\n        return 1;\n        return 2;\n    }\n}\n";
    let halt = "<?php\n\nnamespace Demo;\n\nfinal class Halt\n{\n    public static function now(): never\n    {\n        exit(1);\n    }\n\n    public static function note(int|string $value): void\n    {\n    }\n}\n";

    assert_eq!(
        refusals(("src/Demo/Flow.sharp", sharp), &[("src/Demo/Halt.php", halt)]),
        [
            "10:9 unevaluated-code This statement never runs, because line 9 ends the block. | Delete it, or move it above line 9.",
            "16:9 unevaluated-code This statement never runs, because line 15 ends the block. | Delete it, or move it above line 15.",
            "22:9 unevaluated-code This statement never runs, because line 21 ends the block. | Delete it, or move it above line 21.",
            "29:13 unevaluated-code This statement never runs, because line 28 ends the block. | Delete it, or move it above line 28.",
            "37:13 unevaluated-code This statement never runs, because line 36 ends the block. | Delete it, or move it above line 36.",
            "44:9 unevaluated-code This statement never runs, because line 43 ends the block. | Delete it, or move it above line 43.",
            "54:9 unevaluated-code This statement never runs, because line 49 ends the block. | Delete it, or move it above line 49.",
            "59:13 unevaluated-code This condition never finishes, so its block never runs. | Write `Halt.now();` as its own statement, and delete the `if`.",
            "67:9 unevaluated-code This statement never runs, because line 66 ends the block. | Delete it, or move it above line 66.",
            "77:9 unevaluated-code This statement never runs, because line 74 ends the block. | Delete it, or move it above line 74.",
            "85:9 unevaluated-code This statement never runs, because line 82 ends the block. | Delete it, or move it above line 82.",
            "135:13 unevaluated-code This condition never finishes, so its block never runs. | Write `Halt.now();` as its own statement, and delete the `if`.",
            "144:28 unevaluated-code This condition never finishes, so its block never runs. | Write `Halt.now();` as its own statement, and delete the `for`.",
            "151:16 unevaluated-code This condition never finishes, so its block never runs. | Write `Halt.now();` as its own statement, and delete the `while`.",
            "154:9 unevaluated-code This statement never runs, because line 151 ends the block. | Delete it, or move it above line 151.",
            "159:28 unevaluated-code This condition never finishes, so its block never runs. | Write `Halt.now();` as its own statement, and delete the `for`.",
            "162:9 unevaluated-code This statement never runs, because line 159 ends the block. | Delete it, or move it above line 159.",
            "169:13 unevaluated-code This statement never runs, because line 168 ends the block. | Delete it, or move it above line 168.",
            "177:13 unevaluated-code This statement never runs, because line 176 ends the block. | Delete it, or move it above line 176.",
        ]
    );
    assert_eq!(
        refusals(("src/Demo/Flow.php", php), &[]),
        ["10:9 unevaluated-code Unreachable code detected. | Consider removing this unreachable code."]
    );
}

#[test]
fn a_template_is_a_string_as_php_interpolation_is() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public static string label(int count, string name)\n    {\n        return `${name} has ${count + 1} items`;\n    }\n\n    public static int size(string name)\n    {\n        return `${name}`;\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nclass Report\n{\n    public static function label(int $count, string $name): string\n    {\n        return \"{$name} has \" . ($count + 1) . \" items\";\n    }\n\n    public static function size(string $name): int\n    {\n        return \"{$name}\";\n    }\n}\n";

    assert_eq!(issues(("src/Demo/Report.sharp", sharp), &[]), ["12:16 invalid-return-statement"]);
    assert_eq!(issues(("src/Demo/Report.php", php), &[]), ["14:16 invalid-return-statement"]);
}

/// A call of a function an imported namespace lacks is reported as PHP reports it, and a library that declares the
/// function in PHP's root namespace beside the namespace's classes makes the call compile, spec section 23.
#[test]
fn calling_a_function_that_does_not_exist_is_reported_as_in_php() {
    let pdf = (
        "src/Vendor/Pdf/functions.php",
        "<?php\n\nnamespace Vendor\\Pdf;\n\nfunction render(string $html): string\n{\n    return $html;\n}\n",
    );
    let sharp = "namespace Demo;\n\nimport Vendor.Pdf;\n\nclass Report\n{\n    public static int total(int extra)\n    {\n        return Pdf.missing(extra);\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nclass Report\n{\n    public static function total(int $extra): int\n    {\n        return \\Vendor\\Pdf\\missing($extra);\n    }\n}\n";

    let sharp_issues = issues(("src/Demo/Report.sharp", sharp), &[pdf]);
    let php_issues = issues(("src/Demo/Report.php", php), &[pdf]);

    assert_eq!(sharp_issues, ["9:20 non-existent-function", "9:16 mixed-return-statement"]);
    assert_eq!(codes(&sharp_issues), codes(&php_issues));
    assert_eq!(
        refusals(("src/Demo/Report.sharp", sharp), &[pdf])[0],
        "9:20 non-existent-function Function `Pdf.missing` does not exist. | Check the spelling of `Pdf.missing`, or declare `function missing()` in a `.php` file of the namespace `Vendor.Pdf`."
    );

    let declared =
        ("src/Vendor/Pdf/helpers.php", "<?php\n\nfunction missing(int $value): int\n{\n    return $value;\n}\n");
    let document = ("src/Vendor/Pdf/Document.php", "<?php\n\nnamespace Vendor\\Pdf;\n\nfinal class Document\n{\n}\n");
    assert_eq!(issues(("src/Demo/Report.sharp", sharp), &[pdf, declared, document]), Vec::<String>::new());
}

/// A method that wraps the PHP function of its own name calls it as `global.ceil(x)`, which never reaches the method.
#[test]
fn a_global_call_named_like_a_method_of_its_class_calls_the_php_function() {
    let sharp = "namespace Sharp.Math;\n\npublic static class Math\n{\n    public static float ceil(float x) => global.ceil(x);\n\n    public static int count(List<int> values) => global.count(values);\n}\n";

    assert_eq!(
        issues(("vendor/heyjordanparker/php-sharp-composer/library/Sharp/Math/Math.sharp", sharp), &[]),
        Vec::<String>::new()
    );
}

#[test]
fn a_bare_call_of_a_method_that_no_function_shares_names_the_member_to_write() {
    let sharp = "namespace Demo;\n\nclass Calc\n{\n    public static int total() => 1;\n\n    public static int run() => total();\n\n    public int size() => 1;\n\n    public int measure() => Size();\n}\n";
    let analyzed = ("src/Demo/Calc.sharp", sharp);

    assert_eq!(
        messages(analyzed, &[]),
        [
            "Write `Calc.total()`: a static method reaches the members of its class through the class name.",
            "Could not infer a precise return type for method `Calc.run`. Saw type `Any?`.",
            "Write `this.size()`: members of the same object are always written with `this.`.",
            "Could not infer a precise return type for method `Calc.measure`. Saw type `Any?`.",
        ]
    );
    assert_eq!(
        issues(analyzed, &[]),
        [
            "7:32 non-existent-function",
            "7:32 mixed-return-statement",
            "11:29 non-existent-function",
            "11:29 mixed-return-statement",
        ]
    );

    let php = "<?php\n\nnamespace Demo;\n\nclass Calc\n{\n    public static function total(): int { return 1; }\n\n    public static function run(): int { return total(); }\n\n    public function size(): int { return 1; }\n\n    public function measure(): int { return Size(); }\n}\n";
    assert_eq!(
        messages(("src/Demo/Calc.php", php), &[])
            .into_iter()
            .filter(|message| message.starts_with("Could not find definition"))
            .collect::<Vec<_>>(),
        [
            "Could not find definition for function `Demo\\total` (also tried as `total` in a broader scope).",
            "Could not find definition for function `Demo\\Size` (also tried as `Size` in a broader scope).",
        ]
    );
}

#[test]
fn plus_joins_two_strings_into_the_string_dot_gives_in_php() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public static int total(string name)\n    {\n        const label = \"Order \" + name + `!`;\n        let line = label;\n        line += \"\\n\";\n        return line;\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nclass Report\n{\n    public static function total(string $name): int\n    {\n        $label = \"Order \" . $name . \"!\";\n        $line = $label;\n        $line .= \"\\n\";\n        return $line;\n    }\n}\n";

    assert_eq!(issues(("src/Demo/Report.sharp", sharp), &[]), ["10:16 invalid-return-statement"]);
    assert_eq!(issues(("src/Demo/Report.php", php), &[]), ["12:16 invalid-return-statement"]);
}

/// `int ** int` is an `int` in PHP# as in PHP, whatever the exponent. An `int` raised to a negative int literal always
/// throws `ArithmeticError` in PHP#, as spec section 24 decides, so `**` and `**=` refuse it once, wherever it lands,
/// and quote the fix. A float base, or an exponent the code cannot know, compiles.
#[test]
fn exponentiation_has_the_type_it_has_in_php_and_refuses_an_int_raised_to_a_negative_literal() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public static int power(int base, int exponent, float rate)\n    {\n        let result = base ** exponent;\n        result **= 2;\n        return result + rate ** 2;\n    }\n\n    public static float negative(int base, float rate)\n    {\n        let half = 2 ** -1;\n        let third = base ** -3;\n        let result = base;\n        result **= -2;\n        return rate ** -2 + half + third + result;\n    }\n\n    public float half() => 2 ** -1;\n}\n";

    assert_eq!(
        worded(("src/Demo/Report.sharp", sharp), &[]),
        [
            "9:16 invalid-return-statement Invalid return type for method `Report.power`: expected `int`, but found `float`. | This has type `float` | The type `float` returned here is not compatible with the declared return type `int`. | Change the return value to match `int`, or update the method's return type declaration.",
            "14:20 invalid-operand `2 ** -1` is an `int` raised to a negative power, which throws: write `2.0 ** -1` | This throws `ArithmeticError`.",
            "15:21 invalid-operand `base ** -3` is an `int` raised to a negative power, which throws: write `((float) base) ** -3` | This throws `ArithmeticError`.",
            "17:9 invalid-operand `result **= -2` is an `int` raised to a negative power, which throws: make `result` a `float` | This throws `ArithmeticError`.",
            "21:28 invalid-operand `2 ** -1` is an `int` raised to a negative power, which throws: write `2.0 ** -1` | This throws `ArithmeticError`.",
        ]
    );
}

/// Spec section 24 truncates `/` on two integers toward zero, so in PHP# it gives an `int`, as `/=` does on an `int`
/// field. PHP gives `float|int`, which an `int` hook or field refuses.
#[test]
fn division_of_two_ints_gives_an_int_in_php_sharp_and_float_or_int_in_php() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    private int total = 7;\n\n    public int half => this.total / 2;\n\n    public int shrink(int by)\n    {\n        this.total /= by;\n        return this.total;\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nclass Report\n{\n    private int $total = 7;\n\n    public int $half { get => $this->total / 2; }\n\n    public function shrink(int $by): int\n    {\n        $this->total /= $by;\n        return $this->total;\n    }\n}\n";

    assert_eq!(issues(("src/Demo/Report.sharp", sharp), &[]), Vec::<String>::new());
    assert_eq!(
        issues(("src/Demo/Report.php", php), &[]),
        ["9:31 invalid-return-statement", "13:25 invalid-property-assignment-value"]
    );
}

/// A `float` operand keeps `/` a float division in PHP#, as spec section 24 says.
#[test]
fn division_with_a_float_operand_gives_a_float_in_php_sharp() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public float share(int total, float parts) => total / parts;\n\n    public int whole(int total, float parts) => total / parts;\n}\n";

    assert_eq!(codes(&issues(("src/Demo/Report.sharp", sharp), &[])), ["invalid-return-statement"]);
}

const CELL: &str = "<?php\n\nnamespace Lib;\n\n/** @template T */\nfinal class Cell\n{\n    /** @param T $item */\n    public function __construct(private mixed $item) {}\n\n    /** @param T $item */\n    public function put(mixed $item): void\n    {\n        $this->item = $item;\n    }\n\n    /** @return T */\n    public function get(): mixed\n    {\n        return $this->item;\n    }\n}\n";

const BOXES: &str = "<?php\n\nnamespace Lib;\n\n/** @template-covariant T */\nfinal class Box\n{\n    /** @param T $item */\n    public function __construct(public readonly mixed $item) {}\n}\n\nfinal class Boxes\n{\n    /** @param Box<float> $box */\n    public static function unbox(Box $box): float\n    {\n        return $box->item;\n    }\n\n    /** @param iterable<float> $values */\n    public static function total(iterable $values): float\n    {\n        $sum = 0.0;\n        foreach ($values as $value) {\n            $sum += $value;\n        }\n\n        return $sum;\n    }\n}\n";

/// The issues of `analyzed`, each as its position, its code and its message, without the annotations.
fn titled(analyzed: (&'static str, &'static str), others: &[(&'static str, &'static str)]) -> Vec<String> {
    analyze(&PLUGIN_REGISTRY, settings(), analyzed, others)
        .iter()
        .map(|issue| format!("{} {}", located(analyzed.1, issue), issue.message))
        .collect()
}

/// Spec section 24 refuses an `int` where a `float` is expected in PHP# code, wherever the value lands. Each place
/// reports it once, at the value, with the issue code it gives any value of the wrong type, a `float` type argument too,
/// written on a call or on `new` and carried to a method. One row per place, one line each.
#[test]
fn an_int_where_a_float_is_expected_is_refused_in_every_place_with_its_code() {
    let sharp = "namespace Demo;\n\nimport Lib.Cell;\n\nclass Report\n{\n    public const float RATE = 10;\n    public static float shared = 0.5;\n    public float rate = 5;\n    private Map<string, float> rates = [:];\n    public float computed => 9;\n\n    public float local() { float total = 0; total = 3; return total; }\n    public void field() { this.rate = 2; }\n    public void sharedField() { Report.shared = 11; }\n    public float scale(float by = 2) => by;\n    public float argument() => this.scale(3);\n    public float returned() { return 0; }\n    public List<float> list() { List<float> prices = [1, 2.5]; return prices; }\n    public Map<string, float> map() { Map<string, float> prices = [\"tea\": 4]; return prices; }\n    public float? nullable() { float? discount = 1; return discount; }\n    public float|string either() { float|string label = 7; return label; }\n    public float template() { const cell = new Cell<float>(0.5); cell.put(2); return cell.get(); }\n    public List<float> added() { List<float> prices = []; prices.add(6); return prices; }\n    public Map<string, float> keyed() { Map<string, float> prices = [:]; prices[\"tea\"] = 8; return prices; }\n    public Map<string, float> keyedField() { this.rates[\"a\"] = 2; return this.rates; }\n    public static T same<T>(T value) => value;\n    public float written() => Report.same<float>(3);\n    public float boxed() { const box = new Box<float>(1); box.put(2); return box.value; }\n}\n\nclass Box<TValue>\n{\n    public Box(public TValue value { get; }) { }\n    public void put(TValue value) { }\n}\n";

    assert_eq!(
        worded(("src/Demo/Report.sharp", sharp), &[("src/Lib/Cell.php", CELL)]),
        [
            "7:31 invalid-constant-value `int` is not `float`: write 10.0 | Declared `float`.",
            "9:25 invalid-property-default-value `int` is not `float`: write 5.0 | Declared `float`.",
            "11:30 invalid-return-statement `int` is not `float`: write 9.0 | Declared `float`.",
            "13:42 invalid-local-assignment-value `int` is not `float`: write 0.0 | Declared `float`.",
            "13:53 invalid-local-assignment-value `int` is not `float`: write 3.0 | Declared `float`.",
            "14:39 invalid-property-assignment-value `int` is not `float`: write 2.0 | Declared `float`.",
            "15:49 invalid-property-assignment-value `int` is not `float`: write 11.0 | Declared `float`.",
            "16:35 invalid-parameter-default-value `int` is not `float`: write 2.0 | Declared `float`.",
            "17:43 invalid-argument `int` is not `float`: write 3.0 | Declared `float`.",
            "18:38 invalid-return-statement `int` is not `float`: write 0.0 | Declared `float`.",
            "19:55 invalid-local-assignment-value `int` is not `float`: write 1.0 | Declared `List<float>`.",
            "20:75 invalid-local-assignment-value `int` is not `float`: write 4.0 | Declared `Map<string, float>`.",
            "21:50 invalid-local-assignment-value `int` is not `float`: write 1.0 | Declared `float?`.",
            "22:57 invalid-local-assignment-value `int` is not `float`: write 7.0 | Declared `float|string`.",
            "23:75 invalid-argument `int` is not `float`: write 2.0 | Declared `float`.",
            "24:70 invalid-argument `int` is not `float`: write 6.0 | Declared `float`.",
            "25:90 invalid-local-assignment-value `int` is not `float`: write 8.0 | Declared `Map<string, float>`.",
            "26:64 invalid-property-assignment-value `int` is not `float`: write 2.0 | Declared `Map<string, float>`.",
            "28:50 invalid-argument `int` is not `float`: write 3.0 | Declared `float`.",
            "29:55 invalid-argument `int` is not `float`: write 1.0 | Declared `float`.",
            "29:67 invalid-argument `int` is not `float`: write 2.0 | Declared `float`.",
        ]
    );
}

/// The refusal quotes the one fix for the code written, as rustc's E0308 help does: an int literal's float form,
/// with the digits a decimal literal is written with, or a cast around the expression, wrapped in parentheses when
/// the cast would bind to less than all of it. A value written over several lines is quoted on one line.
#[test]
fn an_int_where_a_float_is_expected_is_refused_with_the_fix_for_the_code_written() {
    let sharp = "namespace Demo;\n\nclass Line\n{\n    public int quantity = 1;\n    public const int LIMIT = 9;\n}\n\nclass Report\n{\n    private Line line;\n\n    public Report(Line line) { this.line = line; }\n\n    public int size() => 4;\n\n    public float zero() => 0;\n    public float negative() => -3;\n    public float million() => 1_000_000;\n    public float hex() => 0x1F;\n    public float local(int count) => count;\n    public float chain() => this.line.quantity;\n    public float call() => this.size();\n    public float sum(int a, int b) => a + b;\n    public float difference(int a, int b) => (a - b);\n    public float largest() => Line.LIMIT;\n    public float negated(int count) => -count;\n    public float chosen(bool flag) => flag ? 3 : 2.0;\n    public float fallback(int? n) => n ?? 0;\n    public float matched(int n) => match (n) {\n        1 => 10,\n        default => 20,\n    };\n}\n";

    assert_eq!(
        worded(("src/Demo/Report.sharp", sharp), &[]),
        [
            "17:28 invalid-return-statement `int` is not `float`: write 0.0 | Declared `float`.",
            "18:32 invalid-return-statement `int` is not `float`: write -3.0 | Declared `float`.",
            "19:31 invalid-return-statement `int` is not `float`: write 1_000_000.0 | Declared `float`.",
            "20:27 invalid-return-statement `int` is not `float`: write 31.0 | Declared `float`.",
            "21:38 invalid-return-statement `int` is not `float`: convert with (float) count | Declared `float`.",
            "22:29 invalid-return-statement `int` is not `float`: convert with (float) this.line.quantity | Declared `float`.",
            "23:28 invalid-return-statement `int` is not `float`: convert with (float) this.size() | Declared `float`.",
            "24:39 invalid-return-statement `int` is not `float`: convert with (float) (a + b) | Declared `float`.",
            "25:46 invalid-return-statement `int` is not `float`: convert with (float) (a - b) | Declared `float`.",
            "26:31 invalid-return-statement `int` is not `float`: convert with (float) Line.LIMIT | Declared `float`.",
            "27:40 invalid-return-statement `int` is not `float`: convert with (float) -count | Declared `float`.",
            "28:39 invalid-return-statement `int` is not `float`: convert with (float) (flag ? 3 : 2.0) | Declared `float`.",
            "29:38 invalid-return-statement `int` is not `float`: convert with (float) (n ?? 0) | Declared `float`.",
            "30:36 invalid-return-statement `int` is not `float`: convert with (float) (match (n) { 1 => 10, default => 20, }) | Declared `float`.",
        ]
    );
}

/// The refusal names the `int` only when it is the one reason the value does not fit. A value that may be another
/// type, a literal with another refused element in either order, and a collection, an object or a function whose
/// element, type argument, return type or parameter is the `int` each keep the message any value of the wrong type
/// gets in its place.
#[test]
fn a_value_refused_for_more_than_an_int_keeps_the_message_of_its_place() {
    let sharp = "namespace Demo;\n\nimport Lib.Box;\nimport Lib.Boxes;\n\nclass Report\n{\n    public float either(int|string value) => value;\n    public List<float> intFirst() => [1, \"a\"];\n    public List<float> stringFirst() => [\"a\", 1];\n    public float boxed() => Boxes.unbox(new Box<int>(1));\n    public float total(List<int> ints) => Boxes.total(ints);\n    public float|List<float> collection(int|List<int> value) => value;\n    public float|Function<float()> callable(int|Function<int()> value) => value;\n    public Function<float(int)> half() => (float amount) => amount / 2.0;\n}\n";

    assert_eq!(
        titled(("src/Demo/Report.sharp", sharp), &[("src/Lib/Boxes.php", BOXES)]),
        [
            "8:46 invalid-return-statement Invalid return type for method `Report.either`: expected `float`, but found `int|string`.",
            "9:38 invalid-return-statement Invalid return type for method `Report.intFirst`: expected `List<float>`, but found `List<int|string>`.",
            "10:41 invalid-return-statement Invalid return type for method `Report.stringFirst`: expected `List<float>`, but found `List<int|string>`.",
            "11:41 possibly-invalid-argument Possible argument type mismatch for argument #1 of `Boxes.unbox`: expected `Box<float>`, but possibly received `Box<int>`.",
            "12:55 possibly-invalid-argument Possible argument type mismatch for argument #1 of `Boxes.total`: expected `Iterable<float>`, but possibly received `List<int>`.",
            "13:65 invalid-return-statement Invalid return type for method `Report.collection`: expected `float|List<float>`, but found `int|List<int>`.",
            "14:75 invalid-return-statement Invalid return type for method `Report.callable`: expected `float|Function<float()>`, but found `int|Function<int()>`.",
            "15:43 invalid-return-statement Invalid return type for method `Report.half`: expected `Function<float(int)>`, but found `Function<float(float)>`.",
        ]
    );
}

/// A float, a written conversion, arithmetic with a float, an `int|float` place and a float in a template slot each
/// land where a `float` is expected with no issue.
#[test]
fn a_float_a_written_conversion_and_mixed_arithmetic_land_where_a_float_is_expected() {
    let sharp = "namespace Demo;\n\nimport Lib.Cell;\n\nclass Report\n{\n    public float run(int count, int n)\n    {\n        float total = 0.0;\n        float price = (float) count;\n        float half = count * 1.5;\n        int|float either = 1;\n        const cell = new Cell<float>(2.0);\n        cell.put(2.0);\n        cell.put((float) n);\n        return total + price + half + either + cell.get();\n    }\n}\n";

    assert_eq!(issues(("src/Demo/Report.sharp", sharp), &[("src/Lib/Cell.php", CELL)]), Vec::<String>::new());
}

#[test]
fn plus_on_a_string_and_a_value_that_may_not_be_one_is_an_invalid_operand() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public static string total(int count, float rate, string name, string? maybe)\n    {\n        const a = name + count;\n        const b = rate + name;\n        const c = maybe + name;\n        const d = count + rate;\n        return name;\n    }\n}\n";

    assert_eq!(
        issues(("src/Demo/Report.sharp", sharp), &[]),
        ["7:19 invalid-operand", "8:19 invalid-operand", "9:19 invalid-operand"]
    );
}

#[test]
fn a_ternary_with_a_bool_condition_has_the_type_it_has_in_php() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public static string? host(string host, bool secure)\n    {\n        const scheme = secure ? \"https\" : \"http\";\n        return host != \"\" ? scheme + host : (secure ? 1 : null);\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nclass Report\n{\n    public static function host(string $host, bool $secure): ?string\n    {\n        $scheme = $secure ? \"https\" : \"http\";\n        return $host != \"\" ? $scheme . $host : ($secure ? 1 : null);\n    }\n}\n";

    let sharp_issues = issues(("src/Demo/Report.sharp", sharp), &[]);
    let php_issues = issues(("src/Demo/Report.php", php), &[]);

    assert!(!php_issues.is_empty(), "{php_issues:?}");
    assert_eq!(codes(&sharp_issues), codes(&php_issues));
}

#[test]
fn a_ternary_whose_condition_is_not_bool_is_an_invalid_operand() {
    let source = "<?php\n\nnamespace Lib;\n\nfinal class Source\n{\n    public static function value(): mixed\n    {\n        return 1;\n    }\n}\n";
    let sharp = "namespace Demo;\n\nimport Lib.Source;\n\nclass Report\n{\n    public static int pick(int count, string name, bool? maybe)\n    {\n        const a = count ? 1 : 2;\n        const b = name ? 1 : 2;\n        const c = maybe ? 1 : 2;\n        const d = Source.value() ? 1 : 2;\n        const e = count ?: 2;\n        return a + b + c + d + e;\n    }\n}\n";

    assert_eq!(
        issues(("src/Demo/Report.sharp", sharp), &[("src/Lib/Source.php", source)]),
        ["9:19 invalid-operand", "10:19 invalid-operand", "11:19 invalid-operand", "12:19 invalid-operand"]
    );
}

#[test]
fn every_condition_that_is_bool_has_no_issue() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public static int pick(int count, string name, bool on)\n    {\n        if (count > 0) {\n            count++;\n        } else if (name != \"\") {\n            count--;\n        }\n        while (count > 10 && on) {\n            count--;\n        }\n        do {\n            count++;\n        } while (count < 3 || !on);\n        for (let i = 3; i > 0; i--) {\n            count++;\n        }\n        while (true) {\n            break;\n        }\n        return on ? count : 0;\n    }\n}\n";

    assert_eq!(issues(("src/Demo/Report.sharp", sharp), &[]), Vec::<String>::new());
}

#[test]
fn a_condition_that_is_not_bool_is_an_invalid_operand_everywhere() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public static int pick(int count, string name, bool on, int n, string s)\n    {\n        if (count) {\n            count++;\n        } else if (name) {\n            count--;\n        }\n        while (count) {\n            count--;\n        }\n        do {\n            count++;\n        } while (count % 3);\n        for (let i = 3; i; i--) {\n            count += s ? 1 : 2;\n        }\n        const a = n && on;\n        const b = on || s;\n        const c = !n;\n        return a && b && c ? 1 : 0;\n    }\n}\n";

    assert_eq!(
        issues(("src/Demo/Report.sharp", sharp), &[]),
        [
            "7:13 invalid-operand",
            "9:20 invalid-operand",
            "12:16 invalid-operand",
            "17:18 invalid-operand",
            "19:22 invalid-operand",
            "18:25 invalid-operand",
            "21:19 invalid-operand",
            "22:25 invalid-operand",
            "23:20 invalid-operand",
        ]
    );
}

/// `check_slice` refuses `!entity is HasDesign` and writes `entity is not HasDesign`, so the analyzer adds no issue on
/// it, while `!` on any other value that is not `bool` keeps its report.
#[test]
fn not_before_is_adds_no_issue_and_not_of_a_value_that_is_not_bool_keeps_its_report() {
    let design = "<?php\n\nnamespace Demo;\n\ninterface HasDesign\n{\n}\n";
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public static bool run(Any entity, int done)\n    {\n        if (!entity is HasDesign) {\n            return true;\n        }\n        if (!done) {\n            return false;\n        }\n        return true;\n    }\n}\n";

    let issues: Vec<String> =
        analyze(&PLUGIN_REGISTRY, settings(), ("src/Demo/Report.sharp", sharp), &[("src/Demo/HasDesign.php", design)])
            .iter()
            .map(|issue| format!("{} {}", located(sharp, issue), issue.message))
            .collect();

    assert_eq!(issues, ["10:14 invalid-operand `!` takes a `bool`, but this is `int`."]);
}

/// Spec section 19's flags: ints joined with `|`, tested with `&`, and `&` binds tighter than `!=` in PHP#. The `.php`
/// twin writes the parentheses PHP needs for the same meaning.
#[test]
fn the_bitwise_operators_and_their_compound_forms_take_ints_as_in_php() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public static int flags(int granted, int count, int n)\n    {\n        const READ = 1;\n        const WRITE = 2;\n        const DELETE = 4;\n        let permissions = granted | WRITE;\n        permissions |= DELETE;\n        if (permissions & WRITE != 0) {\n            permissions = permissions ^ READ;\n        }\n        if ((permissions & WRITE) != 0) {\n            permissions >>= 1;\n        }\n        const mask = 1 << count;\n        n %= 3;\n        n &= ~mask;\n        n ^= permissions >> 1;\n        n <<= 2;\n        return ~mask & permissions | n;\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nclass Report\n{\n    public static function flags(int $granted, int $count, int $n): int\n    {\n        $READ = 1;\n        $WRITE = 2;\n        $DELETE = 4;\n        $permissions = $granted | $WRITE;\n        $permissions |= $DELETE;\n        if (($permissions & $WRITE) != 0) {\n            $permissions = $permissions ^ $READ;\n        }\n        if (($permissions & $WRITE) != 0) {\n            $permissions >>= 1;\n        }\n        $mask = 1 << $count;\n        $n %= 3;\n        $n &= ~$mask;\n        $n ^= $permissions >> 1;\n        $n <<= 2;\n        return ~$mask & $permissions | $n;\n    }\n}\n";

    let sharp_issues = issues(("src/Demo/Report.sharp", sharp), &[]);
    let php_issues = issues(("src/Demo/Report.php", php), &[]);

    assert_eq!(sharp_issues, Vec::<String>::new());
    assert_eq!(codes(&sharp_issues), codes(&php_issues), "{php_issues:?}");
}

/// A flag test is a comparison: the `int` that `&` gives is no condition, as spec section 21 makes every condition a
/// `bool`. PHP tests its truthiness.
#[test]
fn a_bitwise_and_as_a_condition_is_an_int_that_is_not_bool() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public static bool can(int permissions)\n    {\n        const WRITE = 2;\n        if (permissions & WRITE) {\n            return true;\n        }\n        return false;\n    }\n}\n";

    assert_eq!(
        refusals(("src/Demo/Report.sharp", sharp), &[]),
        [
            "8:13 invalid-operand `if` takes a `bool`, but this is `int`. | Compare the value, as in `count > 0` or `name != \"\"`."
        ]
    );
}

/// `~` on an `int` gives an `int`, so `~0`, which is `-1`, never reads as `0`. PHP's analysis kept the operand's own
/// type, which made `~0 == 0` look always true in both dialects.
#[test]
fn bitwise_not_of_an_int_is_an_int_in_both_dialects() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public static int all()\n    {\n        const bits = ~0;\n        if (bits == 0) {\n            return 1;\n        }\n        return bits;\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nclass Report\n{\n    public static function all(): int\n    {\n        $bits = ~0;\n        if ($bits === 0) {\n            return 1;\n        }\n        return $bits;\n    }\n}\n";

    assert_eq!(messages(("src/Demo/Report.sharp", sharp), &[]), Vec::<String>::new());
    assert_eq!(messages(("src/Demo/Report.php", php), &[]), Vec::<String>::new());
}

/// Spec section 21 narrows no property, because it could change between the test and the use, so `order.total` stays
/// `Any?` after `is int`. The error says so and names the fix, a name bound by the test. PHP narrows the property, and
/// its error on an untested `mixed` operand keeps its wording.
#[test]
fn an_operand_read_from_a_tested_property_says_properties_are_not_narrowed() {
    let sharp = "namespace Demo;\n\npublic class Order\n{\n    public Any? total { get; set; }\n\n    public Order(Any? total)\n    {\n        this.total = total;\n    }\n\n    public static int next(Order order)\n    {\n        if (order.total is int) {\n            return order.total + 1;\n        }\n        if (order.total is int t) {\n            return t + 1;\n        }\n        return 0;\n    }\n}\n";

    assert_eq!(
        refusals(("src/Demo/Order.sharp", sharp), &[]),
        [
            "15:20 mixed-operand `order.total` is `Any?` here: a property is not narrowed, because it could change between the test and the use. | Copy the value into a local first: test it with a name, as in `if (order.total is int t)`, and use `t`.",
            "15:20 mixed-return-statement Could not infer a precise return type for method `Order.next`. Saw type `Any?`. | Add specific type hints to variables, parameters, or properties involved in calculating the return value. Consider adding a specific return type declaration to the method signature to catch potential mismatches earlier.",
        ]
    );

    let untested = "<?php\n\nnamespace Demo;\n\nfinal class Order\n{\n    public function __construct(public mixed $total)\n    {\n    }\n\n    public static function next(Order $order): void\n    {\n        echo $order->total + 1;\n        echo 1 + $order->total;\n    }\n}\n";
    assert_eq!(
        refusals(("src/Demo/Order.php", untested), &[]),
        [
            "13:14 mixed-operand Left operand in binary operation has type `mixed`. | Ensure the left operand has a known type (e.g., `int`, `float`, `string`) using type hints, assertions, or checks.",
            "13:14 mixed-argument The first value for `echo` is too general. | Add a specific type hint or assertion for this value.",
            "14:18 mixed-operand Right operand in binary operation has type `mixed`. | Ensure the right operand has a known type (e.g., `int`, `float`, `string`) using type hints, assertions, or checks.",
            "14:14 mixed-argument The first value for `echo` is too general. | Add a specific type hint or assertion for this value.",
        ]
    );
}

/// A condition that always holds names its PHP# type, as the condition error beside it does. PHP names its own type.
#[test]
fn a_condition_that_always_holds_names_its_php_sharp_type() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public static int can()\n    {\n        const WRITE = 2;\n        if (WRITE) {\n            return 1;\n        }\n        let ready = true;\n        if (ready) {\n            return 2;\n        }\n        return 0;\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nclass Report\n{\n    public static function can(): int\n    {\n        $WRITE = 2;\n        if ($WRITE) {\n            return 1;\n        }\n        $ready = true;\n        if ($ready) {\n            return 2;\n        }\n        return 0;\n    }\n}\n";

    assert_eq!(
        messages(("src/Demo/Report.sharp", sharp), &[]),
        [
            "This condition (type `2`) will always evaluate to `true`.",
            "`if` takes a `bool`, but this is `int`.",
            "This condition (type `true`) will always evaluate to `true`.",
        ]
    );
    assert_eq!(
        messages(("src/Demo/Report.php", php), &[]),
        [
            "This condition (type `int(2)`) will always evaluate to true.",
            "This condition (type `true`) will always evaluate to true.",
        ]
    );
}

/// A loop condition that never holds names its PHP# type, in the loop's report and in the report on the variable it
/// tests. PHP names its own type.
#[test]
fn a_loop_condition_that_never_holds_names_its_php_sharp_type() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public static int count()\n    {\n        const n = 0;\n        while (n) {\n            return 1;\n        }\n        return 0;\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nclass Report\n{\n    public static function count(): int\n    {\n        $n = 0;\n        while ($n) {\n            return 1;\n        }\n        return 0;\n    }\n}\n";
    let impossible = |analyzed| -> Vec<String> {
        worded(analyzed, &[]).into_iter().filter(|line| line.contains(" impossible-condition ")).collect()
    };

    assert_eq!(
        impossible(("src/Demo/Report.sharp", sharp)),
        [
            "8:16 impossible-condition Impossible condition: variable `n` (type `0`) will always evaluate to `false`. | This condition always evaluates to `false` | Variable `n` (type `0`) is never `true`, so this condition is always `false`. | Review the logic or type of the variable; this condition will never pass.",
            "8:16 impossible-condition This loop condition (type `0`) will always evaluate to `false`. | This condition is always `false`, the loop body will never execute | Check the logic of this loop condition. The loop body is unreachable.",
        ]
    );
    assert_eq!(
        impossible(("src/Demo/Report.php", php)),
        [
            "10:16 impossible-condition Impossible condition: variable `$n` (type `int(0)`) will always evaluate to false. | This condition always evaluates to false | Variable `$n` (type `int(0)`) is always falsy and can never satisfy a truthiness check. | Review the logic or type of the variable; this condition will never pass.",
            "10:16 impossible-condition This loop condition (type `int(0)`) will always evaluate to false. | This condition is always false, the loop body will never execute | Check the logic of this loop condition. The loop body is unreachable.",
        ]
    );
}

/// A condition that always or never holds speaks of the `bool` it is: always `true` or always `false`. PHP# has no
/// truthiness. PHP keeps its truthy and falsy wording.
#[test]
fn a_condition_that_always_or_never_holds_speaks_of_its_bool() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public static int never() { const off = false; if (off) { return 1; } return 0; }\n    public static int notNever() { const on = true; if (!on) { return 1; } return 0; }\n    public static int always() { const on = true; if (on) { return 1; } return 0; }\n    public static int notAlways() { const off = false; if (!off) { return 1; } return 0; }\n    public static int ternary() { const on = true; const off = false; return (on ? 1 : 2) + (off ? 1 : 2); }\n    public static bool logical(bool flag) { const on = true; const off = false; return (off && flag) || (on || flag); }\n    public static int loops() { const on = true; const off = false; while (off) { return 1; } while (!on) { return 2; } while (on) { return 3; } return 0; }\n    public static int negatedLoop() { const off = false; while (!off) { return 4; } return 0; }\n    public static bool otherwise(bool flag) { const off = false; return off || flag; }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nclass Report\n{\n    public static function never(): int { $off = false; if ($off) { return 1; } return 0; }\n    public static function notNever(): int { $on = true; if (!$on) { return 1; } return 0; }\n    public static function always(): int { $on = true; if ($on) { return 1; } return 0; }\n    public static function notAlways(): int { $off = false; if (!$off) { return 1; } return 0; }\n    public static function ternary(): int { $on = true; $off = false; return ($on ? 1 : 2) + ($off ? 1 : 2); }\n    public static function logical(bool $flag): bool { $on = true; $off = false; return ($off && $flag) || ($on || $flag); }\n    public static function loops(): int { $on = true; $off = false; while ($off) { return 1; } while (!$on) { return 2; } while ($on) { return 3; } return 0; }\n    public static function negatedLoop(): int { $off = false; while (!$off) { return 4; } return 0; }\n    public static function otherwise(bool $flag): bool { $off = false; return $off || $flag; }\n}\n";

    assert_eq!(
        worded(("src/Demo/Report.php", php), &[]),
        [
            "7:61 impossible-condition This condition (type `false`) will always evaluate to false. | Expression of type `false` is always falsy | Because this condition is always false, the code block it controls will never be executed. | Check the logic of this expression. If the code block is intended to be unreachable, consider removing it. Otherwise, revise the condition.",
            "8:62 impossible-condition This condition (type `false`) will always evaluate to false. | Expression of type `false` is always falsy | Because this condition is always false, the code block it controls will never be executed. | Check the logic of this expression. If the code block is intended to be unreachable, consider removing it. Otherwise, revise the condition.",
            "9:60 redundant-condition This condition (type `true`) will always evaluate to true. | Expression of type `true` is always truthy | Because this condition is always true, the code block it controls will always execute if this part of the code is reached. | The explicit condition might be redundant. | Consider simplifying or removing the conditional check if the guarded code should always execute, or verify the expression's logic if a conditional check is truly needed.",
            "10:65 redundant-condition This condition (type `true`) will always evaluate to true. | Expression of type `true` is always truthy | Because this condition is always true, the code block it controls will always execute if this part of the code is reached. | The explicit condition might be redundant. | Consider simplifying or removing the conditional check if the guarded code should always execute, or verify the expression's logic if a conditional check is truly needed.",
            "11:79 redundant-condition Redundant ternary operator: condition is always truthy. | This condition (type `true`) is always truthy | This `then` branch is always evaluated, making it the result of the expression | This `else` branch will never be evaluated | The ternary operator `? :` evaluates the `else` branch only when the condition is falsy. | Consider replacing the entire expression with just this `then` branch.",
            "11:95 impossible-condition Redundant ternary operator: condition is always falsy. | This condition (type `false`) is always falsy | This `then` branch will never be evaluated | This `else` branch is always evaluated, making it the result of the expression | The ternary operator `? :` evaluates the `then` branch only when the condition is truthy. | Consider replacing the entire expression with just this `else` branch.",
            "12:90 redundant-logical-operation Redundant `&&` operation: left operand is always falsy and right operand is not evaluated. | Left operand is always falsy | Right operand is not evaluated | The `&&` operator will always return `false` in this case. | Consider simplifying this expression to `false`.",
            "12:109 redundant-logical-operation Redundant `||` operation: left operand is always true and right operand is not evaluated. | Left operand is always true | Right operand is not evaluated | The `||` operator will always return `true` in this case. | Consider simplifying this expression to `true`.",
            "12:89 redundant-logical-operation Redundant `||` operation: left operand is always falsy and right operand is always truthy. | Left operand is always falsy | Right operand is always truthy | The `||` operator will always return `true` in this case. | Consider simplifying this expression to `true`.",
            "13:76 impossible-condition Impossible condition: variable `$off` (type `false`) will always evaluate to false. | This condition always evaluates to false | Variable `$off` (type `false`) is always falsy and can never satisfy a truthiness check. | Review the logic or type of the variable; this condition will never pass.",
            "13:76 impossible-condition This loop condition (type `false`) will always evaluate to false. | This condition is always false, the loop body will never execute | Check the logic of this loop condition. The loop body is unreachable.",
            "13:103 impossible-condition Impossible condition: variable `$on` (type `true`) will always evaluate to false. | This condition always evaluates to false | Variable `$on` (type `true`) is always truthy, so asserting it is falsy will always be false. | Review the logic or type of the variable; this condition will never pass.",
            "13:103 impossible-condition This loop condition (type `false`) will always evaluate to false. | This condition is always false, the loop body will never execute | Check the logic of this loop condition. The loop body is unreachable.",
            "13:130 redundant-condition Redundant condition: variable `$on` (type `true`) will always evaluate to true. | This condition always evaluates to true | Variable `$on` (type `true`) is always truthy. This condition is redundant and the code block will always execute if reached. | Simplify or remove the redundant condition if the guarded code should always run.",
            "14:70 redundant-condition Redundant condition: variable `$off` (type `false`) will always evaluate to true. | This condition always evaluates to true | Variable `$off` (type `false`) is always falsy, so asserting it's falsy is always true and redundant. | Simplify or remove the redundant condition if the guarded code should always run.",
            "15:79 redundant-condition Redundant condition: variable `$off` (type `false`) will always evaluate to true. | This condition always evaluates to true | Variable `$off` (type `false`) is always falsy, so asserting it's falsy is always true and redundant. | Simplify or remove the redundant condition if the guarded code should always run.",
            "15:79 redundant-logical-operation Redundant `||` operation: left operand is always false and right operand is evaluated. | Left operand is always false | Right operand is evaluated | The `||` operator will always return the boolean value of the right-hand side in this case. | Consider simplifying this expression to just the right operand.",
        ]
    );
    assert_eq!(
        worded(("src/Demo/Report.sharp", sharp), &[]),
        [
            "5:56 impossible-condition This condition (type `false`) will always evaluate to `false`. | Expression of type `false` is always `false` | Because this condition is always `false`, the code block it controls will never be executed. | Check the logic of this expression. If the code block is intended to be unreachable, consider removing it. Otherwise, revise the condition.",
            "6:57 impossible-condition This condition (type `false`) will always evaluate to `false`. | Expression of type `false` is always `false` | Because this condition is always `false`, the code block it controls will never be executed. | Check the logic of this expression. If the code block is intended to be unreachable, consider removing it. Otherwise, revise the condition.",
            "7:55 redundant-condition This condition (type `true`) will always evaluate to `true`. | Expression of type `true` is always `true` | Because this condition is always `true`, the code block it controls will always execute if this part of the code is reached. | The explicit condition might be redundant. | Consider simplifying or removing the conditional check if the guarded code should always execute, or verify the expression's logic if a conditional check is truly needed.",
            "8:60 redundant-condition This condition (type `true`) will always evaluate to `true`. | Expression of type `true` is always `true` | Because this condition is always `true`, the code block it controls will always execute if this part of the code is reached. | The explicit condition might be redundant. | Consider simplifying or removing the conditional check if the guarded code should always execute, or verify the expression's logic if a conditional check is truly needed.",
            "9:79 redundant-condition Redundant ternary operator: condition is always `true`. | This condition (type `true`) is always `true` | This `then` branch is always evaluated, making it the result of the expression | This `else` branch will never be evaluated | The ternary operator `? :` evaluates the `else` branch only when the condition is `false`. | Consider replacing the entire expression with just this `then` branch.",
            "9:94 impossible-condition Redundant ternary operator: condition is always `false`. | This condition (type `false`) is always `false` | This `then` branch will never be evaluated | This `else` branch is always evaluated, making it the result of the expression | The ternary operator `? :` evaluates the `then` branch only when the condition is `true`. | Consider replacing the entire expression with just this `else` branch.",
            "10:89 redundant-logical-operation Redundant `&&` operation: left operand is always `false` and right operand is not evaluated. | Left operand is always `false` | Right operand is not evaluated | The `&&` operator will always return `false` in this case. | Consider simplifying this expression to `false`.",
            "10:106 redundant-logical-operation Redundant `||` operation: left operand is always `true` and right operand is not evaluated. | Left operand is always `true` | Right operand is not evaluated | The `||` operator will always return `true` in this case. | Consider simplifying this expression to `true`.",
            "10:88 redundant-logical-operation Redundant `||` operation: left operand is always `false` and right operand is always `true`. | Left operand is always `false` | Right operand is always `true` | The `||` operator will always return `true` in this case. | Consider simplifying this expression to `true`.",
            "11:76 impossible-condition Impossible condition: variable `off` (type `false`) will always evaluate to `false`. | This condition always evaluates to `false` | Variable `off` (type `false`) is never `true`, so this condition is always `false`. | Review the logic or type of the variable; this condition will never pass.",
            "11:76 impossible-condition This loop condition (type `false`) will always evaluate to `false`. | This condition is always `false`, the loop body will never execute | Check the logic of this loop condition. The loop body is unreachable.",
            "11:102 impossible-condition Impossible condition: variable `on` (type `true`) will always evaluate to `false`. | This condition always evaluates to `false` | Variable `on` (type `true`) is never `false`, so this condition is always `false`. | Review the logic or type of the variable; this condition will never pass.",
            "11:102 impossible-condition This loop condition (type `false`) will always evaluate to `false`. | This condition is always `false`, the loop body will never execute | Check the logic of this loop condition. The loop body is unreachable.",
            "11:128 redundant-condition Redundant condition: variable `on` (type `true`) will always evaluate to `true`. | This condition always evaluates to `true` | Variable `on` (type `true`) is never `false`, so this condition is always `true`. | Simplify or remove the redundant condition if the guarded code should always run.",
            "12:65 redundant-condition Redundant condition: variable `off` (type `false`) will always evaluate to `true`. | This condition always evaluates to `true` | Variable `off` (type `false`) is never `true`, so this condition is always `true`. | Simplify or remove the redundant condition if the guarded code should always run.",
            "13:73 redundant-condition Redundant condition: variable `off` (type `false`) will always evaluate to `true`. | This condition always evaluates to `true` | Variable `off` (type `false`) is never `true`, so this condition is always `true`. | Simplify or remove the redundant condition if the guarded code should always run.",
            "13:73 redundant-logical-operation Redundant `||` operation: left operand is always `false` and right operand is evaluated. | Left operand is always `false` | Right operand is evaluated | The `||` operator will always return the boolean value of the right-hand side in this case. | Consider simplifying this expression to just the right operand.",
        ]
    );
}

/// A null check or a type check that always or never holds speaks of the `bool` it is: always `true` or always
/// `false`. PHP keeps its own wording.
#[test]
fn a_null_or_type_check_that_always_or_never_holds_speaks_of_its_bool() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public static int isNull(int x) { while (x == null) { return 1; } return 0; }\n    public static int notNull(int x) { while (x != null) { return 1; } return 0; }\n    public static int known(int? x) { if (x == null) { while (x != null) { return 1; } } return 0; }\n    public static int other() { const on = true; while (on == false) { return 1; } return 0; }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nclass Report\n{\n    public static function isNull(int $x): int { while ($x === null) { return 1; } return 0; }\n    public static function notNull(int $x): int { while ($x !== null) { return 1; } return 0; }\n    public static function known(?int $x): int { if ($x === null) { while ($x !== null) { return 1; } } return 0; }\n    public static function other(): int { $on = true; while ($on === false) { return 1; } return 0; }\n}\n";
    let checks = |analyzed| -> Vec<String> {
        worded(analyzed, &[]).into_iter().filter(|line| line.contains("-type-comparison ")).collect()
    };

    assert_eq!(
        checks(("src/Demo/Report.php", php)),
        [
            "7:57 impossible-null-type-comparison Impossible condition: variable `$x` (type `int`) can never be `null`. | This condition always evaluates to false | Variable `$x` (type `int`) does not include `null`. | The condition checking if `$x` is `null` will always be false. Remove or refactor the condition.",
            "8:58 impossible-null-type-comparison Impossible condition: variable `$x` (type `int`) will always be `null`. | This condition always evaluates to false | Variable `$x` (type `int`) is already known to be `null`, so asserting it's not `null` is impossible. | The condition checking if `$x` is not `null` will always be false. Review the variable's state or condition.",
            "9:76 redundant-type-comparison Redundant condition: variable `$x` (type `null`) is already known to be `null`. | This condition always evaluates to true | The type of variable `$x` (type `null`) already satisfies the condition that it is `null`. This check is redundant. | This condition is always true and the associated code block will always execute if reached. Consider simplifying.",
            "10:62 impossible-type-comparison Impossible condition: variable `$on` (type `true`) can never be `false`. | This condition always evaluates to false | The type of variable `$on` (type `true`) is incompatible with the assertion that it is `false`. | This condition is impossible and the associated code block will never execute. Review the types and condition logic.",
        ]
    );
    assert_eq!(
        checks(("src/Demo/Report.sharp", sharp)),
        [
            "5:46 impossible-null-type-comparison Impossible condition: variable `x` (type `int`) can never be `null`. | This condition always evaluates to `false` | Variable `x` (type `int`) does not include `null`. | The condition checking if `x` is `null` will always be `false`. Remove or refactor the condition.",
            "6:47 impossible-null-type-comparison Impossible condition: variable `x` (type `int`) will always be `null`. | This condition always evaluates to `false` | Variable `x` (type `int`) is already known to be `null`, so asserting it's not `null` is impossible. | The condition checking if `x` is not `null` will always be `false`. Review the variable's state or condition.",
            "7:63 redundant-type-comparison Redundant condition: variable `x` (type `null`) is already known to be `null`. | This condition always evaluates to `true` | The type of variable `x` (type `null`) already satisfies the condition that it is `null`. This check is redundant. | This condition is always `true` and the associated code block will always execute if reached. Consider simplifying.",
            "8:57 impossible-type-comparison Impossible condition: variable `on` (type `true`) can never be `false`. | This condition always evaluates to `false` | The type of variable `on` (type `true`) is incompatible with the assertion that it is `false`. | This condition is impossible and the associated code block will never execute. Review the types and condition logic.",
        ]
    );
}

/// A comparison that always or never holds writes `true` and `false` as PHP# writes them. A `bool` has no order, so
/// PHP# refuses an ordering of `false` before any PHP rule for `false` is named. PHP keeps its own wording.
#[test]
fn a_comparison_that_always_or_never_holds_speaks_of_its_bool() {
    let store = (
        "src/Lib/Store.php",
        "<?php\n\nnamespace Lib;\n\nfinal class Store\n{\n    public static function off(): false { return false; }\n}\n",
    );
    let sharp = "namespace Demo;\n\nimport Lib.Store;\n\nclass Report\n{\n    public static bool same() { const a = 1; return a != 1; }\n    public static bool other() { const a = 1; return a != 2; }\n    public static bool less() { return Store.off() < 1; }\n    public static int order() { return Store.off() <=> 1; }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nuse Lib\\Store;\n\nclass Report\n{\n    public static function same(): bool { $a = 1; return $a != 1; }\n    public static function other(): bool { $a = 1; return $a != 2; }\n    public static function less(): bool { return Store::off() < 1; }\n    public static function order(): int { return Store::off() <=> 1; }\n}\n";
    let comparisons = |analyzed| -> Vec<String> {
        worded(analyzed, &[store])
            .into_iter()
            .filter(|line| {
                line.contains(" redundant-comparison ")
                    || line.contains(" false-operand ")
                    || line.contains(" invalid-operand ")
            })
            .collect()
    };

    assert_eq!(
        comparisons(("src/Demo/Report.php", php)),
        [
            "9:58 redundant-comparison Redundant `!=` comparison: left-hand side is never equal to (always false for !=) right-hand side. | Left operand is `int(1)` | Right operand is `int(1)` | The `!=` operator will always return `false` in this case. | Consider simplifying or removing this comparison as it always evaluates to `false`.",
            "10:59 redundant-comparison Redundant `!=` comparison: left-hand side is always not equal to (always true for !=) right-hand side. | Left operand is `int(1)` | Right operand is `int(2)` | The `!=` operator will always return `true` in this case. | Consider simplifying or removing this comparison as it always evaluates to `true`.",
            "11:50 false-operand Left operand in `<` comparison is `false`. | This is `false` | PHP compares `false` with other types according to specific rules (e.g., `false == 0` is true using `<`). This can hide bugs. | Ensure this operand is not `false` or explicitly handle the `false` case if it represents a distinct state (e.g., an error from a function).",
            "11:50 redundant-comparison Redundant `<` comparison: left-hand side is always less than right-hand side. | Left operand is `false` | Right operand is `int(1)` | The `<` operator will always return `true` in this case. | Consider simplifying or removing this comparison as it always evaluates to `true`.",
            "12:50 false-operand Left operand in spaceship comparison (`<=>`) is `false`. | This is `false` | PHP compares `false` with other types according to specific rules (e.g., `false == 0` is true, `false < 1` is true). | Ensure this comparison with `false` is intended, or provide a non-false operand.",
        ]
    );
    assert_eq!(
        comparisons(("src/Demo/Report.sharp", sharp)),
        [
            "7:53 redundant-comparison Redundant `!=` comparison: left-hand side is never equal to (always `false` for !=) right-hand side. | Left operand is `1` | Right operand is `1` | The `!=` operator will always return `false` in this case. | Consider simplifying or removing this comparison as it always evaluates to `false`.",
            "8:54 redundant-comparison Redundant `!=` comparison: left-hand side is always not equal to (always `true` for !=) right-hand side. | Left operand is `1` | Right operand is `2` | The `!=` operator will always return `true` in this case. | Consider simplifying or removing this comparison as it always evaluates to `true`.",
            "9:40 invalid-operand `<` orders numbers, strings, and classes and enums that declare `operator <=>`, and `bool` is none of them. | This is `bool`. | This is `int`. | A `bool` and a collection have no order, and an enum's cases have one only where it declares `operator <=>`. | Order a number or a string taken from the value instead.",
            "10:40 invalid-operand `<=>` orders numbers, strings, and classes and enums that declare `operator <=>`, and `bool` is none of them. | This is `bool`. | This is `int`. | A `bool` and a collection have no order, and an enum's cases have one only where it declares `operator <=>`. | Order a number or a string taken from the value instead.",
        ]
    );
}

/// A `match` arm that never or always matches writes the `bool` of its condition as PHP# writes it. PHP keeps its own
/// wording.
#[test]
fn a_match_arm_that_never_or_always_matches_speaks_of_its_bool() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public static string twice(int x) => match (x) { 1 => \"one\", 1 => \"again\", default => \"other\" };\n    public static string always() => match (true) { true => \"yes\", default => \"no\" };\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nclass Report\n{\n    public static function twice(int $x): string { return match ($x) { 1 => 'one', 1 => 'again', default => 'other' }; }\n    public static function always(): string { return match (true) { true => 'yes', default => 'no' }; }\n}\n";
    let arms = |analyzed| -> Vec<String> {
        worded(analyzed, &[])
            .into_iter()
            .filter(|line| line.contains(" unreachable-match-arm ") || line.contains(" match-arm-always-true "))
            .collect()
    };

    assert_eq!(
        arms(("src/Demo/Report.php", php)),
        [
            "7:84 unreachable-match-arm This match arm is unreachable. | This arm can never be reached | In this match expression | The condition is always false in this context.",
            "8:69 match-arm-always-true This match arm is always true, making subsequent arms unreachable. | This arm covers all remaining cases for the subject | In this match expression | Any arms after this one can never be reached.",
        ]
    );
    assert_eq!(
        arms(("src/Demo/Report.sharp", sharp)),
        [
            "5:66 unreachable-match-arm This match arm is unreachable. | This arm can never be reached | In this match expression | The condition is always `false` in this context.",
            "6:53 match-arm-always-true This match arm is always `true`, making subsequent arms unreachable. | This arm covers all remaining cases for the subject | In this match expression | Any arms after this one can never be reached.",
        ]
    );
}

/// A `??` on a key the shape never holds writes the `bool` of the check as PHP# writes it. PHP keeps its own wording.
#[test]
fn a_fallback_on_a_missing_key_speaks_of_its_bool() {
    let store = (
        "src/Lib/Store.php",
        "<?php\n\nnamespace Lib;\n\nfinal class Store\n{\n    /** @return array{a: int} */\n    public static function shape(): array { return ['a' => 1]; }\n}\n",
    );
    let sharp = "namespace Demo;\n\nimport Lib.Store;\n\nclass Report\n{\n    public static int missing() { const m = Store.shape(); return m[\"b\"] ?? 0; }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nuse Lib\\Store;\n\nclass Report\n{\n    public static function missing(): int { $m = Store::shape(); return $m['b'] ?? 0; }\n}\n";
    let checks = |analyzed| -> Vec<String> {
        worded(analyzed, &[store])
            .into_iter()
            .filter(|line| line.contains(" impossible-nonnull-entry-check "))
            .collect()
    };

    assert_eq!(
        checks(("src/Demo/Report.php", php)),
        [
            "9:76 impossible-nonnull-entry-check Impossible `isset` check on key `'b'` accessed on `array{'a': int}`. | `isset` on key `'b'` will always be false here. | The analysis determined that the key `'b'` definitely does not exist in this array, so checking `isset` is unnecessary. | Remove the redundant `isset` check.",
        ]
    );
    assert_eq!(
        checks(("src/Demo/Report.sharp", sharp)),
        [
            "7:69 impossible-nonnull-entry-check Impossible check on key `'b'` accessed on `Map<\"a\", int>`. | A check on key `'b'` will always be `false` here. | The analysis determined that the key `'b'` definitely does not exist in this array, so checking it is unnecessary. | Remove the redundant check.",
        ]
    );
}

/// A method that may return `false` from a PHP function writes `false` as PHP# writes it, and asks for no `int|false`
/// return type, which PHP# cannot write. PHP keeps its own wording. `a_message_names_an_accessor_as_sharp_writes_it`
/// pins the same report on an accessor.
#[test]
fn a_return_that_may_be_false_speaks_of_its_bool() {
    let finder = (
        "src/Lib/Finder.php",
        "<?php\n\nnamespace Lib;\n\nfinal class Finder\n{\n    public static function position(): int|false { return strpos('ab', 'b'); }\n}\n",
    );
    let sharp = "namespace Demo;\n\nimport Lib.Finder;\n\nclass Report\n{\n    public static int position() { return Finder.position(); }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nclass Report\n{\n    public static function position(): int { return strpos('ab', 'b'); }\n}\n";
    let returns = |analyzed| -> Vec<String> {
        worded(analyzed, &[finder]).into_iter().filter(|line| line.contains(" falsable-return-statement ")).collect()
    };

    assert_eq!(
        returns(("src/Demo/Report.php", php)),
        [
            "7:53 falsable-return-statement Function `Demo\\Report::position` is declared to return `int` but possibly returns 'false' (inferred as `false|non-negative-int`). | Potentially 'false' returned here. | Return type declared as non-falsable `int` here | The declared return type does not permit 'false', but the analysis indicates that 'false' or a falsable type could be returned from this path. | You can either change the return type declaration of `Demo\\Report::position` to include 'false' (e.g., 'int|false'), or ensure that this function path never returns 'false'.",
        ]
    );
    assert_eq!(
        returns(("src/Demo/Report.sharp", sharp)),
        [
            "7:43 falsable-return-statement Method `Report.position` is declared to return `int` but possibly returns `false` (inferred as `bool|int`). | Potentially `false` returned here. | Return type declared as non-falsable `int` here | The declared return type does not permit `false`, but this path could return `false`. | Ensure this method path never returns `false`.",
        ]
    );
}

/// A `null` operand of arithmetic, from a PHP method, asks for a number and names no cast, since PHP# casts only
/// between numbers. PHP keeps its own wording.
#[test]
fn a_null_operand_of_arithmetic_asks_for_a_number() {
    let store = (
        "src/Lib/Store.php",
        "<?php\n\nnamespace Lib;\n\nfinal class Store\n{\n    public static function nothing(): null { return null; }\n}\n",
    );
    let sharp = "namespace Demo;\n\nimport Lib.Store;\n\nclass Report\n{\n    public static int left() => Store.nothing() - 1;\n\n    public static int right() => 1 - Store.nothing();\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nuse Lib\\Store;\n\nclass Report\n{\n    public static function left(): int { return Store::nothing() - 1; }\n\n    public static function right(): int { return 1 - Store::nothing(); }\n}\n";
    let operands = |analyzed| -> Vec<String> {
        worded(analyzed, &[store]).into_iter().filter(|line| line.contains(" null-operand ")).collect()
    };

    assert_eq!(
        operands(("src/Demo/Report.php", php)),
        [
            "9:49 null-operand Left operand in arithmetic operation cannot be `null`. | This is `null`. | Performing arithmetic operations on `null` typically results in `0`. | Ensure the left operand is a number (int/float) or a type that can be cast to a number.",
            "11:54 null-operand Right operand in arithmetic operation cannot be `null`. | This is `null`. | Performing arithmetic operations on `null` typically results in `0`. | Ensure the right operand is a number (int/float) or a type that can be cast to a number.",
        ]
    );
    assert_eq!(
        operands(("src/Demo/Report.sharp", sharp)),
        [
            "7:33 null-operand Left operand in arithmetic operation cannot be `null`. | This is `null`. | Performing arithmetic operations on `null` typically results in `0`. | Ensure the left operand is a number (int/float).",
            "9:38 null-operand Right operand in arithmetic operation cannot be `null`. | This is `null`. | Performing arithmetic operations on `null` typically results in `0`. | Ensure the right operand is a number (int/float).",
        ]
    );
}

/// A literal keyed by a value that cannot key a `Map` names the `Map` key rule, as a `Map` type that breaks it does,
/// and names no cast, since PHP# casts only between numbers. PHP keeps its own wording.
#[test]
fn a_literal_keyed_by_a_value_that_cannot_key_a_map_names_the_map_key_rule() {
    let store = (
        "src/Lib/Store.php",
        "<?php\n\nnamespace Lib;\n\nfinal class Store\n{\n    public static function object(): object { return new \\stdClass(); }\n}\n",
    );
    let sharp = "namespace Demo;\n\nimport Lib.Store;\n\nclass Report\n{\n    public static int count() { const m = [Store.object(): 1]; return m.count(); }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nuse Lib\\Store;\n\nclass Report\n{\n    public static function count(): int { $m = [Store::object() => 1]; return count($m); }\n}\n";
    let keys = |analyzed| -> Vec<String> {
        worded(analyzed, &[store]).into_iter().filter(|line| line.contains(" invalid-array-element-key ")).collect()
    };

    assert_eq!(
        keys(("src/Demo/Report.php", php)),
        [
            "9:49 invalid-array-element-key Invalid array key type. | This has type `object`, which cannot be cast to a string or integer. | In PHP, array keys must be strings or integers. While types like `bool` or `float` are automatically cast, a value of type `object` cannot be. | Ensure the array key is either a string or an integer.",
        ]
    );
    assert_eq!(
        keys(("src/Demo/Report.sharp", sharp)),
        [
            "7:44 invalid-array-element-key A `Map`'s key is anything with `==` and `hash()`: an `int`, a `float`, a `string`, a `bool`, `null`, an enum, a struct, a `List`, `Set` or `Map` of them, or a class that declares `operator ==`, and `Object` is none of them. | `Object` keys this `Map`. | Key the `Map` by an `int`, a `float`, a `string`, a `bool`, `null`, an enum, a struct, a `List`, `Set` or `Map` of them, or a class that declares `public static bool operator ==` with `public int hash()`.",
        ]
    );
}

/// A `float`, a `bool`, `null` and an all-digit string each key a literal as itself, where PHP turns the key into an
/// `int` or a `string` without a word. So the literal is the `Map` of that key type, and no other, and a `null` index
/// fits a `Map` whose key type holds `null` alone. PHP keeps its cast.
#[test]
fn a_literal_keeps_a_float_a_bool_null_or_an_all_digit_string_as_its_key() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public static Map<float, int> floats() => [1.5: 1];\n\n    public static Map<bool, int> flags() => [true: 1];\n\n    public static Map<string?, int> nulls() => [null: 1];\n\n    public static Map<string, int> digits() => [\"5\": 1, \"sku-2\": 2];\n\n    public static Map<int, int> cast() => [1.5: 1];\n\n    public static Map<float, int> spread(Map<float, int> prices) => [...prices, 2.5: 1];\n\n    public static Map<float, int> copied(Map<float, int> prices) => [...prices];\n\n    public static int nullIndex()\n    {\n        Map<string?, int> maybe = [null: 1];\n        maybe[null] = 2;\n        Map<string, int> named = [:];\n        named[null] = 3;\n        return (maybe[null] ?? 0) + (named[null] ?? 0);\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nclass Report\n{\n    /** @return array<int, int> */\n    public static function floats(): array { return [1.5 => 1]; }\n\n    /** @return array<int, int> */\n    public static function flags(): array { return [true => 1]; }\n\n    /** @return array<string, int> */\n    public static function nulls(): array { return [null => 1]; }\n\n    /** @return array<int, int> */\n    public static function digits(): array { return [\"5\" => 1]; }\n}\n";

    assert_eq!(worded(("src/Demo/Report.php", php), &[]), Vec::<String>::new());
    assert_eq!(
        worded(("src/Demo/Report.sharp", sharp), &[]),
        [
            "13:43 invalid-return-statement Invalid return type for method `Report.cast`: expected `Map<int, int>`, but found `Map<float, int>`. | This has type `Map<float, int>` | The type `Map<float, int>` returned here is not compatible with the declared return type `Map<int, int>`. | Change the return value to match `Map<int, int>`, or update the method's return type declaration.",
            "24:15 mismatched-array-index `Map<string, int>` is keyed by `string`, but this key is `null`. | This key may not be of type `string`. | Check the key with `is string` first, as in `if (name is string) { … }`.",
            "25:44 mismatched-array-index `Map<string, int>` is keyed by `string`, but this key is `null`. | This key may not be of type `string`. | Check the key with `is string` first, as in `if (name is string) { … }`.",
        ]
    );
}

/// An operand that may be `false`, from a PHP method, asks for a check of `false`. PHP# has no falsiness, and keeps
/// `(int)` between numbers, so no cast turns `false` into one. PHP keeps its own wording.
#[test]
fn an_operand_that_may_be_false_asks_for_a_check_of_false() {
    let store = (
        "src/Lib/Store.php",
        "<?php\n\nnamespace Lib;\n\nfinal class Store\n{\n    public static function count(): int|false { return 1; }\n}\n",
    );
    let sharp = "namespace Demo;\n\nimport Lib.Store;\n\nclass Report\n{\n    public static int add() { return Store.count() + 1; }\n    public static int addRight() { return 1 + Store.count(); }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nuse Lib\\Store;\n\nclass Report\n{\n    public static function add(): int { return Store::count() + 1; }\n    public static function addRight(): int { return 1 + Store::count(); }\n}\n";
    let possibly_false = |analyzed| -> Vec<String> {
        worded(analyzed, &[store]).into_iter().filter(|line| line.contains(" possibly-false-operand ")).collect()
    };

    assert_eq!(
        possibly_false(("src/Demo/Report.sharp", sharp)),
        [
            "7:38 possibly-false-operand Left operand in arithmetic operation might be `false` (type `false|int`). | This might be `false`. | Performing arithmetic operations on `false` typically results in `0`. | Ensure the left operand is not `false` before the operation.",
            "8:47 possibly-false-operand Right operand in arithmetic operation might be `false` (type `false|int`). | This might be `false`. | Performing arithmetic operations on `false` typically results in `0`. | Ensure the right operand is not `false` before the operation.",
        ]
    );
    assert_eq!(
        possibly_false(("src/Demo/Report.php", php)),
        [
            "9:48 possibly-false-operand Left operand in arithmetic operation might be `false` (type `false|int`). | This might be `false`. | Performing arithmetic operations on `false` typically results in `0`. | Ensure the left operand is non-falsy before the operation, or explicitly cast if coercion is intended.",
            "10:57 possibly-false-operand Right operand in arithmetic operation might be `false` (type `false|int`). | This might be `false`. | Performing arithmetic operations on `false` typically results in `0`. | Ensure the right operand is non-falsy before the operation, or explicitly cast if coercion is intended.",
        ]
    );
}

/// A loop over a value that may be `false`, from a PHP method, asks for a check of `false` before the loop. PHP# has
/// no truthiness. PHP keeps its own wording.
#[test]
fn a_loop_over_a_value_that_may_be_false_asks_for_a_check_of_false() {
    let store = (
        "src/Lib/Store.php",
        "<?php\n\nnamespace Lib;\n\nfinal class Store\n{\n    /** @return list<int>|false */\n    public static function ids(): array|false { return [1]; }\n}\n",
    );
    let sharp = "namespace Demo;\n\nimport Lib.Store;\n\nclass Report\n{\n    public static int total() { let sum = 0; for (const id of Store.ids()) { sum += id; } return sum; }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nuse Lib\\Store;\n\nclass Report\n{\n    public static function total(): int { $sum = 0; foreach (Store::ids() as $id) { $sum += $id; } return $sum; }\n}\n";
    let possibly_false = |analyzed| -> Vec<String> {
        worded(analyzed, &[store]).into_iter().filter(|line| line.contains(" possibly-false-iterator ")).collect()
    };

    assert_eq!(
        possibly_false(("src/Demo/Report.sharp", sharp)),
        [
            "7:63 possibly-false-iterator Expression being iterated (type `false|List<int>`) might be `false` at runtime. | This might be `false` | This loop might not be executed | If this expression is `false`, it will be treated as an empty list, and the loop body will not execute. | Consider checking for `false` before the loop if this is not intended.",
        ]
    );
    assert_eq!(
        possibly_false(("src/Demo/Report.php", php)),
        [
            "9:62 possibly-false-iterator Expression being iterated (type `false|list<int>`) might be `false` at runtime. | This might be `false` | This `foreach` might not be executed | If this expression is `false`, it will be treated as an empty array, and the loop body will not execute. | Consider checking for `false` or truthiness before the loop if this is not intended.",
        ]
    );
}

/// A PHP method's `@psalm-assert non-empty-mixed` is named `Any`, the PHP# type that holds it, as every refinement PHP#
/// cannot write is named, so the message names no `mixed`. PHP keeps Mago's `truthy-mixed`.
#[test]
fn an_assertion_of_non_empty_mixed_names_the_any_that_holds_it() {
    let check = (
        "src/Lib/Check.php",
        "<?php\n\nnamespace Lib;\n\nfinal class Check\n{\n    /**\n     * @psalm-pure\n     *\n     * @psalm-assert non-empty-mixed $value\n     */\n    public static function filled(mixed $value): void {}\n}\n",
    );
    let sharp = "namespace Demo;\n\nimport Lib.Check;\n\nclass Report\n{\n    public static void run() { const one = 1; Check.filled(one); }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nuse Lib\\Check;\n\nclass Report\n{\n    public static function run(): void { $one = 1; Check::filled($one); }\n}\n";
    let redundant = |analyzed| -> Vec<String> {
        worded(analyzed, &[check]).into_iter().filter(|line| line.contains(" redundant-type-comparison ")).collect()
    };

    assert_eq!(
        redundant(("src/Demo/Report.sharp", sharp)),
        [
            "7:47 redundant-type-comparison Redundant type assertion: `one` is already `1`. | Argument `one` already has type `1` | The assertion against `Any` always holds because `one` is `1`. | Consider removing this assertion or replacing it with `default` if used in a `match` arm.",
        ]
    );
    assert_eq!(
        redundant(("src/Demo/Report.php", php)),
        [
            "9:52 redundant-type-comparison Redundant type assertion: `$one` is already `int(1)`. | Argument `$one` already has type `int(1)` | The assertion against `truthy-mixed` always holds because `$one` is `int(1)`. | Consider removing this assertion or replacing it with `default` if used in a `match` arm.",
        ]
    );
}

/// A condition that contradicts or repeats an earlier one names its variables and types as PHP# writes them. The
/// earlier condition reads as the `||` it is. PHP keeps its own wording.
#[test]
fn a_paradoxical_or_repeated_condition_names_its_php_sharp_types() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public static int pick(int? count, bool done)\n    {\n        if (count == 2 || done) {\n            if (count != 2 && !done) {\n                return 1;\n            }\n        }\n        if (done) {\n            return 2;\n        } else if (done) {\n            return 3;\n        }\n        if (!done && done) {\n            return 4;\n        }\n        return 0;\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nclass Report\n{\n    public static function pick(?int $count, bool $done): int\n    {\n        if ($count === 2 || $done) {\n            if ($count !== 2 && !$done) {\n                return 1;\n            }\n        }\n        if ($done) {\n            return 2;\n        } else if ($done) {\n            return 3;\n        }\n        if (!$done && $done) {\n            return 4;\n        }\n        return 0;\n    }\n}\n";
    let conditions = |analyzed| -> Vec<String> {
        worded(analyzed, &[])
            .into_iter()
            .filter(|line| line.contains(" paradoxical-condition ") || line.contains(" redundant-condition Redundant "))
            .collect()
    };

    assert_eq!(
        conditions(("src/Demo/Report.sharp", sharp)),
        [
            "8:17 paradoxical-condition Paradoxical condition | This condition (`!done && count is not 2`) can never be `true` here | Because of this preceding condition... | ...the analyzer knows that `count is 2 || done` must be `true` for this code path to be taken. | Therefore, this new condition (`!done && count is not 2`) directly contradicts that established fact. | As a result, the code this condition guards is unreachable. | Remove the unreachable code or refactor the conditional logic.",
            "17:13 redundant-condition Redundant condition | This condition (`!done`) is always `true` here | This was already established as `true` by a previous condition here | The analyzer determined this condition is guaranteed to be `true` based on preceding logic, making this check unnecessary. | Consider removing this redundant conditional check to simplify the code.",
        ]
    );
    assert_eq!(
        conditions(("src/Demo/Report.php", php)),
        [
            "10:17 paradoxical-condition Paradoxical condition | This condition (`!$done && $count is not int(2)`) can never be true here | Because of this preceding condition... | ...the analyzer knows that `$count is int(2) && $done` must be true for this code path to be taken. | Therefore, this new condition (`!$done && $count is not int(2)`) directly contradicts that established fact. | As a result, the code this condition guards is unreachable. | Remove the unreachable code or refactor the conditional logic.",
            "19:13 redundant-condition Redundant condition | This condition (`!$done`) is always true here | This was already established as true by a previous condition here | The analyzer determined this condition is guaranteed to be true based on preceding logic, making this check unnecessary. | Consider removing this redundant conditional check to simplify the code.",
        ]
    );
}

/// `|`, `&` and `^` on two `bool`s name the operator that joins them, and the rest of the code reads the `bool` it
/// meant. A compound form is named as written. PHP turns both `bool`s into ints.
#[test]
fn a_bitwise_operator_on_two_bools_names_the_bool_operator_to_write() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public static bool show(bool isAdmin, bool isOwner)\n    {\n        const either = isAdmin | isOwner;\n        const both = isAdmin & isOwner;\n        const one = isAdmin ^ isOwner;\n        isAdmin |= isOwner;\n        return either && both && one && isAdmin;\n    }\n}\n";
    let help = "`||`, `&&` and `!=` join two `bool` values.";

    assert_eq!(
        refusals(("src/Demo/Report.sharp", sharp), &[]),
        [
            format!(
                "7:24 invalid-operand `|` takes `int`, but both sides are `bool`: write `||` for two `bool` values. | {help}"
            ),
            format!(
                "8:22 invalid-operand `&` takes `int`, but both sides are `bool`: write `&&` for two `bool` values. | {help}"
            ),
            format!(
                "9:21 invalid-operand `^` takes `int`, but both sides are `bool`: write `!=` for two `bool` values. | {help}"
            ),
            format!(
                "10:9 invalid-operand `|=` takes `int`, but both sides are `bool`: write `||` for two `bool` values. | {help}"
            ),
        ]
    );
}

/// Any other operand that is not an `int` is refused by its PHP# type, a nullable `int` included. PHP turns a `float`
/// into an int silently, refuses the `string`, warns on the nullable `int`, and reads its unchecked results as
/// `mixed`.
#[test]
fn a_bitwise_operator_on_a_value_that_is_not_an_int_is_refused_by_its_type() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public static int pack(float ratio, string name, int? count)\n    {\n        const a = ratio | 1;\n        const b = name & 1;\n        const c = count << 1;\n        const d = ~ratio;\n        return a + b + c + d;\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nclass Report\n{\n    public static function pack(float $ratio, string $name, ?int $count): int\n    {\n        $a = $ratio | 1;\n        $b = $name & 1;\n        $c = $count << 1;\n        $d = ~$ratio;\n        return $a + $b + $c + $d;\n    }\n}\n";
    let convert = "Use an `int`: `(int)` converts a `float`, and `Int.parse` reads a `string`.";

    assert_eq!(
        refusals(("src/Demo/Report.sharp", sharp), &[]),
        [
            format!("7:19 invalid-operand `|` takes `int`, but this is `float`. | {convert}"),
            format!("8:19 invalid-operand `&` takes `int`, but this is `string`. | {convert}"),
            "9:19 invalid-operand `<<` takes `int`, but this is `int?`. | Test it with `!= null` first.".to_string(),
            format!("10:20 invalid-operand `~` takes `int`, but this is `float`. | {convert}"),
        ]
    );
    assert_eq!(
        issues(("src/Demo/Report.php", php), &[]),
        [
            "10:14 invalid-operand",
            "10:9 mixed-assignment",
            "11:14 possibly-null-operand",
            "13:21 mixed-operand",
            "13:16 mixed-operand",
            "13:16 mixed-operand",
            "13:16 mixed-return-statement",
        ]
    );
    assert_eq!(
        messages(("src/Demo/Report.php", php), &[])
            .into_iter()
            .filter(|message| message.starts_with("Invalid type for"))
            .collect::<Vec<_>>(),
        ["Invalid type for left operand."]
    );
}

#[test]
fn casts_between_numbers_have_the_types_they_have_in_php() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public static string cents(float price, int count)\n    {\n        const cents = (int)(price * 100);\n        const share = (float)count / 3;\n        return (string)cents + (string)share + (string)(int)share;\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nclass Report\n{\n    public static function cents(float $price, int $count): string\n    {\n        $cents = (int)($price * 100);\n        $share = (float)$count / 3;\n        return (string)$cents . (string)$share . (string)(int)$share;\n    }\n}\n";

    let sharp_issues = issues(("src/Demo/Report.sharp", sharp), &[]);
    let php_issues = issues(("src/Demo/Report.php", php), &[]);

    assert_eq!(sharp_issues, Vec::<String>::new());
    assert_eq!(codes(&sharp_issues), codes(&php_issues));
}

#[test]
fn a_cast_of_a_value_that_is_not_a_number_is_an_invalid_operand() {
    let source = "<?php\n\nnamespace Lib;\n\nfinal class Source\n{\n    public static function value(): mixed\n    {\n        return 1;\n    }\n}\n";
    let sharp = "namespace Demo;\n\nimport Lib.Source;\n\nclass Report\n{\n    public static string pick(string name, bool flag, int? maybe)\n    {\n        const a = (int)name;\n        const b = (float)flag;\n        const c = (string)name;\n        const d = (int)maybe;\n        const e = (string)Source.value();\n        return `${a}${b}${c}${d}${e}`;\n    }\n}\n";

    assert_eq!(
        issues(("src/Demo/Report.sharp", sharp), &[("src/Lib/Source.php", source)]),
        [
            "9:19 invalid-operand",
            "10:19 invalid-operand",
            "11:19 invalid-operand",
            "12:19 invalid-operand",
            "13:19 invalid-operand",
        ]
    );
}

/// Spec section 8 removes `die`, because `die("…")` prints its message and exits with status 0, which reports success.
/// `compact` and `extract` reach locals by their names in strings, and `clone` copies an object without its
/// constructor, where spec section 16 copies a value with `with`. Each bare call names no function, as a misspelled
/// name does.
#[test]
fn die_compact_extract_and_clone_are_functions_php_sharp_has_not() {
    let sharp = "namespace Demo;\n\nclass Shutdown\n{\n    public void fail() { die(\"failed\"); }\n    public void code() { die(1); }\n    public Any? pack() => compact(\"values\");\n    public void unpack(Map<string, int> values) { extract(values); }\n    public Any? copied() => clone(this);\n}\n";
    let missing = |at: &str, name: &str| {
        format!("{at} non-existent-function Function `{name}` does not exist. | Check the spelling of `{name}`.")
    };

    assert_eq!(
        refusals(("src/Demo/Shutdown.sharp", sharp), &[]),
        [
            missing("5:26", "die"),
            missing("6:26", "die"),
            missing("7:27", "compact"),
            missing("8:51", "extract"),
            missing("9:29", "clone"),
        ]
    );
}

/// The standard library's `Int` and `Float`, with the library's signatures, which a project reads from `vendor/`.
const LIBRARY_TYPE_CLASSES: [(&str, &str); 1] = [(
    "vendor/heyjordanparker/php-sharp-composer/library/Sharp/Float.sharp",
    include_str!("../../../../composer/library/Sharp/Float.sharp"),
)];

/// The semantic checks let any file whose namespace is `Sharp` declare `Int`, `Float` and `Bool`, as the engine does,
/// and only the analyzer knows the file is not the standard library's. So it refuses `namespace Sharp` and every
/// namespace under it outside the standard library, which would also reach `Sharp.Internal` with no import. A
/// namespace that only starts with the letters is the app's.
#[test]
fn a_namespace_of_the_standard_library_in_a_project_file_is_a_reserved_name() {
    let refusal = |namespace: &str| {
        format!(
            "1:11 reserved-name-outside-library `{namespace}` is a namespace of the standard library, and only the standard library declares code in it. | Declared here. | Declare the file in a namespace of the app."
        )
    };
    let bool_class = (
        "src/Sharp/Bool.sharp",
        "namespace Sharp;\n\npublic static class Bool\n{\n    public static bool? tryParse(Any? value) => null;\n}\n",
    );
    let int_enum = ("src/Sharp/Int.sharp", "namespace Sharp;\n\npublic enum Int\n{\n    case One;\n}\n");
    let [order_event, order_paid] = ORDER_EVENTS;
    let inside = (
        "app/Sneak/Inside.sharp",
        "namespace Sharp;\n\nimport App.Shop.OrderPaid;\n\npublic class Inside\n{\n    public Listening watch() => Internal.listen(typeof(OrderPaid), (OrderPaid e) => { });\n}\n",
    );
    let internal = ("app/Sneak/Listen.sharp", "namespace Sharp.Internal;\n\npublic class Listen\n{\n}\n");
    let sharpen = ("app/Sharpen/Knife.sharp", "namespace Sharpen;\n\npublic class Knife\n{\n}\n");

    assert_eq!(worded(bool_class, &[]), [refusal("Sharp")]);
    assert_eq!(worded(int_enum, &[]), [refusal("Sharp")]);
    assert_eq!(worded(inside, &[EVENTS, order_event, order_paid]), [refusal("Sharp")]);
    assert_eq!(worded(internal, &[]), [refusal("Sharp.Internal")]);
    assert_eq!(worded(sharpen, &[]), Vec::<String>::new());
}

/// Spec section 23: a class cannot share its full name with a namespace, when the class or anything in the namespace
/// is PHP#. Two plain PHP names may, as PHP allows. The error names the first class in the namespace by name.
#[test]
fn a_class_that_shares_its_full_name_with_a_namespace_is_an_error() {
    let store = ("src/App/Tenant/Store.sharp", "namespace App.Tenant;\n\npublic class Store\n{\n}\n");
    let order = ("src/App/Tenant/Store/Order.sharp", "namespace App.Tenant.Store;\n\npublic class Order\n{\n}\n");
    let php_store = ("src/App/Tenant/Store.php", "<?php\n\nnamespace App\\Tenant;\n\nclass Store\n{\n}\n");
    let php_order = ("src/App/Tenant/Store/Order.php", "<?php\n\nnamespace App\\Tenant\\Store;\n\nclass Order\n{\n}\n");
    let receipts =
        ("src/App/Tenant/Store/Receipts.sharp", "namespace App.Tenant.Store;\n\npublic class Receipts\n{\n}\n");
    let rows = [
        (
            store,
            vec![order],
            Some(
                "3:14 name-already-in-use `App.Tenant.Store` is both a class and a namespace: rename the class or the folder. | `App.Tenant.Store.Order` is in the namespace `App.Tenant.Store`.",
            ),
        ),
        (
            ("src/App/Tenant/Store.sharp", "namespace App.Tenant;\n\npublic interface Store\n{\n}\n"),
            vec![order],
            Some(
                "3:18 name-already-in-use `App.Tenant.Store` is both an interface and a namespace: rename the interface or the folder. | `App.Tenant.Store.Order` is in the namespace `App.Tenant.Store`.",
            ),
        ),
        (
            ("src/App/Tenant/Store.sharp", "namespace App.Tenant;\n\npublic enum Store\n{\n    case Open;\n}\n"),
            vec![order],
            Some(
                "3:13 name-already-in-use `App.Tenant.Store` is both an enum and a namespace: rename the enum or the folder. | `App.Tenant.Store.Order` is in the namespace `App.Tenant.Store`.",
            ),
        ),
        (
            store,
            vec![receipts, order],
            Some(
                "3:14 name-already-in-use `App.Tenant.Store` is both a class and a namespace: rename the class or the folder. | `App.Tenant.Store.Order` is in the namespace `App.Tenant.Store`.",
            ),
        ),
        (
            store,
            vec![php_order],
            Some(
                "3:14 name-already-in-use `App.Tenant.Store` is both a class and a namespace: rename the class or the folder. | `App.Tenant.Store.Order` is in the namespace `App.Tenant.Store`.",
            ),
        ),
        (
            php_store,
            vec![order],
            Some(
                "5:7 name-already-in-use `App\\Tenant\\Store` is both a class and a namespace: rename the class or the folder. | `App\\Tenant\\Store\\Order` is in the namespace `App\\Tenant\\Store`.",
            ),
        ),
        (php_store, vec![php_order], None),
        // `mago compile` prints only `.sharp` files' errors, so the PHP# side of the clash reports it too.
        (
            order,
            vec![php_store],
            Some(
                "3:14 name-already-in-use `App.Tenant.Store` is both a plain PHP class and a namespace: rename the class or the folder. | The plain PHP class is declared here.",
            ),
        ),
        (
            ("src/App/Tenant/Store/Shelf/Item.sharp", "namespace App.Tenant.Store.Shelf;\n\npublic class Item\n{\n}\n"),
            vec![php_store],
            Some(
                "3:14 name-already-in-use `App.Tenant.Store` is both a plain PHP class and a namespace: rename the class or the folder. | The plain PHP class is declared here.",
            ),
        ),
        (
            ("src/App/Tenant/Store/Store.sharp", "namespace App.Tenant.Store;\n\npublic class Store\n{\n}\n"),
            vec![order],
            None,
        ),
        (
            store,
            vec![(
                "src/App/Tenant/Storefront/Order.sharp",
                "namespace App.Tenant.Storefront;\n\npublic class Order\n{\n}\n",
            )],
            None,
        ),
        // `App.Tenant.Store2.Alpha` sorts before `App.Tenant.Store.Order`, and it is not in the namespace.
        (
            store,
            vec![
                order,
                ("src/App/Tenant/Store2/Alpha.sharp", "namespace App.Tenant.Store2;\n\npublic class Alpha\n{\n}\n"),
            ],
            Some(
                "3:14 name-already-in-use `App.Tenant.Store` is both a class and a namespace: rename the class or the folder. | `App.Tenant.Store.Order` is in the namespace `App.Tenant.Store`.",
            ),
        ),
    ];

    for (analyzed, others, expected) in rows {
        let refusals: Vec<String> = analyze(&PLUGIN_REGISTRY, settings(), analyzed, &others)
            .iter()
            .map(|issue| {
                let inside = issue.annotations.last().and_then(|annotation| annotation.message.as_deref());
                format!("{} {} | {}", located(analyzed.1, issue), issue.message, inside.unwrap_or_default())
            })
            .collect();
        assert_eq!(refusals, Vec::from_iter(expected), "{} beside {others:?}", analyzed.0);
    }
}

#[test]
fn int_and_float_parse_have_the_types_of_the_sharp_library_classes() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public static int count(string text, string fallback)\n    {\n        const price = Float.parse(text) + (Float.tryParse(fallback) ?? 0.0);\n        const count = Int.parse(text) + (Int.tryParse(fallback) ?? 0);\n        return price > 1.0 ? count : Int.tryParse(text);\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nclass Report\n{\n    public static function count(string $text, string $fallback): int\n    {\n        $price = \\Sharp\\Float::parse($text) + (\\Sharp\\Float::tryParse($fallback) ?? 0.0);\n        $count = \\Sharp\\Int::parse($text) + (\\Sharp\\Int::tryParse($fallback) ?? 0);\n        return $price > 1.0 ? $count : \\Sharp\\Int::tryParse($text);\n    }\n}\n";

    // `check_throws` skips `.sharp` files, so the PHP twin is analyzed without it.
    let sharp_issues = issues(("src/Demo/Report.sharp", sharp), &LIBRARY_TYPE_CLASSES);
    let php_issues = issues_with(
        Settings { check_throws: false, ..settings() },
        ("src/Demo/Report.php", php),
        &LIBRARY_TYPE_CLASSES,
    );

    assert_eq!(sharp_issues, ["9:16 nullable-return-statement", "9:16 invalid-return-statement"]);
    assert_eq!(codes(&sharp_issues), codes(&php_issues));
}

/// `Position.current()` replaces `__DIR__`, `__FILE__` and `__LINE__`, spec section 27.
#[test]
fn position_current_has_the_types_of_the_sharp_library_class() {
    let sharp = "namespace Demo;\n\nclass Reports\n{\n    public string stubsFolder()\n    {\n        const stubs = Position.current().directory + \"/stubs\";\n        return stubs;\n    }\n\n    public int line() => Position.current().line;\n\n    public int wrong() => Position.current().directory;\n}\n";

    assert_eq!(issues(("src/Demo/Reports.sharp", sharp), &[]), ["13:27 invalid-return-statement"]);
}

/// `Environment` replaces `$_ENV` and `getenv()`, spec section 29: `variable` gives null for a variable that is not
/// set, and `require`, which a module binding calls, throws instead.
#[test]
fn an_environment_variable_is_a_nullable_string_and_a_required_one_a_string() {
    let sharp = "namespace Demo;\n\nimport Sharp.System.Environment;\n\nclass Deploy\n{\n    public Deploy(private Environment environment) { }\n\n    public string region() => this.environment.variable(\"X\") ?? \"d\";\n\n    public int wrong() => this.environment.variable(\"X\") ?? \"d\";\n\n    public string url() => this.environment.require(\"X\");\n\n    public int port() => this.environment.require(\"X\");\n}\n";

    assert_eq!(
        issues(("src/Demo/Deploy.sharp", sharp), &[]),
        ["11:27 invalid-return-statement", "15:26 invalid-return-statement"]
    );
}

/// `arguments` is a `{ get; }` property, because a process's arguments never change, so it is read, never written.
/// The current directory changes, so `currentDirectory()` and `changeDirectory(path)` are methods.
#[test]
fn the_environment_arguments_are_read_only_and_the_current_directory_is_a_method() {
    let sharp = "namespace Demo;\n\nimport Sharp.System.Environment;\n\nclass Deploy\n{\n    public Deploy(private Environment environment) { }\n\n    public List<string> arguments() => this.environment.arguments;\n\n    public string folder() => this.environment.currentDirectory();\n\n    public List<int> numbers() => this.environment.arguments;\n\n    public void change()\n    {\n        this.environment.changeDirectory(\"/tmp\");\n        this.environment.arguments = [\"deploy\"];\n    }\n}\n";

    assert_eq!(
        issues(("src/Demo/Deploy.sharp", sharp), &[]),
        ["13:35 invalid-return-statement", "18:26 invalid-property-write"]
    );
    assert_eq!(
        messages(("src/Demo/Deploy.sharp", sharp), &[])[1..],
        ["Cannot initialize readonly property `Environment.arguments` from within `Deploy`."]
    );

    let php = "<?php\n\nnamespace Demo;\n\nuse Sharp\\System\\Environment;\n\nclass Deploy\n{\n    public function __construct(private Environment $environment) { }\n\n    public function change(): void\n    {\n        $this->environment->arguments = ['deploy'];\n    }\n}\n";
    assert_eq!(
        messages(("src/Demo/Deploy.php", php), &[]),
        ["Cannot initialize readonly property `Sharp\\System\\Environment::$arguments` from within `Demo\\Deploy`."]
    );
}

/// `List.wrap` replaces `(array)value`, spec section 24: a value that is never itself a list wraps as one call.
#[test]
fn list_wrap_of_a_value_or_a_list_of_it_is_a_list_of_the_value() {
    let sharp = "namespace Demo;\n\nclass Tags\n{\n    public List<string> read(string|List<string> value)\n    {\n        List<string> tags = List.wrap(value);\n        return tags;\n    }\n\n    public List<int> wrong(string|List<string> value) => List.wrap(value);\n}\n";

    assert_eq!(issues(("src/Demo/Tags.sharp", sharp), &[]), ["11:58 invalid-return-statement"]);
}

/// A `List` runs as a PHP array, so `wrap` cannot tell a list of lists from a list to wrap. The refusal names what `T`
/// is, and the call keeps the type the code asked for, so the assignment adds no second issue.
#[test]
fn list_wrap_of_a_list_is_refused_once() {
    let sharp = "namespace Demo;\n\nclass Rows\n{\n    public List<List<int>> read(List<int> numbers)\n    {\n        List<List<int>> rows = List.wrap(numbers);\n        return rows;\n    }\n}\n";

    assert_eq!(issues(("src/Demo/Rows.sharp", sharp), &[]), ["7:42 invalid-argument"]);
    assert_eq!(
        messages(("src/Demo/Rows.sharp", sharp), &[]),
        ["T is List<int>, itself a list; write `numbers is List<int> one ? [one] : numbers`"]
    );
}

/// `Class.of(value)` is the class of the object a value holds, spec section 25, so it is a class value of the value's
/// type: it reaches the static of the class it holds, and goes where plain PHP takes a class name. It takes an object
/// only, since a class is what it gives, and the refusal names that bound once.
#[test]
fn class_of_a_value_is_a_class_value_of_its_type() {
    let factory = "<?php\n\nnamespace Lib;\n\nfinal class Factory\n{\n    /**\n     * @template T of object\n     * @param class-string<T> $class\n     * @return T\n     */\n    public static function make(string $class): object\n    {\n        return new $class();\n    }\n}\n";
    let sharp = "namespace Demo;\n\nimport Lib.Factory;\n\nclass Badge\n{\n    public static string tag() => \"badge\";\n\n    public string tagOf(Badge badge)\n    {\n        const type = Class.of(badge);\n        return type.tag();\n    }\n\n    public Badge remade(Badge badge) => Factory.make(Class.of(badge));\n\n    public string named(Badge badge) => Class.of(badge);\n\n    public int wrong(Badge badge) => Class.of(badge);\n\n    public void count() { Class.of(5); }\n}\n";
    let others = [("src/Lib/Factory.php", factory)];

    assert_eq!(
        issues(("src/Demo/Badge.sharp", sharp), &others),
        ["19:38 invalid-return-statement", "21:36 template-constraint-violation"]
    );
    assert_eq!(
        messages(("src/Demo/Badge.sharp", sharp), &others),
        [
            "Invalid return type for method `Badge.wrong`: expected `int`, but found `Class<Badge>`.",
            "`int` does not satisfy the bound `Object` of type parameter `T`."
        ]
    );
}

/// A value from plain PHP typed `mixed` arrives as `Any?`, which could hold a list.
#[test]
fn list_wrap_of_a_value_of_any_type_is_refused() {
    let settings = "<?php\n\nnamespace Lib;\n\nfinal class Settings\n{\n    public static function raw(string $key): mixed\n    {\n        return $key;\n    }\n}\n";
    let sharp = "namespace Demo;\n\nimport Lib.Settings;\n\nclass Plans\n{\n    public void read()\n    {\n        List.wrap(Settings.raw(\"plan\"));\n        List.wrap(Settings.raw(\"plan\") ?? \"free\");\n    }\n}\n";
    let others = [("src/Lib/Settings.php", settings)];

    assert_eq!(issues(("src/Demo/Plans.sharp", sharp), &others), ["9:19 invalid-argument", "10:19 invalid-argument"]);
    assert_eq!(
        messages(("src/Demo/Plans.sharp", sharp), &others),
        [
            "T is Any?, which could itself be a list; check what `Settings.raw(\"plan\")` is with `is` first",
            "T is Any, which could itself be a list; check what `Settings.raw(\"plan\") ?? \"free\"` is with `is` first",
        ]
    );
}

/// An editor shows the docblocks of the PHP# stub on hover. A PHP# user reads them, not the spec's numbering, so each
/// states its reason in words and cites no spec section.
#[test]
fn the_php_sharp_stub_states_its_reasons_without_a_spec_section() {
    let stub = PRELUDE
        .database
        .files()
        .find(|file| file.name.ends_with(b"extensions/sharp.php"))
        .expect("the prelude holds the PHP# stub");
    let contents = String::from_utf8_lossy(&stub.contents);

    assert_eq!(contents.lines().filter(|line| line.contains("section")).collect::<Vec<_>>(), Vec::<&str>::new());
}

/// A `Map` and a `Set` are one object each, so `wrap` holds one in a one-element `List`, as any other value: `T` is the
/// `Map` or the `Set`. Only a `List` is returned as it is, so a list of lists and a value that can be a list are refused.
#[test]
fn list_wrap_holds_a_map_or_a_set_and_refuses_a_value_that_can_be_a_list() {
    let sharp = "namespace Demo;\n\nclass Rows\n{\n    public List<Map<string, int>> counts(Map<string, int> counts) => List.wrap(counts);\n\n    public List<Set<string>> tags(Set<string> tags) => List.wrap(tags);\n\n    public List<string|Map<string, int>> either(string|Map<string, int> either) => List.wrap(either);\n\n    public List<int> wrong(Map<string, int> counts) => List.wrap(counts);\n\n    public void read(List<List<int>> rows, string|List<int> one)\n    {\n        List.wrap(rows);\n        List.wrap(one);\n    }\n}\n";

    assert_eq!(
        issues(("src/Demo/Rows.sharp", sharp), &[]),
        ["11:56 invalid-return-statement", "15:19 invalid-argument"]
    );
    assert_eq!(
        messages(("src/Demo/Rows.sharp", sharp), &[])[1],
        "T is List<List<int>>, itself a list; write `rows is List<List<int>> one ? [one] : rows`"
    );
}

#[test]
fn expression_bodies_and_computed_properties_are_checked_as_php_checks_their_twins() {
    let sharp = "namespace Demo;\n\nimport Lib.Words;\n\nclass Report\n{\n    private string name = \"\";\n    private int count = 0;\n\n    public Report(string name) => this.name = name;\n\n    public string slug => Words.upper(this.name);\n    public int size => this.name;\n    public int total() => this.count + 1;\n    public string label() => this.count;\n    public void touch() => this.count++;\n    public void reset(int unused) => this.count = 0;\n    public void rename() => this.slug = \"x\";\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nuse Lib\\Words;\n\nclass Report\n{\n    private string $name = \"\";\n    private int $count = 0;\n\n    public function __construct(string $name) { $this->name = $name; }\n\n    public string $slug { get => Words::upper($this->name); }\n    public int $size { get => $this->name; }\n    public function total(): int { return $this->count + 1; }\n    public function label(): string { return $this->count; }\n    public function touch(): void { $this->count++; }\n    public function reset(int $unused): void { $this->count = 0; }\n    public function rename(): void { $this->slug = \"x\"; }\n}\n";

    let sharp_issues = issues(("src/Demo/Report.sharp", sharp), &[WORDS]);
    let php_issues = issues(("src/Demo/Report.php", php), &[WORDS]);

    assert_eq!(
        sharp_issues,
        ["13:24 invalid-return-statement", "15:30 invalid-return-statement", "18:34 invalid-property-write"]
    );
    assert_eq!(codes(&sharp_issues), codes(&php_issues));
}

const CUSTOMER: &str = "namespace Demo;\n\nclass Customer\n{\n    public string name { get; set; } = \"\";\n\n    public string label()\n    {\n        return this.name;\n    }\n}\n\nclass Plan\n{\n    public int price { get; set; } = 0;\n}\n";

/// Analyzes `analyzed` together with `others`, and returns its errors as `line:column code`.
fn errors(analyzed: (&'static str, &'static str), others: &[(&'static str, &'static str)]) -> Vec<String> {
    analyze(&PLUGIN_REGISTRY, settings(), analyzed, others)
        .iter()
        .filter(|issue| issue.level == Level::Error)
        .map(|issue| located(analyzed.1, issue))
        .collect()
}

/// Spec section 14.4: a null check on a value whose type has no `?` is a compile error.
#[test]
fn a_null_check_on_a_value_that_is_never_null_is_an_error() {
    let sharp = "namespace Demo;\n\nclass Billing\n{\n    public void renew(Customer customer, Plan plan, Plan? maybe)\n    {\n        const a = customer != null;\n        const b = customer == null;\n        const c = customer !== null;\n        const d = null === customer;\n        const price = plan.price ?? 0;\n        let total = plan.price;\n        total ??= 1;\n        const name = customer?.name;\n        const label = customer?.label();\n        const e = maybe ?? plan;\n        const f = maybe?.price;\n        const g = maybe !== null;\n    }\n}\n";

    assert_eq!(
        errors(("src/Demo/Billing.sharp", sharp), &[("src/Demo/Customer.sharp", CUSTOMER)]),
        [
            "7:19 redundant-comparison",
            "8:19 redundant-comparison",
            "9:19 redundant-comparison",
            "10:28 redundant-comparison",
            "11:23 redundant-null-coalesce",
            "13:9 redundant-null-coalesce",
            "14:30 redundant-nullsafe-operator",
            "15:31 redundant-nullsafe-operator",
        ]
    );
}

#[test]
fn a_null_check_on_a_value_that_is_never_null_keeps_its_php_report() {
    let php = "<?php\n\nnamespace Demo;\n\nclass Billing\n{\n    public function renew(Customer $customer, Plan $plan, ?Plan $maybe): void\n    {\n        $a = $customer != null;\n        $b = $customer == null;\n        $c = $customer !== null;\n        $d = null === $customer;\n        $price = $plan->price ?? 0;\n        $total = $plan->price;\n        $total ??= 1;\n        $name = $customer?->name;\n        $label = $customer?->label();\n        $e = $maybe ?? $plan;\n        $f = $maybe?->price;\n        $g = $maybe !== null;\n    }\n}\n";

    let levelled: Vec<_> =
        analyze(&PLUGIN_REGISTRY, settings(), ("src/Demo/Billing.php", php), &[("src/Demo/Customer.sharp", CUSTOMER)])
            .iter()
            .map(|issue| format!("{} {:?}", located(php, issue), issue.level))
            .collect();

    assert_eq!(
        levelled,
        [
            "9:27 null-operand Error",
            "9:14 impossible-null-type-comparison Warning",
            "10:27 null-operand Error",
            "10:14 impossible-null-type-comparison Warning",
            "11:14 redundant-comparison Help",
            "11:14 impossible-null-type-comparison Warning",
            "12:14 redundant-comparison Help",
            "12:14 impossible-null-type-comparison Warning",
            "13:18 redundant-null-coalesce Help",
            "15:9 redundant-null-coalesce Help",
            "16:26 redundant-nullsafe-operator Help",
        ]
    );
}

/// A null check that cannot matter names the test as the developer wrote it: `is null` and `is not null` run as
/// PHP's `===`, which the developer never wrote. PHP names its own operator.
#[test]
fn a_redundant_null_check_names_the_test_it_is_written_with() {
    let sharp = "namespace Demo;\n\nclass Billing\n{\n    public void renew(Customer report)\n    {\n        const a = report is null;\n        const b = report is not null;\n        const c = report == null;\n        const d = report != null;\n        const e = match (report) {\n            null => 0,\n            default => 1,\n        };\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nclass Billing\n{\n    public function renew(Customer $report): void\n    {\n        $a = $report === null;\n        $b = $report !== null;\n    }\n}\n";
    let redundant = |analyzed| -> Vec<String> {
        worded(analyzed, &[("src/Demo/Customer.sharp", CUSTOMER)])
            .into_iter()
            .filter(|line| line.contains(" redundant-comparison "))
            .collect()
    };

    let sharp_report = |at: &str, check: &str| {
        format!(
            "{at} redundant-comparison Redundant {check}: `Customer` is never `null`. | This is `Customer`, which is never `null` | This null check cannot matter | In PHP# a type holds null only when written with `?`, so a `?` or a null check that cannot matter is an error. | Remove the null check."
        )
    };

    assert_eq!(
        redundant(("src/Demo/Billing.php", php)),
        [
            "9:14 redundant-comparison Redundant `===` comparison: left-hand side is never identical to right-hand side. | Left operand is `Demo\\Customer` | Right operand is `null` | The `===` operator will always return `false` in this case. | Consider simplifying or removing this comparison as it always evaluates to `false`.",
            "10:14 redundant-comparison Redundant `!==` comparison: left-hand side is always not identical to right-hand side. | Left operand is `Demo\\Customer` | Right operand is `null` | The `!==` operator will always return `true` in this case. | Consider simplifying or removing this comparison as it always evaluates to `true`.",
        ]
    );
    assert_eq!(
        redundant(("src/Demo/Billing.sharp", sharp)),
        [
            sharp_report("7:19", "`is null` check"),
            sharp_report("8:19", "`is not null` check"),
            sharp_report("9:19", "`==` comparison"),
            sharp_report("10:19", "`!=` comparison"),
            sharp_report("11:34", "`null` check"),
        ]
    );
}

/// A redundant null check names its pattern by the words the pattern is written with, so a comment between them stays
/// out of the message. The `is` and each `not` lead the check only when they are written right before it, wherever the
/// pattern stands, as after a list's rest or in a case's field. PHP names its own operator.
#[test]
fn a_redundant_null_check_names_its_pattern_without_its_comments() {
    let sharp = "namespace Demo;\n\nclass Billing\n{\n    public void renew(Customer report, List<string> names, List<Customer> customers, Delivery delivery)\n    {\n        const a = report is /* c */ null;\n        const b = report is /* c */ not /* d */ null;\n        const c = report is (/* e */ null) or not null;\n        const d = report is { name: /* f */ null };\n        const e = report is Customer { name: not /* g */ null } customer;\n        const f = names is [not /* h */ null];\n        const g = customers is [..., { name: not /* i */ null }];\n        const h = delivery is Delivery.Noted(not /* j */ null);\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nclass Billing\n{\n    public function renew(Customer $report): void\n    {\n        $a = $report === /* c */ null;\n        $b = $report !== /* c */ null;\n    }\n}\n";
    let delivery =
        ("src/Demo/Delivery.sharp", "namespace Demo;\n\nenum Delivery\n{\n    case Noted(string note);\n}\n");
    let redundant = |analyzed| -> Vec<String> {
        worded(analyzed, &[("src/Demo/Customer.sharp", CUSTOMER), delivery])
            .into_iter()
            .filter(|line| line.contains(" redundant-comparison "))
            .map(|line| line.split(" | ").next().unwrap_or_default().to_owned())
            .collect()
    };

    assert_eq!(
        redundant(("src/Demo/Billing.php", php)),
        [
            "9:14 redundant-comparison Redundant `===` comparison: left-hand side is never identical to right-hand side.",
            "10:14 redundant-comparison Redundant `!==` comparison: left-hand side is always not identical to right-hand side.",
        ]
    );
    assert_eq!(
        redundant(("src/Demo/Billing.sharp", sharp)),
        [
            "7:19 redundant-comparison Redundant `is null` check: `Customer` is never `null`.",
            "8:19 redundant-comparison Redundant `is not null` check: `Customer` is never `null`.",
            "9:19 redundant-comparison Redundant `null` check: `Customer` is never `null`.",
            "9:47 redundant-comparison Redundant `not null` check: `Customer` is never `null`.",
            "10:31 redundant-comparison Redundant `null` check: `string` is never `null`.",
            "11:40 redundant-comparison Redundant `not null` check: `string` is never `null`.",
            "12:29 redundant-comparison Redundant `not null` check: `string` is never `null`.",
            "13:40 redundant-comparison Redundant `not null` check: `string` is never `null`.",
            "14:46 redundant-comparison Redundant `not null` check: `string` is never `null`.",
        ]
    );
}

/// `== null` and `!= null` run as PHP's `=== null` and `!== null`, so they test for null alone and are no loose
/// comparison with `null`.
#[test]
fn equality_with_null_tests_for_null_with_no_operand_issue() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public static int total(int? extra)\n    {\n        if (extra != null) {\n            return extra;\n        }\n        return 0;\n    }\n\n    public static bool missing(int? extra)\n    {\n        return null == extra;\n    }\n}\n";

    assert_eq!(issues(("src/Demo/Report.sharp", sharp), &[]), Vec::<String>::new());
}

/// Each issue in `analyzed`, analyzed together with `others`, as `line:column code message | help`.
fn refusals(analyzed: (&'static str, &'static str), others: &[(&'static str, &'static str)]) -> Vec<String> {
    analyze(&PLUGIN_REGISTRY, settings(), analyzed, others)
        .iter()
        .map(|issue| {
            format!("{} {} | {}", located(analyzed.1, issue), issue.message, issue.help.as_deref().unwrap_or_default())
        })
        .collect()
}

const CART: &str = "<?php\n\nnamespace Demo;\n\nfinal class Cart\n{\n}\n";

/// Spec section 19: numbers compare by value, so `1 == 1.0` is true, a nullable side lifted. The pair narrows nothing,
/// so `count == 1.0` makes no impossible test. PHP reports what its loose `==` and its narrowing give.
#[test]
fn equality_of_an_int_and_a_float_compares_their_values_with_no_issue() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public static bool a(int count, float ratio) => count == ratio;\n\n    public static bool b(float ratio, int? count) => ratio != count;\n\n    public static int c(int count)\n    {\n        if (count == 1.0) {\n            return count;\n        }\n        return 0;\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nclass Report\n{\n    public static function a(int $count, float $ratio): bool { return $count == $ratio; }\n\n    public static function b(float $ratio, ?int $count): bool { return $ratio != $count; }\n\n    public static function c(int $count): int\n    {\n        if ($count == 1.0) {\n            return $count;\n        }\n        return 0;\n    }\n}\n";

    assert_eq!(issues(("src/Demo/Report.php", php), &[]), ["9:82 possibly-null-operand"]);
    assert_eq!(issues(("src/Demo/Report.sharp", sharp), &[]), Vec::<String>::new());
}

/// Spec section 19: values of two different types are never equal, so `==` on them is refused. PHP keeps its loose
/// `==`, where `"1" == 1` is true.
#[test]
fn equality_of_two_different_value_types_is_refused() {
    let enums = [
        ("src/Demo/Status.php", "<?php\n\nnamespace Demo;\n\nenum Status\n{\n    case Open;\n}\n"),
        ("src/Demo/Level.php", "<?php\n\nnamespace Demo;\n\nenum Level\n{\n    case Low;\n}\n"),
    ];
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public static bool a(string text, int total) => text == total;\n\n    public static bool b(Status status, Level level) => status != level;\n}\n";

    assert_eq!(
        refusals(("src/Demo/Report.sharp", sharp), &enums),
        [
            "5:53 invalid-operand `==` cannot compare `string` with `int`. | Convert one side so both sides have the same type.",
            "7:57 invalid-operand `!=` cannot compare `Status` with `Level`. | Convert one side so both sides have the same type.",
        ]
    );
}

/// Spec section 19: `==` on a class instance exists only where the class declares `operator ==`, which `Cart` does not.
/// `===` tests for the same object, and `!= null` tests a nullable instance for null.
#[test]
fn equality_of_a_class_instance_is_refused_until_the_class_declares_operator_equality() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public static bool a(Cart cart, Cart other) => cart == other;\n\n    public static bool b(Cart? maybe, Cart cart) => maybe != cart;\n\n    public static bool c(Cart? maybe) => maybe != null;\n\n    public static bool d(Cart cart, Cart other) => cart === other;\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nclass Report\n{\n    public static function a(Cart $cart, Cart $other): bool { return $cart == $other; }\n\n    public static function b(?Cart $maybe, Cart $cart): bool { return $maybe != $cart; }\n\n    public static function c(?Cart $maybe): bool { return $maybe != null; }\n\n    public static function d(Cart $cart, Cart $other): bool { return $cart === $other; }\n}\n";

    assert_eq!(
        issues(("src/Demo/Report.php", php), &[("src/Demo/Cart.php", CART)]),
        ["9:71 possibly-null-operand", "11:59 possibly-null-operand", "11:69 null-operand"]
    );
    assert_eq!(
        refusals(("src/Demo/Report.sharp", sharp), &[("src/Demo/Cart.php", CART)]),
        [
            "5:52 invalid-operand `==` cannot compare `Cart` with `Cart`: `Cart` declares no `operator ==`. | Use `===` to test whether both sides are the same object.",
            "7:53 invalid-operand `!=` cannot compare `Cart?` with `Cart`: `Cart` declares no `operator ==`. | Use `!==` to test whether both sides are the same object.",
        ]
    );
}

/// Spec section 19: two lists compare element by element and two maps entry by entry, each element with its own `==`,
/// so a list of a class compares only where the class declares `operator ==`, and a list never equals a map. `Any?`
/// against a collection compares by value, spec section 24. The refusal names why the elements can't compare, through
/// nested lists: a class with no `operator ==`, or element types that never match.
#[test]
fn collections_compare_by_value() {
    let sharp = "namespace Demo;\n\nimport App.Money;\n\nclass Report\n{\n    public static bool a(List<int> items, List<int> others) => items == others;\n\n    public static bool b(Any? value, List<int> items) => value != items;\n\n    public static bool c(Map<string, int> a, Map<string, int> b, List<Money> m, List<Money> n, List<List<int>> d, List<List<int>> e) => a == b && m != n && d == e && d.contains(Report.items(1));\n\n    public static bool f(List<Cart> carts, List<Cart> others, List<int> items, Map<string, int> counts) => carts == others || items == counts;\n\n    public static bool g(List<List<Cart>> nested, List<List<Cart>> again, List<int> numbers, List<string> words) => nested == again || numbers == words;\n\n    public static List<int> items(int count) => [count];\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nclass Report\n{\n    /** @param list<int> $items @param list<int> $others */\n    public static function a(array $items, array $others): bool { return $items == $others; }\n\n    /** @param list<int> $items */\n    public static function b(mixed $value, array $items): bool { return $value != $items; }\n}\n";

    assert_eq!(issues(("src/Demo/Report.php", php), &[]), ["11:73 mixed-operand"]);
    assert_eq!(
        refusals(("src/Demo/Report.sharp", sharp), &[("src/Demo/Cart.php", CART), MONEY_OPERATORS]),
        [
            "13:108 invalid-operand `==` compares `List<Cart>` with `List<Cart>` element by element, and `Cart` declares no `operator ==`. | ",
            "13:127 invalid-operand `==` cannot compare `List<int>` with `Map<string, int>`. | Convert one side so both sides have the same type.",
            "15:117 invalid-operand `==` compares `List<List<Cart>>` with `List<List<Cart>>` element by element, and `Cart` declares no `operator ==`. | ",
            "15:136 invalid-operand `==` compares `List<int>` with `List<string>` element by element, and `int` never equals `string`. | ",
        ]
    );
}

/// Spec section 19: `===` and `!==` test whether two class instances are the same object. On any other value they are
/// refused, naming the `==` or `!=` that compares it. PHP keeps its `===`.
#[test]
fn identity_of_a_value_that_is_no_class_instance_is_refused_naming_equality() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public static bool a(int total) => total === 1;\n\n    public static bool b(string text) => text !== \"a\";\n\n    public static bool c(int? maybe) => maybe === null;\n\n    public static bool d(Cart? cart, Cart other) => cart === other;\n}\n";

    assert_eq!(
        refusals(("src/Demo/Report.sharp", sharp), &[("src/Demo/Cart.php", CART)]),
        [
            "5:40 invalid-operand `===` cannot compare `int` with `int`: it tests whether two class instances are the same object. | Use `==` to compare the values.",
            "7:42 invalid-operand `!==` cannot compare `string` with `string`: it tests whether two class instances are the same object. | Use `!=` to compare the values.",
            "9:41 invalid-operand `===` cannot compare `int?` with `null`: it tests whether two class instances are the same object. | Use `==` to compare the values.",
        ]
    );
}

/// PHP# orders a string only against a string, by its bytes, so a string against a number is refused as `==` refuses
/// it. Two numbers keep PHP's `<`, an `int` against a `float` too. PHP keeps its loose `<`.
#[test]
fn ordering_a_string_against_a_number_is_refused() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public static bool a(string text, int total) => text < total;\n\n    public static bool b(string text, float ratio) => text >= ratio;\n\n    public static bool c(string text, string other) => text < other;\n\n    public static bool d(int total, float ratio) => total < ratio;\n}\n";

    assert_eq!(
        refusals(("src/Demo/Report.sharp", sharp), &[]),
        [
            "5:53 invalid-operand `<` cannot compare `string` with `int`. | Convert one side so both sides have the same type.",
            "7:55 invalid-operand `>=` cannot compare `string` with `float`. | Convert one side so both sides have the same type.",
        ]
    );
}

/// Spec section 19 lifts only `==` and `!=` over `null`, so an ordering or `<=>` with a side that may be `null` is refused
/// for a string, an int and a float, as for an instance. Once the side is tested for `null`, it orders. PHP keeps its
/// loose `<`, which orders `null` as `""` or `0`.
#[test]
fn ordering_a_nullable_value_is_refused_until_it_is_tested_for_null() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public static bool a(string? name) => name < \"b\";\n\n    public static bool b(int? count) => count <= 1;\n\n    public static bool c(float? ratio) => ratio > 1.5;\n\n    public static int d(int? count, int total) => count <=> total;\n\n    public static bool e(string? name) => \"b\" >= name;\n\n    public static bool f(string? name) => name != null && name < \"b\";\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nclass Report\n{\n    public static function a(?string $name): bool { return $name < \"b\"; }\n\n    public static function b(?int $count): bool { return $count <= 1; }\n\n    public static function c(?float $ratio): bool { return $ratio > 1.5; }\n\n    public static function d(?int $count, int $total): int { return $count <=> $total; }\n\n    public static function e(?string $name): bool { return \"b\" >= $name; }\n\n    public static function f(?string $name): bool { return $name !== null && $name < \"b\"; }\n}\n";

    assert_eq!(
        issues(("src/Demo/Report.php", php), &[]),
        [
            "7:60 possibly-null-operand",
            "9:58 possibly-null-operand",
            "11:60 possibly-null-operand",
            "13:69 possibly-null-operand",
            "15:67 possibly-null-operand",
        ]
    );
    assert_eq!(
        refusals(("src/Demo/Report.sharp", sharp), &[]),
        [
            "5:43 invalid-operand `<` cannot compare `string?` with `string`: only `==` and `!=` take `null`, so test the value for `null` first. | Test it with `!= null` before the comparison.",
            "7:41 invalid-operand `<=` cannot compare `int?` with `int`: only `==` and `!=` take `null`, so test the value for `null` first. | Test it with `!= null` before the comparison.",
            "9:43 invalid-operand `>` cannot compare `float?` with `float`: only `==` and `!=` take `null`, so test the value for `null` first. | Test it with `!= null` before the comparison.",
            "11:51 invalid-operand `<=>` cannot compare `int?` with `int`: only `==` and `!=` take `null`, so test the value for `null` first. | Test it with `!= null` before the comparison.",
            "13:43 invalid-operand `>=` cannot compare `string` with `string?`: only `==` and `!=` take `null`, so test the value for `null` first. | Test it with `!= null` before the comparison.",
        ]
    );
}

/// A `bool` has no order, so an ordering of `true` is refused, and so is one of a plain PHP value typed `int|false`,
/// whose type holds a `bool`. PHP keeps its loose `<`.
#[test]
fn ordering_a_bool_is_refused() {
    let store = (
        "src/Lib/Store.php",
        "<?php\n\nnamespace Lib;\n\nfinal class Store\n{\n    public static function count(): int|false { return 1; }\n}\n",
    );
    let sharp = "namespace Demo;\n\nimport Lib.Store;\n\nclass Report\n{\n    public static bool a() => true < 1;\n\n    public static bool b() => Store.count() < 1;\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nuse Lib\\Store;\n\nclass Report\n{\n    public static function a(): bool { return true < 1; }\n\n    public static function b(): bool { return Store::count() < 1; }\n}\n";

    assert_eq!(
        worded(("src/Demo/Report.php", php), &[store]),
        [
            "9:47 redundant-comparison Redundant `<` comparison: left-hand side is never less than right-hand side. | Left operand is `true` | Right operand is `int(1)` | The `<` operator will always return `false` in this case. | Consider simplifying or removing this comparison as it always evaluates to `false`.",
            "11:47 possibly-false-operand Left operand in `<` comparison might be `false` (type `false|int`). | This might be `false` | If this operand is `false` at runtime, PHP's specific comparison rules for `false` with `<` will apply. | Ensure this operand is non-false or that comparison with `false` is intended and handled safely.",
        ]
    );
    assert_eq!(
        worded(("src/Demo/Report.sharp", sharp), &[store]),
        [
            "7:31 invalid-operand `<` orders numbers, strings, and classes and enums that declare `operator <=>`, and `bool` is none of them. | This is `bool`. | This is `int`. | A `bool` and a collection have no order, and an enum's cases have one only where it declares `operator <=>`. | Order a number or a string taken from the value instead.",
            "9:31 invalid-operand `<` orders numbers, strings, and classes and enums that declare `operator <=>`, and `bool` is none of them. | This is `bool|int`. | This is `int`. | A `bool` and a collection have no order, and an enum's cases have one only where it declares `operator <=>`. | Order a number or a string taken from the value instead.",
        ]
    );
}

/// An enum case has no order, so `<` and `<=>` on two cases are refused. PHP orders two cases as always `false`.
#[test]
fn ordering_an_enum_case_is_refused() {
    let sharp = "namespace Demo;\n\nimport Lib.Status;\n\nclass Report\n{\n    public static bool a() => Status.Active < Status.Closed;\n\n    public static int b(Status left, Status right) => left <=> right;\n}\n";
    let status = ("src/Lib/Status.php", STATUS);

    assert_eq!(
        worded(("src/Demo/Report.sharp", sharp), &[status]),
        [
            "7:31 invalid-operand `<` orders numbers, strings, and classes and enums that declare `operator <=>`, and `Status` is none of them. | This is `Status`. | This is `Status`. | A `bool` and a collection have no order, and an enum's cases have one only where it declares `operator <=>`. | Declare `public static int operator <=>(Status a, Status b)` in `Status`: an enum orders its cases once it declares `operator <=>`.",
            "9:55 invalid-operand `<=>` orders numbers, strings, and classes and enums that declare `operator <=>`, and `Status` is none of them. | This is `Status`. | This is `Status`. | A `bool` and a collection have no order, and an enum's cases have one only where it declares `operator <=>`. | Declare `public static int operator <=>(Status a, Status b)` in `Status`: an enum orders its cases once it declares `operator <=>`.",
        ]
    );
}

/// A `List` has no order, so an ordering of two lists is refused. PHP orders two arrays by its own rules.
#[test]
fn ordering_a_collection_is_refused() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public static bool a(List<int> lines, List<int> other) => lines < other;\n}\n";

    assert_eq!(
        worded(("src/Demo/Report.sharp", sharp), &[]),
        [
            "5:63 invalid-operand `<` orders numbers, strings, and classes and enums that declare `operator <=>`, and `List<int>` is none of them. | This is `List<int>`. | This is `List<int>`. | A `bool` and a collection have no order, and an enum's cases have one only where it declares `operator <=>`. | Order a number or a string taken from the value instead.",
        ]
    );
}

/// An `Any` or `Any?` ordered against a number keeps its own report, as it must be checked with `is` first. Against a
/// `bool` the ordering is refused, as no check makes a `bool` ordered. PHP keeps its report on `mixed`.
#[test]
fn ordering_an_any_keeps_its_report_unless_the_other_side_has_no_order() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public static bool a(Any value) => value < 1;\n\n    public static bool b(Any? value) => value <= 1;\n\n    public static bool c(Any value) => value < true;\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nclass Report\n{\n    public static function a(mixed $value): bool { return $value < 1; }\n\n    public static function b(mixed $value): bool { return $value <= 1; }\n}\n";
    let mixed = |at: &str, op: &str| {
        format!(
            "{at} mixed-operand Left operand in `{op}` comparison has `mixed` type. | This has type `mixed` | The result of comparing `mixed` types with `{op}` is unpredictable and can hide bugs. | Ensure this operand has a known, comparable type before using this comparison operator."
        )
    };

    assert_eq!(worded(("src/Demo/Report.php", php), &[]), [mixed("7:59", "<"), mixed("9:59", "<=")]);
    assert_eq!(
        refusals(("src/Demo/Report.sharp", sharp), &[]),
        [
            "5:40 mixed-operand Left operand of `<` is `Any`, which has no order. | Check the value with `is` or `match` first, as in `if (value is int n)`, and compare `n`.",
            "7:41 mixed-operand Left operand of `<=` is `Any?`, which has no order. | Check the value with `is` or `match` first, as in `if (value is int n)`, and compare `n`.",
            "9:40 invalid-operand `<` orders numbers, strings, and classes and enums that declare `operator <=>`, and `bool` is none of them. | Order a number or a string taken from the value instead.",
        ]
    );

    let fixed = "namespace Demo;\n\nclass Report\n{\n    public static bool a(Any value)\n    {\n        if (value is int n) {\n            return n < 1;\n        }\n        return false;\n    }\n}\n";
    assert_eq!(issues(("src/Demo/Report.sharp", fixed), &[]), Vec::<String>::new());
}

/// Numbers, strings and instances of a class that declares `operator <=>` keep their order.
#[test]
fn numbers_strings_and_a_class_declaring_operator_spaceship_still_order() {
    let sharp = "namespace App;\n\npublic class Ranking\n{\n    public bool a() => 1 < 2;\n\n    public bool b() => \"a\" < \"b\";\n\n    public bool c() => 1.5 <= 2;\n\n    public bool d(Money low, Money high) => low < high;\n\n    public int e(Money low, Money high) => low <=> high;\n}\n";

    assert_eq!(errors(("src/App/Ranking.sharp", sharp), &[MONEY_OPERATORS]), Vec::<String>::new());
}

/// `sortedBy` orders by the key its function returns, as `<=>` orders, so a key that holds a `bool`, an enum case, a
/// collection or an instance of a class that declares no `operator <=>` is refused, as `<=>` refuses it.
#[test]
fn sorted_by_a_key_with_no_order_is_refused() {
    let sharp = "namespace Demo;\n\nimport Lib.Status;\n\nclass Report\n{\n    public List<Status> a(List<Status> statuses) => statuses.sortedBy(s => s);\n\n    public List<bool> b(List<bool> flags) => flags.sortedBy(f => f);\n\n    public List<Row> c(List<Row> rows) => rows.sortedBy(r => r.tags);\n\n    public List<Cart> d(List<Cart> orders) => orders.sortedBy(o => o);\n}\n";
    let row = "<?php\n\nnamespace Demo;\n\nfinal class Row\n{\n    /** @var list<string> */\n    public array $tags = [];\n}\n";
    let others = [("src/Lib/Status.php", STATUS), ("src/Demo/Cart.php", CART), ("src/Demo/Row.php", row)];

    assert_eq!(
        worded(("src/Demo/Report.sharp", sharp), &others),
        [
            "7:71 invalid-argument `sortedBy` orders numbers, strings, and classes and enums that declare `operator <=>`, and `Status` is none of them. | This returns `Status`. | A `bool` and a collection have no order, and an enum's cases have one only where it declares `operator <=>`. | Declare `public static int operator <=>(Status a, Status b)` in `Status`: an enum orders its cases once it declares `operator <=>`.",
            "9:61 invalid-argument `sortedBy` orders numbers, strings, and classes and enums that declare `operator <=>`, and `bool` is none of them. | This returns `bool`. | A `bool` and a collection have no order, and an enum's cases have one only where it declares `operator <=>`. | Order a number or a string taken from the value instead.",
            "11:57 invalid-argument `sortedBy` orders numbers, strings, and classes and enums that declare `operator <=>`, and `List<string>` is none of them. | This returns `List<string>`. | A `bool` and a collection have no order, and an enum's cases have one only where it declares `operator <=>`. | Order a number or a string taken from the value instead.",
            "13:63 invalid-argument `sortedBy` orders numbers, strings, and classes and enums that declare `operator <=>`, and `Cart` is none of them. | This returns `Cart`. | A class instance has an order only where its class declares `operator <=>`. | Order a number or a string taken from the value instead.",
        ]
    );
}

/// A `Map` and a `Set` order their values by `sortedBy` as a `List` does, and so does a list a chain of calls gives, so
/// each refuses a key with no order.
#[test]
fn sorted_by_on_a_map_a_set_and_a_chain_refuses_a_key_with_no_order() {
    let sharp = "namespace Demo;\n\nimport Lib.Status;\n\nclass Report\n{\n    public List<Status> a(Map<string, Status> owners) => owners.sortedBy(s => s);\n\n    public List<Status> b(Set<Status> statuses) => statuses.sortedBy(s => s);\n\n    public List<Status> c(List<Status> statuses) => statuses.filter(s => s != Status.Closed).sortedBy(s => s);\n}\n";
    let refused = "invalid-argument `sortedBy` orders numbers, strings, and classes and enums that declare `operator <=>`, and `Status` is none of them. | This returns `Status`. | A `bool` and a collection have no order, and an enum's cases have one only where it declares `operator <=>`. | Declare `public static int operator <=>(Status a, Status b)` in `Status`: an enum orders its cases once it declares `operator <=>`.";

    assert_eq!(
        worded(("src/Demo/Report.sharp", sharp), &[("src/Lib/Status.php", STATUS)]),
        [format!("7:74 {refused}"), format!("9:70 {refused}"), format!("11:103 {refused}")]
    );
}

/// A loop body is analyzed more than once, and a `sortedBy` in it is refused once.
#[test]
fn sorted_by_in_a_loop_is_refused_once() {
    let sharp = "namespace Demo;\n\nimport Lib.Status;\n\nclass Report\n{\n    public int a(List<Status> statuses)\n    {\n        let total = 0;\n        while (total < 3) {\n            total += statuses.sortedBy(s => s).count();\n        }\n        return total;\n    }\n}\n";

    assert_eq!(issues(("src/Demo/Report.sharp", sharp), &[("src/Lib/Status.php", STATUS)]), ["11:40 invalid-argument"]);
}

/// `sortedBy` by a number, a string or an instance of a class that declares `operator <=>` still orders, and so does a
/// key of each that may be `null`, as a `null` key sorts first.
#[test]
fn sorted_by_a_number_a_string_or_a_class_declaring_operator_spaceship_still_orders() {
    let sharp = "namespace App;\n\npublic class Ranking\n{\n    public List<int> a(List<int> numbers) => numbers.sortedBy(n => -n);\n\n    public List<float> b(List<float> ratios) => ratios.sortedBy(r => r);\n\n    public List<string> c(List<string> names) => names.sortedBy(n => n);\n\n    public List<int?> d(List<int?> counts) => counts.sortedBy(c => c);\n\n    public List<Money> e(List<Money> prices) => prices.sortedBy(p => p);\n\n    public List<string?> f(List<string?> names) => names.sortedBy(n => n);\n\n    public List<Money?> g(List<Money?> prices) => prices.sortedBy(p => p);\n}\n";

    assert_eq!(errors(("src/App/Ranking.sharp", sharp), &[MONEY_OPERATORS]), Vec::<String>::new());
}

/// A key that may be one of two types that never match has no order, so `sortedBy` refuses it as `<` refuses two such
/// values, a `null` key aside.
#[test]
fn sorted_by_a_key_of_two_types_that_never_match_is_refused_as_less_than_refuses_it() {
    let row = "<?php\n\nnamespace Demo;\n\nfinal class Row\n{\n    public int|string $code = 0;\n\n    public int|string|null $label = null;\n}\n";
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public List<Row> a(List<Row> rows) => rows.sortedBy(r => r.code);\n\n    public List<Row> b(List<Row> rows) => rows.sortedBy(r => r.label);\n\n    public bool c(Row left, Row right) => left.code < right.code;\n}\n";
    let others = [("src/Demo/Row.php", row)];

    assert_eq!(
        worded(("src/Demo/Report.sharp", sharp), &others),
        [
            "5:57 invalid-argument `sortedBy` cannot compare two keys of `int|string`. | This returns `int|string`. | PHP# compares values strictly, so values of two different types never match. | Convert the key so every key has the same type.",
            "7:57 invalid-argument `sortedBy` cannot compare two keys of `int|string`. | This returns `(int|string)?`. | PHP# compares values strictly, so values of two different types never match. | Convert the key so every key has the same type.",
            "9:43 invalid-operand `<` cannot compare `int|string` with `int|string`. | This is `int|string`. | This is `int|string`. | PHP# compares values strictly, so values of two different types never match. | Convert one side so both sides have the same type.",
        ]
    );
}

/// `<` on two `Any` or two `Any?` values reports each side, as an `Any` must be checked with `is` first, so a `sortedBy`
/// key of `Any` or `Any?` gets the same report, a `null` key aside. Each names `Any` as PHP# writes it. A `.php` call of
/// the same method keeps PHP's report.
#[test]
fn sorted_by_an_any_key_reports_what_less_than_reports_on_two_any_values() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public bool a(Any left, Any right) => left < right;\n\n    public bool b(Any? left, Any? right) => left < right;\n\n    public List<Any> c(List<Any> values) => values.sortedBy(v => v);\n\n    public List<Any?> d(List<Any?> values) => values.sortedBy(v => v);\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nuse Sharp\\Internal\\ListMethods;\n\nfinal class Report\n{\n    public function a(mixed $left, mixed $right): bool\n    {\n        return $left < $right;\n    }\n\n    /**\n     * @param ListMethods<mixed> $values\n     *\n     * @return list<mixed>\n     */\n    public function c(ListMethods $values): array\n    {\n        return $values->sortedBy(fn (mixed $v): mixed => $v);\n    }\n}\n";
    let mixed = |at: &str, side: &str| {
        format!(
            "{at} mixed-operand {side} operand in `<` comparison has `mixed` type. | This has type `mixed` | The result of comparing `mixed` types with `<` is unpredictable and can hide bugs. | Ensure this operand has a known, comparable type before using this comparison operator."
        )
    };
    let any = |at: &str, subject: &str, any: &str| {
        format!(
            "{at} mixed-operand {subject} is `{any}`, which has no order. | An `Any` may hold any value, and PHP# orders only numbers, strings and classes that declare `operator <=>`. | Check the value with `is` or `match` first, as in `if (value is int n)`, and compare `n`."
        )
    };

    assert_eq!(worded(("src/Demo/Report.php", php), &[]), [mixed("11:16", "Left"), mixed("11:24", "Right")]);
    assert_eq!(
        worded(("src/Demo/Report.sharp", sharp), &[]),
        [
            any("5:43", "Left operand of `<`", "Any"),
            any("5:50", "Right operand of `<`", "Any"),
            any("7:45", "Left operand of `<`", "Any?"),
            any("7:52", "Right operand of `<`", "Any?"),
            any("9:61", "The `sortedBy` key", "Any"),
            any("11:63", "The `sortedBy` key", "Any"),
        ]
    );
}

/// Spec section 19: `==` and `!=` on a nullable type are lifted, so null equals only null, and an `Any?` compares by
/// value with a string or a number. None of them is an issue in PHP#, though PHP's loose `==` reports them.
#[test]
fn equality_of_a_nullable_value_is_lifted_with_no_issue() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public static bool equal(int? maybe, int total) => maybe == total;\n\n    public static bool known(int? maybe) => maybe != null;\n\n    public static bool missing(int? maybe) => null == maybe;\n\n    public static bool named(Any? value) => value == \"a\";\n\n    public static bool other(Any? value, int total) => value != total;\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nclass Report\n{\n    public static function equal(?int $maybe, int $total): bool { return $maybe == $total; }\n\n    public static function known(?int $maybe): bool { return $maybe != null; }\n\n    public static function missing(?int $maybe): bool { return null == $maybe; }\n\n    public static function named(mixed $value): bool { return $value == \"a\"; }\n\n    public static function other(mixed $value, int $total): bool { return $value != $total; }\n}\n";

    assert_eq!(
        issues(("src/Demo/Report.php", php), &[]),
        [
            "7:74 possibly-null-operand",
            "9:62 possibly-null-operand",
            "9:72 null-operand",
            "11:64 null-operand",
            "11:72 possibly-null-operand",
            "13:63 mixed-operand",
            "15:75 mixed-operand",
        ]
    );
    assert_eq!(issues(("src/Demo/Report.sharp", sharp), &[]), Vec::<String>::new());
}

/// A refused comparison in a condition is reported once: it narrows nothing, so the condition reports no impossible
/// or redundant test on top of it. PHP keeps the report its loose `==` narrowing gives.
#[test]
fn a_refused_comparison_in_a_condition_is_reported_once() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public static int a(string text, int total)\n    {\n        if (text == total || total > 2) {\n            return 1;\n        }\n        return 0;\n    }\n\n    public static int b(string text, int total)\n    {\n        if (text != total) {\n            return 1;\n        }\n        return 0;\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nclass Report\n{\n    public static function a(string $text, int $total): int\n    {\n        if ($text == $total || $total > 2) {\n            return 1;\n        }\n        return 0;\n    }\n\n    public static function b(string $text, int $total): int\n    {\n        if ($text != $total) {\n            return 1;\n        }\n        return 0;\n    }\n}\n";

    assert_eq!(issues(("src/Demo/Report.php", php), &[]), ["9:13 impossible-type-comparison"]);
    assert_eq!(issues(("src/Demo/Report.sharp", sharp), &[]), ["7:13 invalid-operand", "15:13 invalid-operand"]);
}

/// Spec section 19: `==` and `!=` run as `===` and `!==`, so they narrow as `===` and `!==` do. After `value == "a"` the
/// value is that string, and a `string?` that is not `""` may still be null. PHP narrows its loose `==`, under which
/// `null == ""` holds.
#[test]
fn equality_narrows_as_identity() {
    let sharp = "namespace Demo;\n\nclass Report\n{\n    public static string a(Any? value)\n    {\n        if (value == \"a\") {\n            return value;\n        }\n        return \"\";\n    }\n\n    public static int b(Any? value)\n    {\n        if (value != 1) {\n            return 0;\n        }\n        return value;\n    }\n\n    public static string c(string? text)\n    {\n        if (text == \"\") {\n            return \"empty\";\n        }\n        return text ?? \"none\";\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nclass Report\n{\n    public static function a(mixed $value): string\n    {\n        if ($value == \"a\") {\n            return $value;\n        }\n        return \"\";\n    }\n\n    public static function b(mixed $value): int\n    {\n        if ($value != 1) {\n            return 0;\n        }\n        return $value;\n    }\n\n    public static function c(?string $text): string\n    {\n        if ($text == \"\") {\n            return \"empty\";\n        }\n        return $text ?? \"none\";\n    }\n}\n";

    assert_eq!(
        issues(("src/Demo/Report.php", php), &[]),
        [
            "9:13 mixed-operand",
            "10:20 mixed-return-statement",
            "17:13 mixed-operand",
            "20:16 mixed-return-statement",
            "25:13 possibly-null-operand",
            "28:16 redundant-null-coalesce",
        ]
    );
    assert_eq!(issues(("src/Demo/Report.sharp", sharp), &[]), Vec::<String>::new());
}

/// Spec section 14.4: a method that never returns null drops the `?` from its return type. A method a subclass may
/// override keeps it, because the override may return null.
#[test]
fn a_nullable_return_type_on_a_method_that_never_returns_null_is_an_error() {
    let sharp = "namespace Demo;\n\nclass Ledger\n{\n    private Customer customer;\n\n    public Ledger(Customer customer)\n    {\n        this.customer = customer;\n    }\n\n    public Customer? owner(bool known)\n    {\n        if (known) {\n            return this.cached();\n        }\n        return this.find(known);\n    }\n\n    private Customer? cached()\n    {\n        return this.customer;\n    }\n\n    private Customer? find(bool known)\n    {\n        if (known) {\n            return this.customer;\n        }\n        return null;\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nclass Ledger\n{\n    public function __construct(private Customer $customer)\n    {\n    }\n\n    public function owner(): ?Customer\n    {\n        return $this->cached();\n    }\n\n    private function cached(): ?Customer\n    {\n        return $this->customer;\n    }\n}\n";

    assert_eq!(
        errors(("src/Demo/Ledger.sharp", sharp), &[("src/Demo/Customer.sharp", CUSTOMER)]),
        ["20:13 overly-wide-return-type"]
    );
    assert_eq!(issues(("src/Demo/Ledger.php", php), &[("src/Demo/Customer.sharp", CUSTOMER)]), Vec::<String>::new());

    let help = analyze(
        &PLUGIN_REGISTRY,
        settings(),
        ("src/Demo/Ledger.sharp", sharp),
        &[("src/Demo/Customer.sharp", CUSTOMER)],
    )
    .into_iter()
    .find(|issue| issue.code.as_deref() == Some("overly-wide-return-type"))
    .and_then(|issue| issue.help);
    assert_eq!(help.as_deref(), Some("Remove `null` from the return type, giving `Customer`."));
}

/// A PHP# method is closed unless it is `virtual` or an `override`, spec section 22, so a public method drops a `?`
/// that it never returns, as a `final override` does. A `virtual` method and an open `override` keep it.
#[test]
fn a_closed_method_drops_a_nullable_return_type_and_an_open_one_keeps_it() {
    let sharp = "namespace Demo;\n\npublic class Source\n{\n    public Customer? owner(Customer customer)\n    {\n        return customer;\n    }\n\n    public Customer? first(Customer customer) => customer;\n\n    public virtual Customer? fallback(Customer customer)\n    {\n        return customer;\n    }\n}\n\npublic class Archive : Source\n{\n    public override Customer? fallback(Customer customer)\n    {\n        return customer;\n    }\n}\n\npublic class Vault : Archive\n{\n    public final override Customer? fallback(Customer customer)\n    {\n        return customer;\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nclass Source\n{\n    final public function owner(Customer $customer): ?Customer\n    {\n        return $customer;\n    }\n\n    final public function first(Customer $customer): ?Customer\n    {\n        return $customer;\n    }\n\n    public function fallback(Customer $customer): ?Customer\n    {\n        return $customer;\n    }\n}\n\nclass Archive extends Source\n{\n    #[\\Override]\n    public function fallback(Customer $customer): ?Customer\n    {\n        return $customer;\n    }\n}\n\nclass Vault extends Archive\n{\n    #[\\Override]\n    final public function fallback(Customer $customer): ?Customer\n    {\n        return $customer;\n    }\n}\n";

    assert_eq!(
        errors(("src/Demo/Source.sharp", sharp), &[("src/Demo/Customer.sharp", CUSTOMER)]),
        ["5:12 overly-wide-return-type", "10:12 overly-wide-return-type", "28:27 overly-wide-return-type"]
    );
    assert_eq!(issues(("src/Demo/Source.php", php), &[("src/Demo/Customer.sharp", CUSTOMER)]), Vec::<String>::new());
}

#[test]
fn an_abstract_method_keeps_its_nullable_return_type() {
    let sharp = "namespace Demo;\n\nabstract class Source\n{\n    public abstract Customer? current();\n}\n";

    assert_eq!(
        errors(("src/Demo/Source.sharp", sharp), &[("src/Demo/Customer.sharp", CUSTOMER)]),
        Vec::<String>::new()
    );
}

/// Spec section 14.4: a nullable parameter that the method rejects on every path drops its `?`, and the caller checks.
/// A promoted one keeps it, since it also declares the property's type.
#[test]
fn a_nullable_parameter_the_method_rejects_on_every_path_is_an_error() {
    let sharp = "namespace Demo;\n\nimport RuntimeException;\n\nclass Billing\n{\n    public void notify(Customer? customer)\n    {\n        Customer c = customer ?? throw new RuntimeException(\"none\");\n    }\n\n    public string remind(Customer? customer)\n    {\n        if (customer === null) {\n            throw new RuntimeException(\"none\");\n        }\n        return customer.name;\n    }\n\n    public int discount(Plan? plan)\n    {\n        return plan?.price ?? 0;\n    }\n\n    public void log(Customer? customer, bool loud)\n    {\n        if (loud) {\n            Customer c = customer ?? throw new RuntimeException(\"none\");\n        }\n    }\n\n    public string greet(Customer? customer)\n    {\n        const name = customer?.name;\n        Customer c = customer ?? throw new RuntimeException(\"none\");\n        return c.name;\n    }\n\n    public Customer verify(Customer? customer) => customer ?? throw new RuntimeException(\"none\");\n\n    public Billing(public Customer? owner)\n    {\n        if (owner === null) {\n            throw new RuntimeException(\"none\");\n        }\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nuse RuntimeException;\n\nclass Billing\n{\n    public function notify(?Customer $customer): void\n    {\n        $c = $customer ?? throw new RuntimeException(\"none\");\n    }\n}\n";

    assert_eq!(
        errors(("src/Demo/Billing.sharp", sharp), &[("src/Demo/Customer.sharp", CUSTOMER)]),
        ["7:24 rejected-nullable-parameter", "12:26 rejected-nullable-parameter", "39:28 rejected-nullable-parameter"]
    );
    assert!(
        !codes(&issues(("src/Demo/Billing.php", php), &[("src/Demo/Customer.sharp", CUSTOMER)]))
            .contains(&"rejected-nullable-parameter")
    );

    let help = analyze(
        &PLUGIN_REGISTRY,
        settings(),
        ("src/Demo/Billing.sharp", sharp),
        &[("src/Demo/Customer.sharp", CUSTOMER)],
    )
    .into_iter()
    .find(|issue| issue.code.as_deref() == Some("rejected-nullable-parameter"))
    .and_then(|issue| issue.help);
    assert_eq!(help.as_deref(), Some("Declare `customer` as `Customer`, and check for null where the value enters."));
}

/// Each hook event, with the spans of the call's class, method, arguments and whole call.
type StaticCallEvents = Vec<(&'static str, [Span; 4])>;

/// Records every static call its hooks see.
#[derive(Clone, Default)]
struct StaticCallRecorder(Arc<Mutex<StaticCallEvents>>);

impl Provider for StaticCallRecorder {
    fn meta() -> &'static ProviderMeta {
        static META: ProviderMeta = ProviderMeta::new("test::static-call", "static call", "Records static calls.");

        &META
    }
}

impl StaticCallRecorder {
    fn record(&self, event: &'static str, call: &StaticCall<'_, '_>) {
        let spans = [call.class.span(), call.method.span(), call.argument_list.span(), call.span];
        self.0.lock().unwrap().push((event, spans));
    }

    /// The recorded calls, each span read back from `code`.
    fn seen(&self, code: &str) -> Vec<String> {
        let text = |span: Span| &code[span.start.offset as usize..span.end.offset as usize];

        self.0.lock().unwrap().iter().map(|(event, spans)| format!("{event} {}", spans.map(text).join(" "))).collect()
    }
}

impl StaticMethodCallHook for StaticCallRecorder {
    fn before_static_method_call(
        &self,
        call: &StaticCall<'_, '_>,
        _context: &mut HookContext<'_, '_>,
    ) -> HookResult<ExpressionHookResult> {
        self.record("before", call);

        Ok(ExpressionHookResult::Continue)
    }

    fn after_static_method_call(
        &self,
        call: &StaticCall<'_, '_>,
        _context: &mut HookContext<'_, '_>,
    ) -> HookResult<()> {
        self.record("after", call);

        Ok(())
    }
}

/// Records each method call an expression hook sees, as static or instance by the binding of its object.
#[derive(Clone, Default)]
struct CallKindRecorder(Arc<Mutex<Vec<String>>>);

impl Provider for CallKindRecorder {
    fn meta() -> &'static ProviderMeta {
        static META: ProviderMeta = ProviderMeta::new("test::call-kind", "call kind", "Records method call kinds.");

        &META
    }
}

impl ExpressionHook for CallKindRecorder {
    fn before_expression(
        &self,
        expression: &Expression<'_>,
        context: &mut HookContext<'_, '_>,
    ) -> HookResult<ExpressionHookResult> {
        if let Expression::Call(Call::Method(call)) = expression
            && let ClassLikeMemberSelector::Identifier(method) = &call.method
        {
            let is_static = StaticCall::from_method_call(call, context.resolved_names()).is_some();
            let kind = if is_static { "static" } else { "instance" };
            self.record(format!("{} {kind}", String::from_utf8_lossy(method.value)));
        }

        Ok(ExpressionHookResult::Continue)
    }
}

impl CallKindRecorder {
    fn record(&self, call: String) {
        self.0.lock().unwrap().push(call);
    }
}

#[test]
fn an_expression_hook_tells_a_sharp_static_call_by_the_binding_of_its_object() {
    let sharp = "namespace Demo;\n\nimport Lib.Calc;\n\nclass Report\n{\n    public static int total()\n    {\n        return Calc.make().add(1, 2);\n    }\n}\n";
    let recorder = CallKindRecorder::default();
    let mut registry = PluginRegistry::default();
    registry.register_expression_hook(recorder.clone());

    let issues = issues_in(&registry, settings(), ("src/Demo/Report.sharp", sharp), &[("src/Lib/Calc.php", CALC)]);

    assert_eq!(issues, Vec::<String>::new());
    assert_eq!(*recorder.0.lock().unwrap(), ["add instance", "make static"]);
}

#[test]
fn static_call_hooks_see_a_sharp_static_call_as_its_parts_as_in_php() {
    let sharp = "namespace Demo;\n\nimport Lib.Calc;\n\nclass Report\n{\n    public static Calc total()\n    {\n        return Calc.make();\n    }\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nuse Lib\\Calc;\n\nclass Report\n{\n    public static function total(): Calc\n    {\n        return Calc::make();\n    }\n}\n";

    let seen = |analyzed: (&'static str, &'static str)| {
        let recorder = StaticCallRecorder::default();
        let mut registry = PluginRegistry::default();
        registry.register_static_method_call_hook(recorder.clone());

        let issues = issues_in(&registry, settings(), analyzed, &[("src/Lib/Calc.php", CALC)]);
        assert_eq!(issues, Vec::<String>::new());

        recorder.seen(analyzed.1)
    };

    assert_eq!(
        seen(("src/Demo/Report.sharp", sharp)),
        ["before Calc make () Calc.make()", "after Calc make () Calc.make()"]
    );
    assert_eq!(
        seen(("src/Demo/Report.php", php)),
        ["before Calc make () Calc::make()", "after Calc make () Calc::make()"]
    );
}

/// Reports each call by name it sees, skips the analysis of `strtolower`, and gives `strtoupper` the type `int`.
#[derive(Clone, Default)]
struct FunctionCallSkipper;

impl Provider for FunctionCallSkipper {
    fn meta() -> &'static ProviderMeta {
        static META: ProviderMeta =
            ProviderMeta::new("test::function-call", "function call", "Skips calls of two functions.");

        &META
    }
}

impl FunctionCallHook for FunctionCallSkipper {
    fn before_function_call(
        &self,
        call: &NamedCall<'_, '_>,
        context: &mut HookContext<'_, '_>,
    ) -> HookResult<ExpressionHookResult> {
        context.report(
            IssueCode::InvalidArgument,
            Issue::error(format!("Saw `{}`.", call.name)).with_annotation(Annotation::primary(call.span)),
        );

        Ok(if call.calls(&[b"strtoupper"]) {
            ExpressionHookResult::SkipWithType(get_int())
        } else if call.calls(&[b"strtolower"]) {
            ExpressionHookResult::Skip
        } else {
            ExpressionHookResult::Continue
        })
    }
}

/// A function call hook sees the standard library's `global.strtoupper("a")` as PHP's `\strtoupper('a')`: what it
/// reports, the analysis it skips, and the type it gives the call. A call it does not skip, `strrev`, reaches the hooks
/// after the analysis too. With no function call hook the call is analyzed as usual.
#[test]
fn function_call_hooks_see_a_global_call_as_php_call() {
    let library = "vendor/heyjordanparker/php-sharp-composer/library/Sharp/Probe.sharp";
    let sharp = "namespace Sharp;\n\nclass Probe\n{\n    public Any? up() => global.strtoupper(\"a\");\n\n    public Any? down() => global.strtolower(\"a\");\n\n    public Any? same() => global.strrev(\"a\");\n}\n";
    let php = "<?php\n\nnamespace Demo;\n\nclass Probe\n{\n    public function up(): mixed\n    {\n        return \\strtoupper('a');\n    }\n\n    public function down(): mixed\n    {\n        return \\strtolower('a');\n    }\n\n    public function same(): mixed\n    {\n        return \\strrev('a');\n    }\n}\n";
    let mut registry = PluginRegistry::default();
    registry.register_function_call_hook(FunctionCallSkipper);
    let seen = |registry: &PluginRegistry, analyzed: (&'static str, &'static str), up: &str, down: &str| {
        let (issues, artifacts) = analyze_with_artifacts(registry, settings(), analyzed, &[]);
        let type_at = |text: &str| {
            let start = analyzed.1.find(text).unwrap() as u32;
            artifacts
                .expression_types
                .get(&(start, start + text.len() as u32))
                .map(|r#type| r#type.get_id().to_string())
        };
        let messages: Vec<String> =
            issues.iter().map(|issue| format!("{} {}", located(analyzed.1, issue), issue.message)).collect();

        (messages, type_at(up), type_at(down))
    };

    assert_eq!(
        seen(&registry, (library, sharp), "global.strtoupper(\"a\")", "global.strtolower(\"a\")"),
        (
            vec![
                "5:25 invalid-argument Saw `strtoupper`.".to_string(),
                "7:27 invalid-argument Saw `strtolower`.".to_string(),
                "9:27 invalid-argument Saw `strrev`.".to_string()
            ],
            Some("int".to_string()),
            None
        )
    );
    assert_eq!(
        seen(&registry, ("src/Demo/Probe.php", php), "\\strtoupper('a')", "\\strtolower('a')"),
        (
            vec![
                "9:16 invalid-argument Saw `strtoupper`.".to_string(),
                "14:16 invalid-argument Saw `strtolower`.".to_string(),
                "19:16 invalid-argument Saw `strrev`.".to_string()
            ],
            Some("int".to_string()),
            None
        )
    );
    assert_eq!(
        seen(&PluginRegistry::default(), (library, sharp), "global.strtoupper(\"a\")", "global.strtolower(\"a\")"),
        (vec![], Some("uppercase-non-empty-string".to_string()), Some("lowercase-non-empty-string".to_string()))
    );
}

