/// `App\Shop\Cart` and `App\Shop\Charge`, the parameter and return types of the function types below.
const SHOP: (&str, &str) =
    ("src/App/Shop/Shop.php", "<?php\n\nnamespace App\\Shop;\n\nfinal class Cart\n{\n}\n\nfinal class Charge\n{\n}\n");

/// Spec section 29: a function type lists its effects with `uses` inside its brackets, and the PHP twin writes the
/// closure type it runs as.
#[test]
fn a_field_of_a_function_type_with_an_effect_is_checked_as_its_php_twin() {
    let sharp = "namespace App.Shop;\n\npublic class Checkout\n{\n    Function<Charge(Cart) uses Http> charge;\n\n    public Checkout(Function<Charge(Cart) uses Http> charge)\n    {\n        this.charge = charge;\n    }\n\n    public Charge pay(Cart cart) => this.charge(cart);\n}\n";
    let php = "<?php\n\nnamespace App\\Shop;\n\nclass Checkout\n{\n    /** @var \\Closure(Cart): Charge */\n    private \\Closure $charge;\n\n    /** @param \\Closure(Cart): Charge $charge */\n    public function __construct(\\Closure $charge)\n    {\n        $this->charge = $charge;\n    }\n\n    public function pay(Cart $cart): Charge { return ($this->charge)($cart); }\n}\n";

    assert_eq!(issues(("src/App/Shop/Checkout.php", php), &[SHOP]), Vec::<String>::new());
    assert_eq!(issues(("src/App/Shop/Checkout.sharp", sharp), &[SHOP]), Vec::<String>::new());
}

#[test]
fn a_nullable_field_of_a_function_type_with_an_effect_is_accepted() {
    let sharp = "namespace App.Shop;\n\npublic class Checkout\n{\n    Function<Charge(Cart) uses Http>? fallback = null;\n\n    public Function<Charge(Cart) uses Http>? current() => this.fallback;\n\n    public void replace(Function<Charge(Cart) uses Http> next)\n    {\n        this.fallback = next;\n    }\n}\n";

    assert_eq!(issues(("src/App/Shop/Checkout.sharp", sharp), &[SHOP]), Vec::<String>::new());
}

/// `Http` and `Mail` are both effects of the map's value type, so the map takes two type arguments.
#[test]
fn a_map_of_function_types_with_two_effects_is_accepted() {
    let sharp = "namespace App.Shop;\n\npublic class Checkout\n{\n    Map<string, Function<Charge(Cart) uses Http, Mail>> handlers;\n\n    public Checkout(Map<string, Function<Charge(Cart) uses Http, Mail>> handlers)\n    {\n        this.handlers = handlers;\n    }\n\n    public int size() => this.handlers.count();\n}\n";

    assert_eq!(issues(("src/App/Shop/Checkout.sharp", sharp), &[SHOP]), Vec::<String>::new());
}

#[test]
fn a_function_type_taking_a_function_type_with_an_effect_is_accepted() {
    let sharp = "namespace App.Shop;\n\npublic class Checkout\n{\n    public Checkout(private Function<int(Function<int(int) uses Http>)> apply) { }\n\n    public int run(Function<int(int) uses Http> step) => this.apply(step);\n}\n";

    assert_eq!(issues(("src/App/Shop/Checkout.sharp", sharp), &[SHOP]), Vec::<String>::new());
}

/// Spec section 5: a method with no access modifier is `private`, as section 12's `void reserve(string sku, int count)`
/// is. Another class calling one is refused, and a static one too, as their PHP twins' `private` methods are, while an
/// interface method stays public.
#[test]
fn a_method_without_an_access_modifier_is_private_as_its_php_twin() {
    let sharp = "namespace App.Shop;\n\npublic class Stock\n{\n    int reserve(string sku) => 1;\n    static int make() => 2;\n\n    public int run() => this.reserve(\"a\") + Stock.make();\n}\n";
    let php = "<?php\n\nnamespace App\\Shop;\n\nclass Stock\n{\n    private function reserve(string $sku): int { return 1; }\n    private static function make(): int { return 2; }\n\n    public function run(): int { return $this->reserve(\"a\") + Stock::make(); }\n}\n";
    let sharp_reader = "namespace App.Shop;\n\npublic class Order\n{\n    public int held(Stock stock) => stock.reserve(\"a\") + Stock.make();\n}\n";
    let php_reader = "<?php\n\nnamespace App\\Shop;\n\nfinal class Order\n{\n    public function held(Stock $stock): int { return $stock->reserve(\"a\") + Stock::make(); }\n}\n";
    let named = "namespace App.Shop;\n\npublic interface Named\n{\n    string name();\n}\n";
    let named_user =
        "namespace App.Shop;\n\npublic class Label\n{\n    public string of(Named named) => named.name();\n}\n";

    assert_eq!(issues(("src/App/Shop/Stock.sharp", sharp), &[]), Vec::<String>::new());

    let sharp_issues = issues(("src/App/Shop/Order.sharp", sharp_reader), &[("src/App/Shop/Stock.sharp", sharp)]);
    let php_issues = issues(("src/App/Shop/Order.php", php_reader), &[("src/App/Shop/Stock.php", php)]);
    assert_eq!(
        sharp_issues,
        [
            "5:43 invalid-method-access",
            "5:64 invalid-method-access",
            "5:37 mixed-operand",
            "5:58 mixed-operand",
            "5:37 mixed-return-statement",
        ]
    );
    assert_eq!(codes(&sharp_issues), codes(&php_issues), "{php_issues:?}");

    assert_eq!(
        issues(("src/App/Shop/Label.sharp", named_user), &[("src/App/Shop/Named.sharp", named)]),
        Vec::<String>::new()
    );
}

/// Spec sections 6 and 29 write these fields with no access modifier. A field with no modifier is `private`, so an
/// unused one is reported, and another class reading one is refused, as for the PHP twin's `private` properties.
#[test]
fn a_field_without_an_access_modifier_is_private_as_its_php_twin() {
    let offers = (
        "src/App/Shop/Offers.php",
        "<?php\n\nnamespace App\\Shop;\n\nfinal class Plan\n{\n}\n\nfinal class Money\n{\n}\n\nfinal class Offer\n{\n}\n",
    );
    let sharp = "namespace App.Shop;\n\npublic class Checkout\n{\n    Map<string, Plan> cache = [:];\n    Function<Money(Offer) uses Http> priceOf;\n    Function<Charge(Cart) uses Http> charge;\n    Function<Charge(Cart) uses Http>? fallback = null;\n    Map<string, Function<Charge(Cart) uses Http, Mail>> handlers = [:];\n    Function<int(Function<int(int) uses Http>) uses Http> apply;\n\n    public Checkout(Function<Money(Offer) uses Http> priceOf, Function<Charge(Cart) uses Http> charge, Function<int(Function<int(int) uses Http>) uses Http> apply)\n    {\n        this.priceOf = priceOf;\n        this.charge = charge;\n        this.apply = apply;\n    }\n}\n";
    let php = "<?php\n\nnamespace App\\Shop;\n\nclass Checkout\n{\n    /** @var array<string, Plan> */\n    private array $cache = [];\n    /** @var \\Closure(Offer): Money */\n    private \\Closure $priceOf;\n    /** @var \\Closure(Cart): Charge */\n    private \\Closure $charge;\n    /** @var null|\\Closure(Cart): Charge */\n    private ?\\Closure $fallback = null;\n    /** @var array<string, \\Closure(Cart): Charge> */\n    private array $handlers = [];\n    /** @var \\Closure(\\Closure(int): int): int */\n    private \\Closure $apply;\n\n    /**\n     * @param \\Closure(Offer): Money $priceOf\n     * @param \\Closure(Cart): Charge $charge\n     * @param \\Closure(\\Closure(int): int): int $apply\n     */\n    public function __construct(\\Closure $priceOf, \\Closure $charge, \\Closure $apply)\n    {\n        $this->priceOf = $priceOf;\n        $this->charge = $charge;\n        $this->apply = $apply;\n    }\n}\n";
    let sharp_reader = "namespace App.Shop;\n\nimport Vendor.Sums;\n\npublic class Receipt\n{\n    public static int size(Checkout checkout) => Sums.total(checkout.cache);\n}\n";
    let php_reader = "<?php\n\nnamespace App\\Shop;\n\nfinal class Receipt\n{\n    public static function size(Checkout $checkout): int { return \\Vendor\\Sums\\total($checkout->cache); }\n}\n";
    let sums = (
        "src/Vendor/Sums/functions.php",
        "<?php\n\nnamespace Vendor\\Sums;\n\nfunction total(array $values): int\n{\n    return count($values);\n}\n",
    );

    let sharp_issues = issues(("src/App/Shop/Checkout.sharp", sharp), &[SHOP, offers]);
    let php_issues = issues(("src/App/Shop/Checkout.php", php), &[SHOP, offers]);
    assert_eq!(
        sharp_issues,
        [
            "8:39 unused-property",
            "9:57 unused-property",
            "5:23 unused-property",
            "10:59 write-only-property",
            "6:38 write-only-property",
            "7:38 write-only-property",
        ]
    );
    assert_eq!(codes(&sharp_issues), codes(&php_issues));

    let sharp_issues = issues(
        ("src/App/Shop/Receipt.sharp", sharp_reader),
        &[("src/App/Shop/Checkout.sharp", sharp), SHOP, offers, sums],
    );
    let php_issues =
        issues(("src/App/Shop/Receipt.php", php_reader), &[("src/App/Shop/Checkout.php", php), SHOP, offers, sums]);
    assert_eq!(sharp_issues, ["7:70 invalid-property-read", "7:61 no-value"]);
    assert_eq!(codes(&sharp_issues), codes(&php_issues));
    let refused = refusals(
        ("src/App/Shop/Receipt.sharp", sharp_reader),
        &[("src/App/Shop/Checkout.sharp", sharp), SHOP, offers, sums],
    );
    assert!(refused[0].starts_with("7:70 invalid-property-read Cannot read private property `Checkout.cache`."));
    assert_eq!(
        messages(("src/App/Shop/Receipt.php", php_reader), &[("src/App/Shop/Checkout.php", php), SHOP, offers, sums])
            .into_iter()
            .filter(|message| message.starts_with("Cannot read private property"))
            .collect::<Vec<_>>(),
        ["Cannot read private property `$cache` from class `App\\Shop\\Checkout`."]
    );
}

/// A `.sharp` message writes a function type's effects inside its brackets, as the file writes them: a standard effect
/// by its short name or its import's name, and any other by the name the file gives its class.
#[test]
fn a_sharp_message_names_a_function_type_with_its_effects_inside_its_brackets() {
    let sharp = "namespace Demo;\n\nimport App.Effects.Payments as Billing;\nimport Sharp.Net.Mail as Post;\n\nclass Receipt\n{\n    public string step(Function<int(int) uses Http, Post, Billing> step) => `Step: ${step}`;\n}\n";
    let payments =
        ("src/App/Effects/Payments.sharp", "namespace App.Effects;\n\npublic foreign class Payments\n{\n}\n");

    assert_eq!(
        worded(("src/Demo/Receipt.sharp", sharp), &[payments]),
        [
            "8:84 invalid-operand A template shows `int`, `float`, `string`, `bool` or a type that declares `toString()`, and `Function<int(int) uses Http, Post, Billing>` is none of them. | This is `Function<int(int) uses Http, Post, Billing>`. | Show a value taken from it instead, such as a property or the result of a method.",
        ]
    );
}

/// Spec section 29: a function type without `uses` is pure in a field, a local or a return type, so it holds no
/// function value with an effect there, and a parameter whose function type uses `Mail` holds none that uses `Http`. A
/// parameter whose function type states no effects takes on those of the value each call passes, so `apply` takes it.
#[test]
fn a_function_type_refuses_a_function_value_with_an_effect_it_does_not_list() {
    let sharp = "namespace App.Shop;\n\npublic class Pricing\n{\n    private Function<int(int)> rate;\n\n    public Pricing(Function<int(int) uses Http> fetch)\n    {\n        this.rate = fetch;\n        Function<int(int)> local = fetch;\n        Pricing.apply(fetch);\n        Pricing.mail(fetch);\n    }\n\n    public static int apply(Function<int(int)> step) => step(1);\n\n    public static int mail(Function<int(int) uses Mail> step) => step(1);\n\n    public Function<int(int)> current(Function<int(int) uses Http> fetch) => fetch;\n\n    public int price() => this.rate(2);\n}\n";

    assert_eq!(
        analyze(&PLUGIN_REGISTRY, settings(), ("src/App/Shop/Pricing.sharp", sharp), &[])
            .iter()
            .map(|issue| format!("{} {}", located(sharp, issue), issue.message))
            .collect::<Vec<_>>(),
        [
            "9:21 invalid-property-assignment-value Invalid type for property `Pricing.rate`: expected `Function<int(int)>`, but got `Function<int(int) uses Http>`.",
            "10:36 invalid-local-assignment-value Invalid assignment to `local`: it is declared as `Function<int(int)>`.",
            "12:22 invalid-argument `fetch` has the effect `Http`, so a `Function<int(int) uses Mail>` cannot hold it.",
            "19:78 invalid-return-statement Invalid return type for method `Pricing.current`: expected `Function<int(int)>`, but found `Function<int(int) uses Http>`.",
        ]
    );
}

/// A nullable function type holds `null` and no function value with an effect it does not list, whether or not the
/// value may be `null`, and each is refused for the effect it has.
#[test]
fn a_nullable_function_type_refuses_a_function_value_with_an_effect_it_does_not_list() {
    let sharp = "namespace App.Shop;\n\npublic class Pricing\n{\n    public static int apply(Function<int(int) uses Mail>? step) => step == null ? 0 : step(1);\n\n    public int run(Function<int(int) uses Http> fetch, Function<int(int) uses Http>? maybe) => Pricing.apply(fetch) + Pricing.apply(maybe);\n}\n";

    assert_eq!(
        analyze(&PLUGIN_REGISTRY, settings(), ("src/App/Shop/Pricing.sharp", sharp), &[])
            .iter()
            .map(|issue| format!("{} {}", located(sharp, issue), issue.message))
            .collect::<Vec<_>>(),
        [
            "7:110 invalid-argument `fetch` has the effect `Http`, so a `Function<int(int) uses Mail>?` cannot hold it.",
            "7:133 invalid-argument `maybe` has the effect `Http`, so a `Function<int(int) uses Mail>?` cannot hold it.",
        ]
    );
}

/// A function type that lists more effects than a function value uses holds it, as a wider type holds a narrower value.
