/// Spec section 15: a trailing `on` clause makes a method listen to the events it lists. The method takes no parameter,
/// or one that every listed event is, and nothing else. The help names the most specific interface every listed event
/// is or implements, when every listed name is a type. A `private` listener counts as used, because the engine runs it. A
/// parameter without a type and a second method of one name report only their own errors.
#[test]
fn a_listener_takes_no_parameter_or_one_that_every_listed_event_is() {
    let notices = (
        "app/Shop/OrderNotices.sharp",
        "namespace App.Shop;\n\nimport Illuminate.Queue.Events.JobFailed;\n\npublic class OrderNotices\n{\n    public void send(OrderEvent e) on OrderPaid, OrderRefunded { }\n\n    public void refresh() on OrderPaid { }\n\n    public void audit(OrderEvent e) on OrderEvent { }\n\n    public void alert(JobFailed e) on JobFailed { }\n\n    private void deliver(OrderPaid e) on OrderPaid { }\n}\n",
    );
    let errors = (
        "app/Shop/Errors.sharp",
        "namespace App.Shop;\n\npublic class Errors\n{\n    public void send(OrderPaid e) on OrderPaid, OrderRefunded { }\n\n    public void ship(OrderPaid e) on OrderPaid, Shipped { }\n\n    public void log(OrderPaid e, Logger logger) on OrderPaid { }\n\n    public void settle(OrderPaid e) on OrderRefunded, OrderSettled { }\n\n    public void bill(Charge e) on Charge, Credit { }\n\n    public void watch(OrderPaid e) on OrderPaid, OrderEvent { }\n}\n",
    );
    let billed = ("app/Shop/Billed.sharp", "namespace App.Shop;\n\npublic interface Billed\n{\n}\n");
    let charged = ("app/Shop/Charged.sharp", "namespace App.Shop;\n\npublic interface Charged : Billed\n{\n}\n");
    let charge = ("app/Shop/Charge.sharp", "namespace App.Shop;\n\npublic event Charge(int id) : Billed, Charged;\n");
    let credit = ("app/Shop/Credit.sharp", "namespace App.Shop;\n\npublic event Credit(int id) : Billed, Charged;\n");
    let billing = (
        "app/Shop/Billing.sharp",
        "namespace App.Shop;\n\npublic class Billing\n{\n    public void bill(Charged e) on Charge, Credit { }\n\n    public void watch(OrderEvent e) on OrderPaid, OrderEvent { }\n}\n",
    );
    let untyped = (
        "app/Shop/Untyped.sharp",
        "namespace App.Shop;\n\npublic class Untyped\n{\n    public void send(e) on OrderPaid { }\n}\n",
    );
    let twice = (
        "app/Shop/Twice.sharp",
        "namespace App.Shop;\n\npublic class Twice\n{\n    public void send(OrderPaid e) on OrderPaid { }\n\n    public void send(OrderPaid e, Logger logger) on OrderPaid { }\n}\n",
    );
    let [order_event, order_paid, refunded, shipped, events, queue, logger] = listened();
    let others = [order_event, order_paid, refunded, shipped, events, queue, logger, billed, charged, charge, credit];

    assert_eq!(worded(notices, &listened()), Vec::<String>::new());
    assert_eq!(
        worded(errors, &others),
        [
            "5:49 invalid-event `send` takes an `OrderPaid`, and it listens to `OrderRefunded`, which is not one. | Listed here. | The event it takes. | Take a type every listed event implements, such as `OrderEvent`, or take no parameter.",
            "7:49 invalid-event `ship` takes an `OrderPaid`, and it listens to `Shipped`, which is not one. | Listed here. | The event it takes. | Take a type every listed event implements, or take no parameter.",
            "9:34 invalid-event A listener takes only its event, and `log` also takes `logger`. | Not the event. | A listener gets everything else through its class's constructor.",
            "11:55 non-existent-class-like Cannot find type `App.Shop.OrderSettled`. | No type of this name is declared. | Check the name's spelling, and import the type with `import` when another namespace declares it.",
            "11:40 invalid-event `settle` takes an `OrderPaid`, and it listens to `OrderRefunded`, which is not one. | Listed here. | The event it takes. | Take a type every listed event implements, or take no parameter.",
            "13:43 invalid-event `bill` takes a `Charge`, and it listens to `Credit`, which is not one. | Listed here. | The event it takes. | Take a type every listed event implements, such as `Charged`, or take no parameter.",
            "15:50 invalid-event `watch` takes an `OrderPaid`, and it listens to `OrderEvent`, which is not one. | Listed here. | The event it takes. | Take a type every listed event implements, such as `OrderEvent`, or take no parameter.",
        ]
    );
    assert_eq!(worded(billing, &others), Vec::<String>::new());
    assert_eq!(
        worded(untyped, &listened()),
        ["5:22 parse A PHP# parameter needs a type, as in `int extra`. | Written here."]
    );
    assert_eq!(worded(twice, &listened()), Vec::<String>::new());
}

/// Spec section 15: an `on` clause lists events, which `event` or `extern event` declares, or interfaces an event
/// implements, so every listener can run. A type that exists and is not an event, a class, an enum or a built-in type,
/// is refused as one. A name of no type is the error any unknown type is.
#[test]
fn an_on_clause_lists_events_or_interfaces_an_event_implements() {
    let watch = (
        "app/Shop/Watch.sharp",
        "namespace App.Shop;\n\npublic class Watch\n{\n    public void log(Logger logger) on Logger { }\n\n    public void track() on Tracked, OrderSettled { }\n\n    public void scalar() on int, string { }\n\n    public void any() on Any { }\n\n    public void level() on Level { }\n}\n",
    );
    let tracked = ("app/Shop/Tracked.sharp", "namespace App.Shop;\n\npublic interface Tracked\n{\n}\n");
    let level = ("app/Shop/Level.sharp", "namespace App.Shop;\n\npublic enum Level\n{\n    case Low;\n}\n");
    let [order_event, order_paid, refunded, shipped, events, queue, logger] = listened();
    let note =
        "An `on` clause lists events, which `event` or `extern event` declares, or interfaces an event implements.";

    assert_eq!(
        worded(watch, &[order_event, order_paid, refunded, shipped, events, queue, logger, tracked, level]),
        [
            format!("5:39 invalid-event `Logger` is not an event. | Listed here. | {note}"),
            format!("7:28 invalid-event No event implements `Tracked`, so `track` never runs. | Listed here. | {note}"),
            "7:37 non-existent-class-like Cannot find type `App.Shop.OrderSettled`. | No type of this name is declared. | Check the name's spelling, and import the type with `import` when another namespace declares it.".to_owned(),
            format!("9:29 invalid-event `int` is not an event. | Listed here. | {note}"),
            format!("9:34 invalid-event `string` is not an event. | Listed here. | {note}"),
            format!("11:26 invalid-event `Any` is not an event. | Listed here. | {note}"),
            format!("13:28 invalid-event `Level` is not an event. | Listed here. | {note}"),
        ]
    );
}

/// Spec section 15: an `on` clause names a generic event's type arguments, as every type does, spec section 11, so
/// `on Saved<Order>` hears only a `Saved<Order>`, as C# subscribes to an `EventHandler<OrderSaved>`. A bare `on Saved`
/// names none, and type arguments outside the bound or too many are refused as anywhere else. The parameter is a type
/// every listed event is, the interface the event implements among them.
#[test]
fn an_on_clause_names_the_type_arguments_of_a_generic_event() {
    let entity = ("app/Shop/Entity.sharp", "namespace App.Shop;\n\npublic class Entity\n{\n}\n");
    let order = ("app/Shop/Order.sharp", "namespace App.Shop;\n\npublic class Order : Entity\n{\n}\n");
    let invoice = ("app/Shop/Invoice.sharp", "namespace App.Shop;\n\npublic class Invoice : Entity\n{\n}\n");
    let entity_event = ("app/Shop/EntityEvent.sharp", "namespace App.Shop;\n\npublic interface EntityEvent\n{\n}\n");
    let saved =
        ("app/Shop/Saved.sharp", "namespace App.Shop;\n\npublic event Saved<T : Entity>(T entity) : EntityEvent;\n");
    let hears = (
        "app/Shop/Hears.sharp",
        "namespace App.Shop;\n\npublic class Hears\n{\n    public void orders(Saved<Order> e) on Saved<Order> { }\n\n    public void any(EntityEvent e) on Saved<Order>, Saved<Invoice> { }\n\n    public void bare(Saved<Order> e) on Saved { }\n\n    public void wrong(Saved<Invoice> e) on Saved<Order> { }\n\n    public void unbound() on Saved<string> { }\n\n    public void many() on Saved<Order, Invoice> { }\n}\n",
    );
    // A class's type parameter is no type argument a listener can know.
    let tracker = (
        "app/Shop/Tracker.sharp",
        "namespace App.Shop;\n\npublic class Tracker<T : Entity>\n{\n    public void heard(Saved<T> e) on Saved<T> { }\n}\n",
    );

    assert_eq!(
        worded(tracker, &[entity, order, entity_event, saved]),
        [
            "5:38 invalid-event `Saved<T>` names a type parameter, which no listener can know: name the type it hears, as in `Saved<Order>`, or listen on an interface the event implements. | Listed here. | An `on` clause lists events, which `event` or `extern event` declares, or interfaces an event implements."
        ]
    );
    assert_eq!(
        worded(hears, &[entity, order, invoice, entity_event, saved]),
        [
            "9:41 missing-template-parameter `Saved` needs its type argument. | `Saved` has type parameters | A type, `new` and a static member name the type arguments of a generic class. | Write a type for its type parameter: `Saved<T>`.",
            "11:44 invalid-event `wrong` takes a `Saved<Invoice>`, and it listens to `Saved<Order>`, which is not one. | Listed here. | The event it takes. | Take a type every listed event implements, such as `EntityEvent`, or take no parameter.",
            "13:30 template-constraint-violation Type argument `string` does not satisfy `Saved`'s `T`. | `string` is supplied for `T` here... | ...but `T` is bounded by `Entity`. | Supply a type contained by `Entity`.",
            "15:27 excess-template-parameter Too many type arguments for `Saved`: expected 1, but found 2. | `Saved` is applied here. | `Saved` declares 1 type parameter.",
        ]
    );
}

/// Spec section 15: a listener runs on an object PHP# creates, so it is not `static`, and its class-like is a class
/// that is not abstract and whose constructor is public. It returns nothing.
#[test]
fn a_listener_is_an_instance_method_returning_nothing_in_a_class_the_container_creates() {
    let fixed = (
        "app/Shop/Tick.sharp",
        "namespace App.Shop;\n\npublic class Tick\n{\n    public void tick() on OrderPaid { }\n}\n",
    );
    let r#static = (
        "app/Shop/Tick.sharp",
        "namespace App.Shop;\n\npublic class Tick\n{\n    public static void tick() on OrderPaid { }\n}\n",
    );
    let returning = (
        "app/Shop/Tick.sharp",
        "namespace App.Shop;\n\npublic class Tick\n{\n    public int tick() on OrderPaid\n    {\n        return 1;\n    }\n}\n",
    );
    let r#abstract = (
        "app/Shop/Tick.sharp",
        "namespace App.Shop;\n\npublic abstract class Tick\n{\n    public void tick() on OrderPaid { }\n}\n",
    );
    let r#enum = (
        "app/Shop/Tick.sharp",
        "namespace App.Shop;\n\npublic enum Tick\n{\n    case Open;\n\n    public void tick() on OrderPaid { }\n}\n",
    );
    let interface =
        ("app/Shop/Tick.sharp", "namespace App.Shop;\n\npublic interface Tick\n{\n    void tick() on OrderPaid;\n}\n");
    let opened = (
        "app/Shop/Tick.sharp",
        "namespace App.Shop;\n\npublic class Tick\n{\n    public Tick() { }\n\n    public void tick() on OrderPaid { }\n}\n",
    );
    let hidden = (
        "app/Shop/Tick.sharp",
        "namespace App.Shop;\n\npublic class Tick\n{\n    private Tick() { }\n\n    public void tick() on OrderPaid { }\n}\n",
    );
    let guarded = (
        "app/Shop/Tick.sharp",
        "namespace App.Shop;\n\npublic class Tick\n{\n    protected Tick() { }\n\n    public void tick() on OrderPaid { }\n}\n",
    );

    assert_eq!(worded(fixed, &listened()), Vec::<String>::new());
    assert_eq!(worded(opened, &listened()), Vec::<String>::new());
    assert_eq!(
        worded(hidden, &listened()),
        [
            "7:24 invalid-event `Tick`'s constructor is private, so PHP# can't create a `Tick` to run `tick`. | `tick` listens here."
        ]
    );
    assert_eq!(
        worded(guarded, &listened()),
        [
            "7:24 invalid-event `Tick`'s constructor is protected, so PHP# can't create a `Tick` to run `tick`. | `tick` listens here."
        ]
    );
    assert_eq!(
        worded(r#static, &listened()),
        ["5:12 invalid-event A listener runs on an object, so `tick` cannot be `static`. | Declared `static` here."]
    );
    assert_eq!(
        worded(returning, &listened()),
        ["5:12 invalid-event A listener returns nothing, and `tick` returns `int`. | Returned type. | Return `void`."]
    );
    assert_eq!(
        worded(r#abstract, &listened()),
        [
            "5:24 invalid-event `Tick` is abstract, so the container cannot create it to run `tick`. | `tick` listens here."
        ]
    );
    assert_eq!(
        worded(r#enum, &listened()),
        [
            "7:24 invalid-event `Tick` is an enum, so the container cannot create it to run `tick`. | `tick` listens here."
        ]
    );
    assert_eq!(
        worded(interface, &listened()),
        [
            "5:17 invalid-event `Tick` is an interface, so the container cannot create it to run `tick`. | `tick` listens here."
        ]
    );
}

/// Spec sections 15 and 32: PHP# creates a new object of a listener's class for every event, with no binding of the
/// class, and fills its constructor as it fills a bound class's: each parameter from a binding in the base module of
/// the class's namespace or of a namespace above it, of any lifetime. Each row is the modules of the project and the
/// refusals `Tick`, which takes a `Logger`, gets.
#[test]
fn a_listener_class_takes_services_its_namespace_modules_bind() {
    let tick = (
        "app/Shop/Tick.sharp",
        "namespace App.Shop;\n\npublic class Tick\n{\n    public Tick(private Logger logger) { }\n\n    public void tick() on OrderPaid { }\n}\n",
    );
    let module = |path: &'static str, namespace: &str, members: &str| {
        (path, leak(format!("namespace {namespace};\n\nimport App.Shop.Logger;\n\nmodule\n{{\n{members}\n}}\n")))
    };
    let missing = "5:17 missing-service `Tick` listens to `OrderPaid` and needs a `Logger`, and no module binds one: the container can't build `Tick`. | Bind `Logger` in a module of `Tick`'s namespace or one above it, as in `transient Logger = Logger;`.";

    for (modules, expected) in [
        (vec![], vec![missing]),
        (vec![module("app/Shop/Module.sharp", "App.Shop", "    transient Logger = Logger;")], vec![]),
        (vec![module("app/Shop/Module.sharp", "App.Shop", "    scoped Logger = Logger;")], vec![]),
        (vec![module("app/Module.sharp", "App", "    singleton Logger = Logger;")], vec![]),
        (vec![module("app/Mail/Module.sharp", "App.Mail", "    singleton Logger = Logger;")], vec![missing]),
    ] {
        let files: Vec<_> = listened().into_iter().chain(modules.iter().copied()).collect();
        let refused: Vec<_> =
            refusals(tick, &files).into_iter().filter(|refusal| refusal.contains(" missing-service ")).collect();
        assert_eq!(refused, expected, "{modules:?}");
    }

    let fixed = (
        "app/Shop/Tick.sharp",
        "namespace App.Shop;\n\npublic class Tick\n{\n    public void tick() on OrderPaid { }\n}\n",
    );
    assert_eq!(refusals(fixed, &listened()), Vec::<String>::new());
}

const LABEL: (&str, &str) = (
    "app/Shop/Label.sharp",
    "namespace App.Shop;\n\nimport Acme.Letters;\n\npublic class Label\n{\n    public Label(private string name) { }\n\n    public string text => Letters.whisper(this.name);\n\n    law named(Label label) => label.text != \"\";\n}\n",
);

#[test]
fn a_getter_calling_a_function_an_extern_declares_pure_passes() {
    let stub = ("app/Stubs/Letters.sharp", "namespace App.Stubs;\n\nimport Acme.Letters;\n\nextern Letters.whisper;\n");

    assert_eq!(effect_issues(&[LABEL, LETTERS, stub]), Vec::<String>::new());
}

/// A getter may call anything, spec section 6, and a read of it carries what it calls, so a law reading it is held to
/// the getter's call.
#[test]
fn a_law_reading_a_getter_that_calls_a_function_with_no_extern_is_refused_and_names_the_missing_declaration() {
    assert_eq!(
        effect_issues(&[LABEL, LETTERS]),
        [
            "app/Shop/Label.sharp:11:31 impure-law: Law `named` reaches `Label.text`, which calls `Letters.whisper` with no `extern` declaration. Laws hold only over pure code. Help: Declare it in a .sharp file: `extern Letters.whisper;` when it has no effect, or name its effects after `uses`."
        ]
    );
}

/// Spec sections 23 and 29: an `extern` names a plain PHP function a library declares in PHP's root namespace through
/// the namespace of the library's classes beside it, as `extern Foundation.now uses Clock;`, and the effects it lists
/// reach each call of `Foundation.now()`. A bare `extern now;` names no function, as a misspelled name does.
#[test]
fn an_extern_declares_a_library_s_root_function_through_its_library_s_namespace() {
    let helpers = ("vendor/laravel/Foundation/helpers.php", "<?php\n\nfunction now(): int\n{\n    return time();\n}\n");
    let application = (
        "vendor/laravel/Foundation/Application.php",
        "<?php\n\nnamespace Vendor\\Foundation;\n\nclass Application\n{\n}\n",
    );
    let page = (
        "app/Shop/Page.sharp",
        "namespace App.Shop;\n\nimport Vendor.Foundation;\n\npublic class Page\n{\n    public int stamped => Foundation.now();\n\n    law dated(Page page) => page.stamped > 0;\n}\n",
    );
    let stub = (
        "app/Stubs/Foundation.sharp",
        "namespace App.Stubs;\n\nimport Vendor.Foundation;\n\nextern Foundation.now uses Clock;\n",
    );
    let bare = ("app/Stubs/Clock.sharp", "namespace App.Stubs;\n\nextern now uses Clock;\n");

    assert_eq!(issues(stub, &[helpers, application]), Vec::<String>::new());
    assert_eq!(
        effect_issues(&[page, stub, helpers, application]),
        [
            "app/Shop/Page.sharp:9:29 impure-law: Law `dated` reaches `Page.stamped`, which calls `Foundation.now` with the effect `Clock`. Laws hold only over pure code."
        ]
    );
    assert_eq!(
        refusals(bare, &[helpers, application]),
        ["3:8 non-existent-function Function `now` does not exist. | "]
    );
}

/// Spec section 23 names a plain PHP function through its namespace in an `extern` as in a call: `Pdf.render` after
/// `import Vendor.Pdf;`. The effects it lists reach each call of the function, a function with no `extern` names the one
/// to write, and a bare `extern trim;` of PHP's own function names no function, as a misspelled name does.
#[test]
fn an_extern_declares_a_plain_php_function_through_its_namespace() {
    let pdf = (
        "src/Vendor/Pdf/functions.php",
        "<?php\n\nnamespace Vendor\\Pdf;\n\nfunction render(string $html): string\n{\n    return $html;\n}\n",
    );
    let page = (
        "app/Shop/Page.sharp",
        "namespace App.Shop;\n\nimport Vendor.Pdf;\n\npublic class Page\n{\n    public Page(private string html) { }\n\n    public string printed => Pdf.render(this.html);\n\n    law printable(Page page) => page.printed != \"\";\n}\n",
    );
    let stub = ("app/Stubs/Pdf.sharp", "namespace App.Stubs;\n\nimport Vendor.Pdf;\n\nextern Pdf.render uses Files;\n");
    let bare = ("app/Stubs/Text.sharp", "namespace App.Stubs;\n\nextern trim;\n");

    assert_eq!(
        effect_issues(&[page, pdf, stub]),
        [
            "app/Shop/Page.sharp:11:33 impure-law: Law `printable` reaches `Page.printed`, which calls `Pdf.render` with the effect `Files`. Laws hold only over pure code."
        ]
    );
    assert_eq!(
        effect_issues(&[page, pdf]),
        [
            "app/Shop/Page.sharp:11:33 impure-law: Law `printable` reaches `Page.printed`, which calls `Pdf.render` with no `extern` declaration. Laws hold only over pure code. Help: Declare it in a .sharp file: `extern Pdf.render;` when it has no effect, or name its effects after `uses`."
        ]
    );
    assert_eq!(refusals(bare, &[]), ["3:8 non-existent-function Function `trim` does not exist. | "]);
}

const MAGIC: (&str, &str) = (
    "src/Lib/Magic.php",
    "<?php\n\nnamespace Lib;\n\nfinal class Bag\n{\n    /** @param list<mixed> $arguments */\n    public function __call(string $name, array $arguments): int\n    {\n        return 0;\n    }\n}\n\nfinal class Codes\n{\n    /** @param list<mixed> $arguments */\n    public static function __callStatic(string $name, array $arguments): int\n    {\n        return 0;\n    }\n}\n",
);

const SHELF: (&str, &str) = (
    "app/Shop/Shelf.sharp",
    "namespace App.Shop;\n\nimport Lib.Bag;\nimport Lib.Codes;\n\npublic class Shelf\n{\n    public Shelf(private Bag bag) { }\n\n    public int count => this.bag.size();\n\n    public int code => Codes.next();\n\n    law counted(Shelf shelf) => shelf.count > 0;\n\n    law coded(Shelf shelf) => shelf.code > 0;\n}\n",
);

/// A method no class declares runs the class's `__call` or `__callStatic`, so its call has the effects the `extern` on
/// that magic method declares, and an unknown effect without one, as any call of a plain PHP method does. A law
/// reading a getter that makes the call has them too.
#[test]
fn a_call_of_a_method_a_magic_method_serves_has_the_effects_of_the_magic_method() {
    let pure = (
        "app/Stubs/Magic.sharp",
        "namespace App.Stubs;\n\nimport Lib.Bag;\nimport Lib.Codes;\n\nextern Bag.__call;\nextern Codes.__callStatic;\n",
    );
    let timed = (
        "app/Stubs/Magic.sharp",
        "namespace App.Stubs;\n\nimport Lib.Bag;\nimport Lib.Codes;\n\nextern Bag.__call uses Clock;\nextern Codes.__callStatic;\n",
    );

    assert_eq!(
        effect_issues(&[SHELF, MAGIC]),
        [
            "app/Shop/Shelf.sharp:14:33 impure-law: Law `counted` reaches `Shelf.count`, which calls `Bag.__call` with no `extern` declaration. Laws hold only over pure code. Help: Declare it in a .sharp file: `extern Bag;` when it has no effect, or name its effects after `uses`.",
            "app/Shop/Shelf.sharp:16:31 impure-law: Law `coded` reaches `Shelf.code`, which calls `Codes.__callStatic` with no `extern` declaration. Laws hold only over pure code. Help: Declare it in a .sharp file: `extern Codes;` when it has no effect, or name its effects after `uses`.",
        ]
    );
    assert_eq!(issues(pure, &[MAGIC]), Vec::<String>::new());
    assert_eq!(effect_issues(&[SHELF, MAGIC, pure]), Vec::<String>::new());
    assert_eq!(
        effect_issues(&[SHELF, MAGIC, timed]),
        [
            "app/Shop/Shelf.sharp:14:33 impure-law: Law `counted` reaches `Shelf.count`, which calls `Bag.__call` with the effect `Clock`. Laws hold only over pure code."
        ]
    );
}

/// Spec section 29: code without a body is pure unless it says `uses`, function types included, so calling a property
/// a PHP# class declares with a `Function` type has no effect.
#[test]
fn a_getter_calling_a_property_holding_a_function_type_passes() {
    let pricing = (
        "app/Shop/Pricing.sharp",
        "namespace App.Shop;\n\npublic class Pricing\n{\n    public Pricing(private Function<int(int)> rate) { }\n\n    public int price => this.rate(2);\n}\n",
    );

    assert_eq!(effect_issues(&[pricing]), Vec::<String>::new());
}

/// A plain PHP `fetch`, which its `extern` gives the effect `Http`.
const FETCH: (&str, &str) = (
    "src/Acme/Remote/fetch.php",
    "<?php\n\nnamespace Acme\\Remote;\n\nfunction fetch(int $id): int\n{\n    return $id;\n}\n",
);

const FETCH_STUB: (&str, &str) =
    ("app/Stubs/Fetch.sharp", "namespace App.Stubs;\n\nimport Acme.Remote;\n\nextern Remote.fetch uses Http;\n");

/// Spec section 29: a declaration without a body is held to what each declaration it overrides allows, as an
/// implementation is, so a sub-interface may narrow its parent's `uses` but never widen it. The refusal is at the
/// declaration.
#[test]
fn a_declaration_has_only_the_effects_the_declaration_it_overrides_allows() {
    let fetcher = (
        "app/Shop/Fetcher.sharp",
        "namespace App.Shop;\n\npublic interface Fetcher\n{\n    int fetch() uses Http, Clock;\n}\n",
    );
    let pinger = ("app/Shop/Pinger.sharp", "namespace App.Shop;\n\npublic interface Pinger\n{\n    int ping();\n}\n");
    let wide = (
        "app/Shop/WideFetcher.sharp",
        "namespace App.Shop;\n\npublic interface WideFetcher : Fetcher, Pinger\n{\n    int fetch() uses Http, Clock, Files;\n\n    int ping() uses Http;\n}\n",
    );
    let narrow = (
        "app/Shop/NarrowFetcher.sharp",
        "namespace App.Shop;\n\npublic interface NarrowFetcher : Fetcher\n{\n    int fetch() uses Http;\n}\n",
    );
    let base = (
        "app/Shop/Source.sharp",
        "namespace App.Shop;\n\npublic abstract class Source : Fetcher\n{\n    public abstract int fetch() uses Mail;\n}\n",
    );

    assert_eq!(
        refusals(wide, &[fetcher, pinger]),
        [
            "5:9 incompatible-effects `WideFetcher.fetch` uses `Files`, so `uses Http, Clock` on `Fetcher.fetch` cannot accept it. | ",
            "7:9 incompatible-effects `WideFetcher.ping` uses `Http`, so the pure `Pinger.ping` cannot accept it. | ",
        ]
    );
    assert_eq!(refusals(narrow, &[fetcher]), Vec::<String>::new());
    assert_eq!(
        refusals(base, &[fetcher]),
        [
            "5:25 incompatible-effects `Source.fetch` uses `Mail`, so `uses Http, Clock` on `Fetcher.fetch` cannot accept it. | "
        ]
    );
}

/// Spec section 29: a method without a body is pure unless it says `uses`, and every implementation is held to what
/// the declaration allows, an interface's or an abstract class's. The refusal is at the call that has the effect.
#[test]
fn an_implementation_has_only_the_effects_its_declaration_allows() {
    let implementation = (
        "app/Shop/LiveRates.sharp",
        "namespace App.Shop;\n\nimport Acme.Remote;\n\npublic class LiveRates : Rates\n{\n    public int rate(int id) => Remote.fetch(id);\n}\n",
    );
    let refused = "app/Shop/LiveRates.sharp:7:32 incompatible-effects: `LiveRates.rate` calls `Remote.fetch`, which has the effect `Http`, so";

    for (declaration, allowed) in [
        ("namespace App.Shop;\n\npublic interface Rates\n{\n    int rate(int id);\n}\n", None),
        ("namespace App.Shop;\n\npublic interface Rates\n{\n    int rate(int id) uses Mail;\n}\n", None),
        ("namespace App.Shop;\n\npublic interface Rates\n{\n    int rate(int id) uses Mail, Http;\n}\n", Some(())),
        ("namespace App.Shop;\n\npublic abstract class Rates\n{\n    public abstract int rate(int id);\n}\n", None),
    ] {
        let rates = ("app/Shop/Rates.sharp", declaration);
        let issues = effect_issues(&[implementation, rates, FETCH, FETCH_STUB]);

        match allowed {
            Some(()) => assert_eq!(issues, Vec::<String>::new(), "{declaration}"),
            None => assert!(issues.len() == 1 && issues[0].starts_with(refused), "{declaration}: {issues:?}"),
        }
    }
    assert_eq!(
        effect_issues(&[
            implementation,
            (
                "app/Shop/Rates.sharp",
                "namespace App.Shop;\n\npublic interface Rates\n{\n    int rate(int id) uses Mail;\n}\n"
            ),
            FETCH,
            FETCH_STUB,
        ]),
        [format!("{refused} `uses Mail` on `Rates.rate` cannot accept it.")]
    );
    assert_eq!(
        effect_issues(&[
            implementation,
            ("app/Shop/Rates.sharp", "namespace App.Shop;\n\npublic interface Rates\n{\n    int rate(int id);\n}\n"),
            FETCH,
            FETCH_STUB,
        ]),
        [format!("{refused} the pure `Rates.rate` cannot accept it.")]
    );
}

/// An implementation that calls plain PHP with no `extern` is refused like a getter that does: the help names the
/// `extern` of the class to write, with the effects the declaration's `uses` lists, and the import its file lacks.
#[test]
fn an_implementation_calling_plain_php_with_no_extern_names_the_extern_to_write() {
    let sync = (
        "app/Shop/AudienceSync.sharp",
        "namespace App.Shop;\n\npublic interface AudienceSync\n{\n    void sync(int contact) uses Http, Mail;\n}\n",
    );
    let mailchimp = (
        "app/Shop/MailchimpSync.sharp",
        "namespace App.Shop;\n\nimport Lib.Meter;\n\npublic class MailchimpSync : AudienceSync\n{\n    public MailchimpSync(private Meter meter) { }\n\n    public void sync(int contact) { this.meter.read(); }\n}\n",
    );
    assert_eq!(
        effect_issues(&[mailchimp, sync, METER]),
        [
            "app/Shop/MailchimpSync.sharp:9:37 incompatible-effects: `MailchimpSync.sync` calls `Meter.read`, which has no `extern` declaration, so `uses Http, Mail` on `AudienceSync.sync` cannot accept it. Help: Declare its effect in a .sharp file, such as `extern Meter uses Http, Mail;`."
        ]
    );

    let gauge = (
        "app/Shop/Gauge.sharp",
        "namespace App.Shop;\n\nimport Lib.Meter;\n\npublic class Gauge\n{\n    public Gauge(private Meter source) { }\n\n    public Meter meter() => this.source;\n}\n",
    );
    let rates =
        ("app/Shop/Rates.sharp", "namespace App.Shop;\n\npublic interface Rates\n{\n    int rate(int id);\n}\n");
    let implementation = (
        "app/Shop/MeterRates.sharp",
        "namespace App.Shop;\n\npublic class MeterRates : Rates\n{\n    public MeterRates(private Gauge gauge) { }\n\n    public int rate(int id) => this.gauge.meter().read();\n}\n",
    );

    assert_eq!(
        effect_issues(&[implementation, rates, gauge, METER]),
        [
            "app/Shop/MeterRates.sharp:7:32 incompatible-effects: `MeterRates.rate` calls `Meter.read`, which has no `extern` declaration, so the pure `Rates.rate` cannot accept it. Help: Declare it in a .sharp file: `extern Meter;` when it has no effect, or name its effects after `uses`. Add `import Lib.Meter;` to the file."
        ]
    );
}

/// The plain PHP a returned-object row calls: `Client` and `Desk` return a `Session`, which has no `extern` of its own,
/// as `DB::table()` returns a query builder through `Facade::__callStatic`.
const RETURNED: [(&str, &str); 4] = [
    (
        "src/Lib/Client.php",
        "<?php\n\nnamespace Lib;\n\nfinal class Client\n{\n    public static function make(): Session\n    {\n        return new Session();\n    }\n}\n",
    ),
    (
        "src/Lib/Session.php",
        "<?php\n\nnamespace Lib;\n\nclass Session\n{\n    public function send(): void\n    {\n    }\n\n    public function next(): static\n    {\n        return $this;\n    }\n}\n",
    ),
    (
        "src/Lib/Facade.php",
        "<?php\n\nnamespace Lib;\n\nabstract class Facade\n{\n    public static function __callStatic(string $method, array $args): mixed\n    {\n        return null;\n    }\n}\n",
    ),
    (
        "src/Lib/Desk.php",
        "<?php\n\nnamespace Lib;\n\n/**\n * @method static Session open()\n */\nfinal class Desk extends Facade\n{\n}\n",
    ),
];

/// Spec section 29: an object a declared plain PHP call returns carries that call's effect, through a chain, a local, a
/// field, a `static` return and a facade's `__callStatic`, and an `extern` on the returned class wins over it. A class
/// two declared calls return carries the effects of both.
#[test]
fn an_object_a_declared_call_returns_carries_its_effect() {
    let stub = |externs: &'static str| {
        (
            "app/Stubs/Lib.sharp",
            &*Box::leak(
                format!(
                    "namespace App.Stubs;\n\nimport Lib.Client;\nimport Lib.Desk;\nimport Lib.Session;\n\n{externs}"
                )
                .into_boxed_str(),
            ),
        )
    };
    let sender = (
        "app/Shop/Sender.sharp",
        "namespace App.Shop;\n\npublic interface Sender\n{\n    void chain() uses Http;\n\n    void local() uses Http;\n\n    void field() uses Http;\n\n    void next() uses Http;\n}\n",
    );
    let client_sender = (
        "app/Shop/ClientSender.sharp",
        "namespace App.Shop;\n\nimport Lib.Client;\nimport Lib.Session;\n\npublic class ClientSender : Sender\n{\n    private Session session = Client.make();\n\n    public void chain() { Client.make().send(); }\n\n    public void local()\n    {\n        const session = Client.make();\n        session.send();\n    }\n\n    public void field() { this.session.send(); }\n\n    public void next() { Client.make().next().send(); }\n}\n",
    );
    let desk = (
        "app/Shop/DeskSender.sharp",
        "namespace App.Shop;\n\nimport Lib.Desk;\n\npublic interface Opens\n{\n    void open() uses Http;\n}\n\npublic class DeskSender : Opens\n{\n    public void open() { Desk.open().send(); }\n}\n",
    );
    let [client, session, facade, desk_class] = RETURNED;

    assert_eq!(
        effect_issues(&[
            client_sender,
            sender,
            stub("extern Client uses Http;\nextern Desk uses Http;\n"),
            client,
            session,
            facade,
            desk_class,
            desk
        ]),
        Vec::<String>::new()
    );
    assert_eq!(
        effect_issues(&[
            client_sender,
            sender,
            stub("extern Client uses Http;\nextern Desk uses Http;\nextern Session uses Mail;\n"),
            client,
            session,
            facade,
            desk_class,
            desk
        ]),
        [
            "app/Shop/ClientSender.sharp:10:27 incompatible-effects: `ClientSender.chain` calls `Session.send`, which has the effect `Mail`, so `uses Http` on `Sender.chain` cannot accept it.",
            "app/Shop/ClientSender.sharp:15:9 incompatible-effects: `ClientSender.local` calls `Session.send`, which has the effect `Mail`, so `uses Http` on `Sender.local` cannot accept it.",
            "app/Shop/ClientSender.sharp:18:27 incompatible-effects: `ClientSender.field` calls `Session.send`, which has the effect `Mail`, so `uses Http` on `Sender.field` cannot accept it.",
            "app/Shop/ClientSender.sharp:20:26 incompatible-effects: `ClientSender.next` calls `Session.send`, which has the effect `Mail`, so `uses Http` on `Sender.next` cannot accept it.",
            "app/Shop/DeskSender.sharp:12:26 incompatible-effects: `DeskSender.open` calls `Session.send`, which has the effect `Mail`, so `uses Http` on `Opens.open` cannot accept it.",
        ]
    );
    // A body that reaches the call, and a method value of it, name the declared call too.
    let relay = (
        "app/Shop/Relay.sharp",
        "namespace App.Shop;\n\nimport Lib.Desk;\nimport Lib.Session;\n\npublic class Relay : Opens\n{\n    public void open() { this.send(Desk.open()); }\n\n    public void send(Session session) { session.send(); }\n\n    public void later(Function<void() uses Http> f) { f(); }\n\n    public void valued() { this.later(Desk.open().send); }\n}\n",
    );
    assert_eq!(
        effect_issues(&[relay, desk, stub("extern Desk uses Mail;\n"), client, session, facade, desk_class]),
        [
            "app/Shop/Relay.sharp:14:39 invalid-argument: `Session.send` has the effect `Mail` that `Desk.open` declares for the `Session` it returns, so a `Function<void() uses Http>` cannot hold it. Help: An `extern` on `Session` overrides the effects it carries: write `extern Session uses Http;` in a .sharp file.",
            "app/Shop/Relay.sharp:8:26 incompatible-effects: `Relay.open` reaches `Relay.send`, which calls `Session.send` with the effect `Mail` that `Desk.open` declares for the `Session` it returns, so `uses Http` on `Opens.open` cannot accept it. Help: An `extern` on `Session` overrides the effects it carries: write `extern Session uses Http;` in a .sharp file.",
            "app/Shop/DeskSender.sharp:12:26 incompatible-effects: `DeskSender.open` calls `Session.send`, which has the effect `Mail` that `Desk.open` declares for the `Session` it returns, so `uses Http` on `Opens.open` cannot accept it. Help: An `extern` on `Session` overrides the effects it carries: write `extern Session uses Http;` in a .sharp file. Add `import Lib.Session;` to the file.",
        ]
    );
    // `Desk` returns a `Session` with `Mail`, and `Client` one with `Http`, so every `Session` has both. The message
    // names the declared call a carried effect comes from, and the help the `extern` on the class that overrides it.
    assert_eq!(
        effect_issues(&[
            client_sender,
            sender,
            stub("extern Client uses Http;\nextern Desk uses Mail;\n"),
            client,
            session,
            facade,
            desk_class,
            desk
        ]),
        [
            "app/Shop/ClientSender.sharp:10:27 incompatible-effects: `ClientSender.chain` calls `Session.send`, which has the effect `Mail` that `Desk.open` declares for the `Session` it returns, so `uses Http` on `Sender.chain` cannot accept it. Help: An `extern` on `Session` overrides the effects it carries: write `extern Session uses Http;` in a .sharp file.",
            "app/Shop/ClientSender.sharp:15:9 incompatible-effects: `ClientSender.local` calls `Session.send`, which has the effect `Mail` that `Desk.open` declares for the `Session` it returns, so `uses Http` on `Sender.local` cannot accept it. Help: An `extern` on `Session` overrides the effects it carries: write `extern Session uses Http;` in a .sharp file.",
            "app/Shop/ClientSender.sharp:18:27 incompatible-effects: `ClientSender.field` calls `Session.send`, which has the effect `Mail` that `Desk.open` declares for the `Session` it returns, so `uses Http` on `Sender.field` cannot accept it. Help: An `extern` on `Session` overrides the effects it carries: write `extern Session uses Http;` in a .sharp file.",
            "app/Shop/ClientSender.sharp:20:26 incompatible-effects: `ClientSender.next` calls `Session.send`, which has the effect `Mail` that `Desk.open` declares for the `Session` it returns, so `uses Http` on `Sender.next` cannot accept it. Help: An `extern` on `Session` overrides the effects it carries: write `extern Session uses Http;` in a .sharp file.",
            "app/Shop/DeskSender.sharp:12:26 incompatible-effects: `DeskSender.open` calls `Session.send`, which has the effect `Mail` that `Desk.open` declares for the `Session` it returns, so `uses Http` on `Opens.open` cannot accept it. Help: An `extern` on `Session` overrides the effects it carries: write `extern Session uses Http;` in a .sharp file. Add `import Lib.Session;` to the file.",
        ]
    );
}

/// The standard library's declarations of PHP's built-in functions and exception classes, as `sharp/bin/builtins`
/// writes them.
const BUILTINS: (&str, &str) = (
    "vendor/heyjordanparker/php-sharp-composer/library/Sharp/Internal/Builtins.sharp",
    include_str!("../../../../composer/library/Sharp/Internal/Builtins.sharp"),
);

/// Spec section 29: every PHP built-in exception class comes declared pure, so pure code may create and throw one: a
/// standard exception in a project, and one in a namespace in the standard library, the only code that names it
/// (decision 83). Without the declaration the refusal names the class `new` names, not the class that declares its
/// constructor.
#[test]
fn creating_a_built_in_exception_is_pure() {
    let gauge = (
        "app/Shop/Gauge.sharp",
        "namespace App.Shop;\n\npublic class Gauge\n{\n    public int first(List<int> values) => values.count() > 0 ? values[0] : throw new ValueError(\"empty\");\n\n    public int parsed(string text) => text != \"\" ? 1 : throw new JsonException(\"blank\");\n\n    law first(Gauge gauge) => gauge.first([1]) == 1;\n\n    law parsed(Gauge gauge) => gauge.parsed(\"1\") == 1;\n}\n",
    );
    let seeds = (
        "vendor/heyjordanparker/php-sharp-composer/library/Sharp/System/Seeds.sharp",
        "namespace Sharp.System;\n\nimport Random.RandomException;\n\npublic class Seeds\n{\n    public int seeded(int seed) => seed > 0 ? seed : throw new RandomException(\"no seed\");\n\n    law seeded(Seeds seeds) => seeds.seeded(1) == 1;\n}\n",
    );

    assert_eq!(issues(gauge, &[BUILTINS]), Vec::<String>::new());
    assert_eq!(issues(seeds, &[BUILTINS]), Vec::<String>::new());
    assert_eq!(effect_issues(&[gauge, seeds, BUILTINS]), Vec::<String>::new());
    assert_eq!(
        effect_issues(&[gauge, seeds]),
        [
            "app/Shop/Gauge.sharp:5:82 impure-law: Law `first` calls `ValueError`, which has no `extern` declaration. Laws hold only over pure code. Help: Declare it in a .sharp file: `extern ValueError;` when it has no effect, or name its effects after `uses`.",
            "app/Shop/Gauge.sharp:7:62 impure-law: Law `parsed` calls `JsonException`, which has no `extern` declaration. Laws hold only over pure code. Help: Declare it in a .sharp file: `extern JsonException;` when it has no effect, or name its effects after `uses`.",
            "vendor/heyjordanparker/php-sharp-composer/library/Sharp/System/Seeds.sharp:7:60 impure-law: Law `seeded` calls `RandomException`, which has no `extern` declaration. Laws hold only over pure code. Help: Declare it in a .sharp file: `extern RandomException;` when it has no effect, or name its effects after `uses`.",
        ]
    );
}

/// Spec section 29: a date is a value once created, so the standard library declares `DateTimeImmutable` pure, but
/// each member that can read the clock is declared `uses Clock`: `modify`, the constructor and `createFromFormat`,
/// whose text may say "now". Reading a date it is given keeps a method pure. Only the standard library names the
/// class (decision 83), so its own files show it.
#[test]
fn a_date_member_that_can_read_the_clock_has_the_effect_clock() {
    let reading = (
        "vendor/heyjordanparker/php-sharp-composer/library/Sharp/Time/Reading.sharp",
        "namespace Sharp.Time;\n\nimport DateTimeImmutable;\n\npublic interface Reading\n{\n    int moved(DateTimeImmutable given);\n\n    int made();\n\n    int read(DateTimeImmutable given);\n}\n",
    );
    let stamped = (
        "vendor/heyjordanparker/php-sharp-composer/library/Sharp/Time/Stamped.sharp",
        "namespace Sharp.Time;\n\nimport DateTimeImmutable;\n\npublic class Stamped : DateTimeImmutable\n{\n    public Stamped() : super(\"now\") { }\n}\n",
    );
    let pure = (
        "vendor/heyjordanparker/php-sharp-composer/library/Sharp/Time/PureReading.sharp",
        "namespace Sharp.Time;\n\nimport DateTimeImmutable;\n\npublic class PureReading : Reading\n{\n    public int moved(DateTimeImmutable given) => given.modify(\"now\").getTimestamp();\n\n    public int made() => new Stamped().getTimestamp();\n\n    public int read(DateTimeImmutable given) => given.getTimestamp();\n}\n",
    );

    assert_eq!(issues(pure, &[reading, stamped, BUILTINS]), Vec::<String>::new());
    assert_eq!(
        effect_issues(&[pure, reading, stamped, BUILTINS]),
        [
            "vendor/heyjordanparker/php-sharp-composer/library/Sharp/Time/PureReading.sharp:7:50 incompatible-effects: `PureReading.moved` calls `DateTimeImmutable.modify`, which has the effect `Clock`, so the pure `Reading.moved` cannot accept it.",
            "vendor/heyjordanparker/php-sharp-composer/library/Sharp/Time/PureReading.sharp:9:26 incompatible-effects: `PureReading.made` reaches `Stamped.Stamped`, which calls `DateTimeImmutable.__construct` with the effect `Clock`, so the pure `Reading.made` cannot accept it.",
        ]
    );
}

/// Decision 83: PHP is reached only through the standard library, so a PHP built-in class, interface or namespace of
/// them is the name a misspelled one is in a `.sharp` file: a type, `new`, a static call, `is` and a header with no
/// import, and an import, each get the error the misspelling gets, with no message that recognizes PHP's class. The
/// standard library's own files name and create them as any plain PHP class.
#[test]
fn a_php_built_in_class_is_the_name_a_misspelled_class_is() {
    let used = |class: &str| {
        leak(format!(
            "namespace App.Shop;\n\npublic class Stamp : {class}\n{{\n    public {class} open() => new {class}(\"sqlite::memory:\");\n\n    public bool held(Any? value) => value is {class};\n\n    public int drivers() => {class}.getAvailableDrivers().count();\n}}\n"
        ))
    };
    let imported =
        |class: &str| leak(format!("namespace App.Shop;\n\nimport {class};\n\npublic class Stamp\n{{\n}}\n"));

    let misspelled = refusals(("app/Shop/Stamp.sharp", used("PDQ")), &[]);
    assert!(!misspelled.is_empty());
    assert_eq!(
        refusals(("app/Shop/Stamp.sharp", used("PDO")), &[]),
        misspelled.iter().map(|refusal| refusal.replace("PDQ", "PDO")).collect::<Vec<_>>()
    );
    for (class, typo) in [
        ("PDO", "PDQ"),
        ("DateTimeImmutable", "DateTimeImmutabel"),
        ("Random.Randomizer", "Random.Randomiser"),
        ("Random", "Randon"),
    ] {
        let misspelled = refusals(("app/Shop/Stamp.sharp", imported(typo)), &[]);
        assert!(!misspelled.is_empty(), "{typo}");
        assert_eq!(
            refusals(("app/Shop/Stamp.sharp", imported(class)), &[]),
            misspelled.iter().map(|refusal| refusal.replace(typo, class)).collect::<Vec<_>>(),
            "{class}"
        );
    }

    let library = (
        "vendor/heyjordanparker/php-sharp-composer/library/Sharp/Data/Stamp.sharp",
        "namespace Sharp.Data;\n\nimport DateTimeImmutable;\nimport PDO;\n\npublic class Stamp\n{\n    public string year(DateTimeImmutable moment) => moment.format(\"Y\");\n\n    public int drivers() => PDO.getAvailableDrivers().count();\n\n    public DateTimeImmutable? at(string text) => DateTimeImmutable.createFromFormat(\"Y-m-d\", text) ?: null;\n\n    public PDO open() => new PDO(\"sqlite::memory:\");\n}\n",
    );
    assert_eq!(issues(library, &[]), Vec::<String>::new());
}

/// Decision 83: the standard library names the interfaces a PHP# class implements for a plain PHP library, the root of
/// every exception and the class that makes a class an attribute, as it names the standard exceptions, so a bare
/// `Countable`, `JsonSerializable`, `Throwable` and `Attribute` name PHP's with no import.
#[test]
fn the_standard_library_names_the_interfaces_a_plain_php_library_needs_with_no_import() {
    let tagged = ("app/Shop/Tagged.sharp", "namespace App.Shop;\n\n[Attribute]\npublic class Tagged\n{\n}\n");
    let basket = (
        "app/Shop/Basket.sharp",
        "namespace App.Shop;\n\n[Tagged]\npublic class Basket : Countable, JsonSerializable\n{\n    public int count() => 0;\n\n    public Any? jsonSerialize() => null;\n\n    public static bool failed(Any? value) => value is Throwable;\n}\n",
    );

    assert_eq!(issues(tagged, &[]), Vec::<String>::new());
    assert_eq!(issues(basket, &[tagged]), Vec::<String>::new());
}

/// The standard root classes a bare name names are the class-likes in PHP's root namespace that `Builtins.sharp`
/// declares: each class it declares with no import, which is no function and no member.
#[test]
fn the_standard_root_classes_are_the_root_classes_the_standard_library_declares() {
    let imported: HashSet<&str> = BUILTINS
        .1
        .lines()
        .filter_map(|line| line.strip_prefix("import ")?.strip_suffix(';'))
        .map(|import| import.rsplit([' ', '.']).next().unwrap())
        .collect();
    let mut root: Vec<&str> = BUILTINS
        .1
        .lines()
        .filter_map(|line| line.strip_prefix("extern ")?.strip_suffix(';'))
        .filter(|name| !name.contains('.') && !imported.contains(name))
        .collect();
    root.sort_unstable();
    let mut standard = STANDARD_ROOT_CLASSES.to_vec();
    standard.sort_unstable();

    assert_eq!(standard, root);
}

/// Spec section 23: a bare name of a standard exception class names PHP's own with no import, as `Sharp`'s names do. A
/// class of the file's namespace, or one it imports, wins over it, so `kind()`, which only those declare, resolves.
#[test]
fn a_standard_exception_needs_no_import_and_a_class_of_the_namespace_or_an_import_wins_over_it() {
    let own = (
        "app/Shop/ValueError.sharp",
        "namespace App.Shop;\n\npublic class ValueError\n{\n    public ValueError(public string reason { get; }) { }\n\n    public string kind() => \"shop\";\n}\n",
    );
    let imported = (
        "vendor/lib/src/ValueError.php",
        "<?php\n\nnamespace Lib;\n\nfinal class ValueError extends \\Exception\n{\n    public function kind(): string\n    {\n        return 'lib';\n    }\n}\n",
    );

    for (row, analyzed, others) in [
        (
            "a bare ValueError in a namespaced file",
            (
                "app/Shop/Gauge.sharp",
                "namespace App.Shop;\n\npublic class Gauge\n{\n    public int first(List<int> values) => values.count() > 0 ? values[0] : throw new ValueError(\"empty\");\n}\n",
            ),
            vec![BUILTINS],
        ),
        (
            "a ValueError of the file's namespace",
            (
                "app/Shop/Gauge.sharp",
                "namespace App.Shop;\n\npublic class Gauge\n{\n    public string kind() => new ValueError(\"empty\").kind();\n}\n",
            ),
            vec![BUILTINS, own],
        ),
        (
            "an imported ValueError",
            (
                "app/Shop/Gauge.sharp",
                "namespace App.Shop;\n\nimport Lib.ValueError;\n\npublic class Gauge\n{\n    public string kind() => new ValueError(\"empty\").kind();\n}\n",
            ),
            vec![BUILTINS, imported],
        ),
        (
            "a catch of OutOfRangeException",
            (
                "app/Shop/Gauge.sharp",
                "namespace App.Shop;\n\npublic class Gauge\n{\n    public int first(Function<int()> read)\n    {\n        try {\n            return read();\n        } catch (OutOfRangeException e) {\n            return 0;\n        }\n    }\n}\n",
            ),
            vec![BUILTINS],
        ),
    ] {
        assert_eq!(issues(analyzed, &others), Vec::<String>::new(), "{row}");
    }
}

/// A catch of a class that does not exist catches nothing, and its note names the checker, never the tool.
#[test]
fn a_catch_of_a_class_that_does_not_exist_is_reported() {
    let gauge = (
        "src/Gauge.php",
        "<?php\n\nfunction first(int $read): int\n{\n    try {\n        return intdiv(10, $read);\n    } catch (OutOfRangeError $e) {\n        return 0;\n    }\n}\n",
    );

    assert_eq!(issues(gauge, &[]), ["7:14 non-existent-catch-type", "7:14 no-valid-catch-type-found"]);
    assert!(
        worded(gauge, &[]).last().is_some_and(|issue| issue.contains("the checker might internally default")),
        "{:?}",
        worded(gauge, &[])
    );
}

/// A call of a method without a body has the effects its `uses` lists, which every implementation is held to, so a
/// law reading a getter that calls it through an interface is refused naming them.
#[test]
fn a_call_of_a_method_without_a_body_has_the_effects_its_uses_lists() {
    let rates = |uses: &'static str| {
        (
            "app/Shop/Rates.sharp",
            Box::leak(
                format!("namespace App.Shop;\n\npublic interface Rates\n{{\n    int rate(int id){uses};\n}}\n")
                    .into_boxed_str(),
            ) as &str,
        )
    };
    let quote = (
        "app/Shop/Quote.sharp",
        "namespace App.Shop;\n\npublic class Quote\n{\n    public Quote(private Rates rates) { }\n\n    public int price => this.rates.rate(1);\n\n    law priced(Quote quote) => quote.price > 0;\n}\n",
    );

    assert_eq!(effect_issues(&[quote, rates("")]), Vec::<String>::new());
    assert_eq!(
        effect_issues(&[quote, rates(" uses Http")]),
        [
            "app/Shop/Quote.sharp:9:32 impure-law: Law `priced` reaches `Quote.price`, which calls `Rates.rate` with the effect `Http`. Laws hold only over pure code."
        ]
    );
}

/// Spec section 29: a call through a function value has the effects its function type lists, whether the value is a
/// field, a parameter or a local. A getter may call one that uses `Database`, spec section 6, and a law reading the
/// getter is refused naming `Database`.
#[test]
fn a_law_reading_a_getter_that_calls_a_function_value_with_an_effect_is_refused_naming_the_effect() {
    let pricing = (
        "app/Shop/Pricing.sharp",
        "namespace App.Shop;\n\npublic class Pricing\n{\n    public Pricing(private Function<int(int) uses Database> rate) { }\n\n    public int price => this.rate(2);\n\n    public int total => this.apply(this.rate);\n\n    public int stored\n    {\n        get\n        {\n            Function<int(int) uses Database> lookup = this.rate;\n            return lookup(3);\n        }\n    }\n\n    public int apply(Function<int(int) uses Database> step) => step(1);\n\n    law priced(Pricing pricing) => pricing.price > 0;\n\n    law totaled(Pricing pricing) => pricing.total > 0;\n\n    law kept(Pricing pricing) => pricing.stored > 0;\n}\n",
    );

    assert_eq!(issues(pricing, &[]), Vec::<String>::new());
    assert_eq!(
        effect_issues(&[pricing]),
        [
            "app/Shop/Pricing.sharp:22:36 impure-law: Law `priced` reaches `Pricing.price`, which calls `Pricing.rate` with the effect `Database`. Laws hold only over pure code.",
            "app/Shop/Pricing.sharp:24:37 impure-law: Law `totaled` reaches `Pricing.apply`, which calls `step` with the effect `Database`. Laws hold only over pure code.",
            "app/Shop/Pricing.sharp:26:34 impure-law: Law `kept` reaches `Pricing.stored`, which calls `lookup` with the effect `Database`. Laws hold only over pure code.",
        ]
    );
}

/// A call that runs a function value has that value's effects, whether a local holding a lambda runs it, or a plain
/// PHP function or method runs a lambda, a method value or a function value it is given, even when its `extern`
/// declares it pure. A getter that runs one has them, and so a law reading it is refused.
#[test]
fn running_a_function_value_through_plain_php_or_a_local_has_the_value_s_effects() {
    let effects = (
        "app/Shop/Effects.sharp",
        "namespace App.Shop;\n\nimport Acme.Chrono;\nimport Acme.Lists;\nimport Acme.Relay;\nimport Lib.Runner;\n\npublic class Effects\n{\n    public Effects(private Function<int() uses Clock> tick) { }\n\n    public int viaLocalLambda\n    {\n        get\n        {\n            const f = () => Chrono.now();\n            return f();\n        }\n    }\n\n    public int viaMap => Lists.size(Lists.map(x => Chrono.now() + x, [1, 2]));\n\n    public int viaRelay => Relay.run(() => Chrono.now());\n\n    public int viaSorted\n    {\n        get\n        {\n            List<int> xs = Lists.sorted([2, 1], (int a, int b) => Chrono.now() + a - b);\n            return xs[0];\n        }\n    }\n\n    public int viaPlainMethod => Runner.run(() => Chrono.now());\n\n    public int viaMethodValue => Lists.size(Lists.map(this.stamp, [1]));\n\n    public int viaFunctionValue => Relay.run(this.tick);\n\n    public int stamp(int x) => Chrono.now() + x;\n\n    law local(Effects effects) => effects.viaLocalLambda > 0;\n\n    law mapped(Effects effects) => effects.viaMap > 0;\n\n    law called(Effects effects) => effects.viaRelay > 0;\n\n    law sorted(Effects effects) => effects.viaSorted > 0;\n\n    law run(Effects effects) => effects.viaPlainMethod > 0;\n\n    law valued(Effects effects) => effects.viaMethodValue > 0;\n\n    law ticked(Effects effects) => effects.viaFunctionValue > 0;\n}\n",
    );
    let runner = (
        "app/Lib/Runner.php",
        "<?php\n\nnamespace Lib;\n\nfinal class Runner\n{\n    public static function run(callable $f): int\n    {\n        return $f();\n    }\n}\n",
    );
    let lists = (
        "src/Acme/Lists/functions.php",
        "<?php\n\nnamespace Acme\\Lists;\n\n/**\n * @template T\n *\n * @param callable(int): T $f\n * @param list<int> $items\n *\n * @return list<T>\n */\nfunction map(callable $f, array $items): array\n{\n    return array_values(array_map($f, $items));\n}\n\n/**\n * @template T\n *\n * @param list<T> $items\n * @param callable(T, T): int $compare\n *\n * @return list<T>\n */\nfunction sorted(array $items, callable $compare): array\n{\n    usort($items, $compare);\n\n    return $items;\n}\n\n/** @param array<mixed> $items */\nfunction size(array $items): int\n{\n    return count($items);\n}\n",
    );
    let stub = (
        "app/Stubs/Lists.sharp",
        "namespace App.Stubs;\n\nimport Acme.Lists;\nimport Lib.Runner;\n\nextern Runner;\nextern Lists.map;\nextern Lists.sorted;\nextern Lists.size;\n",
    );

    assert_eq!(
        effect_issues(&[effects, runner, lists, stub, RELAY, RELAY_STUB, NOW, CLOCK_STUB]),
        [
            "app/Shop/Effects.sharp:42:35 impure-law: Law `local` reaches `Effects.viaLocalLambda`, which calls `Chrono.now` with the effect `Clock`. Laws hold only over pure code.",
            "app/Shop/Effects.sharp:44:36 impure-law: Law `mapped` reaches `Effects.viaMap`, which calls `Chrono.now` with the effect `Clock`. Laws hold only over pure code.",
            "app/Shop/Effects.sharp:46:36 impure-law: Law `called` reaches `Effects.viaRelay`, which calls `Chrono.now` with the effect `Clock`. Laws hold only over pure code.",
            "app/Shop/Effects.sharp:48:36 impure-law: Law `sorted` reaches `Effects.viaSorted`, which calls `Chrono.now` with the effect `Clock`. Laws hold only over pure code.",
            "app/Shop/Effects.sharp:50:33 impure-law: Law `run` reaches `Effects.viaPlainMethod`, which calls `Chrono.now` with the effect `Clock`. Laws hold only over pure code.",
            "app/Shop/Effects.sharp:52:36 impure-law: Law `valued` reaches `Effects.stamp`, which calls `Chrono.now` with the effect `Clock`. Laws hold only over pure code.",
            "app/Shop/Effects.sharp:54:36 impure-law: Law `ticked` reaches `Effects.viaFunctionValue`, which calls `this.tick` with the effect `Clock`. Laws hold only over pure code.",
        ]
    );
    assert_eq!(issues(effects, &[runner, lists, stub, RELAY, RELAY_STUB, NOW, CLOCK_STUB]), Vec::<String>::new());
}

/// A law takes a function value as any parameter, and calling it has the effects its function type lists.
#[test]
fn a_law_calling_a_function_value_with_the_effect_clock_is_refused() {
    let rule = (
        "app/Shop/Rule.sharp",
        "namespace App.Shop;\n\npublic class Rule\n{\n    law positive(Function<int() uses Clock> clock) => clock() > 0;\n}\n",
    );

    assert_eq!(
        effect_issues(&[rule]),
        [
            "app/Shop/Rule.sharp:5:55 impure-law: Law `positive` calls `clock`, which has the effect `Clock`. Laws hold only over pure code."
        ]
    );
}

/// Spec section 29 holds every implementation to what its declaration allows, so a lambda stored where a pure function
/// type is declared may have no effect. The solve knows a lambda's effects only after every file is analyzed, so the
/// refusal names the call that has the effect.
#[test]
fn a_lambda_with_an_effect_stored_in_a_pure_function_type_is_refused() {
    let pricing = (
        "app/Shop/Pricing.sharp",
        "namespace App.Shop;\n\nimport Acme.Remote;\n\npublic class Pricing\n{\n    private Function<int(int)> rate;\n\n    public Pricing()\n    {\n        this.rate = n => Remote.fetch(n);\n    }\n\n    public int price() => this.rate(2);\n}\n",
    );

    assert_eq!(issues(pricing, &[FETCH, FETCH_STUB]), Vec::<String>::new());
    assert_eq!(
        effect_issues(&[pricing, FETCH, FETCH_STUB]),
        [
            "app/Shop/Pricing.sharp:11:21 invalid-property-assignment-value: This lambda calls `Remote.fetch`, which has the effect `Http`, so a pure `Function<int(int)>` cannot hold it."
        ]
    );
}

/// A lambda returned where a pure function type is declared, or held in a typed local of one, is refused as a stored
/// one is, with the code a value of the wrong type gets there.
#[test]
fn a_lambda_with_an_effect_returned_or_held_in_a_local_of_a_pure_function_type_is_refused() {
    let pricing = (
        "app/Shop/Pricing.sharp",
        "namespace App.Shop;\n\nimport Acme.Remote;\n\npublic class Pricing\n{\n    public Function<int(int)> rate() => n => Remote.fetch(n);\n\n    public int price()\n    {\n        Function<int(int)> live = n => Remote.fetch(n) + 1;\n        return live(2);\n    }\n}\n",
    );

    assert_eq!(issues(pricing, &[FETCH, FETCH_STUB]), Vec::<String>::new());
    assert_eq!(
        effect_issues(&[pricing, FETCH, FETCH_STUB]),
        [
            "app/Shop/Pricing.sharp:7:41 invalid-return-statement: This lambda calls `Remote.fetch`, which has the effect `Http`, so a pure `Function<int(int)>` cannot hold it.",
            "app/Shop/Pricing.sharp:11:35 invalid-local-assignment-value: This lambda calls `Remote.fetch`, which has the effect `Http`, so a pure `Function<int(int)>` cannot hold it.",
        ]
    );
}

#[test]
fn a_lambda_with_an_effect_stored_in_a_function_type_that_lists_it_passes() {
    let pricing = (
        "app/Shop/Pricing.sharp",
        "namespace App.Shop;\n\nimport Acme.Remote;\n\npublic class Pricing\n{\n    private Function<int(int) uses Http> rate;\n\n    public Pricing()\n    {\n        this.rate = n => Remote.fetch(n);\n    }\n\n    public int price() => this.rate(2);\n}\n",
    );

    assert_eq!(issues(pricing, &[FETCH, FETCH_STUB]), Vec::<String>::new());
    assert_eq!(effect_issues(&[pricing, FETCH, FETCH_STUB]), Vec::<String>::new());
}

/// A method value runs the method's body, so a function type holds it only when it lists the method's effects.
#[test]
fn a_method_value_with_an_effect_passed_where_a_pure_function_type_is_declared_is_refused() {
    let pricing = (
        "app/Shop/Pricing.sharp",
        "namespace App.Shop;\n\nimport Acme.Remote;\n\npublic class Pricing\n{\n    public static int apply(Function<int(int) uses Mail> step) => step(1);\n\n    public int live(int n) => Remote.fetch(n);\n\n    public int fixed(int n) => n;\n\n    public int run() => Pricing.apply(this.live) + Pricing.apply(this.fixed);\n}\n",
    );
    let php = (
        "app/Shop/Pricing.php",
        "<?php\n\nnamespace App\\Shop;\n\nuse function Acme\\Remote\\fetch;\n\nclass Pricing\n{\n    /** @param \\Closure(int): int $step */\n    public static function apply(\\Closure $step): int { return $step(1); }\n\n    public function live(int $n): int { return fetch($n); }\n\n    public function fixed(int $n): int { return $n; }\n\n    public function run(): int { return self::apply($this->live(...)) + self::apply($this->fixed(...)); }\n}\n",
    );

    assert_eq!(issues(php, &[FETCH]), Vec::<String>::new());
    assert_eq!(issues(pricing, &[FETCH, FETCH_STUB]), Vec::<String>::new());
    assert_eq!(
        effect_issues(&[pricing, FETCH, FETCH_STUB]),
        [
            "app/Shop/Pricing.sharp:13:39 invalid-argument: `Pricing.live` calls `Remote.fetch`, which has the effect `Http`, so a `Function<int(int) uses Mail>` cannot hold it."
        ]
    );
}

/// A method value of a method without a body has the effects its `uses` lists, as a call of it does, so a function
/// type holds it only when it lists them.
#[test]
fn a_method_value_of_a_method_without_a_body_is_held_to_its_uses() {
    let rates = (
        "app/Shop/Rates.sharp",
        "namespace App.Shop;\n\npublic interface Rates\n{\n    int rate(int id) uses Http;\n\n    int fixed(int id);\n}\n",
    );
    let pricing = (
        "app/Shop/Pricing.sharp",
        "namespace App.Shop;\n\npublic class Pricing\n{\n    public Pricing(private Rates rates) { }\n\n    public static int apply(Function<int(int) uses Mail> step) => step(1);\n\n    public int run() => Pricing.apply(this.rates.rate) + Pricing.apply(this.rates.fixed);\n}\n",
    );

    assert_eq!(issues(pricing, &[rates]), Vec::<String>::new());
    assert_eq!(
        effect_issues(&[pricing, rates]),
        [
            "app/Shop/Pricing.sharp:9:39 invalid-argument: `Rates.rate` has the effect `Http`, so a `Function<int(int) uses Mail>` cannot hold it."
        ]
    );
}

/// A method value of a standard library method the prelude declares, as `List.wrap`, has no effect, so a pure function
/// type holds it.
#[test]
fn a_method_value_of_a_prelude_method_is_pure() {
    let shelf = (
        "app/Shop/Shelf.sharp",
        "namespace App.Shop;\n\npublic class Shelf\n{\n    public static List<Any?> make(Function<List<Any?>(Any?)> wrap) => wrap(1);\n\n    public List<Any?> run() => Shelf.make(List.wrap);\n}\n",
    );

    assert_eq!(issues(shelf, &[]), Vec::<String>::new());
    assert_eq!(effect_issues(&[shelf]), Vec::<String>::new());
}

/// A static method value has its method's effects wherever it runs, as a method value read from an object has: passed
/// to a function parameter, as `Scope.run(Job.ping)`, or to plain PHP, as `Relay.run(Job.ping)`. So a pure interface
/// method refuses an implementation that runs one.
#[test]
fn a_static_method_value_has_its_method_s_effects_where_it_runs() {
    let pinged = ("app/Shop/Pinged.sharp", "namespace App.Shop;\n\npublic event Pinged(int number);\n");
    let runner = ("app/Shop/Runner.sharp", "namespace App.Shop;\n\npublic interface Runner\n{\n    string go();\n}\n");
    for go in ["Scope.run(Job.ping)", "Relay.run(Job.ping)"] {
        let code = format!(
            "namespace App.Shop;\n\nimport Acme.Relay;\nimport Sharp.Scope;\n\npublic class Job : Runner\n{{\n    public static string ping()\n    {{\n        emit new Pinged(1);\n        return \"pinged\";\n    }}\n\n    public string go() => {go};\n}}\n"
        );
        let job = ("app/Shop/Job.sharp", Box::leak(code.into_boxed_str()) as &'static str);

        assert_eq!(issues(job, &[pinged, runner, RELAY_STUB, RELAY, SCOPE]), Vec::<String>::new(), "{go}");
        assert_eq!(
            effect_issues(&[job, pinged, runner, RELAY_STUB, RELAY, SCOPE]),
            [
                "app/Shop/Job.sharp:14:37 incompatible-effects: `Job.go` reaches `Job.ping`, which emits `Pinged` with the effect `Events`, so the pure `Runner.go` cannot accept it."
            ],
            "{go}"
        );
    }
}

/// A method value of a `foreign` class has that class's effect wherever it runs, as a call of the method has, so a law
/// that runs `environment.require` through a function parameter is impure.
#[test]
fn a_method_value_of_a_foreign_class_has_its_effect_where_it_runs() {
    let shelf = (
        "app/Shop/Shelf.sharp",
        "namespace App.Shop;\n\nimport Sharp.System.Environment;\n\npublic class Shelf\n{\n    public Shelf(private Environment environment) { }\n\n    public static string carried(Function<string(string)> body) => body(\"HOME\");\n\n    public string home => Shelf.carried(this.environment.require);\n\n    law reads(Shelf shelf) => shelf.home != \"\";\n}\n",
    );

    assert_eq!(issues(shelf, &[]), Vec::<String>::new());
    assert_eq!(
        effect_issues(&[shelf]),
        [
            "app/Shop/Shelf.sharp:13:31 impure-law: Law `reads` reaches `Shelf.home`, which calls `Environment.require` with the effect `Environment`. Laws hold only over pure code.",
        ]
    );
}

/// A conditional may give either branch, so each lambda in it is held to the place's function type, whichever branch
/// holds it and whatever the other branch holds.
#[test]
fn a_lambda_with_an_effect_in_either_branch_of_a_conditional_is_refused() {
    let branch = (
        "app/Shop/Branch.sharp",
        "namespace App.Shop;\n\nimport Acme.Remote;\n\npublic class Branch\n{\n    private Function<int(int)> rate;\n\n    public Branch(bool live)\n    {\n        this.rate = live ? (int n) => Remote.fetch(n) : (int n) => n + 1;\n        this.rate = live ? (int n) => n + 2 : (int n) => Remote.fetch(n) + 3;\n        this.rate = live ? (int n) => Remote.fetch(n) + 4 : this.fixed;\n        this.rate = live ? this.fixed : (int n) => Remote.fetch(n) + 5;\n        this.rate = live ? (int n) => Remote.fetch(n) + 6 : (int n) => Remote.fetch(n) + 7;\n    }\n\n    public int fixed(int n) => n;\n\n    public int price() => this.rate(2);\n}\n",
    );

    assert_eq!(issues(branch, &[FETCH, FETCH_STUB]), Vec::<String>::new());
    let message = "invalid-property-assignment-value: This lambda calls `Remote.fetch`, which has the effect `Http`, so a pure `Function<int(int)>` cannot hold it.";
    assert_eq!(
        effect_issues(&[branch, FETCH, FETCH_STUB]),
        [
            format!("app/Shop/Branch.sharp:11:21 {message}"),
            format!("app/Shop/Branch.sharp:12:21 {message}"),
            format!("app/Shop/Branch.sharp:13:21 {message}"),
            format!("app/Shop/Branch.sharp:14:21 {message}"),
            format!("app/Shop/Branch.sharp:15:21 {message}"),
        ]
    );
}

/// Spec section 29: a file that imports a plain PHP class named like a standard effect, as Laravel's `Http` facade,
/// still writes the effect in `uses`, and a function type that lists it holds a lambda calling a class an `extern`
/// gives that effect, the facade too, and refuses one calling a class with no `extern`.
#[test]
fn a_uses_in_a_file_that_imports_a_class_named_like_the_effect_lists_the_effect() {
    for name in sharp_effect_names() {
        let checkout = (
            "app/Shop/Checkout.sharp",
            leak(format!(
                "namespace App.Shop;\n\nimport Lib.Client;\nimport Lib.{name};\nimport Lib.Store;\n\npublic class Checkout\n{{\n    private Function<int(int) uses {name}> step;\n\n    public Checkout(private Client client)\n    {{\n        this.step = n => this.client.get(n);\n        this.step = n => {name}.post(n);\n        this.step = n => Store.get(n);\n    }}\n\n    public int size => this.client.get(1);\n\n    public static int apply(Function<int(int)> step) => step(1);\n\n    public int run() => this.step(1) + Checkout.apply(this.client.get);\n\n    law positive(Client client) => client.get(1) > 0;\n}}\n"
            )),
        );
        let services = (
            "src/Lib/Services.php",
            "<?php\n\nnamespace Lib;\n\nfinal class Client\n{\n    public function get(int $id): int\n    {\n        return $id;\n    }\n}\n\nfinal class Store\n{\n    public static function get(int $id): int\n    {\n        return $id;\n    }\n}\n",
        );
        let facade = (
            leak(format!("src/Lib/{name}.php")),
            leak(format!(
                "<?php\n\nnamespace Lib;\n\nfinal class {name}\n{{\n    public static function post(int $id): int\n    {{\n        return $id;\n    }}\n}}\n"
            )),
        );
        let client_stub = (
            "app/Stubs/Client.sharp",
            leak(format!("namespace App.Stubs;\n\nimport Lib.Client;\n\nextern Client uses {name};\n")),
        );
        let facade_stub = (
            "app/Stubs/Facade.sharp",
            leak(format!("namespace App.Stubs;\n\nimport Lib.{name};\n\nextern {name} uses {name};\n")),
        );
        let files = [checkout, services, facade, client_stub, facade_stub];

        assert_eq!(issues(checkout, &files[1..]), Vec::<String>::new(), "{name}");
        assert_eq!(
            effect_issues(&files),
            [
                format!(
                    "app/Shop/Checkout.sharp:24:36 impure-law: Law `positive` calls `Client.get`, which has the effect `{name}`. Laws hold only over pure code."
                ),
                format!(
                    "app/Shop/Checkout.sharp:15:21 invalid-property-assignment-value: This lambda calls `Store.get`, which has no `extern` declaration, so a `Function<int(int) uses {name}>` cannot hold it. Help: Declare its effect in a .sharp file, such as `extern Store uses {name};`."
                ),
            ],
            "{name}"
        );
    }
}

/// `Client` is plain PHP that its `extern` gives the effect `Http`, `Cache` is plain PHP its `extern` declares pure, and
/// `Store` is plain PHP with no `extern`.
const SERVICES: (&str, &str) = (
    "src/Lib/Services.php",
    "<?php\n\nnamespace Lib;\n\nfinal class Client\n{\n    public function get(int $id): int\n    {\n        return $id;\n    }\n}\n\nfinal class Cache\n{\n    public function get(int $id): int\n    {\n        return $id;\n    }\n}\n\nfinal class Store\n{\n    public function get(int $id): int\n    {\n        return $id;\n    }\n}\n",
);

const SERVICES_STUB: (&str, &str) = (
    "app/Stubs/Services.sharp",
    "namespace App.Stubs;\n\nimport Lib.Cache;\nimport Lib.Client;\n\nextern Client uses Http;\nextern Cache;\n",
);

/// A plain PHP method value runs the method, so a function type holds it only when it lists every effect the method's
/// `extern` declares, as a call of the method has them. A method with no `extern` has an unknown effect, and a method
/// of the `foreign` class `Sharp\System\Environment` has the effect `Environment`.
#[test]
fn a_plain_php_method_value_is_held_to_the_effects_its_extern_declares() {
    let pricing = (
        "app/Shop/Pricing.sharp",
        "namespace App.Shop;\n\nimport Lib.Cache;\nimport Lib.Client;\nimport Lib.Store;\nimport Sharp.System.Environment;\n\npublic class Pricing\n{\n    public Pricing(private Client client, private Cache cache, private Store store, private Environment environment) { }\n\n    public static int apply(Function<int(int) uses Mail> step) => step(1);\n\n    public static string? read(Function<string?(string) uses Mail> lookup) => lookup(\"HOME\");\n\n    public int run() => Pricing.apply(this.client.get) + Pricing.apply(this.cache.get) + Pricing.apply(this.store.get);\n\n    public string? home() => Pricing.read(this.environment.variable);\n}\n",
    );

    assert_eq!(issues(pricing, &[SERVICES, SERVICES_STUB]), Vec::<String>::new());
    assert_eq!(
        effect_issues(&[pricing, SERVICES, SERVICES_STUB]),
        [
            "app/Shop/Pricing.sharp:16:39 invalid-argument: `Client.get` has the effect `Http`, so a `Function<int(int) uses Mail>` cannot hold it.",
            "app/Shop/Pricing.sharp:16:104 invalid-argument: `Store.get` has no `extern` declaration, so a `Function<int(int) uses Mail>` cannot hold it. Help: Declare its effect in a .sharp file, such as `extern Store uses Mail;`.",
            "app/Shop/Pricing.sharp:18:43 invalid-argument: `Environment.variable` has the effect `Environment`, so a `Function<string?(string) uses Mail>` cannot hold it.",
        ]
    );
}

/// A method value and a call of the method find the same `extern`: the one on the class it is read through, before its
/// parent's that declares the method, however the value reaches its place. `RemoteFeed`'s `extern` gives `get` the
/// effect `Http` that `Feed`'s does not, and `QuietChild`'s declares the `get` of `Quiet`, which has none, pure.
#[test]
fn a_plain_php_method_value_read_through_a_subclass_is_held_to_the_subclass_extern() {
    let feeds = (
        "src/Lib/Feeds.php",
        "<?php\n\nnamespace Lib;\n\nclass Feed\n{\n    public function get(int $id): int\n    {\n        return $id;\n    }\n}\n\nfinal class RemoteFeed extends Feed\n{\n}\n\nclass Quiet\n{\n    public function get(int $id): int\n    {\n        return $id;\n    }\n}\n\nfinal class QuietChild extends Quiet\n{\n}\n",
    );
    let stub = (
        "app/Stubs/Feeds.sharp",
        "namespace App.Stubs;\n\nimport Lib.Feed;\nimport Lib.QuietChild;\nimport Lib.RemoteFeed;\n\nextern Feed;\nextern RemoteFeed uses Http;\nextern QuietChild;\n",
    );
    let pricing = (
        "app/Shop/Pricing.sharp",
        "namespace App.Shop;\n\nimport Lib.QuietChild;\nimport Lib.RemoteFeed;\n\npublic class Pricing\n{\n    public Pricing(private RemoteFeed feed, private QuietChild quiet) { }\n\n    public static int apply(Function<int(int) uses Mail> step) => step(1);\n\n    public int run() => Pricing.apply(this.feed.get) + Pricing.apply((this.feed.get));\n\n    public int viaLocal()\n    {\n        let step = this.feed.get;\n        return Pricing.apply(step);\n    }\n\n    public int price => this.feed.get(1);\n\n    public int stepped\n    {\n        get\n        {\n            let step = this.feed.get;\n            return step(1);\n        }\n    }\n\n    public int calm() => Pricing.apply(this.quiet.get) + Pricing.apply((this.quiet.get));\n\n    public int calmViaLocal()\n    {\n        let step = this.quiet.get;\n        return Pricing.apply(step);\n    }\n\n    public int quietly\n    {\n        get\n        {\n            let step = this.quiet.get;\n            return step(1);\n        }\n    }\n\n    law priced(Pricing pricing) => pricing.price > 0;\n\n    law stepping(Pricing pricing) => pricing.stepped > 0;\n\n    law quiets(Pricing pricing) => pricing.quietly > 0;\n}\n",
    );

    assert_eq!(issues(pricing, &[feeds, stub]), Vec::<String>::new());
    let message =
        "invalid-argument: `RemoteFeed.get` has the effect `Http`, so a `Function<int(int) uses Mail>` cannot hold it.";
    assert_eq!(
        effect_issues(&[pricing, feeds, stub]),
        [
            "app/Shop/Pricing.sharp:48:36 impure-law: Law `priced` reaches `Pricing.price`, which calls `RemoteFeed.get` with the effect `Http`. Laws hold only over pure code.".to_owned(),
            "app/Shop/Pricing.sharp:50:38 impure-law: Law `stepping` reaches `Pricing.stepped`, which calls `RemoteFeed.get` with the effect `Http`. Laws hold only over pure code.".to_owned(),
            format!("app/Shop/Pricing.sharp:12:39 {message}"),
            format!("app/Shop/Pricing.sharp:12:70 {message}"),
            format!("app/Shop/Pricing.sharp:17:30 {message}"),
        ]
    );
}

/// A method value read through a subclass runs the method its parent declares: a call of it returns the type the
/// method's parameters give and its unused result is reported for a `#[\NoDiscard]` method, a partial application of it
/// has the method's type, and the value of a built-in method takes no argument the method does not list.
#[test]
fn a_method_value_read_through_a_subclass_is_the_method_its_parent_declares() {
    let books = (
        "src/Lib/Books.php",
        "<?php\n\nnamespace Lib;\n\nclass Ledger\n{\n    #[\\NoDiscard]\n    public function total(int $n): int\n    {\n        return $n;\n    }\n\n    /** @return ($n is int ? int : string) */\n    public function pick(int|string $n): int|string\n    {\n        return $n;\n    }\n}\n\nfinal class BranchLedger extends Ledger\n{\n}\n\nfinal class Bag extends \\ArrayObject\n{\n}\n",
    );
    let closing = (
        "app/Shop/Closing.sharp",
        "namespace App.Shop;\n\nimport Lib.Bag;\nimport Lib.BranchLedger;\n\npublic class Closing\n{\n    public Closing(private BranchLedger ledger, private Bag bag) { }\n\n    public static int apply(Function<int(int)> step) => step(1);\n\n    public void close()\n    {\n        (this.ledger.total)(1);\n    }\n\n    public int count() => Closing.apply(this.bag.count);\n\n    public int picked() => (this.ledger.pick)(1);\n\n    public Function<int(int)> partial() => (this.ledger.total)(?);\n}\n",
    );
    let php = (
        "app/Shop/Closing.php",
        "<?php\n\nnamespace App\\Shop;\n\nuse Lib\\Bag;\nuse Lib\\BranchLedger;\n\nclass Closing\n{\n    public function __construct(private BranchLedger $ledger, private Bag $bag) {}\n\n    /** @param \\Closure(int): int $step */\n    public static function apply(\\Closure $step): int { return $step(1); }\n\n    public function close(): void\n    {\n        ($this->ledger->total(...))(1);\n    }\n\n    public function count(): int { return self::apply($this->bag->count(...)); }\n\n    public function picked(): int { return ($this->ledger->pick(...))(1); }\n\n    /** @return \\Closure(int): int */\n    public function partial(): \\Closure { return ($this->ledger->total(...))(?); }\n}\n",
    );

    assert_eq!(issues(php, &[books]), ["17:9 unused-method-call", "20:55 invalid-argument"]);
    assert_eq!(issues(closing, &[books]), ["14:9 unused-method-call", "17:41 invalid-argument"]);
}

/// PHP's `Child::method(...)` names the class it is written with, which may inherit the method, so its closure is the
/// method its parent declares: an unused result of a `#[\NoDiscard]` method is reported, a built-in method takes no
/// argument it does not list, and a call returns the type the method's parameters give.
#[test]
fn a_php_static_method_closure_through_a_subclass_is_the_method_its_parent_declares() {
    let probe = (
        "src/App/Probe.php",
        "<?php\n\nnamespace App;\n\nclass Ledger\n{\n    #[\\NoDiscard]\n    public static function total(int $n): int { return $n; }\n\n    /** @return ($n is int ? int : string) */\n    public static function pick(int|string $n): int|string { return $n; }\n}\n\nfinal class BranchLedger extends Ledger\n{\n}\n\nfinal class MyDate extends \\DateTime\n{\n}\n\nfinal class Probe\n{\n    /** @param \\Closure(int): mixed $step */\n    public static function apply(\\Closure $step): mixed { return $step(1); }\n\n    public function close(): void\n    {\n        (BranchLedger::total(...))(1);\n    }\n\n    public function picked(): int\n    {\n        return (BranchLedger::pick(...))(1);\n    }\n\n    public function errors(): mixed\n    {\n        return self::apply(MyDate::getLastErrors(...));\n    }\n}\n",
    );

    assert_eq!(issues(probe, &[]), ["29:9 unused-method-call", "39:28 invalid-argument"]);
}

/// An initial value that is not constant runs in the constructor, so a lambda in it is held to the property's function
/// type, even in a class with no method.
#[test]
fn a_lambda_with_an_effect_as_the_initial_value_of_a_pure_function_type_is_refused() {
    let pricing = (
        "app/Shop/Pricing.sharp",
        "namespace App.Shop;\n\nimport Acme.Remote;\n\npublic class Pricing\n{\n    private Function<int(int)> rate = (int n) => Remote.fetch(n);\n}\n",
    );
    let listed = (
        "app/Shop/Pricing.sharp",
        "namespace App.Shop;\n\nimport Acme.Remote;\n\npublic class Pricing\n{\n    private Function<int(int) uses Http> rate = (int n) => Remote.fetch(n);\n}\n",
    );

    assert_eq!(
        effect_issues(&[pricing, FETCH, FETCH_STUB]),
        [
            "app/Shop/Pricing.sharp:7:39 invalid-property-default-value: This lambda calls `Remote.fetch`, which has the effect `Http`, so a pure `Function<int(int)>` cannot hold it."
        ]
    );
    assert_eq!(effect_issues(&[listed, FETCH, FETCH_STUB]), Vec::<String>::new());
}

/// A lambda of the wrong type is refused once, for its type: whether its effects fit a type it does not have is moot.
#[test]
fn a_lambda_argument_of_the_wrong_type_is_refused_once() {
    let twice = (
        "app/Shop/Twice.sharp",
        "namespace App.Shop;\n\nimport Acme.Remote;\n\npublic class Twice\n{\n    public static int apply(Function<int(int)> step) => step(1);\n\n    public int run() => Twice.apply((string s) => Remote.fetch(1));\n}\n",
    );
    let php = (
        "app/Shop/Twice.php",
        "<?php\n\nnamespace App\\Shop;\n\nuse function Acme\\Remote\\fetch;\n\nclass Twice\n{\n    /** @param \\Closure(int): int $step */\n    public static function apply(\\Closure $step): int { return $step(1); }\n\n    public function run(): int { return self::apply(fn (string $s): int => fetch(1)); }\n}\n",
    );

    assert_eq!(issues(php, &[FETCH]), ["12:53 invalid-argument"]);
    assert_eq!(issues(twice, &[FETCH, FETCH_STUB]), ["9:37 invalid-argument"]);
    assert_eq!(effect_issues(&[twice, FETCH, FETCH_STUB]), Vec::<String>::new());
}

const HOLDER: (&str, &str) = (
    "src/Lib/Holder.php",
    "<?php\n\nnamespace Lib;\n\nfinal class Formatter\n{\n    public function __invoke(int $amount): int\n    {\n        return $amount;\n    }\n}\n\nfinal class Holder\n{\n    /** @var \\Closure(int): int */\n    public \\Closure $closure;\n\n    /** @var callable(int): int */\n    public $callback;\n\n    public Formatter $format;\n}\n",
);

/// A plain PHP property holding a closure or a callable declares no effect, and an `extern` on its class declares the
/// class's own members, not the code the property holds, so calling it always has an unknown effect. An object with
/// `__invoke` has the effects of its `__invoke`. A law reading a getter that makes such a call has them too.
#[test]
fn a_call_of_a_plain_php_property_holding_a_function_has_an_unknown_effect() {
    let holder = HOLDER;
    let till = (
        "app/Shop/Till.sharp",
        "namespace App.Shop;\n\nimport Lib.Holder;\n\npublic class Till\n{\n    public Till(private Holder holder) { }\n\n    public int closed => this.holder.closure(2);\n\n    public int called => this.holder.callback(2);\n\n    public int formatted => this.holder.format(2);\n\n    law closes(Till till) => till.closed > 0;\n\n    law calls(Till till) => till.called > 0;\n\n    law formats(Till till) => till.formatted > 0;\n}\n",
    );
    let class_extern = ("app/Stubs/Holder.sharp", "namespace App.Stubs;\n\nimport Lib.Holder;\n\nextern Holder;\n");
    let refused = [
        "app/Shop/Till.sharp:15:30 impure-law: Law `closes` reaches `Till.closed`, which calls `Holder.closure` with no `extern` declaration. Laws hold only over pure code. Help: Property `Holder.closure` holds plain PHP code, which no `extern` can declare. Call it outside the law, or through a method of `Holder` that an `extern` declares.",
        "app/Shop/Till.sharp:17:29 impure-law: Law `calls` reaches `Till.called`, which calls `Holder.callback` with no `extern` declaration. Laws hold only over pure code. Help: Property `Holder.callback` holds plain PHP code, which no `extern` can declare. Call it outside the law, or through a method of `Holder` that an `extern` declares.",
        "app/Shop/Till.sharp:19:31 impure-law: Law `formats` reaches `Till.formatted`, which calls `Formatter.__invoke` with no `extern` declaration. Laws hold only over pure code. Help: Declare it in a .sharp file: `extern Formatter;` when it has no effect, or name its effects after `uses`. Add `import Lib.Formatter;` to the file.",
    ];

    assert_eq!(effect_issues(&[till, holder]), refused);
    assert_eq!(effect_issues(&[till, holder, class_extern]), refused);
}

/// A law calling a plain PHP property that holds a closure is refused as a getter is, and its help names the law.
#[test]
fn a_law_calling_a_plain_php_property_holding_a_closure_has_an_unknown_effect() {
    let rule = (
        "app/Shop/Rule.sharp",
        "namespace App.Shop;\n\nimport Lib.Holder;\n\npublic class Rule\n{\n    law positive(Holder holder) => holder.closure(2) > 0;\n}\n",
    );

    assert_eq!(
        effect_issues(&[rule, HOLDER]),
        [
            "app/Shop/Rule.sharp:7:36 impure-law: Law `positive` calls `Holder.closure`, which has no `extern` declaration. Laws hold only over pure code. Help: Property `Holder.closure` holds plain PHP code, which no `extern` can declare. Call it outside the law, or through a method of `Holder` that an `extern` declares."
        ]
    );
}

/// Spec section 6: a getter may run anything, as a method does, so one reaching a method in another file that calls an
/// `extern` with the effect `Clock` compiles. A read of it carries `Clock`, so a law reading it, which must be pure, is
/// refused naming the call.
#[test]
fn a_getter_with_an_effect_compiles_and_a_law_reading_it_is_refused() {
    let order = (
        "app/Shop/Order.sharp",
        "namespace App.Shop;\n\nimport Acme.Chrono;\n\npublic class Order\n{\n    public int price() => Chrono.now();\n}\n",
    );
    let cart = (
        "app/Shop/Cart.sharp",
        "namespace App.Shop;\n\npublic class Cart\n{\n    public Cart(private Order order) { }\n\n    public int total => this.order.price();\n}\n",
    );
    let checked = (
        "app/Shop/Cart.sharp",
        "namespace App.Shop;\n\npublic class Cart\n{\n    public Cart(private Order order) { }\n\n    public int total => this.order.price();\n\n    law totaled(Cart cart) => cart.total > 0;\n}\n",
    );

    assert_eq!(effect_issues(&[cart, order, CLOCK_STUB, NOW]), Vec::<String>::new());
    assert_eq!(
        effect_issues(&[checked, order, CLOCK_STUB, NOW]),
        [
            "app/Shop/Cart.sharp:9:31 impure-law: Law `totaled` reaches `Order.price`, which calls `Chrono.now` with the effect `Clock`. Laws hold only over pure code."
        ]
    );
}

/// Spec section 6.2: an observer runs inside the `set` hook on each write once the object is built, so a write after
/// the constructor returns carries its effects, and a law that writes the property is refused naming the observer's
/// call. A constructor's write and a named constructor's run no observer, so a law that only builds the object is pure.
#[test]
fn a_write_of_a_property_carries_its_observers_effects_once_the_object_is_built() {
    let quiet = (
        "app/Shop/Tag.sharp",
        "namespace App.Shop;\n\npublic class Tag\n{\n    public string name { get; set; didSet => this.name.length; } = \"\";\n\n    public Tag()\n    {\n        this.name = \"new\";\n    }\n\n    public static Tag renamed()\n    {\n        const tag = new Tag();\n        tag.name = \"old\";\n        return tag;\n    }\n}\n",
    );
    let timed = (
        "app/Shop/Tag.sharp",
        "namespace App.Shop;\n\nimport Acme.Chrono;\n\npublic class Tag\n{\n    public string name { get; set; didSet => Chrono.now(); } = \"\";\n\n    public Tag()\n    {\n        this.name = \"new\";\n    }\n\n    public Tag.titled(string title) : this()\n    {\n        this.name = title;\n    }\n\n    public static Tag renamed()\n    {\n        const tag = new Tag();\n        tag.name = \"old\";\n        return tag;\n    }\n}\n",
    );
    let quiet_laws = (
        "app/Shop/Labels.sharp",
        "namespace App.Shop;\n\npublic class Labels\n{\n    law built(int size) => new Tag().name.length > size;\n\n    law renamed(int size) => Tag.renamed().name.length > size;\n}\n",
    );
    let timed_laws = (
        "app/Shop/Labels.sharp",
        "namespace App.Shop;\n\npublic class Labels\n{\n    law built(int size) => new Tag().name.length > size;\n\n    law titled(int size) => Tag.titled(\"a\").name.length > size;\n\n    law renamed(int size) => Tag.renamed().name.length > size;\n}\n",
    );

    assert_eq!(effect_issues(&[quiet, quiet_laws, CLOCK_STUB, NOW]), Vec::<String>::new());
    assert_eq!(
        effect_issues(&[timed, timed_laws, CLOCK_STUB, NOW]),
        [
            "app/Shop/Labels.sharp:9:30 impure-law: Law `renamed` reaches `Tag.name`, which calls `Chrono.now` with the effect `Clock`. Laws hold only over pure code."
        ]
    );
}

/// Decision 3: a static property's accessors run on its reads and writes as an instance property's do, so a law
/// reading a static computed property reaches its body's effect. A write of a static changes shared state first.
#[test]
fn a_static_property_s_reads_and_writes_carry_its_accessors_effects() {
    let stamp = (
        "app/Shop/Stamp.sharp",
        "namespace App.Shop;\n\nimport Acme.Chrono;\n\npublic class Stamp\n{\n    public static int now => Chrono.now();\n    public static int last { get; set { field = value + Chrono.now(); } } = 0;\n\n    law read(int size) => Stamp.now > size;\n\n    law written(int size) => Stamp.mark(size) > 0;\n\n    public static int mark(int size)\n    {\n        Stamp.last = size;\n        return size;\n    }\n}\n",
    );

    assert_eq!(
        effect_issues(&[stamp, CLOCK_STUB, NOW]),
        [
            "app/Shop/Stamp.sharp:10:27 impure-law: Law `read` reaches `Stamp.now`, which calls `Chrono.now` with the effect `Clock`. Laws hold only over pure code.",
            "app/Shop/Stamp.sharp:12:30 impure-law: Law `written` reaches `Stamp.mark`, which changes `Stamp.last`. Laws hold only over code that changes nothing.",
        ]
    );
}

/// Spec section 6: a static's initial value that is not constant runs once, when the app first uses its class's
/// statics, so a use of any static of the class has the effects of those initial values. A class whose statics all
/// start constant gives a use none.
#[test]
fn a_use_of_a_class_s_statics_has_the_effects_of_their_initial_values() {
    let started = (
        "app/Shop/Started.sharp",
        "namespace App.Shop;\n\nimport Acme.Chrono;\n\npublic class Started\n{\n    public static int at { get; } = Chrono.now();\n\n    public static int size { get; } = 3;\n\n    public static int doubled() => size * 2;\n}\n",
    );
    let fixed = (
        "app/Shop/Fixed.sharp",
        "namespace App.Shop;\n\npublic class Fixed\n{\n    public static int size { get; } = 3;\n}\n",
    );
    let reader = (
        "app/Shop/Reader.sharp",
        "namespace App.Shop;\n\npublic class Reader\n{\n    law read(int size) => Started.at > size;\n\n    law other(int size) => Started.size > size;\n\n    law constant(int size) => Fixed.size > size;\n\n    law inside(int size) => Started.doubled() > size;\n}\n",
    );

    assert_eq!(issues(reader, &[started, fixed, CLOCK_STUB, NOW]), Vec::<String>::new());
    assert_eq!(
        effect_issues(&[reader, started, fixed, CLOCK_STUB, NOW]),
        [
            "app/Shop/Reader.sharp:5:27 impure-law: Law `read` reaches `Started.at`, which calls `Chrono.now` with the effect `Clock`. Laws hold only over pure code.",
            "app/Shop/Reader.sharp:7:28 impure-law: Law `other` reaches `Started.at`, which calls `Chrono.now` with the effect `Clock`. Laws hold only over pure code.",
            "app/Shop/Reader.sharp:11:29 impure-law: Law `inside` reaches `Started.at`, which calls `Chrono.now` with the effect `Clock`. Laws hold only over pure code.",
        ]
    );
}

const BEHAVIOR_LIBRARY: (&str, &str) = (
    "vendor/heyjordanparker/php-sharp-composer/library/Sharp/Behavior.sharp",
    "namespace Sharp;\n\npublic interface Behavior<T>\n{\n    T get(T value);\n\n    T set(T value);\n}\n",
);

/// Spec section 6.4: a behavior's `get` and `set` are the property's accessors. Each may have any effect, and `set`
/// writes the behavior's own fields, so `Stamped` compiles. A read of the property carries what `get` does, so a method
/// that must be pure and reads it is refused naming the effect, and a `get` that writes the behavior's own fields is
/// refused as any getter writing `this` is.
#[test]
fn a_behavior_s_accessors_may_have_any_effect_and_the_property_s_reads_carry_it() {
    let stamped = (
        "app/Shop/Stamped.sharp",
        "namespace App.Shop;\n\nimport Acme.Chrono;\nimport Sharp.Behavior;\n\npublic class Stamped : Behavior<int>\n{\n    private int writes = 0;\n\n    public int get(int value) => value + Chrono.now();\n\n    public int set(int value)\n    {\n        this.writes = this.writes + 1;\n        return value;\n    }\n}\n",
    );
    let tag = (
        "app/Shop/Tag.sharp",
        "namespace App.Shop;\n\npublic class Tag\n{\n    public int stamp { get; set; } via Stamped = 0;\n}\n",
    );
    let sizes = (
        "app/Shop/Sizes.sharp",
        "namespace App.Shop;\n\npublic interface Sizes\n{\n    int size(Tag tag);\n}\n\npublic class TagSizes : Sizes\n{\n    public int size(Tag tag) => tag.stamp;\n}\n",
    );
    let counted = (
        "app/Shop/Counted.sharp",
        "namespace App.Shop;\n\nimport Sharp.Behavior;\n\npublic class Counted : Behavior<int>\n{\n    private int reads = 0;\n\n    public int get(int value)\n    {\n        this.reads = this.reads + 1;\n        return value;\n    }\n\n    public int set(int value) => value;\n}\n",
    );
    let note = (
        "app/Shop/Note.sharp",
        "namespace App.Shop;\n\npublic class Note\n{\n    public int views { get; set; } via Counted = 0;\n}\n",
    );

    assert_eq!(issues(tag, &[BEHAVIOR_LIBRARY, stamped, CLOCK_STUB, NOW]), Vec::<String>::new());
    assert_eq!(effect_issues(&[tag, BEHAVIOR_LIBRARY, stamped, CLOCK_STUB, NOW]), Vec::<String>::new());
    assert_eq!(
        effect_issues(&[sizes, tag, BEHAVIOR_LIBRARY, stamped, CLOCK_STUB, NOW]),
        [
            "app/Shop/Sizes.sharp:10:33 incompatible-effects: `TagSizes.size` reaches `Stamped.get`, which calls `Chrono.now` with the effect `Clock`, so the pure `Sizes.size` cannot accept it."
        ]
    );
    assert_eq!(
        effect_issues(&[note, BEHAVIOR_LIBRARY, counted]),
        [
            "app/Shop/Note.sharp:5:40 getter-writes-this: Getter `views` reaches `Counted.get`, which changes `this.reads`. A getter never writes `this`. Help: Write the change in a method, and call it before the read."
        ]
    );
}

/// Spec sections 6.4 and 11: `via` names a type, so a generic behavior takes its type arguments as any written type
/// does. `Logged<string>` is a `Behavior<string>`, and `Logged<int>` on a `string` property names both types.
#[test]
fn a_generic_behavior_takes_its_type_arguments() {
    let logged = (
        "src/Demo/Logged.sharp",
        "namespace Demo;\n\nimport Sharp.Behavior;\n\npublic class Logged<T> : Behavior<T>\n{\n    public T get(T value) => value;\n\n    public T set(T value) => value;\n}\n",
    );
    let order = "namespace Demo;\n\npublic class Order\n{\n    public string name { get; set; } via Logged<string> = \"\";\n    public string code { get; set; } via Logged<int> = \"\";\n}\n";
    let note = "A behavior runs the property's `get` and `set`: it is a class that implements `Behavior` for the property's type, and PHP# creates one for each object with no arguments.";

    assert_eq!(
        worded(("src/Demo/Order.sharp", order), &[BEHAVIOR_LIBRARY, logged]),
        [format!(
            "6:42 invalid-property-behavior `Logged<int>` is a `Behavior<int>`, and `code` is a `string`. | Named here. | {note} | Name a behavior that implements `Behavior<string>`, as `code` is a `string`."
        )]
    );
}

/// Spec section 6.4: a behavior is a class that implements `Sharp.Behavior<T>` for the property's type, which PHP#
/// creates for each object with `new` and no arguments. One for another type names both types, a class that is no
/// behavior says so, an interface, an abstract class and a constructor that needs an argument can't be created, and a
/// name that is no class is the error any unknown class is.
#[test]
fn a_behavior_implements_behavior_for_the_property_s_type() {
    let behavior = (
        "vendor/heyjordanparker/php-sharp-composer/library/Sharp/Behavior.sharp",
        "namespace Sharp;\n\npublic interface Behavior<T>\n{\n    T get(T value);\n\n    T set(T value);\n}\n",
    );
    let behaviors = (
        "src/Demo/Behaviors.sharp",
        "namespace Demo;\n\nimport Lib.Words;\nimport Sharp.Behavior;\n\npublic class Trimmed : Behavior<string>\n{\n    public string get(string value) => value;\n\n    public string set(string value) => Words.trim(value);\n}\n\npublic abstract class Base : Behavior<string>\n{\n    public string get(string value) => value;\n\n    public abstract string set(string value);\n}\n\npublic class Logged : Behavior<string>\n{\n    public Logged(private string prefix)\n    {\n    }\n\n    public string get(string value) => value;\n\n    public string set(string value) => this.prefix + value;\n}\n\npublic class Plain\n{\n}\n\npublic class Hidden : Behavior<string>\n{\n    private Hidden()\n    {\n    }\n\n    public string get(string value) => value;\n\n    public string set(string value) => value;\n}\n",
    );
    let order = "namespace Demo;\n\nimport Sharp.Behavior;\n\npublic class Order\n{\n    public string name { get; set; } via Trimmed = \"\";\n    public int count { get; set; } via Trimmed = 0;\n    public string code { get; set; } via Missing = \"\";\n    public string kind { get; set; } via Behavior = \"\";\n    public string base { get; set; } via Base = \"\";\n    public string log { get; set; } via Logged = \"\";\n    public string note { get; set; } via Plain = \"\";\n    public string word { get; set; } via Hidden = \"\";\n}\n";
    let note = "A behavior runs the property's `get` and `set`: it is a class that implements `Behavior` for the property's type, and PHP# creates one for each object with no arguments.";

    assert_eq!(
        worded(("src/Demo/Order.sharp", order), &[behavior, behaviors, WORDS]),
        [
            format!(
                "8:40 invalid-property-behavior `Trimmed` is a `Behavior<string>`, and `count` is an `int`. | Named here. | {note} | Name a behavior that implements `Behavior<int>`, as `count` is an `int`."
            ),
            "9:42 non-existent-class-like Cannot find type `Demo.Missing`. | No type of this name is declared. | Check the name's spelling, and import the type with `import` when another namespace declares it.".to_owned(),
            format!(
                "10:42 invalid-property-behavior `Behavior` can't be created: PHP# creates each behavior with `new` for each object. | Named here. | {note} | Name a class that implements `Behavior` for the property's type, such as one that extends `Behavior`."
            ),
            format!(
                "11:42 invalid-property-behavior `Base` can't be created: PHP# creates each behavior with `new` for each object. | Named here. | {note} | Name a class that implements `Behavior` for the property's type, such as one that extends `Base`."
            ),
            format!(
                "12:41 invalid-property-behavior `Logged` needs `prefix` to be created: PHP# creates each behavior as `new Logged()`. | Named here. | {note} | Give `prefix` a default value, or keep what it holds in the behavior's own fields."
            ),
            format!(
                "13:42 invalid-property-behavior `Plain` is no `Behavior`, so it can't run the `get` and `set` of `note`. | Named here. | {note} | Name a behavior that implements `Behavior<string>`, as `note` is a `string`."
            ),
            format!(
                "14:42 invalid-property-behavior `Order` can't create `Hidden`: its constructor is `private`, and PHP# creates each behavior as `new Hidden()` in `Order`. | Named here. | {note} | Make the constructor of `Hidden` reachable from `Order`, as `public` is."
            ),
        ]
    );

    // A constructor parameter's property is checked as one in the class body, spec section 9, and a later behavior
    // may be generic.
    let shouted = (
        "src/Demo/Shouted.sharp",
        "namespace Demo;\n\nimport Sharp.Behavior;\n\npublic class Shouted<T> : Behavior<string>\n{\n    public string get(string value) => value;\n\n    public string set(string value) => value;\n}\n",
    );
    let promoted = "namespace Demo;\n\nimport Sharp.Behavior;\n\npublic class Order\n{\n    public Order(\n        public string name { get; set; } via Trimmed, Shouted<int> = \"\",\n        public int count { get; set; } via Trimmed = 0,\n        public string code { get; set; } via Missing = \"\",\n        public string kind { get; set; } via Behavior = \"\",\n    ) { }\n}\n";
    assert_eq!(
        worded(("src/Demo/Order.sharp", promoted), &[behavior, behaviors, shouted]),
        [
            format!(
                "9:44 invalid-property-behavior `Trimmed` is a `Behavior<string>`, and `count` is an `int`. | Named here. | {note} | Name a behavior that implements `Behavior<int>`, as `count` is an `int`."
            ),
            "10:46 non-existent-class-like Cannot find type `Demo.Missing`. | No type of this name is declared. | Check the name's spelling, and import the type with `import` when another namespace declares it.".to_owned(),
            format!(
                "11:46 invalid-property-behavior `Behavior` can't be created: PHP# creates each behavior with `new` for each object. | Named here. | {note} | Name a class that implements `Behavior` for the property's type, such as one that extends `Behavior`."
            ),
        ]
    );

    // An untyped property is the parser's error, so its behaviors have no type to be checked against.
    let untyped = "namespace Demo;\n\npublic class Order\n{\n    public name { get; set; } via Trimmed = \"\";\n}\n";
    assert_eq!(issues(("src/Demo/Order.sharp", untyped), &[behavior, behaviors]), ["5:12 parse"]);

    // A behavior that names no class is semantics' error, so the analyzer checks nothing more of it.
    let no_class =
        "namespace Demo;\n\npublic class Order\n{\n    public string name { get; set; } via string = \"\";\n}\n";
    assert_eq!(issues(("src/Demo/Order.sharp", no_class), &[behavior, behaviors]), Vec::<String>::new());
}

/// Spec section 6.2: an observer sees `value`, the written value, and `field`, the stored one, each of
/// the property's type, so passing either where an `int` goes is the error a `set` body's is. `field` in `willSet` is
/// the value the write replaces.
#[test]
fn an_observer_sees_value_and_field_of_the_property_type() {
    let sharp = "namespace Demo;\n\nclass Tag\n{\n    public string name { get; set; willSet => this.size(value); didSet => this.size(field); } = \"\";\n    public string title { get; set; willSet => this.size(field); } = \"\";\n\n    private void size(int count)\n    {\n    }\n}\n";

    assert_eq!(
        issues(("src/Demo/Tag.sharp", sharp), &[]),
        ["5:57 invalid-argument", "5:85 invalid-argument", "6:58 invalid-argument"]
    );
}

/// Spec section 6.5: a `lazy` body may have any effect, so one calling a method with the effect `Database` compiles. A
/// read of it carries `Database`, so a law reading it is refused. The value the property keeps is the language's write,
/// so it is no write of `this`, but a `lazy` body that writes `this` itself is refused as any getter is.
#[test]
fn a_lazy_body_with_an_effect_compiles_and_a_read_of_it_has_the_effect() {
    let rows = (
        "src/Lib/Rows.php",
        "<?php\n\nnamespace Lib;\n\nfinal class Rows\n{\n    public function find(int $id): int\n    {\n        return $id;\n    }\n}\n",
    );
    let stub = ("app/Stubs/Rows.sharp", "namespace App.Stubs;\n\nimport Lib.Rows;\n\nextern Rows uses Database;\n");
    let plan = (
        "app/Shop/Plan.sharp",
        "namespace App.Shop;\n\nimport Lib.Rows;\n\npublic class Plan\n{\n    public Plan(private Rows rows) { }\n\n    public lazy int tier => this.rows.find(1);\n}\n",
    );
    let checked = (
        "app/Shop/Plan.sharp",
        "namespace App.Shop;\n\nimport Lib.Rows;\n\npublic class Plan\n{\n    public Plan(private Rows rows) { }\n\n    public lazy int tier => this.rows.find(1);\n\n    law tiered(Plan plan) => plan.tier > 0;\n}\n",
    );
    let counting = (
        "app/Shop/Plan.sharp",
        "namespace App.Shop;\n\npublic class Plan\n{\n    private int reads = 0;\n\n    public lazy int tier => this.count();\n\n    public int count()\n    {\n        this.reads = this.reads + 1;\n        return this.reads;\n    }\n}\n",
    );

    assert_eq!(issues(plan, &[rows, stub]), Vec::<String>::new());
    assert_eq!(effect_issues(&[plan, rows, stub]), Vec::<String>::new());
    assert_eq!(
        effect_issues(&[checked, rows, stub]),
        [
            "app/Shop/Plan.sharp:11:30 impure-law: Law `tiered` reaches `Plan.tier`, which calls `Rows.find` with the effect `Database`. Laws hold only over pure code."
        ]
    );
    assert_eq!(
        effect_issues(&[counting]),
        [
            "app/Shop/Plan.sharp:7:29 getter-writes-this: Getter `tier` reaches `Plan.count`, which changes `this.reads`. A getter never writes `this`. Help: Write the change in a method, and call it before the read."
        ]
    );
}

/// Spec section 6.1: a `get` body may have any effect but never writes `this`, so a getter that writes a field of
/// `this`, or calls a method of `this` that writes one, is refused naming the write. Unlike a method marked
/// `readonly`, a getter calls a plain PHP method through `this`, as the spec's accessor over Eloquent's
/// `getAttribute` does, because PHP# sees no write in it.
#[test]
fn a_getter_writing_this_or_calling_a_method_that_writes_it_is_refused() {
    let order = (
        "src/Demo/Order.sharp",
        "namespace Demo;\n\nimport Lib.Model;\n\nclass Order : Model\n{\n    public Address? shipping { get => this.getAttribute(\"shipping\") as Address; set => this.setAttribute(\"shipping\", value); }\n}\n\nclass Address\n{\n}\n",
    );
    assert_eq!(effect_issues(&[order, ("src/Lib/Model.php", MODEL)]), Vec::<String>::new());

    let counter = (
        "app/Shop/Counter.sharp",
        "namespace App.Shop;\n\npublic class Counter\n{\n    private int count = 0;\n\n    public int next { get { this.count = this.count + 1; return this.count; } }\n\n    public int bumped => this.bump();\n\n    public int bump()\n    {\n        this.count = this.count + 1;\n        return this.count;\n    }\n}\n",
    );

    assert_eq!(
        effect_issues(&[counter]),
        [
            "app/Shop/Counter.sharp:7:29 getter-writes-this: Getter `next` changes `this.count`. A getter never writes `this`. Help: Write the change in a method, and call it before the read.",
            "app/Shop/Counter.sharp:9:26 getter-writes-this: Getter `bumped` reaches `Counter.bump`, which changes `this.count`. A getter never writes `this`. Help: Write the change in a method, and call it before the read.",
        ]
    );
}

#[test]
fn a_getter_building_and_changing_a_new_object_passes() {
    let builder = (
        "app/Shop/Builder.sharp",
        "namespace App.Shop;\n\npublic class Builder\n{\n    private string text = \"\";\n\n    public void add(string part)\n    {\n        this.text = this.text + part;\n    }\n\n    public string build() => this.text;\n}\n",
    );
    let page = (
        "app/Shop/Page.sharp",
        "namespace App.Shop;\n\npublic class Page\n{\n    public string title\n    {\n        get\n        {\n            let builder = new Builder();\n            builder.add(\"Shop\");\n            return builder.build();\n        }\n    }\n}\n",
    );

    assert_eq!(effect_issues(&[page, builder]), Vec::<String>::new());
    let (codebase, summaries) = summarized(&[page, builder]);
    let add = FunctionLikeIdentifier::Method(ascii_lowercase_word(b"App\\Shop\\Builder"), ascii_lowercase_word(b"add"));
    assert_eq!(
        Effects::solve(&codebase, &summaries).impurity(&codebase, &add).as_deref(),
        Some("changes `this.text`"),
        "the getter calls a method that changes its object, and the object is the getter's own"
    );
}

/// A call's result has the roots of what the call is given, as `f?.(x)` gives `x`'s when `f` is there, so a getter that
/// changes what a function value returns for a field of `this` changes `this`.
#[test]
fn a_getter_changing_what_a_function_value_returns_for_its_field_is_refused() {
    let builder = (
        "app/Shop/Builder.sharp",
        "namespace App.Shop;\n\npublic class Builder\n{\n    private string text = \"\";\n\n    public void add(string part)\n    {\n        this.text = this.text + part;\n    }\n}\n",
    );
    let page = (
        "app/Shop/Page.sharp",
        "namespace App.Shop;\n\npublic class Page\n{\n    private Builder? builder = null;\n\n    private Function<Builder(Builder?)>? pick = null;\n\n    public string title\n    {\n        get\n        {\n            this.pick?.(this.builder)?.add(\"Shop\");\n            return \"\";\n        }\n    }\n}\n",
    );

    assert_eq!(
        effect_issues(&[page, builder]),
        [
            "app/Shop/Page.sharp:13:13 getter-writes-this: Getter `title` reaches `Builder.add`, which changes `this.text`. A getter never writes `this`. Help: Write the change in a method, and call it before the read."
        ]
    );
}

/// `: super(…)` runs in the constructor, so `new` reaches the effects of its arguments and of the base class's
/// constructor, as it reaches the constructor body's.
#[test]
fn creating_an_object_whose_super_call_has_an_effect_has_that_effect() {
    let stamps = (
        "app/Shop/Stamp.sharp",
        "namespace App.Shop;\n\nimport Acme.Chrono;\n\npublic class Stamp\n{\n    public Stamp(public int at { get; }) { }\n}\n\npublic class Late : Stamp\n{\n    public Late() : super(Chrono.now()) { }\n}\n\npublic class Timed\n{\n    public Timed() { Chrono.now(); }\n}\n\npublic class Child : Timed\n{\n    public Child() : super() { }\n}\n\npublic class Card\n{\n    public int late => new Late().at;\n\n    public bool child => new Child() != null;\n\n    law dated(Card card) => card.late > 0;\n\n    law born(Card card) => card.child;\n}\n",
    );

    assert_eq!(
        effect_issues(&[stamps, CLOCK_STUB, NOW]),
        [
            "app/Shop/Stamp.sharp:31:29 impure-law: Law `dated` reaches `Late.Late`, which calls `Chrono.now` with the effect `Clock`. Laws hold only over pure code.",
            "app/Shop/Stamp.sharp:33:28 impure-law: Law `born` reaches `Timed.Timed`, which calls `Chrono.now` with the effect `Clock`. Laws hold only over pure code.",
        ]
    );
}

/// `new Stamp.now()` runs the named constructor's body, so a getter reaches its effects, and those of its `: this(…)`.
#[test]
fn creating_an_object_whose_named_constructor_has_an_effect_has_that_effect() {
    let stamps = (
        "app/Shop/Stamp.sharp",
        "namespace App.Shop;\n\nimport Acme.Chrono;\n\npublic class Stamp\n{\n    public Stamp(public int at { get; }) { }\n\n    public Stamp.zero() : this(0) { }\n    public Stamp.current() : this(Chrono.now()) { }\n    public Stamp.logged() : this(0) { Chrono.now(); }\n}\n\npublic class Card\n{\n    public int zero => new Stamp.zero().at;\n\n    public int current => new Stamp.current().at;\n\n    public int logged => new Stamp.logged().at;\n\n    law zeroed(Card card) => card.zero == 0;\n\n    law dated(Card card) => card.current > 0;\n\n    law noted(Card card) => card.logged == 0;\n}\n",
    );

    assert_eq!(
        effect_issues(&[stamps, CLOCK_STUB, NOW]),
        [
            "app/Shop/Stamp.sharp:24:29 impure-law: Law `dated` reaches `Stamp.current`, which calls `Chrono.now` with the effect `Clock`. Laws hold only over pure code.",
            "app/Shop/Stamp.sharp:26:29 impure-law: Law `noted` reaches `Stamp.logged`, which calls `Chrono.now` with the effect `Clock`. Laws hold only over pure code.",
        ]
    );
}

/// A write runs the property's `set` or `init` body with the written value as `value`, so a body that changes `value`
/// changes the object the caller wrote. Here that object is a field of the getter's `this`, which a getter never
/// writes.
#[test]
fn a_getter_whose_new_object_changes_the_value_its_init_accessor_is_given_is_refused() {
    let builder = (
        "app/Shop/Builder.sharp",
        "namespace App.Shop;\n\npublic class Builder\n{\n    private string text = \"\";\n\n    public void add(string part)\n    {\n        this.text = this.text + part;\n    }\n}\n",
    );
    let page = (
        "app/Shop/Page.sharp",
        "namespace App.Shop;\n\npublic class Box\n{\n    public Builder held { get; init { value.add(\"x\"); field = value; } }\n\n    public Box(Builder held)\n    {\n        this.held = held;\n    }\n}\n\npublic class Page\n{\n    private Builder builder = new Builder();\n\n    public bool boxed => new Box(this.builder) != null;\n}\n",
    );

    assert_eq!(
        effect_issues(&[page, builder]),
        [
            "app/Shop/Page.sharp:17:26 getter-writes-this: Getter `boxed` reaches `Builder.add`, which changes `this.text`. A getter never writes `this`. Help: Write the change in a method, and call it before the read."
        ]
    );
}

#[test]
fn a_call_of_a_virtual_method_has_the_effects_of_its_overrides() {
    let rates = (
        "app/Shop/Rate.sharp",
        "namespace App.Shop;\n\nimport Acme.Chrono;\n\npublic class Rate\n{\n    public virtual int value() => 1;\n}\n\npublic class LiveRate : Rate\n{\n    public override int value() => Chrono.now();\n}\n",
    );
    let quote = (
        "app/Shop/Quote.sharp",
        "namespace App.Shop;\n\npublic class Quote\n{\n    public Quote(private Rate rate) { }\n\n    public int amount => this.rate.value();\n\n    law priced(Quote quote) => quote.amount > 0;\n}\n",
    );

    assert_eq!(
        effect_issues(&[quote, rates, CLOCK_STUB, NOW]),
        [
            "app/Shop/Quote.sharp:9:32 impure-law: Law `priced` reaches `LiveRate.value`, which calls `Chrono.now` with the effect `Clock`. Laws hold only over pure code."
        ]
    );
}

/// A collection method has the effects of the lambda passed to it, as a function parameter of a PHP# method takes them on, and the lambda is part of
/// the law, so the error points into it.
#[test]
fn a_law_whose_list_map_lambda_calls_an_undeclared_function_is_refused() {
    let names = (
        "app/Shop/Names.sharp",
        "namespace App.Shop;\n\nimport Acme.Letters;\n\npublic class Names\n{\n    law loud(List<string> all) => all.map(name => Letters.shout(name)).count() == all.count();\n}\n",
    );

    assert_eq!(
        effect_issues(&[names, LETTERS]),
        [
            "app/Shop/Names.sharp:7:51 impure-law: Law `loud` calls `Letters.shout`, which has no `extern` declaration. Laws hold only over pure code. Help: Declare it in a .sharp file: `extern Letters.shout;` when it has no effect, or name its effects after `uses`."
        ]
    );
}

#[test]
fn reading_the_environment_has_the_effect_environment() {
    let deploy = (
        "app/Ops/Deploy.sharp",
        "namespace App.Ops;\n\nimport Sharp.System.Environment;\n\npublic class Deploy\n{\n    public Deploy(private Environment environment) { }\n\n    public string region => this.environment.variable(\"AWS_REGION\") ?? \"us-east-1\";\n\n    law regional(Deploy deploy) => deploy.region != \"\";\n}\n",
    );

    assert_eq!(
        effect_issues(&[deploy]),
        [
            "app/Ops/Deploy.sharp:11:36 impure-law: Law `regional` reaches `Deploy.region`, which calls `Environment.variable` with the effect `Environment`. Laws hold only over pure code."
        ]
    );
}

/// Spec section 29 lists `require` among `Environment`'s instance members, so a call reads the environment only
/// through an `Environment` object, never through the class.
#[test]
fn environment_require_is_called_on_an_environment_object() {
    let deploy = (
        "app/Ops/Deploy.sharp",
        "namespace App.Ops;\n\nimport Sharp.System.Environment;\n\npublic class Deploy\n{\n    public Deploy(private Environment environment) { }\n\n    public string key() => this.environment.require(\"APP_KEY\");\n\n    public string staticKey() => Environment.require(\"APP_KEY\");\n}\n",
    );

    assert_eq!(issues(deploy, &[]), ["11:46 invalid-static-method-access", "11:34 mixed-return-statement"]);
}

/// Spec section 29: code has a `foreign` class's effect by holding one of its objects, so a getter that calls or reads
/// through a field or a constructor parameter of a project's `foreign` class has it, and a law reading the getter is
/// refused, naming the class.
#[test]
fn a_getter_reaching_through_a_foreign_object_has_the_effect_of_its_class() {
    let payments = (
        "app/Billing/Payments.sharp",
        "namespace App.Billing;\n\npublic foreign class Payments\n{\n    public int fee = 30;\n\n    public int charge(int cents) => cents;\n}\n",
    );
    let field = (
        "app/Shop/Checkout.sharp",
        "namespace App.Shop;\n\nimport App.Billing.Payments;\n\npublic class Checkout\n{\n    private Payments payments;\n\n    public Checkout(Payments payments)\n    {\n        this.payments = payments;\n    }\n\n    public int total => this.payments.charge(100);\n\n    law totaled(Checkout checkout) => checkout.total > 0;\n}\n",
    );
    let parameter = (
        "app/Shop/Checkout.sharp",
        "namespace App.Shop;\n\nimport App.Billing.Payments;\n\npublic class Checkout\n{\n    public Checkout(private Payments payments) { }\n\n    public int total => this.payments.charge(100);\n\n    law totaled(Checkout checkout) => checkout.total > 0;\n}\n",
    );
    let read = (
        "app/Shop/Checkout.sharp",
        "namespace App.Shop;\n\nimport App.Billing.Payments;\n\npublic class Checkout\n{\n    public Checkout(private Payments payments) { }\n\n    public int total => this.payments.fee;\n\n    law totaled(Checkout checkout) => checkout.total > 0;\n}\n",
    );
    let named_at_run_time = (
        "app/Shop/Checkout.sharp",
        "namespace App.Shop;\n\nimport App.Billing.Payments;\n\npublic class Checkout\n{\n    public Checkout(private Payments payments) { }\n\n    public int total => this.payments.{\"fee\"};\n\n    law totaled(Checkout checkout) => checkout.total > 0;\n}\n",
    );

    for (form, refused) in [
        (
            field,
            "app/Shop/Checkout.sharp:16:39 impure-law: Law `totaled` reaches `Checkout.total`, which calls `Payments.charge` with the effect `Payments`. Laws hold only over pure code.",
        ),
        (
            parameter,
            "app/Shop/Checkout.sharp:11:39 impure-law: Law `totaled` reaches `Checkout.total`, which calls `Payments.charge` with the effect `Payments`. Laws hold only over pure code.",
        ),
        (
            read,
            "app/Shop/Checkout.sharp:11:39 impure-law: Law `totaled` reaches `Checkout.total`, which calls `Payments.fee` with the effect `Payments`. Laws hold only over pure code.",
        ),
        (
            named_at_run_time,
            "app/Shop/Checkout.sharp:11:39 impure-law: Law `totaled` reaches `Checkout.total`, which calls `Payments` with the effect `Payments`. Laws hold only over pure code.",
        ),
    ] {
        assert_eq!(effect_issues(&[form, payments]), [refused], "{}", form.1);
    }

    // A subclass of a `foreign` class is that class's object, so it has that class's effect.
    let gateway = (
        "app/Billing/Gateway.sharp",
        "namespace App.Billing;\n\npublic abstract foreign class Gateway\n{\n    public virtual int fee() => 1;\n}\n",
    );
    let stripe = (
        "app/Billing/Stripe.sharp",
        "namespace App.Billing;\n\npublic class Stripe : Gateway\n{\n    public override int fee() => 2;\n}\n",
    );
    let subclass = (
        "app/Shop/Checkout.sharp",
        "namespace App.Shop;\n\nimport App.Billing.Stripe;\n\npublic class Checkout\n{\n    public Checkout(private Stripe stripe) { }\n\n    public int total => this.stripe.fee();\n\n    law totaled(Checkout checkout) => checkout.total > 0;\n}\n",
    );
    assert_eq!(
        effect_issues(&[subclass, gateway, stripe]),
        [
            "app/Shop/Checkout.sharp:11:39 impure-law: Law `totaled` reaches `Checkout.total`, which calls `Stripe.fee` with the effect `Gateway`. Laws hold only over pure code."
        ]
    );
}

/// Spec section 29: code that reaches a `foreign` object has its class's effect, whatever its members do, so each
/// member of a `foreign` class has that effect too. A pure interface method refuses a `foreign` implementation, and a
/// call through an interface or a base class has the effect of its `foreign` implementation.
#[test]
fn a_foreign_class_s_members_have_its_effect_behind_an_interface_or_a_base_class() {
    let store = |uses: &'static str| {
        (
            "app/Cache/Store.sharp",
            Box::leak(
                format!("namespace App.Cache;\n\npublic interface Store\n{{\n    int size(){uses};\n}}\n")
                    .into_boxed_str(),
            ) as &str,
        )
    };
    let quiet = (
        "app/Cache/QuietStore.sharp",
        "namespace App.Cache;\n\npublic foreign class QuietStore : Store\n{\n    public int size() => 3;\n}\n",
    );
    let quiet_reader = (
        "app/Cache/QuietReader.sharp",
        "namespace App.Cache;\n\npublic class QuietReader\n{\n    public QuietReader(private Store store) { }\n\n    public int count => this.store.size();\n\n    public Function<int()> counter() => () => this.store.size();\n\n    law counted(QuietReader reader) => reader.count > 0;\n}\n",
    );
    let plain = (
        "app/Cache/Plain.sharp",
        "namespace App.Cache;\n\npublic abstract class Plain\n{\n    public virtual int size() => 1;\n}\n",
    );
    let sneaky = (
        "app/Cache/Sneaky.sharp",
        "namespace App.Cache;\n\npublic foreign class Sneaky : Plain\n{\n    public override int size() => 2;\n}\n",
    );
    let plain_reader = (
        "app/Cache/PlainReader.sharp",
        "namespace App.Cache;\n\npublic class PlainReader\n{\n    public PlainReader(private Plain plain) { }\n\n    public int count => this.plain.size();\n\n    public Function<int()> counter() => () => this.plain.size();\n\n    law counted(PlainReader reader) => reader.count > 0;\n}\n",
    );

    assert_eq!(
        effect_issues(&[quiet, store(""), quiet_reader]),
        [
            "app/Cache/QuietStore.sharp:5:26 incompatible-effects: `QuietStore.size` is a member of the `foreign` class `QuietStore`, so the pure `Store.size` cannot accept it."
        ]
    );
    assert_eq!(
        effect_issues(&[quiet, store(" uses QuietStore"), quiet_reader]),
        [
            "app/Cache/QuietReader.sharp:11:40 impure-law: Law `counted` reaches `QuietReader.count`, which calls `Store.size` with the effect `QuietStore`. Laws hold only over pure code.",
            "app/Cache/QuietReader.sharp:9:41 invalid-return-statement: This lambda calls `Store.size`, which has the effect `QuietStore`, so a pure `Function<int()>` cannot hold it.",
        ]
    );
    assert_eq!(
        effect_issues(&[sneaky, plain, plain_reader]),
        [
            "app/Cache/PlainReader.sharp:11:40 impure-law: Law `counted` reaches `Sneaky.size`, a member of the `foreign` class `Sneaky`. Laws hold only over pure code.",
            "app/Cache/PlainReader.sharp:9:41 invalid-return-statement: This lambda reaches `Sneaky.size`, a member of the `foreign` class `Sneaky`, so a pure `Function<int()>` cannot hold it.",
        ]
    );
}

/// Spec section 29: a `foreign` object is created in a module binding and nowhere else, so a `.sharp` file's `new` of a
/// `foreign` class, or of a class that extends one, is refused outside a binding's expression. Plain PHP creates one
/// freely.
#[test]
fn a_foreign_object_is_created_only_in_a_module_binding() {
    let store = ("app/Cache/RedisStore.sharp", "namespace App.Cache;\n\npublic foreign class RedisStore\n{\n}\n");
    let fake = ("app/Cache/FakeStore.sharp", "namespace App.Cache;\n\npublic class FakeStore : RedisStore\n{\n}\n");
    let factory = (
        "app/Cache/Factory.sharp",
        "namespace App.Cache;\n\npublic class Factory\n{\n    public RedisStore make() => new RedisStore();\n\n    public RedisStore fake()\n    {\n        const make = () => new FakeStore();\n        return make();\n    }\n}\n",
    );
    let help = "A module binding decides how often a `foreign` object is created. | Take it as a constructor or method parameter, and create it in a module binding.";

    assert_eq!(
        worded(factory, &[store, fake]),
        [
            format!(
                "5:37 foreign-outside-module `RedisStore` is `foreign`, so only a module binding creates it. | {help}"
            ),
            format!(
                "9:32 foreign-outside-module `FakeStore` is a `foreign` `RedisStore`, so only a module binding creates it. | {help}"
            ),
        ]
    );
    let module = (
        "app/Cache/Module.sharp",
        "namespace App.Cache;\n\nmodule\n{\n    singleton RedisStore = new RedisStore();\n\n    singleton Function<RedisStore()> = () => new FakeStore();\n}\n",
    );
    assert_eq!(worded(module, &[store, fake]), Vec::<String>::new());
    let php = (
        "src/Make.php",
        "<?php\n\nnamespace App;\n\nfinal class Make\n{\n    public function store(): \\App\\Cache\\RedisStore\n    {\n        return new \\App\\Cache\\RedisStore();\n    }\n}\n",
    );
    assert_eq!(worded(php, &[store]), Vec::<String>::new());
}

/// Spec section 29: a static outlives the module binding that creates a `foreign` object, so a static field holds none,
/// alone or inside a collection. A static field written without its type holds nothing the check can name, so only the parser
/// reports it. `App.Cache.Cache` shares its short name with the standard library's `Cache`, so a message names it in
/// full.
#[test]
fn a_static_field_holding_a_foreign_object_is_refused() {
    let store = ("app/Cache/RedisStore.sharp", "namespace App.Cache;\n\npublic foreign class RedisStore\n{\n}\n");
    let message = "`App.Cache.Cache.store` is static, so it cannot hold a `RedisStore`.";

    for (field, column) in [
        ("public static RedisStore store;", 30),
        ("public static RedisStore? store = null;", 31),
        ("public static List<RedisStore> store = [];", 36),
    ] {
        let cache =
            Box::leak(format!("namespace App.Cache;\n\npublic class Cache\n{{\n    {field}\n}}\n").into_boxed_str());

        assert_eq!(
            worded(("app/Cache/Cache.sharp", cache), &[store]),
            [format!(
                "5:{column} foreign-in-static {message} | A module binding decides how often a `foreign` object is created, and a static outlives every binding, so no static holds one. | Take the `RedisStore` as a constructor or method parameter instead."
            )],
            "{field}"
        );
    }
    assert_eq!(
        worded(
            ("app/Cache/Cache.sharp", "namespace App.Cache;\n\npublic class Cache\n{\n    public static store;\n}\n"),
            &[store]
        ),
        ["5:19 parse A PHP# field needs a type, as in `private int count = 0;`. | Written here."]
    );

    let money = ("app/Cache/Money.sharp", "namespace App.Cache;\n\npublic class Money\n{\n}\n");
    assert_eq!(
        worded(
            (
                "app/Cache/Cache.sharp",
                "namespace App.Cache;\n\npublic class Cache\n{\n    public static Money? cache = null;\n}\n"
            ),
            &[store, money]
        ),
        Vec::<String>::new()
    );
}

/// Spec section 29: a `foreign` object is an ordinary type in a parameter and a return value. A method that calls one
/// it takes has its effect, as when it calls one it holds, so a pure interface method's implementation that calls a
/// `Clock` parameter is refused. A caller that uses a returned one has the effect at that call. A static still holds
/// none.
#[test]
fn a_foreign_object_is_an_ordinary_parameter_and_return_type() {
    let instant = (
        "vendor/heyjordanparker/php-sharp-composer/library/Sharp/Time/Instant.sharp",
        include_str!("../../../../composer/library/Sharp/Time/Instant.sharp"),
    );
    let stamp = (
        "app/Shop/Stamp.sharp",
        "namespace App.Shop;\n\nimport Sharp.Time.Clock;\n\npublic class Stamp\n{\n    public Stamp(private Clock clock) { }\n\n    public string stampedWith(Clock clock) => clock.now().toString();\n\n    public Clock held() => this.clock;\n\n    public int later(Stamp other) => other.held().now().epochSeconds + 1;\n}\n",
    );

    assert_eq!(issues(stamp, &[instant]), Vec::<String>::new());
    let (codebase, summaries) = summarized(&[stamp, instant, BUILTINS]);
    let effects = Effects::solve(&codebase, &summaries);
    let method = |name: &[u8]| {
        FunctionLikeIdentifier::Method(ascii_lowercase_word(b"App\\Shop\\Stamp"), ascii_lowercase_word(name))
    };
    let clock = Some(vec![word("Sharp\\Time\\Clock")]);
    assert_eq!(effects.function_effects(&method(b"stampedWith")), clock, "a parameter");
    assert_eq!(effects.function_effects(&method(b"later")), clock, "a returned one");

    let stamps = (
        "app/Shop/Stamps.sharp",
        "namespace App.Shop;\n\nimport Sharp.Time.Clock;\n\npublic interface Stamps\n{\n    int stamped(Clock clock);\n}\n",
    );
    let stamper = (
        "app/Shop/Stamper.sharp",
        "namespace App.Shop;\n\nimport Sharp.Time.Clock;\n\npublic class Stamper : Stamps\n{\n    public int stamped(Clock clock) => clock.now();\n}\n",
    );
    assert_eq!(
        effect_issues(&[stamps, stamper]),
        [
            "app/Shop/Stamper.sharp:7:40 incompatible-effects: `Stamper.stamped` calls `Clock.now`, which has the effect `Clock`, so the pure `Stamps.stamped` cannot accept it."
        ],
        "a pure interface method"
    );

    let kept = (
        "app/Shop/Kept.sharp",
        "namespace App.Shop;\n\nimport Sharp.Time.Clock;\n\npublic class Kept\n{\n    public static Clock? clock = null;\n}\n",
    );
    assert!(
        issues(kept, &[]).iter().any(|issue| issue.ends_with(" foreign-in-static")),
        "a static: {:?}",
        issues(kept, &[])
    );
}

/// Spec section 29: pure limits only what a method reaches outside the program, so a pure method may change its own
/// object and its arguments. `readonly` after the parameters promises it changes nothing, and holds every
/// implementation to it (section 13). A law reasons about values and sees no object two names share, so a law that
/// reaches a change is refused naming the method.
#[test]
fn a_pure_method_may_change_its_object_and_its_arguments() {
    let tally = (
        "app/Shop/Tally.sharp",
        "namespace App.Shop;\n\npublic class Tally\n{\n    public int count { get; set; } = 0;\n}\n",
    );
    let counter = (
        "app/Shop/Counter.sharp",
        "namespace App.Shop;\n\npublic interface Counter\n{\n    int next();\n\n    void bump(Tally tally);\n}\n",
    );
    let ticker = (
        "app/Shop/Ticker.sharp",
        "namespace App.Shop;\n\npublic class Ticker : Counter\n{\n    private int count = 0;\n\n    public int next()\n    {\n        this.count += 1;\n        return this.count;\n    }\n\n    public void bump(Tally tally)\n    {\n        tally.count += 1;\n    }\n}\n",
    );

    assert_eq!(issues(ticker, &[counter, tally]), Vec::<String>::new(), "a pure implementation changes `this`");
    assert_eq!(effect_issues(&[ticker, counter, tally]), Vec::<String>::new(), "and its argument");

    let peek =
        ("app/Shop/Peek.sharp", "namespace App.Shop;\n\npublic interface Peek\n{\n    int peek() readonly;\n}\n");
    let peeker = (
        "app/Shop/Peeker.sharp",
        "namespace App.Shop;\n\npublic class Peeker : Peek\n{\n    private int count = 0;\n\n    public int peek() readonly\n    {\n        this.count += 1;\n        return this.count;\n    }\n}\n",
    );
    assert!(!issues(peeker, &[peek]).is_empty(), "a readonly implementation changes `this`");

    let law = (
        "app/Shop/Counted.sharp",
        "namespace App.Shop;\n\npublic class Counted\n{\n    public static int bumped(Tally tally)\n    {\n        tally.count += 1;\n        return tally.count;\n    }\n\n    law grows(Tally tally) => Counted.bumped(tally) > 0;\n}\n",
    );
    assert_eq!(
        effect_issues(&[law, tally]),
        [
            "app/Shop/Counted.sharp:11:31 impure-law: Law `grows` reaches `Counted.bumped`, which changes `tally.count`. Laws hold only over code that changes nothing."
        ],
        "a law"
    );
}

/// Spec section 29: no static holds a `foreign` object, so a write of one into a static whose declared type is wider,
/// such as `Any?`, a `List<Any>` or an interface the class implements, is refused at the value, as a changing
/// collection method on a static is.
#[test]
fn a_foreign_object_written_into_a_static_is_refused() {
    let store = ("app/Cache/Store.sharp", "namespace App.Cache;\n\npublic interface Store\n{\n}\n");
    let redis =
        ("app/Cache/RedisStore.sharp", "namespace App.Cache;\n\npublic foreign class RedisStore : Store\n{\n}\n");
    let message = "foreign-in-static `App.Cache.Cache.loose` is static, so it cannot hold a `RedisStore`. | A module binding decides how often a `foreign` object is created, and a static outlives every binding, so no static holds one. | Take the `RedisStore` as a constructor or method parameter instead.";

    for (field, write, column) in [
        ("public static Any? loose = null;", "Cache.loose = this.store;", 40),
        ("public static List<Any> loose = [];", "Cache.loose = [this.store];", 40),
        ("public static Store? loose = null;", "Cache.loose = this.store;", 40),
        ("public static List<Any> loose = [];", "Cache.loose.add(this.store);", 42),
    ] {
        let cache = Box::leak(
            format!(
                "namespace App.Cache;\n\npublic class Cache\n{{\n    {field}\n\n    public Cache(private RedisStore store) {{ }}\n\n    public void keep() {{ {write} }}\n}}\n"
            )
            .into_boxed_str(),
        );

        assert_eq!(
            worded(("app/Cache/Cache.sharp", cache), &[store, redis]),
            [format!("9:{column} {message}")],
            "{write}"
        );
    }
}

/// A value whose type parameter has a `foreign` bound is a `foreign` object, and so is a generic class's `foreign`
/// type argument, so a static holds neither. A bound that is no `foreign` class holds nothing the check can name.
#[test]
fn a_foreign_object_behind_a_type_parameter_or_a_type_argument_is_refused_in_a_static() {
    let store = ("app/Cache/Store.sharp", "namespace App.Cache;\n\npublic interface Store\n{\n}\n");
    let redis =
        ("app/Cache/RedisStore.sharp", "namespace App.Cache;\n\npublic foreign class RedisStore : Store\n{\n}\n");
    let shelf = ("app/Cache/Shelf.sharp", "namespace App.Cache;\n\npublic class Shelf<TItem>\n{\n}\n");
    let refused = |property: &str, column: usize| {
        vec![format!(
            "5:{column} foreign-in-static `App.Cache.Cache.{property}` is static, so it cannot hold a `RedisStore`. | A module binding decides how often a `foreign` object is created, and a static outlives every binding, so no static holds one. | Take the `RedisStore` as a constructor or method parameter instead."
        )]
    };

    for (member, expected) in [
        ("public static void keep<TStore : RedisStore>(TStore held) { Cache.loose = held; }", refused("loose", 79)),
        ("public static void keep<TStore : Store>(TStore held) { Cache.loose = held; }", vec![]),
        ("public static Shelf<RedisStore>? shelf = null;", refused("shelf", 38)),
        ("public static Shelf<Store>? shelf = null;", vec![]),
    ] {
        let cache = Box::leak(
            format!("namespace App.Cache;\n\npublic class Cache\n{{\n    {member}\n\n    public static Any? loose = null;\n}}\n")
                .into_boxed_str(),
        );

        assert_eq!(worded(("app/Cache/Cache.sharp", cache), &[store, redis, shelf]), expected, "{member}");
    }
}

/// Two methods that call each other form one strongly connected part, which the solve iterates to a fixpoint instead
/// of following forever. `impurity` answers for a method as it does for a getter.
#[test]
fn a_recursive_pair_of_methods_solves_without_looping() {
    let tree = (
        "app/Shop/Tree.sharp",
        "namespace App.Shop;\n\nimport Acme.Chrono;\n\npublic class Tree\n{\n    public int even(int n) => n == 0 ? 0 : this.odd(n - 1);\n\n    public int odd(int n) => n == 0 ? Chrono.now() : this.even(n - 1);\n\n    public int depth => this.even(4);\n\n    law deep(Tree tree) => tree.depth >= 0;\n}\n",
    );
    let files = [tree, CLOCK_STUB, NOW];

    assert_eq!(
        effect_issues(&files),
        [
            "app/Shop/Tree.sharp:13:28 impure-law: Law `deep` reaches `Tree.odd`, which calls `Chrono.now` with the effect `Clock`. Laws hold only over pure code."
        ]
    );
    let (codebase, summaries) = summarized(&files);
    let effects = Effects::solve(&codebase, &summaries);
    let even = FunctionLikeIdentifier::Method(ascii_lowercase_word(b"App\\Shop\\Tree"), ascii_lowercase_word(b"even"));
    assert_eq!(
        effects.impurity(&codebase, &even).as_deref(),
        Some("reaches `Tree.odd`, which calls `Chrono.now` with the effect `Clock`")
    );
}

/// Spec section 21: a function type lists the effects of each body its function calls, in any file, so an edit of one
/// can change it. `callee_files` gives the file of each method a call reaches, every override it can run, each
/// accessor's class and the class of each static whose initial value a use runs, but never the calling file itself. A change of state is no effect, so the type lists none for it.
#[test]
fn the_files_a_call_reaches_are_its_methods_its_overrides_and_its_accessors() {
    let base = (
        "app/Shop/Base.sharp",
        "namespace App.Shop;\n\npublic abstract class Base\n{\n    public virtual int price() => 1;\n}\n",
    );
    let sale = (
        "app/Shop/Sale.sharp",
        "namespace App.Shop;\n\nimport Acme.Chrono;\n\npublic class Sale : Base\n{\n    public override int price() => Chrono.now();\n}\n",
    );
    let stock = (
        "app/Shop/Stock.sharp",
        "namespace App.Shop;\n\npublic class Stock\n{\n    public int count { get => 2; }\n}\n",
    );
    let opened = (
        "app/Shop/Opened.sharp",
        "namespace App.Shop;\n\nimport Acme.Chrono;\n\npublic class Opened\n{\n    public static int at { get; } = 3 + Chrono.now();\n}\n",
    );
    let till = (
        "app/Shop/Till.sharp",
        "namespace App.Shop;\n\npublic class Till\n{\n    private int rung = 0;\n\n    public int ring(Base item, Stock stock) => item.price() + stock.count + this.add() + Opened.at;\n\n    public int add()\n    {\n        this.rung += 1;\n        return this.rung;\n    }\n}\n",
    );
    let (codebase, summaries) = summarized(&[base, sale, stock, opened, till, CLOCK_STUB, NOW]);
    let effects = Effects::solve(&codebase, &summaries);
    let file = |class: &[u8]| codebase.get_class_like(class).expect("the class is declared").span.file_id;
    let method = |name: &[u8]| {
        FunctionLikeIdentifier::Method(ascii_lowercase_word(b"App\\Shop\\Till"), ascii_lowercase_word(name))
    };

    let callee_files = effects.callee_files(&codebase);
    assert_eq!(
        callee_files.get(&file(b"App\\Shop\\Till")),
        Some(
            &[
                file(b"App\\Shop\\Base"),
                file(b"App\\Shop\\Sale"),
                file(b"App\\Shop\\Stock"),
                file(b"App\\Shop\\Opened")
            ]
            .into_iter()
            .collect()
        )
    );
    assert_eq!(callee_files.get(&file(b"App\\Shop\\Sale")), None);
    assert_eq!(effects.function_effects(&method(b"add")), Some(Vec::new()));
    assert_eq!(effects.function_effects(&method(b"ring")), Some(vec![word("Sharp\\Time\\Clock")]));
}

/// An operator on an instance runs the operator its class declares (spec section 19), so a getter that applies one
/// reaches that operator's body, as a getter that calls a method reaches the method's.
#[test]
fn applying_an_operator_has_the_effects_of_its_body() {
    let money = (
        "app/Shop/Money.sharp",
        "namespace App.Shop;\n\nimport Acme.Chrono;\n\npublic class Money\n{\n    public Money(public int cents) { }\n\n    public int hash() => this.cents;\n\n    public static Money operator +(Money a, Money b) => new Money(a.cents + b.cents + Chrono.now());\n\n    public static Money operator -(Money a) => new Money(Chrono.now() - a.cents);\n\n    public static bool operator ==(Money a, Money b) => a.cents == b.cents + Chrono.now();\n\n    public static int operator <=>(Money a, Money b) => a.cents - b.cents + Chrono.now();\n}\n",
    );
    let cart = (
        "app/Shop/Cart.sharp",
        "namespace App.Shop;\n\npublic class Cart\n{\n    public Cart(private Money price, private Money tax) { }\n\n    public Money total => this.price + this.tax;\n\n    public Money refund => -this.price;\n\n    public bool even => this.price == this.tax;\n\n    public bool cheaper => this.price < this.tax;\n\n    public Money doubled\n    {\n        get\n        {\n            let sum = this.price;\n            sum += this.price;\n            return sum;\n        }\n    }\n\n    law totals(Cart cart) => cart.total.cents > 0;\n\n    law refunds(Cart cart) => cart.refund.cents > 0;\n\n    law evens(Cart cart) => cart.even;\n\n    law cheapens(Cart cart) => cart.cheaper;\n\n    law doubles(Cart cart) => cart.doubled.cents > 0;\n}\n",
    );

    assert_eq!(
        effect_issues(&[cart, money, CLOCK_STUB, NOW]),
        [
            "app/Shop/Cart.sharp:25:30 impure-law: Law `totals` reaches `Money.operator +`, which calls `Chrono.now` with the effect `Clock`. Laws hold only over pure code.",
            "app/Shop/Cart.sharp:27:31 impure-law: Law `refunds` reaches `Money.operator -`, which calls `Chrono.now` with the effect `Clock`. Laws hold only over pure code.",
            "app/Shop/Cart.sharp:29:29 impure-law: Law `evens` reaches `Money.operator ==`, which calls `Chrono.now` with the effect `Clock`. Laws hold only over pure code.",
            "app/Shop/Cart.sharp:31:32 impure-law: Law `cheapens` reaches `Money.operator <=>`, which calls `Chrono.now` with the effect `Clock`. Laws hold only over pure code.",
            "app/Shop/Cart.sharp:33:31 impure-law: Law `doubles` reaches `Money.operator +`, which calls `Chrono.now` with the effect `Clock`. Laws hold only over pure code.",
        ]
    );
}

/// Spec section 28's `Money`, whose law holds over its pure `add`.
const LAWFUL_MONEY: (&str, &str) = (
    "app/Shared/Money.sharp",
    "namespace App.Shared;\n\npublic class Money\n{\n    public Money(public int amount { get; }, public string currency { get; }) { }\n    public Money add(Money other) => new Money(this.amount + other.amount, this.currency);\n\n    law addKeepsCurrency(Money a, Money b) => a.add(b).currency == a.currency;\n}\n",
);

/// Spec section 28: a law is a `bool` expression over typed parameters, analyzed as a static method's body.
#[test]
fn a_law_over_pure_code_reports_no_issue() {
    assert_eq!(issues(LAWFUL_MONEY, &[]), Vec::<String>::new());
    assert_eq!(effect_issues(&[LAWFUL_MONEY]), Vec::<String>::new());
}

/// Spec section 28's state machine: a law covers every state and event through the enum's pure transition method.
#[test]
fn a_law_over_an_enum_transition_reports_no_issue() {
    let payment = (
        "app/Shop/Payment.sharp",
        "namespace App.Shop;\n\npublic enum Payment\n{\n    case Captured;\n    case Returned;\n}\n",
    );
    let status = (
        "app/Shop/Status.sharp",
        "namespace App.Shop;\n\npublic enum Status : string\n{\n    case Open = \"open\";\n    case Paid = \"paid\";\n    case Refunded = \"refunded\";\n\n    public Status after(Payment e) => match (this) {\n        Status.Open => e == Payment.Captured ? Status.Paid : Status.Open,\n        Status.Paid => e == Payment.Returned ? Status.Refunded : Status.Paid,\n        Status.Refunded => Status.Refunded,\n    };\n\n    law refundedIsFinal(Payment e) => Status.Refunded.after(e) == Status.Refunded;\n}\n",
    );

    assert_eq!(issues(status, &[payment]), Vec::<String>::new());
    assert_eq!(effect_issues(&[status, payment]), Vec::<String>::new());
}

const GATEWAY: (&str, &str) = (
    "src/Billing/Gateway.php",
    "<?php\n\nnamespace Billing;\n\nfinal class Gateway\n{\n    public static function charge(int $amount): bool\n    {\n        return $amount > 0;\n    }\n}\n",
);

/// Spec section 28: laws hold only over pure code, so a law that calls code with an effect is refused on the call.
#[test]
fn a_law_calling_plain_php_with_an_effect_is_refused_on_the_call() {
    let stub = (
        "app/Stubs/Billing.sharp",
        "namespace App.Stubs;\n\nimport Billing.Gateway;\n\nextern Gateway.charge uses Http;\n",
    );
    let refund = (
        "app/Shop/Refund.sharp",
        "namespace App.Shop;\n\nimport Billing.Gateway;\n\npublic class Refund\n{\n    law refundAllowed(int amount) => Gateway.charge(amount);\n}\n",
    );

    assert_eq!(
        effect_issues(&[refund, stub, GATEWAY]),
        [
            "app/Shop/Refund.sharp:7:38 impure-law: Law `refundAllowed` calls `Gateway.charge`, which has the effect `Http`. Laws hold only over pure code."
        ]
    );
}

/// A law that reaches an effect through PHP# code in another file names the method it reaches, in a class and in a
/// module alike.
#[test]
fn a_law_reaching_a_method_with_an_effect_in_another_file_is_refused() {
    let timer = (
        "src/Lib/Timer.php",
        "<?php\n\nnamespace Lib;\n\nfinal class Timer\n{\n    public static function now(): int\n    {\n        return time();\n    }\n}\n",
    );
    let stub = ("app/Stubs/Timer.sharp", "namespace App.Stubs;\n\nimport Lib.Timer;\n\nextern Timer.now uses Clock;\n");
    let order = (
        "app/Shop/Order.sharp",
        "namespace App.Shop;\n\nimport Lib.Timer;\n\npublic class Order\n{\n    public int total() => Timer.now();\n}\n",
    );

    for law in [
        (
            "app/Shop/Checkout.sharp",
            "namespace App.Shop;\n\npublic class Checkout\n{\n    law totalMatches(Order order) => order.total() == order.total();\n}\n",
        ),
        (
            "app/Shop/Module.sharp",
            "namespace App.Shop;\n\nmodule\n{\n    law totalMatches(Order order) => order.total() == order.total();\n}\n",
        ),
    ] {
        assert_eq!(
            effect_issues(&[law, order, stub, timer]),
            [format!(
                "{}:5:38 impure-law: Law `totalMatches` reaches `Order.total`, which calls `Timer.now` with the effect `Clock`. Laws hold only over pure code.",
                law.0
            )]
        );
    }
}

/// Spec section 28: the effect rule reads all of a law: its `when` condition and every statement of its body, a local
/// no law call reads after it included, as well as its claim.
#[test]
fn an_effect_in_a_law_s_condition_or_body_is_refused() {
    let timer = (
        "src/Lib/Timer.php",
        "<?php\n\nnamespace Lib;\n\nfinal class Timer\n{\n    public static function now(): int\n    {\n        return time();\n    }\n}\n",
    );
    let stub = ("app/Stubs/Timer.sharp", "namespace App.Stubs;\n\nimport Lib.Timer;\n\nextern Timer.now uses Clock;\n");

    for (law, at) in [
        (
            (
                "app/Shop/Clock.sharp",
                "namespace App.Shop;\n\nimport Lib.Timer;\n\npublic class Clock\n{\n    law ticks(int x) => true\n    {\n        let now = Timer.now();\n    }\n}\n",
            ),
            "9:19",
        ),
        (
            (
                "app/Shop/Clock.sharp",
                "namespace App.Shop;\n\nimport Lib.Timer;\n\npublic class Clock\n{\n    law ticks(int x) when Timer.now() > 0 => true;\n}\n",
            ),
            "7:27",
        ),
    ] {
        assert_eq!(
            effect_issues(&[law, stub, timer]),
            [format!(
                "{}:{at} impure-law: Law `ticks` calls `Timer.now`, which has the effect `Clock`. Laws hold only over pure code.",
                law.0
            )],
            "{}",
            law.1
        );
    }
}

